/* Finished film-specific poster menus. Recipes and shopping lists are kept together.
   Add each approved edition here; existing films continue to work during the rollout. */
const MOVIE_MENU_EDITIONS = {"The Warriors (1979)":{"poster":"assets/menu-posters/the-warriors-1979.jpg","colour":"#a52b20","servings":4,"tagline":"Last stop: Coney Island.","cue":"Bring out the chilli dogs when the journey heads back towards Coney Island.","menu":{"s":[{"n":"Boardwalk pretzel bites","note":"Warm soft pretzel bites brushed with butter and coarse salt, with a hot cheddar sauce and yellow mustard for dipping.","how":"Mix 250g plain flour, 4g instant yeast, 1 tsp sugar, 1/2 tsp salt and 160ml warm water. Knead 8 minutes, cover and rise 1 hour. Roll into ropes and cut into 24 bites. Simmer 1 litre water with 30g bicarbonate of soda; boil bites in batches for 20 seconds, drain and bake on baking paper at 220°C for 12 to 15 minutes. Brush with 20g melted butter. For dip, melt 15g butter, stir in 15g flour, whisk in 150ml milk and simmer 2 minutes. Remove from heat and stir in 100g grated cheddar. Serve with mustard.","shop":["250g + 15g plain flour@Pantry","4g instant yeast@Pantry","1 tsp sugar@Pantry","1/2 tsp salt@Pantry","30g bicarbonate of soda@Pantry","35g butter@Dairy","150ml milk@Dairy","100g cheddar@Dairy","yellow mustard@Pantry"]},{"n":"Street-cart corn","note":"Corn ribs roasted until charred and curling, brushed with chilli butter and smoked salt, finished with plenty of lime.","how":"Quarter 4 corn cobs lengthways on a secure board with a sturdy sharp knife; use whole cobs if easier. Brush with 30g melted butter mixed with 1/2 tsp chilli flakes and a pinch of smoked salt. Roast at 220°C for 20 to 25 minutes, turning once, until tender and charred at the edges. Finish with the juice of 1 lime.","shop":["4 corn cobs@Produce","1 lime@Produce","30g butter@Dairy","1/2 tsp chilli flakes@Pantry","smoked salt@Pantry"]}],"m":[{"n":"Coney Island chilli dogs","note":"griddled frankfurts under loose spiced beef sauce, mustard and onion, can you dig it","how":"Dice 1 onion; reserve a quarter for topping. Fry the rest in 1 tbsp oil with 2 minced garlic cloves, add 400g beef mince and brown well. Stir in 1 tbsp tomato paste, 1 tsp each ground cumin and smoked paprika, 400g tinned tomatoes and 100ml water. Simmer 25 minutes; season with salt. Bake 600g shoestring fries as directed on the packet. Griddle 8 beef franks until piping hot and warm 8 buns. Fill buns with franks and chilli; finish with reserved onion and mustard. Serve fries alongside.","shop":["400g beef mince@Meat","8 beef franks@Meat","8 hot dog buns@Bakery","600g shoestring fries@Frozen","1 onion@Produce","2 garlic cloves@Produce","1 tbsp oil@Pantry","1 tbsp tomato paste@Pantry","1 tsp ground cumin@Pantry","1 tsp smoked paprika@Pantry","400g tinned tomatoes@Pantry","salt@Pantry","yellow mustard@Pantry"]}],"w":[{"n":"Chocolate-dipped ice-cream sandwiches","note":"Vanilla ice cream, chewy chocolate cookies and dark chocolate.","how":"Soften 500ml vanilla ice cream just enough to scoop. Sandwich between 8 large chewy chocolate cookies to make 4 sandwiches. Freeze on a lined tray for 1 hour. Melt 150g dark chocolate gently, cool until just warm, dip half of each sandwich and return to the freezer for 15 minutes. Make ahead so they're ready when the film finishes.","shop":["500ml vanilla ice cream@Frozen","8 large chewy chocolate cookies@Bakery","150g dark chocolate@Pantry"]}],"d":[{"n":"Cherry cola","note":"Ice-cold cola, cherry syrup and a squeeze of lime.","how":"Fill 4 glasses with ice. Add 15ml cherry syrup to each, top each with 250ml cola and squeeze in a lime wedge. Stir once. Taste before adding more syrup.","shop":["1 litre cola@Drinks","60ml cherry syrup@Drinks","1 lime@Produce","ice@Frozen"]}],"shopping":["250g + 15g plain flour@Pantry","4g instant yeast@Pantry","1 tsp sugar@Pantry","1/2 tsp salt@Pantry","30g bicarbonate of soda@Pantry","65g butter@Dairy","150ml milk@Dairy","100g cheddar@Dairy","yellow mustard@Pantry","4 corn cobs@Produce","2 limes@Produce","1/2 tsp chilli flakes@Pantry","smoked salt@Pantry","400g beef mince@Meat","8 beef franks@Meat","8 hot dog buns@Bakery","600g shoestring fries@Frozen","1 onion@Produce","2 garlic cloves@Produce","1 tbsp oil@Pantry","1 tbsp tomato paste@Pantry","1 tsp ground cumin@Pantry","1 tsp smoked paprika@Pantry","400g tinned tomatoes@Pantry","salt@Pantry","500ml vanilla ice cream@Frozen","8 large chewy chocolate cookies@Bakery","150g dark chocolate@Pantry","1 litre cola@Drinks","60ml cherry syrup@Drinks","ice@Frozen"]}},"Ghostbusters (1984)":{"poster":"assets/menu-posters/ghostbusters-1984.jpg","colour":"#bc2c28","servings":4,"tagline":"Firehouse night shift.","cue":"Serve the meatball subs when the team settles in at the firehouse.","menu":{"s":[{"n":"Slimer's slime dip","note":"green spinach and artichoke dip, corn chips for scooping","how":"Wilt 250g spinach in a dry pan, cool, squeeze very dry and chop with 150g drained marinated artichokes. Mix with 150g softened cream cheese, 100g sour cream, 75g grated mozzarella, 30g grated parmesan and 1 crushed garlic clove. Spoon into a small baking dish, top with 25g mozzarella and bake at 190°C for 20 minutes until bubbling. Serve hot with 200g corn chips for scooping.","shop":["250g spinach@Produce","150g marinated artichokes@Deli","150g cream cheese@Dairy","100g sour cream@Dairy","100g mozzarella@Dairy","30g parmesan@Dairy","1 garlic clove@Produce","200g corn chips@Pantry"]},{"n":"Dana's fridge devilled eggs","note":"yolks whipped with mayo and Dijon, tinted a little green, piped back in, guarded by Zuul","how":"Boil 6 eggs for 10 minutes, cool in iced water and peel. Halve them and scoop the yolks into a bowl. Whip the yolks with 3 tbsp mayonnaise, 1 tsp Dijon mustard, a pinch of salt and a drop of green food colouring until smooth. Pipe back into the whites and scatter over 2 tbsp snipped chives.","shop":["6 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","green food colouring@Pantry","salt@Pantry","1 bunch chives@Produce"]}],"m":[{"n":"Firehouse meatball sub","note":"long enough for the whole crew","how":"Mix 250g pork mince and 250g beef mince with 1 egg, 40g grated parmesan, 30g breadcrumbs, 1 crushed garlic clove, salt and pepper, and roll into 16 meatballs. Bake on a lined tray at 200°C for 15 minutes. Simmer 700ml passata with 1 tsp dried oregano, add the meatballs and simmer for 15 minutes. Split 4 long rolls, pack in the meatballs and sauce and lay 8 slices provolone on top. Grill for 2 to 3 minutes until the cheese has melted.","shop":["250g pork mince@Meat","250g beef mince@Meat","1 egg@Dairy","40g parmesan@Dairy","30g breadcrumbs@Pantry","1 garlic clove@Produce","pepper@Pantry","700ml passata@Pantry","1 tsp dried oregano@Pantry","4 long rolls@Bakery","8 slices provolone@Deli"]}],"w":[{"n":"Stay Puft s'mores","note":"giant marshmallows, toasted until they melt down","how":"Lay 8 digestive biscuits on a tray and put a square from 100g milk chocolate on each. Toast 8 large marshmallows over a flame until golden and melting, or sit one on each chocolate square and put the tray under a hot grill for 30 seconds. Press 8 more biscuits on top and eat straight away.","shop":["8 large marshmallows@Pantry","16 digestive biscuits@Pantry","100g milk chocolate@Pantry"]}],"d":[{"n":"Ectoplasm slushie","note":"lime, ice and very green","how":"Blitz 600g ice with 150ml lime cordial and 600ml chilled lemonade until slushy. Add a drop of green food colouring and blitz again. Pour into 4 glasses and add a slice from 1 lime to each.","shop":["600g ice@Frozen","150ml lime cordial@Drinks","600ml lemonade@Drinks","green food colouring@Pantry","1 lime@Produce"]}],"shopping":["250g spinach@Produce","150g marinated artichokes@Deli","150g cream cheese@Dairy","100g sour cream@Dairy","100g mozzarella@Dairy","70g parmesan@Dairy","2 garlic cloves@Produce","200g corn chips@Pantry","7 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","green food colouring@Pantry","salt@Pantry","1 bunch chives@Produce","250g pork mince@Meat","250g beef mince@Meat","30g breadcrumbs@Pantry","pepper@Pantry","700ml passata@Pantry","1 tsp dried oregano@Pantry","4 long rolls@Bakery","8 slices provolone@Deli","8 large marshmallows@Pantry","16 digestive biscuits@Pantry","100g milk chocolate@Pantry","600g ice@Frozen","150ml lime cordial@Drinks","600ml lemonade@Drinks","1 lime@Produce"]}},"The Godfather (1972)":{"poster":"assets/menu-posters/the-godfather-1972.jpg","colour":"#743525","servings":4,"tagline":"A Sunday at the Corleone table.","cue":"Set out the antipasto during Connie's wedding, then bring the Sunday sauce to the table.","menu":{"s":[{"n":"Connie's wedding antipasto","note":"salami, provolone, olives and roast peppers laid out like the garden party","how":"Arrange 100g sliced salami, 100g aged provolone, 100g olives and 150g drained roast capsicum on a platter. Drizzle the capsicum with olive oil and add a little cracked pepper. Serve at room temperature while the main simmers.","shop":["100g salami@Deli","100g aged provolone@Deli","100g olives@Deli","150g roast capsicum@Deli","olive oil@Pantry","black pepper@Pantry"]},{"n":"Golden arancini","note":"Crumbed risotto balls with a molten mozzarella centre, fried golden and served hot with a pinch of sea salt.","how":"Use 400g cold, thick cooked risotto. Divide into 8 portions and wrap each around a cube cut from 80g mozzarella. Roll into balls, dust with 40g flour, dip in 1 beaten egg and coat in 80g breadcrumbs. Chill 20 minutes. Fry in 170°C neutral oil in batches until golden and hot throughout, about 4 to 5 minutes; drain. Make the risotto the day before, cool promptly and refrigerate, or use 8 ready-made mozzarella arancini following the packet instructions.","shop":["400g cold cooked risotto or 8 ready-made arancini@Deli","80g mozzarella@Dairy","40g plain flour@Pantry","1 egg@Dairy","80g breadcrumbs@Pantry","neutral oil for frying@Pantry"]}],"m":[{"n":"Clemenza's Sunday sauce","note":"garlic, tomato, sausage and meatballs, taught to Michael in the hideout kitchen","how":"Mix 400g pork and beef mince with 1 egg, 40g breadcrumbs, 30g grated pecorino and a pinch of salt; form 12 meatballs. Brown in olive oil with 3 fennel sausages cut into chunks; set aside. Soften 1 diced onion, add 3 sliced garlic cloves and 2 tbsp tomato paste. Stir in 800g tinned tomatoes and 200ml water. Return meat, cover partly and simmer gently 60 to 90 minutes, stirring and adding water if needed. Check meatballs are cooked through. Boil 400g rigatoni, toss with sauce and serve with the meat and another 30g pecorino.","shop":["400g pork and beef mince@Meat","3 fennel sausages@Meat","1 egg@Dairy","40g breadcrumbs@Pantry","60g pecorino@Dairy","olive oil@Pantry","salt@Pantry","1 onion@Produce","3 garlic cloves@Produce","2 tbsp tomato paste@Pantry","800g tinned tomatoes@Pantry","400g rigatoni@Pantry"]}],"w":[{"n":"Clemenza's cannoli","note":"the pastry box Clemenza makes sure gets home, whatever else happens","how":"Drain 250g ricotta in a lined sieve in the fridge for at least 2 hours. Beat with 40g icing sugar and zest of 1 orange; fold in 30g finely chopped dark chocolate. Pipe into 8 small bought cannoli shells just before serving. Dip ends into 30g crushed pistachios and dust lightly with icing sugar.","shop":["250g ricotta@Dairy","40g icing sugar@Pantry","1 orange@Produce","30g dark chocolate@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Blood orange Italian soda","note":"Blood orange syrup, sparkling water and a fresh orange twist.","how":"Fill 4 glasses with ice. Add 25ml blood orange syrup to each and top each with 200ml sparkling water. Stir gently and finish with a thin twist from 1 orange. Adjust syrup to taste.","shop":["100ml blood orange syrup@Drinks","800ml sparkling water@Drinks","1 orange@Produce","ice@Frozen"]}],"shopping":["100g salami@Deli","100g aged provolone@Deli","100g olives@Deli","150g roast capsicum@Deli","olive oil@Pantry","black pepper@Pantry","400g cold cooked risotto or 8 ready-made arancini@Deli","80g mozzarella@Dairy","40g plain flour@Pantry","2 eggs@Dairy","120g breadcrumbs@Pantry","neutral oil for frying@Pantry","400g pork and beef mince@Meat","3 fennel sausages@Meat","60g pecorino@Dairy","salt@Pantry","1 onion@Produce","3 garlic cloves@Produce","2 tbsp tomato paste@Pantry","800g tinned tomatoes@Pantry","400g rigatoni@Pantry","250g ricotta@Dairy","40g icing sugar@Pantry","2 oranges@Produce","30g dark chocolate@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry","100ml blood orange syrup@Drinks","800ml sparkling water@Drinks","ice@Frozen"]}},"The Thing (1982)":{"poster":"assets/menu-posters/the-thing-1982.jpg","colour":"#163b5c","servings":4,"tagline":"Trust no one. Not even the dip.","cue":"Serve the snacks when the husky runs into camp.","menu":{"s":[{"n":"Outpost 31 rec room nachos","note":"Corn chips baked with black beans, cheddar and jalapeños","how":"Spread 300g corn chips over a large oven tray. Scatter over a 400g tin of drained black beans, 200g grated cheddar and 2 sliced jalapeños. Bake at 200C for 8 minutes until the cheese melts. Top with 150g sour cream and 150g salsa and serve straight from the tray.","shop":["300g corn chips@Pantry","400g black beans@Pantry","200g cheddar@Dairy","2 jalapeños@Produce","150g sour cream@Dairy","150g salsa@Pantry"]},{"n":"Hot buttered toast","note":"Thick white toast spread with salted butter right to the crusts","how":"Toast 8 slices thick white bread until deep golden. Spread each straight away with salted butter right to the crusts, about 80g in total, so it melts in. Cut into soldiers and pile on a warm plate.","shop":["8 slices thick white bread@Bakery","80g salted butter@Dairy"]}],"m":[{"n":"Antarctic base chilli","note":"Slow cooked beef chuck chilli with chipotle and cumin","how":"Cut 1kg beef chuck into chunks and brown in batches. Soften 2 diced brown onions and 3 garlic cloves, add 2 tbsp chipotle in adobo, 2 tsp ground cumin, 800g crushed tomatoes, a 400g tin kidney beans and the beef. Cover and braise at 160C for 2.5 hours. Bake a 350g cornbread mix as the packet says and serve alongside.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 garlic cloves@Produce","2 tbsp chipotle in adobo@Pantry","2 tsp ground cumin@Pantry","800g crushed tomatoes@Pantry","400g kidney beans@Pantry","350g cornbread mix@Pantry"]}],"w":[{"n":"Petri dish jelly","note":"Wobbly set raspberry jelly","how":"Soak 5 gelatine leaves in cold water for 5 minutes. Blitz 300g raspberries with 100g caster sugar and 300ml water, warm until steaming and strain. Squeeze the gelatine dry and stir into the hot purée with the juice of half a lemon. Pour into four shallow glass dishes and set in the fridge for 4 hours. Top with 125g fresh raspberries.","shop":["5 gelatine leaves@Pantry","425g raspberries@Produce","100g caster sugar@Pantry","1 lemon@Produce"]}],"d":[{"n":"MacReady's Rob Roy","note":"Blended Scotch, sweet vermouth and bitters stirred cold","how":"Chill 4 coupe or rocks glasses. For each drink, stir 60ml blended Scotch, 25ml sweet red vermouth and 2 dashes aromatic bitters with plenty of ice in a jug for 20 seconds. Strain into the glasses and drop in a cocktail cherry. Totals are 240ml Scotch, 100ml vermouth and 4 cherries. Serve over one big ice block for anyone who likes it on the rocks.","shop":["240ml blended Scotch@Bottle shop","100ml sweet red vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}],"shopping":["300g corn chips@Pantry","400g black beans@Pantry","200g cheddar@Dairy","2 jalapeños@Produce","150g sour cream@Dairy","150g salsa@Pantry","8 slices thick white bread@Bakery","80g salted butter@Dairy","1kg beef chuck@Meat","2 brown onions@Produce","3 garlic cloves@Produce","2 tbsp chipotle in adobo@Pantry","2 tsp ground cumin@Pantry","800g crushed tomatoes@Pantry","400g kidney beans@Pantry","350g cornbread mix@Pantry","5 gelatine leaves@Pantry","425g raspberries@Produce","100g caster sugar@Pantry","1 lemon@Produce","240ml blended Scotch@Bottle shop","100ml sweet red vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}},"A Nightmare on Elm Street (1984)":{"poster":"assets/menu-posters/a-nightmare-on-elm-street-1984.jpg","colour":"#8c1e22","servings":4,"tagline":"Keep your eyes open. Dessert is worth staying up for.","cue":"Serve the coffee when Nancy tries to stay awake.","menu":{"s":[{"n":"Elm Street chips and dip","note":"Sour cream and cream cheese dip blended with parsley, chives and garlic","how":"Blitz 200g sour cream, 100g cream cheese, 1 garlic clove, the juice of half a lemon, a big handful of parsley and a bunch of chives until green and smooth. Season with salt and chill 30 minutes. Serve with 300g kettle chips.","shop":["200g sour cream@Dairy","100g cream cheese@Dairy","1 garlic clove@Produce","1 lemon@Produce","1 bunch parsley@Produce","1 bunch chives@Produce","300g kettle chips@Pantry"]},{"n":"Five finger pretzels","note":"rods with tips dipped in dark chocolate, set in fives on baking paper with flaky salt","how":"Melt 150g dark chocolate in short bursts. Dip the tips of 20 pretzel rods, lay them on baking paper in groups of five like fingers and sprinkle each tip with a pinch of sea salt flakes. Leave 20 minutes to set.","shop":["150g dark chocolate@Pantry","20 pretzel rods@Pantry","1 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Stay-awake chilli","note":"Slow cooked beef chuck chilli with chipotle, cumin and cocoa","how":"Brown 1kg diced beef chuck in batches. Soften 2 diced brown onions and 3 garlic cloves, add 2 tbsp chipotle in adobo, 2 tsp cumin, 1 tbsp cocoa, 800g crushed tomatoes, a 400g tin kidney beans and the beef. Cover and braise at 160C for 3 hours until thick. Serve topped with 150g sour cream and 100g grated cheddar.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 garlic cloves@Produce","2 tbsp chipotle in adobo@Pantry","2 tsp ground cumin@Pantry","1 tbsp cocoa@Pantry","800g crushed tomatoes@Pantry","400g kidney beans@Pantry","150g sour cream@Dairy","100g cheddar@Dairy"]}],"w":[{"n":"Red and green swirl cupcakes","note":"Freddy's sweater, in buttercream","how":"Beat 125g soft butter with 150g caster sugar, add 2 eggs, then fold in 200g self-raising flour and 100ml milk. Spoon into 12 cases and bake at 175C for 18 minutes. Beat 150g butter with 300g icing sugar, split in two and colour one red and one green. Spoon both side by side into one piping bag and pipe swirls.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","100ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle red food colouring@Pantry","1 bottle green food colouring@Pantry"]}],"d":[{"n":"Strong black coffee","note":"plunger brew, 60g ground beans to a litre, steeped four minutes, served in big mugs","how":"Put 60g ground coffee in a large plunger, pour over 1 litre of just-off-the-boil water and steep 4 minutes. Plunge and pour into four big mugs. Serve black, with 100ml milk on the side for anyone who isn't trying to stay awake.","shop":["60g ground coffee@Pantry","100ml full cream milk@Dairy"]}],"shopping":["350g sour cream@Dairy","100g cream cheese@Dairy","1 garlic clove@Produce","1 lemon@Produce","1 bunch parsley@Produce","1 bunch chives@Produce","300g kettle chips@Pantry","150g dark chocolate@Pantry","20 pretzel rods@Pantry","1 tsp sea salt flakes@Pantry","1kg beef chuck@Meat","2 brown onions@Produce","3 garlic cloves@Produce","2 tbsp chipotle in adobo@Pantry","2 tsp ground cumin@Pantry","1 tbsp cocoa@Pantry","800g crushed tomatoes@Pantry","400g kidney beans@Pantry","100g cheddar@Dairy","275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","200ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle red food colouring@Pantry","1 bottle green food colouring@Pantry","60g ground coffee@Pantry"]}},"Shaun of the Dead (2004)":{"poster":"assets/menu-posters/shaun-of-the-dead-2004.jpg","colour":"#982a25","servings":4,"tagline":"One pub. One very bad day. Plenty of crisps.","cue":"Serve the drinks when they make it to the Winchester.","menu":{"s":[{"n":"Winchester pub nuts","note":"Peanuts roasted in a smoked paprika coating","how":"Whisk 1 egg white until frothy, then stir in 2 tsp smoked paprika, 1 tsp salt and 1 tbsp caster sugar. Toss through 300g peanuts, spread on a lined tray and roast at 160C for 15 minutes, stirring once, until crisp. Cool and serve in small bowls.","shop":["1 egg@Dairy","2 tsp smoked paprika@Pantry","1 tbsp caster sugar@Pantry","300g peanuts@Pantry"]},{"n":"Corner shop crisps","note":"Thin homemade crisps with salt and malt vinegar.","how":"Slice 600g potatoes paper thin on a mandoline, rinse well and dry completely. Fry at 170C in small batches for 3 to 4 minutes until golden and crisp. Drain, sprinkle with sea salt flakes and splash with 2 tbsp malt vinegar.","shop":["600g potatoes@Produce","1.5L vegetable oil@Pantry","1 tsp sea salt flakes@Pantry","2 tbsp malt vinegar@Pantry"]}],"m":[{"n":"Pub pie and chips","note":"Beef and ale pie with a puff pastry lid, chips and crushed peas","how":"Brown 1kg diced beef chuck, then soften 2 sliced brown onions. Add 330ml English ale, 300ml beef stock and 2 tbsp flour stirred in first, cover and braise at 160C for 2.5 hours. Cool slightly, tip into a pie dish, cover with 1 sheet puff pastry and bake at 200C for 25 minutes. Serve with 1kg chips and 400g frozen peas cooked and crushed.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","330ml English ale@Bottle shop","300ml beef stock@Pantry","2 tbsp plain flour@Pantry","1 sheet puff pastry@Frozen","1kg potatoes@Produce","400g frozen peas@Frozen","1.5L vegetable oil@Pantry"]}],"w":[{"n":"Sticky toffee pudding","note":"Date sponge with warm toffee sauce and cream","how":"Soak 200g chopped dates in 250ml boiling water with 1 tsp bicarb soda for 10 minutes. Beat 80g butter with 150g brown sugar, add 2 eggs, fold in 180g self-raising flour and the dates. Bake in a greased dish at 180C for 30 minutes. Simmer 100g butter, 150g brown sugar and 200ml cream for 3 minutes and pour over. Serve with cream.","shop":["200g dates@Pantry","1 tsp bicarb soda@Pantry","180g butter@Dairy","300g brown sugar@Pantry","2 eggs@Dairy","180g self-raising flour@Pantry","300ml thickened cream@Dairy"]}],"d":[{"n":"Pint at the Winchester","note":"English ale or lager poured into pint glasses for a toast.","how":"Chill four 500ml cans or bottles of English ale, or lager for anyone who prefers it. Pour into pint glasses at a tilt so the head settles, and raise them to the Winchester.","shop":["1L English ale@Bottle shop","1L lager@Bottle shop"]}],"shopping":["3 eggs@Dairy","2 tsp smoked paprika@Pantry","1 tbsp caster sugar@Pantry","300g peanuts@Pantry","1.6kg potatoes@Produce","3L vegetable oil@Pantry","1 tsp sea salt flakes@Pantry","2 tbsp malt vinegar@Pantry","1kg beef chuck@Meat","2 brown onions@Produce","1.33L English ale@Bottle shop","300ml beef stock@Pantry","2 tbsp plain flour@Pantry","1 sheet puff pastry@Frozen","400g frozen peas@Frozen","200g dates@Pantry","1 tsp bicarb soda@Pantry","180g butter@Dairy","300g brown sugar@Pantry","180g self-raising flour@Pantry","300ml thickened cream@Dairy","1L lager@Bottle shop"]}},"Young Frankenstein (1974)":{"poster":"assets/menu-posters/young-frankenstein-1974.jpg","colour":"#493528","servings":4,"tagline":"A castle, a lab and a very long dinner table.","cue":"Serve the goulash when Frederick and Igor first reach the castle.","menu":{"s":[{"n":"Castle cheese and crackers","note":"Cheddar, gouda and Swiss with rye crispbread, pickles and grainy mustard","how":"Cut 120g vintage cheddar, 120g gouda and 120g Swiss cheese into rough chunks on a dark wooden board. Add 1 pack rye crispbread, a jar of pickled onions and a pot of grainy mustard. Leave out 20 minutes before serving so the cheese softens.","shop":["120g vintage cheddar@Dairy","120g gouda@Deli","120g Swiss cheese@Deli","1 pack rye crispbread@Pantry","1 jar pickled onions@Pantry"]},{"n":"Abby Normal's brain dip","note":"Roasted beetroot, chickpea and tahini dip with crackers","how":"Wrap 2 beetroots in foil and roast at 200C for 1 hour, then peel. Blitz with a drained 400g tin chickpeas, 3 tbsp tahini, the juice of 1 lemon, 1 garlic clove and 3 tbsp water until smooth. Swirl into a bowl and serve with 150g crackers.","shop":["2 beetroots@Produce","400g chickpeas@Pantry","3 tbsp tahini@Pantry","1 lemon@Produce","1 garlic clove@Produce","150g crackers@Pantry"]}],"m":[{"n":"Transylvanian goulash","note":"Beef and paprika goulash over buttered noodles with sour cream","how":"Brown 1kg diced beef chuck in batches. Cook 3 sliced brown onions slowly for 20 minutes, stir in 2 tbsp sweet paprika and 1 tsp caraway seeds, then add 400g crushed tomatoes, 300ml beef stock and the beef. Cover and braise at 160C for 3 hours. Serve over 400g buttered egg noodles with 150g sour cream.","shop":["1kg beef chuck@Meat","3 brown onions@Produce","2 tbsp sweet paprika@Pantry","1 tsp caraway seeds@Pantry","400g crushed tomatoes@Pantry","300ml beef stock@Pantry","400g egg noodles@Pantry","20g butter@Dairy","150g sour cream@Dairy"]}],"w":[{"n":"Puttin' on the Ritz cupcakes","note":"Chocolate cupcakes with chocolate swirls and white chocolate brim hats","how":"Beat 125g butter with 150g caster sugar, add 2 eggs, then fold in 170g self-raising flour, 30g cocoa and 100ml milk. Bake in 12 cases at 175C for 18 minutes and cool. Beat 150g butter, 250g icing sugar and 30g cocoa and pipe a tall swirl on each. Melt 100g white chocolate into 12 thin discs, set, and sit one under each swirl as a hat brim.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","170g self-raising flour@Pantry","60g cocoa@Pantry","100ml full cream milk@Dairy","250g icing sugar@Pantry","100g white chocolate@Pantry"]}],"d":[{"n":"Frau Blücher's brandy milk punch","note":"Warm honey vanilla milk with cinnamon and brandy, nutmeg on top","how":"Warm 800ml full cream milk with 3 tbsp honey, 1 cinnamon stick and half a tsp vanilla extract until steaming, without boiling. Rest 5 minutes and remove the cinnamon. Whisk hard until frothy. Pour into 4 mugs, add 30ml brandy to each and grate over a little nutmeg. Leave out the brandy for the warm milk crowd.","shop":["800ml full cream milk@Dairy","3 tbsp honey@Pantry","1 packet cinnamon sticks@Pantry","1 bottle vanilla extract@Pantry","120ml brandy@Bottle shop","1 whole nutmeg@Pantry"]}],"shopping":["120g vintage cheddar@Dairy","120g gouda@Deli","120g Swiss cheese@Deli","1 pack rye crispbread@Pantry","1 jar pickled onions@Pantry","2 beetroots@Produce","400g chickpeas@Pantry","3 tbsp tahini@Pantry","1 lemon@Produce","1 garlic clove@Produce","150g crackers@Pantry","1kg beef chuck@Meat","3 brown onions@Produce","2 tbsp sweet paprika@Pantry","1 tsp caraway seeds@Pantry","400g crushed tomatoes@Pantry","300ml beef stock@Pantry","400g egg noodles@Pantry","295g butter@Dairy","150g sour cream@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","170g self-raising flour@Pantry","60g cocoa@Pantry","900ml full cream milk@Dairy","250g icing sugar@Pantry","100g white chocolate@Pantry","3 tbsp honey@Pantry","1 packet cinnamon sticks@Pantry","1 bottle vanilla extract@Pantry","120ml brandy@Bottle shop","1 whole nutmeg@Pantry"]}},"Mad Max 2 (1981)":{"poster":"assets/menu-posters/mad-max-2-1981.jpg","colour":"#a35225","servings":4,"tagline":"Guzzoline not included.","cue":"Serve the snacks when Max eats his tinned dinner.","menu":{"s":[{"n":"Wasteland tin dinner","note":"Corned beef hash and a fried egg, in a tin.","how":"Dice 400g potatoes and boil 6 minutes, then drain. Fry 1 diced brown onion in 30g butter, add the potato and 340g corned beef broken up, press flat and fry without stirring until crusty, then turn and repeat. Fry 4 eggs. Serve the hash in clean empty tins with an egg on top.","shop":["400g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","340g corned beef@Deli","4 eggs@Dairy"]},{"n":"Gyro Captain's frankfurt pastry snake","note":"frankfurts coiled in sesame puff with peppercorn eyes and two dips, this one doesn't bite","how":"Heat the oven to 200°C and line a large tray. Cut each pastry sheet into 3 strips. Lay the frankfurts end to end along the strips, roll the pastry around them and pinch the joins so they make one long roll. Coil the roll on the tray like a snake. Shape a head at one end and press in the peppercorns for eyes. Brush with egg, scatter with sesame seeds and bake for 25 minutes until puffed and golden. Serve on a board with the barbecue sauce and mustard to dip.","shop":["8 frankfurts@Deli","3 sheets frozen puff pastry@Frozen","1 egg@Dairy","2 tbsp sesame seeds@Pantry","2 black peppercorns@Spices","125ml barbecue sauce@Pantry","125ml American mustard@Pantry"]}],"m":[{"n":"Compound barbecue","note":"Pulled lamb with flatbread.","how":"Rub a 2kg lamb shoulder with 4 crushed garlic cloves, 2 tbsp chopped rosemary, 2 tsp smoked paprika and 2 tsp salt. Roast covered at 150C for 5 hours until it pulls apart. Serve with 8 warm flatbreads, 250g Greek yoghurt and a salad of 4 chopped tomatoes with red onion.","shop":["2kg lamb shoulder@Meat","4 garlic cloves@Produce","1 bunch rosemary@Produce","2 tsp smoked paprika@Pantry","8 flatbreads@Bakery","250g Greek yoghurt@Dairy","4 tomatoes@Produce","1 red onion@Produce"]}],"w":[{"n":"Wasteland golden syrup dumplings","note":"Soft dumplings simmered in golden syrup sauce, served with cream","how":"Rub 40g butter into 250g self-raising flour, mix in 150ml milk to a soft dough and roll into 12 balls. Bring 250ml water, 100g golden syrup, 100g brown sugar and 40g butter to a simmer in a wide pan. Drop in the dumplings, cover and cook 20 minutes without lifting the lid. Serve with 200ml cream.","shop":["80g butter@Dairy","250g self-raising flour@Pantry","150ml full cream milk@Dairy","100g golden syrup@Pantry","100g brown sugar@Pantry","200ml thickened cream@Dairy"]}],"d":[{"n":"Guzzoline dark and stormy","note":"Dark rum floated over ginger beer and lime","how":"Fill 4 tall glasses with ice. Squeeze 15ml lime juice into each and add 150ml cold ginger beer. Pour 45ml dark rum slowly over the back of a spoon so it floats dark on top. Add a lime wedge and serve unstirred. Totals are 180ml dark rum, 600ml ginger beer and 2 limes. Skip the rum for a plain ginger beer and lime.","shop":["180ml dark rum@Bottle shop","600ml ginger beer@Drinks","2 limes@Produce","1 bag ice@Frozen"]}],"shopping":["400g potatoes@Produce","1 brown onion@Produce","310g butter@Dairy","340g corned beef@Deli","4 eggs@Dairy","100g icing sugar@Pantry","300g plain flour@Pantry","100g dark chocolate@Pantry","2kg lamb shoulder@Meat","4 garlic cloves@Produce","1 bunch rosemary@Produce","2 tsp smoked paprika@Pantry","8 flatbreads@Bakery","250g Greek yoghurt@Dairy","4 tomatoes@Produce","1 red onion@Produce","250g self-raising flour@Pantry","150ml full cream milk@Dairy","100g golden syrup@Pantry","100g brown sugar@Pantry","200ml thickened cream@Dairy","180ml dark rum@Bottle shop","600ml ginger beer@Drinks","2 limes@Produce","1 bag ice@Frozen"]}},"Night of the Living Dead (1968)":{"poster":"assets/menu-posters/night-of-the-living-dead-1968.jpg","colour":"#343434","servings":4,"tagline":"Board up the windows. Bring the snacks.","cue":"Serve the snacks when everyone boards up the windows.","menu":{"s":[{"n":"Barbra's cemetery sandwiches","note":"egg and cress, ham and mustard on white, crusts off, they're coming to get you","how":"Boil 2 eggs for 10 minutes, cool, peel and mash with 20g mayonnaise. Stir in 10g chopped cress. Butter 8 slices white bread with 25g softened butter. Use four slices to make two egg-and-cress sandwiches. Use the other four for two sandwiches with 80g leg ham and 10g Dijon mustard. Trim the crusts and cut each sandwich into four small pieces. Wrap in baking paper for a 1968-style picnic and serve four pieces each.","shop":["2 eggs@Dairy","20g mayonnaise@Pantry","10g cress@Produce","8 slices white bread@Bakery","25g butter@Dairy","80g leg ham@Deli","10g Dijon mustard@Pantry"]},{"n":"Black and white popcorn","note":"black and white like the film stock. The blood on set was chocolate syrup","how":"Pop 60g popcorn kernels in 1 tbsp neutral oil in a covered pot over medium heat for 3 to 4 minutes, shaking regularly. Divide equally. Toss one half with 15g melted butter and 1/4 tsp fine salt. Toss the other with 15g melted butter, 1/4 tsp cracked black pepper and 10g black sesame seeds. Arrange side by side in a shared bowl.","shop":["60g popcorn kernels@Pantry","1 tbsp neutral oil@Pantry","30g butter@Dairy","fine salt@Pantry","black pepper@Pantry","10g black sesame seeds@Pantry"]}],"m":[{"n":"Cellar or upstairs farmhouse stew","note":"beef chuck browned and braised slow with onion, carrot, potato, stock and thyme","how":"Cut 800g beef chuck into chunks and season with 1/2 tsp salt and 1/4 tsp black pepper. Brown in 1 tbsp neutral oil in a heavy casserole for 8 minutes, in batches. Add 1 chopped brown onion, 2 chopped carrots, 500g potato chunks, 500ml beef stock and 4 thyme sprigs. Cover and braise at 160°C conventional for 2.5 hours, stirring once, until the beef is tender. Serve with 200g crusty Italian bread for soaking up the stock.","shop":["800g beef chuck@Meat","salt@Pantry","black pepper@Pantry","1 tbsp neutral oil@Pantry","1 brown onion@Produce","2 carrots@Produce","500g potatoes@Produce","500ml beef stock@Pantry","4 thyme sprigs@Produce","200g crusty Italian bread@Bakery"]}],"w":[{"n":"Pantry peach cobbler with cream","note":"tinned peaches under a cinnamon scone top. Nobody goes down to the cellar for cream","how":"Drain 2 x 825g tins peach halves, keeping 100ml syrup. Toss the peaches with the syrup and 1 tbsp cornflour in a baking dish. Rub 80g cold butter into 200g self-raising flour, 60g caster sugar and 1 tsp cinnamon, then mix in 120ml milk to a soft dough. Drop spoonfuls over the peaches, sprinkle with raw sugar and bake at 190C for 30 minutes until golden. Serve warm with 300ml pouring cream.","shop":["2 x 825g tins peach halves@Pantry","1 box cornflour@Pantry","80g butter@Dairy","200g self-raising flour@Pantry","60g caster sugar@Pantry","1 jar ground cinnamon@Pantry","120ml milk@Dairy","1 bag raw sugar@Pantry","300ml pouring cream@Dairy"]}],"d":[{"n":"Long night spiked percolator coffee","note":"strong stovetop brew with brown sugar and Irish whiskey, lightly whipped cream floated on top","how":"Brew 800ml strong coffee in a stovetop pot or plunger. Warm 4 heatproof glasses with hot water and tip it out. Put 2 tsp brown sugar and 30ml Irish whiskey in each glass, pour in 200ml hot coffee and stir to dissolve. Whip 150ml thickened cream until just thick enough to pour, then float it over the back of a spoon. Skip the whiskey for anyone who wants it plain.","shop":["800ml brewed coffee@Pantry","1 bag brown sugar@Pantry","120ml Irish whiskey@Bottle shop","150ml thickened cream@Dairy"]}],"shopping":["2 eggs@Dairy","20g mayonnaise@Pantry","10g cress@Produce","8 slices white breads@Bakery","135g butter@Dairy","80g leg ham@Deli","10g Dijon mustard@Pantry","60g popcorn kernels@Pantry","2 tbsp neutral oil@Pantry","fine salt@Pantry","black pepper@Pantry","10g black sesame seeds@Pantry","800g beef chuck@Meat","salt@Pantry","1 brown onion@Produce","2 carrots@Produce","500g potatoes@Produce","500ml beef stock@Pantry","4 thyme sprigs@Produce","200g crusty Italian bread@Bakery","2 x 825g tins peach halves@Pantry","1 box cornflour@Pantry","200g self-raising flour@Pantry","60g caster sugar@Pantry","1 jar ground cinnamon@Pantry","120ml milk@Dairy","1 bag raw sugar@Pantry","300ml pouring cream@Dairy","800ml brewed coffee@Pantry","1 bag brown sugar@Pantry","120ml Irish whiskey@Bottle shop","150ml thickened cream@Dairy"]}},"The Big Lebowski (1998)":{"poster":"assets/menu-posters/the-big-lebowski-1998.jpg","colour":"#762a27","servings":4,"tagline":"League night at the lanes. White Russians at the bar.","cue":"Serve a White Russian every time the Dude makes one.","menu":{"s":[{"n":"Persian rug flatbread","note":"the rug that really tied the room together","how":"Charred yoghurt flatbread striped with za'atar, sumac and nigella, whipped feta, pomegranate, mint and dill. For 4: 300g self-raising flour, 350g Greek yoghurt, 1 tsp salt, 200g feta, 1 lemon, 4 tbsp olive oil, 2 tbsp za'atar, 2 tsp sumac, 2 tsp nigella seeds, 80g pomegranate seeds, 1 small bunch mint, 1 small bunch dill. Mix the flour, 250g of the yoghurt and the salt into a soft dough, knead for 1 minute, then rest 10 minutes. Whip the feta with the remaining 100g yoghurt, the lemon zest and juice and 2 tbsp of the olive oil until smooth. Divide the dough into 4 and roll each piece into a thin rectangle about 25cm long. Cook each flatbread in a hot dry frying pan for 2 minutes a side, until puffed and charred in spots. Brush with the rest of the olive oil and sprinkle the za'atar, sumac and nigella seeds in stripes across each one, like a rug. Spread the whipped feta on a platter, lay the flatbreads alongside and scatter with the pomegranate, mint and dill.","shop":["300g self-raising flour@Pantry","350g Greek yoghurt@Dairy","1 tsp salt@Pantry","200g feta@Dairy","1 lemon@Produce","4 tbsp olive oil@Pantry","2 tbsp za'atar@Pantry","2 tsp sumac@Pantry","2 tsp nigella seeds@Pantry","80g pomegranate seeds@Produce","1 small bunch mint@Produce","1 small bunch dill@Produce"]},{"n":"Jesus Quintana's chorizo taquitos","note":"nobody messes with the Jesus","how":"Corn tortillas rolled round chorizo, potato and cheddar, fried crisp, with purple pickled onion, lime crema and salsa verde. For 4: 1 red onion, thinly sliced, 80ml red wine vinegar, 1 tsp sugar, 1 tsp salt, 400g potatoes, peeled and diced, 250g fresh chorizo sausages, skins removed, 1 tsp ground cumin, 100g cheddar, grated, 16 small corn tortillas, neutral oil, for shallow frying, 150g sour cream, 1 lime, 150g salsa verde, 1 small bunch coriander. Toss the onion with the vinegar, sugar and half the salt and leave it to turn purple while you cook. Boil the potatoes in water with the rest of the salt for 10 minutes until tender, then drain. Fry the chorizo, broken up, in a dry pan for 6 minutes, add the cumin and potatoes and crush together, then stir in the cheddar. Warm the tortillas in the microwave under a damp tea towel for 1 minute so they roll without cracking. Spoon the filling along each tortilla, roll tightly and hold with a toothpick. Shallow fry the taquitos in 1cm of hot oil, seam side down first, for 3 to 4 minutes, turning, until crisp. Drain on paper towel. Mix the sour cream with the lime zest and juice. Serve the taquitos with the lime crema, salsa verde, pickled onion and coriander.","shop":["1 red onion@Produce","80ml red wine vinegar@Pantry","1 tsp sugar@Pantry","1 tsp salt@Pantry","400g potatoes@Produce","250g fresh chorizo sausages@Meat","1 tsp ground cumin@Pantry","100g cheddar@Dairy","16 small corn tortillas@Bakery","neutral oil@Pantry","150g sour cream@Dairy","1 lime@Produce","150g salsa verde@Pantry","1 small bunch coriander@Produce"]}],"m":[{"n":"In-N-Out double-double, animal style","note":"those are good burgers, Walter","how":"Two smashed beef patties seared in mustard, American cheese, slow-cooked onion, pickles and spread on a toasted bun. Fries on the side. For 4: 700g potatoes, neutral oil, for frying, 1 tsp salt, 640g beef mince, 20% fat, 2 onions, finely diced, 20g butter, 80g mayonnaise, 2 tbsp tomato sauce, 1 tbsp sweet pickle relish, 2 tbsp American mustard, 8 slices American cheese, 4 burger buns, 4 iceberg lettuce leaves, 1 tomato, sliced, 80g dill pickles, sliced. Cut the potatoes into thin fries, rinse well and pat completely dry. Fry the fries in the oil at 150C for 5 minutes, then drain and cool for 15 minutes. Cook the onions in the butter over low heat for 15 minutes, stirring, until soft and golden. Mix the mayonnaise, tomato sauce and relish for the spread. Roll the mince into 8 balls. Smash each one thin on a very hot griddle, season and brush the top with mustard. Cook 2 minutes, flip mustard side down, add a slice of cheese and cook 1 minute more. Fry the fries again at 190C for 3 minutes until crisp and toss with the salt. Toast the buns cut side down. Build each with spread, lettuce, tomato, a patty, onions, pickles, a second patty and more spread. Serve with the fries.","shop":["700g potatoes@Produce","neutral oil@Pantry","1 tsp salt@Pantry","640g beef mince@Meat","2 onions@Produce","20g butter@Dairy","80g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tbsp sweet pickle relish@Pantry","2 tbsp American mustard@Pantry","8 slices American cheese@Dairy","4 burger buns@Bakery","4 iceberg lettuce leaves@Produce","1 tomato@Produce","80g dill pickles@Pantry"]}],"w":[{"n":"Nihilist lingonberry Dutch baby","note":"the nihilists' order at the coffee shop","how":"A puffed oven pancake with lingonberry jam, whipped crème fraîche, lemon and icing sugar. For 4: 4 eggs, 160ml milk, 100g plain flour, 1 tbsp caster sugar, half a tsp salt, 1 tsp vanilla extract, 40g butter, 200g lingonberry jam, 200g crème fraîche, 1 lemon, 1 tbsp icing sugar. Heat the oven to 220C (200C fan) with a 26cm cast-iron or ovenproof frying pan inside. Blend the eggs, milk, flour, caster sugar, salt and vanilla until smooth. Add the butter to the hot pan, swirl until it foams, pour in the batter and bake for 18 to 20 minutes until puffed high and golden. Keep the oven door shut. Whip the crème fraîche with the lemon zest until it just holds its shape. Take it to the table straight away. Spoon over the lingonberry jam and crème fraîche, squeeze over a little lemon juice and dust with the icing sugar.","shop":["4 eggs@Dairy","160ml milk@Dairy","100g plain flour@Pantry","1 tbsp caster sugar@Pantry","0.5 tsp salt@Pantry","1 tsp vanilla extract@Pantry","40g butter@Dairy","200g lingonberry jam@Pantry","200g crème fraîche@Dairy","1 lemon@Produce","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"White Russian","note":"the Dude's Caucasian, careful, man","how":"Vodka and coffee liqueur over ice, topped with half-and-half and stirred lazily. For 4: 400g ice, 180ml vodka, 80ml coffee liqueur, 60ml thickened cream, 60ml full-cream milk. Fill four rocks glasses with the ice and pour 45ml vodka and 20ml coffee liqueur into each. Stir the cream and milk together for a half-and-half, float 30ml on each drink and stir lazily.","shop":["400g ice@Frozen","180ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop","60ml thickened cream@Dairy","60ml full-cream milk@Dairy"]}],"shopping":["250g fresh chorizo sausages@Meat","640g beef mince@Meat","2 lemons@Produce","80g pomegranate seeds@Produce","1 small bunch mint@Produce","1 small bunch dill@Produce","1 red onion@Produce","1.1kg potatoes@Produce","1 lime@Produce","1 small bunch coriander@Produce","2 onions@Produce","4 iceberg lettuce leaves@Produce","1 tomato@Produce","350g Greek yoghurt@Dairy","200g feta@Dairy","100g cheddar@Dairy","150g sour cream@Dairy","60g butter@Dairy","8 slices American cheese@Dairy","4 eggs@Dairy","160ml milk@Dairy","200g crème fraîche@Dairy","60ml thickened cream@Dairy","60ml full-cream milk@Dairy","16 small corn tortillas@Bakery","4 burger buns@Bakery","400g ice@Frozen","300g self-raising flour@Pantry","3.5 tsp salt@Pantry","4 tbsp olive oil@Pantry","2 tbsp za'atar@Pantry","2 tsp sumac@Pantry","2 tsp nigella seeds@Pantry","80ml red wine vinegar@Pantry","1 tsp sugar@Pantry","1 tsp ground cumin@Pantry","neutral oil@Pantry","150g salsa verde@Pantry","80g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tbsp sweet pickle relish@Pantry","2 tbsp American mustard@Pantry","80g dill pickles@Pantry","100g plain flour@Pantry","1 tbsp caster sugar@Pantry","1 tsp vanilla extract@Pantry","200g lingonberry jam@Pantry","1 tbsp icing sugar@Pantry","180ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop"]}},"Groundhog Day (1993)":{"poster":"assets/menu-posters/groundhog-day-1993.jpg","colour":"#2e4b64","servings":4,"tagline":"Same breakfast. Every day.","cue":"Serve the breakfast feast when Phil gorges at the diner.","menu":{"s":[{"n":"Ned Ryerson's eggs","note":"yolks, mayo, Dijon and hot sauce piped into whites, am I right or am I right","how":"Boil 4 eggs for 10 minutes, cool in iced water and peel. Halve and remove the yolks. Whip the yolks with 30g mayonnaise, 1 tsp Dijon mustard, 1/2 tsp hot sauce and 1/4 tsp smoked paprika until smooth. Pipe back into the eight white halves and refrigerate until serving.","shop":["4 eggs@Dairy","30g mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1/2 tsp hot sauce@Pantry","1/4 tsp smoked paprika@Pantry"]},{"n":"Tip Top Cafe silver dollar pancakes","note":"little buttermilk stacks with crisp bacon and whipped maple butter, same as yesterday","how":"Whisk the flour, sugar and a pinch of salt with the buttermilk, eggs and 40g melted butter. Rest 15 minutes. Beat 40g soft butter with the maple syrup. Fry the bacon until crisp and drain on paper. Cook tablespoons of batter in a little of the last butter over medium heat for 1 to 2 minutes a side. Stack the pancakes, top with a little maple butter and scatter with the bacon.","shop":["250g self-raising flour@Pantry","1 tbsp caster sugar@Pantry","375ml buttermilk@Dairy","2 eggs@Dairy","100g butter@Dairy","2 tbsp maple syrup@Pantry","150g bacon@Meat"]}],"m":[{"n":"Phil's diner feast","note":"pancakes, eggs, bacon, toast and pie, everything at once","how":"Mix 150g plain flour, 1 tsp baking powder, 15g caster sugar, 1 egg and 200ml buttermilk into a batter. Rest 15 minutes. Render 200g bacon slowly in a frying pan over medium heat for 10 minutes until crisp and keep warm. Cook eight small pancakes in 20g butter for about 2 minutes per side until bubbles set and both sides are golden. Fry 4 eggs in the bacon pan for 3 minutes, or until the whites are set. Toast 4 slices white bread and butter with 20g butter. Warm four small 50g slices ready-baked pie at 180°C for 10 minutes. Bring everything to the table at once, with 60ml maple syrup for the pancakes.","shop":["150g plain flour@Pantry","1 tsp baking powder@Pantry","15g caster sugar@Pantry","5 eggs@Dairy","200ml buttermilk@Dairy","200g bacon@Meat","40g butter@Dairy","4 slices white bread@Bakery","200g ready-baked pie@Bakery","60ml maple syrup@Pantry"]}],"w":[{"n":"Angel food cake","note":"airy sponge of whipped egg whites and sugar, cooled upside down, served with berries and cream","how":"Whisk 5 egg whites with 1/4 tsp cream of tartar to soft peaks. Gradually add 75g caster sugar and whisk until glossy. Sift 60g cake flour with 75g icing sugar, then gently fold into the whites in three additions. Spoon into an ungreased 16cm tube pan. Bake at 175°C conventional for 40 minutes until golden and springy. Invert the tin and cool upside down completely before loosening the cake. Cut into four portions and serve with 150g fresh berries and 80ml thickened cream softly whipped.","shop":["5 eggs, whites only@Dairy","1/4 tsp cream of tartar@Pantry","75g caster sugar@Pantry","60g cake flour@Pantry","75g icing sugar@Pantry","150g berries@Produce","80ml thickened cream@Dairy"]}],"d":[{"n":"Rita's sweet vermouth on the rocks","note":"Rita's order at the bar, the one Phil learns by heart","how":"Put one large ice block in each of 4 rocks glasses. Pour 75ml sweet red vermouth over each and add a dash of aromatic bitters. Peel 4 long strips of orange zest, twist each over the glass to release the oil, rub round the rim and drop in. Stir twice. Totals are 300ml vermouth and 1 orange. Raise a glass to world peace.","shop":["300ml sweet red vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["4 small cake doughnuts@Bakery","120g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","9 eggs@Dairy","30g mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1/2 tsp hot sauce@Pantry","1/4 tsp smoked paprika@Pantry","150g plain flour@Pantry","1 tsp baking powder@Pantry","200ml buttermilk@Dairy","200g bacon@Meat","40g butter@Dairy","4 slices white breads@Bakery","200g ready-baked pie@Bakery","60ml maple syrup@Pantry","5 eggs, whites only@Dairy","1/4 tsp cream of tartar@Pantry","60g cake flour@Pantry","75g icing sugar@Pantry","150g berries@Produce","80ml thickened cream@Dairy","300ml sweet red vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","1 bag ice@Frozen"]}},"Dumb and Dumber (1994)":{"poster":"assets/menu-posters/dumb-and-dumber-1994.jpg","colour":"#df681c","servings":4,"tagline":"Road trip to Aspen.","cue":"Serve the hot chilli burgers when Harry and Lloyd load Mental's burger with hot peppers.","menu":{"s":[{"n":"Mutt Cutts road snacks","note":"chips eaten in a van shaped like a dog","how":"Tip 60g potato chips, 60g cheese puffs and 60g dog-bone-shaped pretzels into a big shared bowl. Toss gently and share between four people for the road trip.","shop":["60g potato chips@Pantry","60g cheese puffs@Pantry","60g dog-bone-shaped pretzels@Pantry"]},{"n":"Truck stop onion rings","note":"Sea Bass's truck stop diner","how":"Slice 2 brown onions into thick rings and soak in 150ml buttermilk for 30 minutes. Whisk 120g plain flour with 150ml cold lager and 1/4 tsp salt. Drain the onions, dip in the batter and fry in small batches in neutral oil at 185°C for 3 to 4 minutes until puffed and golden. Drain and salt lightly.","shop":["2 brown onions@Produce","150ml buttermilk@Dairy","120g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry"]}],"m":[{"n":"Extra hot chilli burger","note":"spiked for Mental, mild for you","how":"Brown 200g beef mince with 1 diced onion in 1 tsp oil for 5 minutes. Add 1 tsp chilli powder, 1/2 tsp cumin, 200g chopped tinned tomatoes and 100ml water. Simmer 25 minutes until thick and season. Shape another 500g beef mince into four patties. Griddle over medium-high heat for about 4 minutes per side until cooked through, checking 75°C at the centre. Top with 80g cheddar to melt. Toast 4 burger buns and fill with patties, chilli and 40g pickled jalapeños. Put 40ml hot sauce on the table for anyone wanting the extra-hot version.","shop":["700g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","200g tinned tomatoes@Pantry","salt@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","40g pickled jalapeños@Pantry","40ml hot sauce@Pantry"]}],"w":[{"n":"Aspen snowflake cookies","note":"vanilla sugar biscuits in wintry shapes, iced white, silver cachous, for the trip to the Rockies","how":"Beat 80g softened butter with 60g caster sugar until pale. Beat in 1 egg yolk and 1/2 tsp vanilla extract, then mix in 130g plain flour. Chill 30 minutes. Roll 5mm thick and cut into 8 snowflakes. Bake at 180°C conventional for 8 minutes until pale gold at the edges. Cool completely. Mix 80g icing sugar with 2 to 3 tsp water to a spreadable white icing, coat the cookies and decorate with 10g edible silver cachous. Serve two each.","shop":["80g butter@Dairy","60g caster sugar@Pantry","1 egg, yolk only@Dairy","1/2 tsp vanilla extract@Pantry","130g plain flour@Pantry","80g icing sugar@Pantry","10g edible silver cachous@Pantry"]}],"d":[{"n":"Ski lodge hot chocolate","note":"dark couverture melted into hot milk, whisked frothy, marshmallows, after the chairlift stops","how":"Heat 600ml full cream milk until steaming, without boiling. Add 100g dark chocolate and whisk until melted and frothy. Divide among four mugs. Softly whip 80ml thickened cream, spoon on top and finish with 40g marshmallows.","shop":["600ml full cream milk@Dairy","100g dark chocolate@Pantry","80ml thickened cream@Dairy","40g marshmallows@Pantry"]}],"shopping":["60g potato chips@Pantry","60g cheese puffs@Pantry","60g dog-bone-shaped pretzels@Pantry","2 brown onions@Produce","150ml buttermilk@Dairy","250g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry","700g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","200g tinned tomatoes@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","40g pickled jalapeños@Pantry","40ml hot sauce@Pantry","80g butter@Dairy","60g caster sugar@Pantry","1 egg, yolk only@Dairy","1/2 tsp vanilla extract@Pantry","80g icing sugar@Pantry","10g edible silver cachous@Pantry","600ml full cream milk@Dairy","100g dark chocolate@Pantry","80ml thickened cream@Dairy","40g marshmallows@Pantry"]}},"Planes, Trains and Automobiles (1987)":{"poster":"assets/menu-posters/planes-trains-and-automobiles-1987.jpg","colour":"#85282c","servings":4,"tagline":"Three days to get home. Snacks for every leg.","cue":"Serve the snacks when Neal and Del wake up holding hands.","menu":{"s":[{"n":"Braidwood Inn vending machine mix","note":"salted peanuts, pretzels, chocolate bars and jerky tipped into a bowl, the motel snack haul","how":"Tip 60g salted peanuts, 60g pretzels, 60g chopped chocolate bars and 40g beef jerky into a shared bowl. Mix gently and divide between four people for the motel snack break.","shop":["60g salted peanuts@Pantry","60g pretzels@Pantry","60g chocolate bars@Pantry","40g beef jerky@Pantry"]},{"n":"Shower curtain ring onion rings","note":"thick onion slices soaked in buttermilk, dipped in beer batter and fried puffed and golden","how":"Slice 2 brown onions into thick rings and soak in 150ml buttermilk for 30 minutes. Whisk 120g plain flour, 150ml cold lager and 1/4 tsp salt into a batter. Drain the rings, dip in the batter and fry in small batches in neutral oil at 185°C for 3 to 4 minutes until puffed and golden. Drain and serve hot.","shop":["2 brown onions@Produce","150ml buttermilk@Dairy","120g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry"]}],"m":[{"n":"Thanksgiving turkey sliders","note":"brined roast breast in soft buns, cranberry, stuffing and gravy, worth the long trip home","how":"Dissolve 30g salt in 1 litre cold water. Submerge 700g turkey breast and refrigerate for 6 hours. Drain, pat dry and roast at 170°C conventional for about 50 to 60 minutes, until the centre reaches 70°C and stays at that temperature for 2 minutes. Rest 15 minutes and slice. Prepare 150g stuffing mix with the packet's water amount, spread in a small baking dish and bake beside the turkey for 25 minutes, then cut into 8 squares. Make gravy by melting 20g butter, stirring in 20g flour for 1 minute and whisking in 300ml chicken stock; simmer 5 minutes. Fill 8 soft slider buns with turkey, 80g cranberry sauce, stuffing squares and a spoonful of gravy. Serve two each.","shop":["700g turkey breast@Meat","30g salt@Pantry","150g stuffing mix@Pantry","20g butter@Dairy","20g plain flour@Pantry","300ml chicken stock@Pantry","8 soft slider buns@Bakery","80g cranberry sauce@Pantry"]}],"w":[{"n":"Thanksgiving pumpkin pie","note":"roast pumpkin purée with eggs, brown sugar, cream and warm spices in shortcrust, whipped cream","how":"Roast 450g peeled pumpkin at 200°C conventional for 30 minutes until soft, then purée and measure 300g. Line a 20cm pie dish with 250g sweet shortcrust pastry. Blind-bake with baking paper and weights at 180°C for 15 minutes, remove the weights and bake 5 minutes more. Whisk the pumpkin purée with 2 eggs, 80g brown sugar, 100ml thickened cream, 1/2 tsp cinnamon, 1/4 tsp ground ginger and 1/8 tsp nutmeg. Pour into the crust and bake at 170°C for 50 minutes until just set. Cool, then serve four portions with another 100ml cream softly whipped.","shop":["450g peeled pumpkin@Produce","250g sweet shortcrust pastry@Frozen","2 eggs@Dairy","80g brown sugar@Pantry","200ml thickened cream@Dairy","1/2 tsp cinnamon@Pantry","1/4 tsp ground ginger@Pantry","1/8 tsp nutmeg@Pantry"]}],"d":[{"n":"Home for Thanksgiving apple cider punch","note":"cloudy juice warmed with cinnamon, cloves and orange, bourbon for adults, those aren't pillows","how":"Put 1.5L cloudy apple juice, 2 cinnamon sticks, 6 cloves, 1 sliced orange and 2 tbsp brown sugar in a saucepan. Bring to a gentle simmer and keep it there for 15 minutes without boiling. Strain into a jug. Pour into 4 mugs, add 30ml bourbon to each adult mug, and serve with a fresh cinnamon stick.","shop":["1.5L cloudy apple juice@Drinks","1 packet cinnamon sticks@Pantry","1 jar whole cloves@Pantry","1 orange@Produce","2 tbsp brown sugar@Pantry","120ml bourbon@Bottle shop"]}],"shopping":["60g salted peanuts@Pantry","60g pretzels@Pantry","60g chocolate bars@Pantry","40g beef jerky@Pantry","2 brown onions@Produce","150ml buttermilk@Dairy","140g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry","700g turkey breast@Meat","30g salt@Pantry","150g stuffing mix@Pantry","20g butter@Dairy","300ml chicken stock@Pantry","8 soft slider buns@Bakery","80g cranberry sauce@Pantry","450g peeled pumpkin@Produce","250g sweet shortcrust pastry@Frozen","2 eggs@Dairy","80g brown sugar@Pantry","200ml thickened cream@Dairy","1/2 tsp cinnamon@Pantry","1/4 tsp ground ginger@Pantry","1/8 tsp nutmeg@Pantry","1.5L cloudy apple juice@Drinks","1 packet cinnamon sticks@Pantry","1 jar whole cloves@Pantry","1 orange@Produce","2 tbsp brown sugar@Pantry","120ml bourbon@Bottle shop"]}},"Pretty in Pink (1986)":{"poster":"assets/menu-posters/pretty-in-pink-1986.jpg","colour":"#b63269","servings":4,"tagline":"Pink lemonade. Obviously.","cue":"Serve the snacks when Duckie dances on the record shop counter.","menu":{"s":[{"n":"Duckie's dance-off popcorn","note":"pink and sweet, like his big moment","how":"Pop 50g popcorn kernels in 1 tbsp neutral oil in a covered pot over medium heat for 3 to 4 minutes, shaking regularly. Melt 80g white chocolate gently. Crush 10g freeze-dried raspberries to a powder and stir into the chocolate to tint it pink. Toss through the popcorn, spread on a lined tray and leave 20 minutes to set.","shop":["50g popcorn kernels@Pantry","1 tbsp neutral oil@Pantry","80g white chocolate@Pantry","10g freeze-dried raspberries@Pantry"]},{"n":"Steff's party salmon maki","note":"rolls of salmon, cucumber and spicy mayo with soy, wasabi and pickled ginger","how":"Rinse the rice until the water runs clear, then cook with 480ml water, covered, on low for 12 minutes. Rest 10 minutes. Stir the vinegar with the sugar and 1 tsp salt until dissolved, fold through the rice and cool. Cut the salmon and cucumber into long strips. Mix the mayonnaise with the sriracha. Spread a quarter of the rice over each nori sheet, leaving a strip bare at the far edge. Lay salmon, cucumber and a line of spicy mayo along the middle and roll up tight with a mat. Slice each roll into 8 with a wet knife. Serve with soy, wasabi and ginger.","shop":["400g sushi rice@Pantry","80ml rice vinegar@Pantry","1 tbsp caster sugar@Pantry","4 nori sheets@Pantry","300g sashimi-grade salmon@Seafood","1 Lebanese cucumber@Produce","3 tbsp Japanese mayonnaise@Pantry","1 tsp sriracha@Pantry","60ml soy sauce@Pantry","1 tube wasabi@Pantry","1 jar pickled ginger@Pantry"]}],"m":[{"n":"Andie's dad's pot roast","note":"beef chuck braised slow with onion, carrot, garlic and stock, potatoes added for the last hour","how":"Season 900g beef chuck roast with 1 tsp salt and 1/2 tsp black pepper. Brown all sides in 1 tbsp neutral oil in a heavy casserole for 8 minutes. Add 2 quartered brown onions, 3 chopped carrots, 4 garlic cloves and 500ml beef stock. Cover and braise at 160°C conventional for 3 hours. After 2 hours add 600g peeled potato chunks, cover and cook for the final hour until the beef and potatoes are tender. Rest the beef 15 minutes, slice or pull apart and serve with the vegetables and rich stock.","shop":["900g beef chuck roast@Meat","salt@Pantry","black pepper@Pantry","1 tbsp neutral oil@Pantry","2 brown onions@Produce","3 carrots@Produce","4 garlic cloves@Produce","500ml beef stock@Pantry","600g potatoes@Produce"]}],"w":[{"n":"Two-dress prom cake","note":"pink and white, cut and stitched together like her dress","how":"Heat the oven to 180°C conventional and line two 12cm round tins. Cook 100g chopped strawberries over low heat for 8 minutes until reduced to about 30g thick purée; cool. Beat 120g softened butter with 120g caster sugar until pale. Beat in 2 eggs, then fold in 140g self-raising flour. Divide the batter equally. Stir 1/2 tsp vanilla into one half and the strawberry purée into the other. Bake side by side for 20 to 25 minutes until a skewer comes out clean. Cool, cut both cakes in half and join one vanilla and one strawberry semicircle using buttercream. Save the spare halves or use them for a second layer. Beat 80g softened butter with 160g icing sugar and 1 tsp milk. Tint half pink. Cover half the cake pink and half white, piping a seam along the join. Cut four portions.","shop":["100g strawberries@Produce","200g butter@Dairy","120g caster sugar@Pantry","2 eggs@Dairy","140g self-raising flour@Pantry","1/2 tsp vanilla extract@Pantry","160g icing sugar@Pantry","1 tsp milk@Dairy","pink food colouring@Pantry"]}],"d":[{"n":"Pink lemonade prom punch","note":"cranberry and pineapple juice with lemonade, orange slices and frozen raspberries in a glass bowl","how":"Mix 500ml cranberry juice, 500ml pineapple juice and 750ml lemonade in a big glass bowl. Add 2 sliced oranges and 150g frozen raspberries so they float on top. Ladle into 4 glasses over ice.","shop":["500ml cranberry juice@Drinks","500ml pineapple juice@Drinks","750ml lemonade@Drinks","2 oranges@Produce","150g frozen raspberries@Frozen"]}],"shopping":["220g caster sugar@Pantry","250g whole almonds@Pantry","2 tbsp freeze-dried raspberry powder@Pantry","100g salted pretzels@Pantry","50g popcorn kernels@Pantry","2 tbsp neutral oil@Pantry","80g white chocolate@Pantry","10g freeze-dried raspberries@Pantry","900g beef chuck roast@Meat","salt@Pantry","black pepper@Pantry","2 brown onions@Produce","3 carrots@Produce","4 garlic cloves@Produce","500ml beef stock@Pantry","600g potatoes@Produce","100g strawberries@Produce","200g butter@Dairy","2 eggs@Dairy","140g self-raising flour@Pantry","1/2 tsp vanilla extract@Pantry","160g icing sugar@Pantry","1 tsp milk@Dairy","pink food colouring@Pantry","500ml cranberry juice@Drinks","500ml pineapple juice@Drinks","750ml lemonade@Drinks","2 oranges@Produce","150g frozen raspberries@Frozen"]}},"The Breakfast Club (1985)":{"poster":"assets/menu-posters/the-breakfast-club-1985.jpg","colour":"#87322d","servings":4,"tagline":"Five strangers. One detention. Plenty of snacks.","cue":"Serve the snacks when everyone unpacks their lunch.","menu":{"s":[{"n":"Andrew's triple-stack ham and cheese","note":"three toasted layers of ham, Swiss and cheddar with mustard mayo and pickles, a wrestler's lunch","how":"Mix 3 tbsp mayo with 1 tbsp wholegrain mustard. Toast 12 slices white bread. Build 4 stacks of toast, sauce, 50g leg ham and a slice of Swiss, toast, sauce, 50g leg ham, a slice of cheddar and pickles, then toast. Press lightly, cut each into 3 fingers and pin with toothpicks. Slice 2 apples and toss with lemon juice to serve alongside.","shop":["3 tbsp mayo@Pantry","wholegrain mustard@Pantry","12 slices white bread@Bakery","400g leg ham@Deli","4 slices Swiss cheese@Dairy","4 slices cheddar@Dairy","1 jar dill pickles@Pantry","2 apples@Produce","1 lemon@Produce"]},{"n":"Bender's share plate","note":"crackers, cheese and salami on a plate in the middle for anyone who forgot lunch","how":"Arrange 80g crackers, 100g cubed cheddar and 80g sliced salami on a shared plate in the middle of the table. Let everyone help themselves.","shop":["80g crackers@Pantry","100g cheddar@Dairy","80g salami@Deli"]}],"m":[{"n":"Brian's lunch","note":"soup in a thermos, PB and J with the crusts cut off","how":"Halve 800g tomatoes and put in a roasting dish with 1 quartered brown onion, 3 garlic cloves and 1 tbsp olive oil. Roast at 200°C conventional for 35 minutes until softened and browned. Transfer to a pot with 500ml chicken stock and simmer 10 minutes. Blitz smooth with 80ml thickened cream and season with salt and pepper. Pour into four warmed thermoses. Make four peanut butter and jam sandwiches with 8 slices white bread, 80g peanut butter and 60g jam; cut off the crusts and serve with the soup.","shop":["800g tomatoes@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tbsp olive oil@Pantry","500ml chicken stock@Pantry","80ml thickened cream@Dairy","salt and pepper@Pantry","8 slices white bread@Bakery","80g peanut butter@Pantry","60g jam@Pantry"]}],"w":[{"n":"Detention brownies","note":"Vernon, the brownie hound","how":"Melt 100g dark chocolate with 100g butter gently and cool slightly. Whisk in 120g caster sugar and 2 eggs. Fold in 60g plain flour and a pinch of salt. Pour into a lined 18cm square tin and bake at 175°C conventional for 25 minutes until the edges are set and the middle still gently wobbles. Cool at least 30 minutes before cutting into four portions.","shop":["100g dark chocolate@Pantry","100g butter@Dairy","120g caster sugar@Pantry","2 eggs@Dairy","60g plain flour@Pantry","salt@Pantry"]}],"d":[{"n":"Detention strawberry milkshake","note":"Brian asks, \"Will milk be made available?\"","how":"Hull 250g strawberries, keeping 4 for garnish. Blend the rest with 6 scoops vanilla ice cream, 500ml cold milk and 1 tbsp caster sugar for 30 seconds until thick and smooth. Pour into 4 tall glasses, top with whipped cream and a strawberry on the rim, and serve with straws.","shop":["250g strawberries@Produce","1 litre vanilla ice cream@Frozen","500ml full cream milk@Dairy","1 tbsp caster sugar@Pantry","1 can whipped cream@Dairy"]}],"shopping":["3 tbsp mayo@Pantry","wholegrain mustard@Pantry","20 slices white breads@Bakery","400g leg ham@Deli","4 slices Swiss cheeses@Dairy","4 slices cheddars@Dairy","1 jar dill pickles@Pantry","2 apples@Produce","1 lemon@Produce","80g crackers@Pantry","100g cheddar@Dairy","80g salami@Deli","800g tomatoes@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tbsp olive oil@Pantry","500ml chicken stock@Pantry","80ml thickened cream@Dairy","salt and pepper@Pantry","80g peanut butter@Pantry","60g jam@Pantry","100g dark chocolate@Pantry","100g butter@Dairy","120g caster sugar@Pantry","2 eggs@Dairy","60g plain flour@Pantry","salt@Pantry","250g strawberries@Produce","1 litre vanilla ice cream@Frozen","500ml full cream milk@Dairy","1 tbsp caster sugar@Pantry","1 can whipped cream@Dairy"]}},"Aliens (1986)":{"poster":"assets/menu-posters/aliens-1986.jpg","colour":"#28525b","servings":4,"tagline":"Colonial Marines. Dinner's on.","cue":"Serve the snacks at the marines' breakfast on the Sulaco.","menu":{"s":[{"n":"Sulaco mess hall cornbread","note":"buttermilk, cornmeal and egg batter poured into a hot buttered pan, baked and cut into squares","how":"Heat the oven to 200°C conventional with a 20cm ovenproof frying pan inside. Mix 100g fine cornmeal, 80g plain flour, 20g caster sugar, 1 tsp baking powder and 1/4 tsp salt. Whisk 150ml buttermilk, 1 egg and 30g melted butter, then stir into the dry ingredients. Carefully butter the hot pan with 10g butter, pour in the batter and bake for 20 minutes until golden and a skewer comes out clean. Cool 5 minutes and cut into 8 squares.","shop":["100g fine cornmeal@Pantry","80g plain flour@Pantry","20g caster sugar@Pantry","1 tsp baking powder@Pantry","salt@Pantry","150ml buttermilk@Dairy","1 egg@Dairy","40g butter@Dairy"]},{"n":"Bishop's knife trick breadsticks","note":"spread them across the table, fingers optional","how":"Roll 250g pizza dough into 12 long thin sticks. Place on a lined tray, brush with 1 tbsp extra virgin olive oil and roll in 15g sesame seeds and 1/2 tsp sea salt flakes. Bake at 220°C conventional for 12 minutes until crisp and golden. Cool slightly before serving.","shop":["250g pizza dough@Bakery","1 tbsp extra virgin olive oil@Pantry","15g sesame seeds@Pantry","1/2 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Sulaco mess hall meatloaf","note":"breakfast for the marines, served at dinner","how":"Soak 50g breadcrumbs in 80ml milk for 5 minutes. Mix with 350g beef mince, 250g pork mince, 1 egg, 1 finely diced onion, 1 tbsp anchovy-free Worcestershire sauce, 1/2 tsp salt and 1/4 tsp black pepper. Shape into a loaf on a lined tray and glaze with 60g tomato sauce. Bake at 180°C conventional for 1 hour until cooked through, at least 75°C in the centre. Rest 10 minutes. Meanwhile peel and chop 800g potatoes, boil 20 minutes until tender and mash with 40g butter and 100ml warm milk. Slice the loaf and serve with mash.","shop":["50g breadcrumbs@Pantry","180ml milk@Dairy","350g beef mince@Meat","250g pork mince@Meat","1 egg@Dairy","1 onion@Produce","1 tbsp anchovy-free Worcestershire sauce@Pantry","salt@Pantry","black pepper@Pantry","60g tomato sauce@Pantry","800g potatoes@Produce","40g butter@Dairy"]}],"w":[{"n":"Facehugger panna cotta","note":"pale, wobbly and unsettling","how":"Soak 4g gelatine leaves, using the packet's equivalent weight, in cold water for 5 minutes. Warm 250ml thickened cream, 150ml full cream milk, 40g caster sugar and seeds of half a vanilla bean over low heat until steaming, without boiling. Remove from heat, squeeze the gelatine dry and stir in until dissolved. Divide into four lightly oiled 100ml round moulds and refrigerate at least 4 hours until set. Dip each mould briefly in warm water and turn out. Fan 40g candied orange peel strips around the puddings as legs.","shop":["4g gelatine leaves@Pantry","250ml thickened cream@Dairy","150ml full cream milk@Dairy","40g caster sugar@Pantry","1/2 vanilla bean@Pantry","neutral oil for moulds@Pantry","40g candied orange peel@Pantry"]}],"d":[{"n":"Sulaco condensed milk iced coffee","note":"strong enough to get you out of cryosleep","how":"The night before, stir 100g coarsely ground dark roast coffee into 800ml cold water, cover and refrigerate 12 to 16 hours, then strain through a paper filter. Spoon 2 tbsp sweetened condensed milk into each of 4 tall glasses. Fill with ice, pour 180ml cold brew into each and stir until creamy. Dust with a pinch of cinnamon.","shop":["100g ground dark roast coffee@Pantry","1 tin sweetened condensed milk@Pantry","ground cinnamon@Pantry","1 bag ice@Frozen"]}],"shopping":["100g fine cornmeal@Pantry","80g plain flour@Pantry","60g caster sugar@Pantry","1 tsp baking powder@Pantry","salt@Pantry","150ml buttermilk@Dairy","2 eggs@Dairy","80g butter@Dairy","250g pizza dough@Bakery","1 tbsp extra virgin olive oil@Pantry","15g sesame seeds@Pantry","1/2 tsp sea salt flakes@Pantry","50g breadcrumbs@Pantry","180ml milk@Dairy","350g beef mince@Meat","250g pork mince@Meat","1 onion@Produce","1 tbsp anchovy-free Worcestershire sauce@Pantry","black pepper@Pantry","60g tomato sauce@Pantry","800g potatoes@Produce","4g gelatine leaves@Pantry","250ml thickened cream@Dairy","150ml full cream milk@Dairy","1/2 vanilla bean@Pantry","neutral oil for moulds@Pantry","40g candied orange peel@Pantry","100g ground dark roast coffee@Pantry","1 tin sweetened condensed milk@Pantry","ground cinnamon@Pantry","1 bag ice@Frozen"]}},"Back to the Future (1985)":{"poster":"assets/menu-posters/back-to-the-future-1985.jpg","colour":"#265b7e","servings":4,"tagline":"Hill Valley, 1955. Save room for a malt.","cue":"Serve the mains when Marty walks into Lou's Cafe in 1955 and asks for a sugar-free drink.","menu":{"s":[{"n":"Lou's Cafe fries","note":"1955 prices, 1985 portions","how":"Hand-cut 500g potatoes into chips, rinse and dry thoroughly. Heat vegetable oil in a sturdy deep pan to 140°C. Blanch the chips in batches for 5 minutes without browning, drain and cool 15 minutes. Increase the oil to 185°C and fry for 2 to 3 minutes until crisp. Drain, season with 1/2 tsp fine salt and serve in red-checked food-safe paper boats.","shop":["500g potatoes@Produce","vegetable oil for frying@Pantry","1/2 tsp fine salt@Pantry"]},{"n":"Clock tower cheese straws","note":"standing tall, struck by lightning","how":"Brush 1 sheet puff pastry with half of 1 beaten egg. Scatter over 60g grated cheddar, 20g grated parmesan and 1/8 tsp cayenne pepper. Fold in half and press lightly. Cut into 8 tall strips, twist each and place on a lined tray. Brush with the remaining egg. Bake at 220°C conventional for 12 minutes until puffed and golden.","shop":["1 sheet puff pastry@Frozen","1 egg@Dairy","60g cheddar@Dairy","20g parmesan@Dairy","1/8 tsp cayenne pepper@Pantry"]}],"m":[{"n":"Lou's malt shop cheeseburger","note":"griddled onions, pickles and a slice of American","how":"Divide 600g beef mince into four loose balls. Slice 1 onion very thin. Heat a griddle until hot. Put the beef balls on the griddle, top with the onions and press firmly into thin patties. Season with 1/2 tsp salt and 1/4 tsp black pepper. Cook 3 minutes, flip and cook 2 to 3 minutes until cooked through, checking the centre reaches 75°C. Add 80g American-style cheese to melt. Toast 4 burger buns and fill with the patties, 60g sliced dill pickles and 30g yellow mustard.","shop":["600g beef mince@Meat","1 onion@Produce","salt@Pantry","black pepper@Pantry","80g American-style cheese@Dairy","4 burger buns@Bakery","60g dill pickles@Pantry","30g yellow mustard@Pantry"]}],"w":[{"n":"Enchantment Under the Sea cupcakes","note":"ocean blue frosting for the dance","how":"Beat 80g softened butter with 80g caster sugar until pale. Beat in 1 egg and 1 tsp vanilla extract. Fold in 100g self-raising flour and 40ml milk. Divide among 8 cupcake cases and bake at 180°C conventional for 18 minutes until a skewer comes out clean. Cool completely. Beat 60g softened butter with 120g icing sugar and 1 tsp milk until fluffy. Tint with a little blue food colouring, pipe on the cakes and top with 10g sugar pearls and 8 fish-shaped gummy sweets. Serve two small cupcakes each.","shop":["140g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","blue food colouring@Pantry","10g sugar pearls@Pantry","8 fish-shaped gummy sweets@Pantry"]}],"d":[{"n":"Lou's Cafe chocolate malt","note":"vanilla ice cream blended thick with milk, chocolate syrup and malted milk, cream, two straws","how":"Add 12 scoops vanilla ice cream, 800ml cold milk, 8 tbsp chocolate syrup and 8 tbsp malted milk powder to a blender, working in two batches if needed. Blend 30 seconds until thick but pourable. Pour into 4 tall chilled glasses, top with whipped cream and a sprinkle of malted milk powder, and serve each with two straws.","shop":["2 litres vanilla ice cream@Frozen","800ml full cream milk@Dairy","1 bottle chocolate syrup@Pantry","1 jar malted milk powder@Pantry","1 can whipped cream@Dairy"]}],"shopping":["500g potatoes@Produce","vegetable oil for frying@Pantry","1/2 tsp fine salt@Pantry","1 sheet puff pastry@Frozen","2 eggs@Dairy","60g cheddar@Dairy","20g parmesan@Dairy","1/8 tsp cayenne pepper@Pantry","600g beef mince@Meat","1 onion@Produce","salt@Pantry","black pepper@Pantry","80g American-style cheese@Dairy","4 burger buns@Bakery","60g dill pickles@Pantry","30g yellow mustard@Pantry","140g butter@Dairy","80g caster sugar@Pantry","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","blue food colouring@Pantry","10g sugar pearls@Pantry","8 fish-shaped gummy sweets@Pantry","2 litres vanilla ice cream@Frozen","800ml full cream milk@Dairy","1 bottle chocolate syrup@Pantry","1 jar malted milk powder@Pantry","1 can whipped cream@Dairy"]}},"Running Scared (1986)":{"poster":"assets/menu-posters/running-scared-1986.jpg","colour":"#285574","servings":4,"tagline":"Two Chicago cops. One more week.","cue":"Serve the mains when the pair requisition bulletproof vests.","menu":{"s":[{"n":"Chicago hot dogs","note":"all-beef frankfurts in poppy seed buns, mustard, relish, onion and sport peppers, for the beat","how":"Heat 4 small all-beef franks in simmering water for 5 minutes until piping hot. Warm 4 small poppy seed hot dog buns in a steamer for 1 minute. Add the franks and divide 20g yellow mustard, 30g sweet relish, half a diced onion, 1 sliced tomato, 4 pickle spears and 8 sport peppers among the buns. Finish with 1/4 tsp celery salt. Serve one small hot dog each.","shop":["4 small all-beef franks@Meat","4 small poppy seed hot dog buns@Bakery","20g yellow mustard@Pantry","30g sweet relish@Pantry","1/2 onion@Produce","1 tomato@Produce","4 pickle spears@Pantry","8 sport peppers@Pantry","1/4 tsp celery salt@Pantry"]},{"n":"Key West conch fritters","note":"chopped prawn in a capsicum, onion and celery batter, fried in spoonfuls, lime mayo","how":"Finely chop 300g peeled prawns. Mix 150g flour, 1 tsp baking powder, 1 egg and 125ml milk to a thick batter, then fold in the prawns, half a diced red capsicum, half a diced onion and 1 diced celery stick. Fry spoonfuls at 180C for 3 minutes until golden. Serve with 150g mayonnaise mixed with the juice of 1 lime.","shop":["300g peeled prawns@Seafood","150g plain flour@Pantry","1 tsp baking powder@Pantry","1 egg@Dairy","125ml milk@Dairy","1 red capsicum@Produce","1 onion@Produce","1 celery stick@Produce","150g mayonnaise@Pantry","1 lime@Produce","2L vegetable oil@Pantry"]}],"m":[{"n":"Best of the worst Italian beef","note":"rare topside shaved thin, warmed in garlic oregano jus, piled in dipped rolls with hot giardiniera","how":"Season 800g beef topside with 1 tsp salt and 1/2 tsp black pepper. Roast at 200°C conventional for about 40 minutes, checking with a thermometer, until 52°C at the centre for rare. Rest 20 minutes. Simmer 400ml beef stock with 3 crushed garlic cloves and 1 tsp dried oregano for 10 minutes to make jus. Shave the rested beef very thin and warm gently in the jus for 1 minute. Pile into 4 long rolls, dip briefly in the jus and top with 100g hot giardiniera.","shop":["800g beef topside@Meat","salt@Pantry","black pepper@Pantry","400ml beef stock@Pantry","3 garlic cloves@Produce","1 tsp dried oregano@Pantry","4 long rolls@Bakery","100g hot giardiniera@Pantry"]}],"w":[{"n":"Key lime pie","note":"biscuit crust, condensed milk, yolk and citrus juice custard baked briefly, chilled, whipped cream","how":"Crush 150g digestive biscuits and mix with 60g melted butter. Press into a 20cm pie dish. Whisk 400g condensed milk, 4 egg yolks and 120ml lime juice until smooth, then pour into the crust. Bake at 160°C conventional for 15 minutes until just set. Cool and chill for at least 4 hours. Softly whip 100ml thickened cream, spoon over the pie and divide into four generous portions.","shop":["150g digestive biscuits@Pantry","60g butter@Dairy","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice@Produce","100ml thickened cream@Dairy"]}],"d":[{"n":"Key West rum punch","note":"rum with pineapple, orange and lime juice, a dash of grenadine over ice, grated nutmeg","how":"Fill four glasses with 400g ice. For each drink add 45ml golden rum, 30ml pineapple juice, 30ml orange juice, 15ml lime juice and 5ml grenadine. Stir and finish with a light grating of nutmeg. Totals are 180ml rum, 120ml each pineapple and orange juice, 60ml lime juice and 20ml grenadine.","shop":["400g ice@Frozen","180ml golden rum@Bottle shop","120ml pineapple juice@Drinks","120ml orange juice@Drinks","2 limes for 60ml juice@Produce","20ml grenadine@Drinks","ground or whole nutmeg@Pantry"]}],"shopping":["4 small all-beef franks@Meat","4 small poppy seed hot dog buns@Bakery","20g yellow mustard@Pantry","30g sweet relish@Pantry","1/2 onion@Produce","1 tomato@Produce","4 pickle spears@Pantry","8 sport peppers@Pantry","1/4 tsp celery salt@Pantry","300g peeled prawns@Seafood","150g plain flour@Pantry","1 tsp baking powder@Pantry","1 egg@Dairy","125ml milk@Dairy","1 red capsicum@Produce","1 onion@Produce","1 celery stick@Produce","150g mayonnaise@Pantry","1 lime@Produce","2L vegetable oil@Pantry","800g beef topside@Meat","salt@Pantry","black pepper@Pantry","400ml beef stock@Pantry","3 garlic cloves@Produce","1 tsp dried oregano@Pantry","4 long rolls@Bakery","100g hot giardiniera@Pantry","150g digestive biscuits@Pantry","60g butter@Dairy","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice@Produce","100ml thickened cream@Dairy","400g ice@Frozen","180ml golden rum@Bottle shop","120ml pineapple juice@Drinks","120ml orange juice@Drinks","2 limes for 60ml juice@Produce","20ml grenadine@Drinks","ground or whole nutmeg@Pantry"]}},"Rush Hour (1998)":{"poster":"assets/menu-posters/rush-hour-1998.jpg","colour":"#a52624","servings":4,"tagline":"Two cops. One case. Several misunderstandings.","cue":"Serve the mains when Carter walks into the Foo Chow alone.","menu":{"s":[{"n":"Consulate spring rolls","note":"cabbage, carrot, shiitake and glass noodles rolled in thin pastry, fried crisp, sweet chilli","how":"Soak 30g glass noodles in hot water for 5 minutes, drain and cut short. Stir-fry 120g shredded cabbage, 1 grated carrot and 60g finely sliced shiitake in 1 tsp oil for 4 minutes. Add the noodles and 1 tsp light soy sauce, stir 1 minute and cool completely. Divide among 8 spring roll pastry sheets, roll tightly and seal with a paste of 1 tsp flour and 1 tsp water. Fry in neutral oil at 180°C for 3 to 4 minutes until golden. Serve with 40ml sweet chilli sauce.","shop":["30g glass noodles@Pantry","120g cabbage@Produce","1 carrot@Produce","60g shiitake@Produce","neutral oil for frying@Pantry","1 tsp light soy sauce@Pantry","8 spring roll pastry sheets@Frozen","1 tsp plain flour@Pantry","40ml sweet chilli sauce@Pantry"]},{"n":"Five spice chicken wings","note":"wings in a soy and five spice crust, baked crisp, tossed in lemon butter and spring onion","how":"Pat 600g chicken wings dry and toss with 1/2 tsp salt, 35ml light soy sauce, 1/4 tsp Chinese five spice, 1 beaten egg and 20g cornflour until coated. Bake on a rack at 220°C conventional for 45 minutes, turning halfway, until crisp and at least 74°C inside. Melt 25g butter with 1 tsp lemon juice and toss through the wings. Scatter with 2 sliced spring onions and serve.","shop":["600g chicken wings@Meat","salt@Pantry","25g butter@Dairy","35ml light soy sauce@Pantry","1 egg@Dairy","20g cornflour@Pantry","2 spring onions@Produce","1/4 tsp Chinese five spice@Pantry","1 tsp lemon juice@Produce"]}],"m":[{"n":"Beef chow fun","note":"wide rice noodles wok-fried with beef, bean sprouts and spring onion","how":"Thinly slice 400g beef rump and marinate for 20 minutes with 1 tbsp light soy sauce, 1 tsp cornflour and 1 tsp sesame oil. Separate 600g fresh wide rice noodles gently. Heat 1 tbsp neutral oil in a wok over high heat; stir-fry the beef in two batches for 2 minutes and set aside. Add another 1 tbsp oil and fry the noodles for 2 minutes. Add 150g bean sprouts, 3 sliced spring onions, 1 tbsp dark soy sauce and 1 tbsp light soy sauce. Return the beef and toss over high heat for 2 minutes until piping hot. Serve immediately.","shop":["400g beef rump@Meat","2 tbsp light soy sauce@Pantry","1 tsp cornflour@Pantry","1 tsp sesame oil@Pantry","600g fresh wide rice noodles@Pantry","2 tbsp neutral oil@Pantry","150g bean sprouts@Produce","3 spring onions@Produce","1 tbsp dark soy sauce@Pantry"]}],"w":[{"n":"Ransom fortune cookies","note":"thin vanilla wafers baked in circles, folded around paper messages while hot","how":"Write 8 fortunes on small clean food-safe paper strips. Whisk 2 egg whites with 50g caster sugar until foamy. Stir in 25g melted butter, 40g plain flour, 1/2 tsp vanilla extract and 1 tbsp water. Spread two thin 10cm circles at a time on a lined tray. Bake at 180°C conventional for 6 minutes until the edges turn golden. Working quickly while hot, place a fortune in each, fold in half and bend over a mug rim into the classic shape. Cool in muffin-tin cups. Repeat for 8 cookies. Remind everyone to remove the paper before eating.","shop":["2 eggs, whites only@Dairy","50g caster sugar@Pantry","25g butter@Dairy","40g plain flour@Pantry","1/2 tsp vanilla extract@Pantry"]}],"d":[{"n":"Consulate lychee and jasmine martini","note":"vodka shaken with jasmine tea, lychee syrup and lime, a whole lychee in the coupe","how":"Brew 1 jasmine tea bag in 120ml hot water for 3 minutes and cool. Drain a 565g tin of lychees, keeping the syrup. Shake 160ml vodka, the tea, 80ml lychee syrup and the juice of 1 lime with ice for 15 seconds. Strain into 4 chilled coupes and drop a lychee into each.","shop":["160ml vodka@Bottle shop","1 box jasmine tea@Pantry","1 tin lychees (565g)@Pantry","1 lime@Produce","1 bag ice@Frozen"]}],"shopping":["30g glass noodles@Pantry","120g cabbage@Produce","1 carrot@Produce","60g shiitake@Produce","neutral oil for frying@Pantry","1 tsp light soy sauce@Pantry","8 spring roll pastry sheets@Frozen","1 tsp plain flour@Pantry","40ml sweet chilli sauce@Pantry","600g chicken wings@Meat","salt@Pantry","50g butter@Dairy","35ml light soy sauce@Pantry","1 egg@Dairy","20g cornflour@Pantry","2 spring onions@Produce","1/4 tsp Chinese five spice@Pantry","1 tsp lemon juice@Produce","400g beef rump@Meat","2 tbsp light soy sauce@Pantry","1 tsp cornflour@Pantry","1 tsp sesame oil@Pantry","600g fresh wide rice noodles@Pantry","2 tbsp neutral oil@Pantry","150g bean sprouts@Produce","3 spring onions@Produce","1 tbsp dark soy sauce@Pantry","2 eggs, whites only@Dairy","50g caster sugar@Pantry","40g plain flour@Pantry","1/2 tsp vanilla extract@Pantry","160ml vodka@Bottle shop","1 box jasmine tea@Pantry","1 tin lychees (565g)@Pantry","1 lime@Produce","1 bag ice@Frozen"]}},"Bad Boys (1995)":{"poster":"assets/menu-posters/bad-boys-1995.jpg","colour":"#23696e","servings":4,"tagline":"Two Miami cops. One swapped life.","cue":"Serve dinner when Marcus has to pretend to be Mike.","menu":{"s":[{"n":"Miami croquetas","note":"thick ham and nutmeg béchamel chilled, rolled into logs, crumbed and fried golden","how":"Melt 30g butter, stir in 40g plain flour and cook 2 minutes. Gradually whisk in 250ml full cream milk and cook 5 minutes until a very thick béchamel forms. Stir in 120g finely chopped leg ham and 1/8 tsp nutmeg. Spread in a shallow dish, cool promptly and refrigerate overnight. Shape into 8 logs. Dust with 20g flour, dip in 1 beaten egg and coat in 60g breadcrumbs. Fry in neutral oil at 180°C for 3 to 4 minutes until golden and hot throughout. Drain and serve two each.","shop":["30g butter@Dairy","60g plain flour@Pantry","250ml full cream milk@Dairy","120g leg ham@Deli","1/8 tsp nutmeg@Pantry","1 egg@Dairy","60g breadcrumbs@Pantry","neutral oil for frying@Pantry"]},{"n":"Fried sweet plantains","note":"Sweet plantain, which nobody argues over like a french fry","how":"Peel 2 very ripe plantains and cut diagonally into 1cm slices. Heat 3 tbsp vegetable oil in a frying pan over medium heat. Fry the slices in batches for 3 minutes each side until caramelised and soft. Drain and finish with 1/4 tsp sea salt flakes.","shop":["2 very ripe plantains@Produce","3 tbsp vegetable oil@Pantry","1/4 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Mike and Marcus swap Cuban sandwich","note":"soft long roll with mustard, mojo pork, ham, Swiss and pickles, buttered and pressed flat","how":"Marinate 700g boneless pork shoulder overnight with juice of 1 orange and 1 lime, 3 crushed garlic cloves, 1 tsp oregano, 1 tsp cumin and 1/2 tsp salt. Put in a covered roasting dish with 100ml water and roast at 160°C conventional for about 3 hours until tender; rest 20 minutes and shred. Split 4 long soft rolls and spread with 40g yellow mustard. Fill with the pork, 120g leg ham, 120g Swiss cheese and 80g sliced dill pickles. Butter the outsides with 30g butter and press in a hot sandwich press for 5 minutes, until crisp and flat and the filling is piping hot.","shop":["700g boneless pork shoulder@Meat","1 orange@Produce","1 lime@Produce","3 garlic cloves@Produce","1 tsp oregano@Pantry","1 tsp cumin@Pantry","salt@Pantry","4 long soft rolls@Bakery","40g yellow mustard@Pantry","120g leg ham@Deli","120g Swiss cheese@Dairy","80g dill pickles@Pantry","30g butter@Dairy"]}],"w":[{"n":"Key lime pie","note":"biscuit crust with a tangy condensed milk and citrus custard, baked briefly, chilled, whipped cream","how":"Crush 150g digestive biscuits, mix with 60g melted butter and press into a 20cm pie dish. Bake at 180°C conventional for 10 minutes. Whisk 400g condensed milk with 4 egg yolks, 120ml lime juice and zest of 2 limes. Pour into the crust and bake at 160°C for 15 minutes until just set. Cool and refrigerate for at least 4 hours. Softly whip 100ml thickened cream and spread over the pie. Cut four generous portions.","shop":["150g digestive biscuits@Pantry","60g butter@Dairy","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice and zest@Produce","100ml thickened cream@Dairy"]}],"d":[{"n":"Mike Lowrey's ocean view mojito","note":"Mint, lime, rum. Still no cup holder in the Porsche.","how":"Gently muddle 24 mint leaves with 60ml sugar syrup and 60ml lime juice in a jug, avoiding shredding the mint. Add 180ml white rum. Divide between four glasses filled with 500g crushed ice. Top with 400ml soda water and stir gently. Garnish with 4 mint sprigs.","shop":["24 mint leaves and 4 sprigs@Produce","60ml sugar syrup@Drinks","2 limes for 60ml juice@Produce","180ml white rum@Bottle shop","500g crushed ice@Frozen","400ml soda water@Drinks"]}],"shopping":["120g butter@Dairy","60g plain flour@Pantry","250ml full cream milk@Dairy","240g leg ham@Deli","1/8 tsp nutmeg@Pantry","1 egg@Dairy","60g breadcrumbs@Pantry","neutral oil for frying@Pantry","2 very ripe plantains@Produce","3 tbsp vegetable oil@Pantry","1/4 tsp sea salt flakes@Pantry","700g boneless pork shoulder@Meat","1 orange@Produce","1 lime@Produce","3 garlic cloves@Produce","1 tsp oregano@Pantry","1 tsp cumin@Pantry","salt@Pantry","4 long soft rolls@Bakery","40g yellow mustard@Pantry","120g Swiss cheese@Dairy","80g dill pickles@Pantry","150g digestive biscuits@Pantry","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice and zest@Produce","100ml thickened cream@Dairy","24 mint leaves and 4 sprigs@Produce","60ml sugar syrup@Drinks","2 limes for 60ml juice@Produce","180ml white rum@Bottle shop","500g crushed ice@Frozen","400ml soda water@Drinks"]}},"Tango & Cash (1989)":{"poster":"assets/menu-posters/tango-and-cash-1989.jpg","colour":"#214fc0","servings":4,"tagline":"Two cops. One shower. Zero patience.","cue":"Serve the mains when Tango and Cash first clash over the bust.","menu":{"s":[{"n":"Cleopatra Club toasties","note":"bologna and cheese on griddled white. Ask for Katherine","how":"Spread 8 slices white bread with 20g yellow mustard. Layer 120g devon and 80g American-style cheese between the slices to make four sandwiches. Butter the outside using 30g softened butter. Griddle over medium heat under a weighted pan for 3 minutes each side until crisp and the cheese melts. Cut each into fingers to share.","shop":["8 slices white bread@Bakery","20g yellow mustard@Pantry","120g devon@Deli","80g American-style cheese@Dairy","30g butter@Dairy"]},{"n":"LA street tacos","note":"marinated beef grilled and chopped, warm corn tortillas, onion, coriander, salsa verde and lime","how":"Marinate 500g skirt steak in the juice of 2 limes, 2 garlic cloves and 1 tsp cumin for 1 hour. Grill hot for 3 minutes a side, rest and chop small. Warm 12 small corn tortillas and fill with the steak, diced white onion, coriander and salsa verde, lime wedges on the side.","shop":["500g skirt steak@Meat","3 limes@Produce","1 garlic bulb@Produce","1 tsp ground cumin@Pantry","12 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","200g salsa verde@Pantry"]}],"m":[{"n":"Tango's tailored rib eye","note":"dry-brined, seared hard and basted with thyme butter, pulled at medium rare","how":"Pat dry four 200g rib eye steaks, season with 1 tsp fine salt and refrigerate uncovered for 4 to 12 hours to dry-brine. Heat a heavy pan with 1 tbsp neutral oil until hot. Sear the steaks hard for about 3 minutes per side in batches. Lower the heat and add 50g butter, 4 thyme sprigs and 3 crushed garlic cloves. Baste for 1 to 2 minutes. Remove at 54°C in the centre for medium rare, or cook longer if preferred. Rest for 8 minutes, slice and spoon over the pan butter.","shop":["800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","50g butter@Dairy","4 thyme sprigs@Produce","3 garlic cloves@Produce"]}],"w":[{"n":"Kiki's cupcakes","note":"for Kiki. Pink buttercream and sprinkles, and Cash can stop asking","how":"Beat 80g softened butter with 80g caster sugar until pale. Beat in 1 egg and 1 tsp vanilla extract. Fold in 100g self-raising flour and 40ml milk. Divide between 8 cupcake cases and bake at 180°C conventional for 18 minutes until a skewer comes out clean. Cool completely. Beat 60g softened butter with 120g icing sugar and 1 tsp milk until fluffy; tint with a little pink food colouring. Pipe onto the cupcakes and cover with 20g sprinkles. Serve two small cupcakes each.","shop":["140g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","pink food colouring@Pantry","20g sprinkles@Pantry"]}],"d":[{"n":"Tango's sharp-dressed Manhattan","note":"pick the real Perret in the mirrors. Rye, sweet vermouth, bitters, a cherry","how":"Chill 4 coupe glasses in the freezer. Fill a jug with ice and add 200ml rye whiskey, 80ml sweet vermouth and 8 dashes aromatic bitters. Stir for 30 seconds until very cold. Strain into the coupes and drop a cocktail cherry into each. Twist a strip of orange peel over the top.","shop":["200ml rye whiskey@Bottle shop","80ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["8 slices white breads@Bakery","20g yellow mustard@Pantry","120g devon@Deli","80g American-style cheese@Dairy","220g butter@Dairy","500g skirt steak@Meat","3 limes@Produce","1 garlic bulb@Produce","1 tsp ground cumin@Pantry","12 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","200g salsa verde@Pantry","800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","4 thyme sprigs@Produce","3 garlic cloves@Produce","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","pink food colouring@Pantry","20g sprinkles@Pantry","200ml rye whiskey@Bottle shop","80ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 orange@Produce","1 bag ice@Frozen"]}},"Beverly Hills Cop (1984)":{"poster":"assets/menu-posters/beverly-hills-cop-1984.jpg","colour":"#b32021","servings":4,"tagline":"Detroit attitude. Beverly Hills prices.","cue":"Serve the bananas when Axel stuffs them up the cop car's exhaust.","menu":{"s":[{"n":"Banana in the tailpipe bread","note":"overripe banana loaf with brown sugar and vanilla, sliced thick and toasted in butter","how":"Mash 3 overripe bananas and mix with 120g melted butter, 150g brown sugar, 1 egg and 1 tsp vanilla extract. Fold in 200g self-raising flour and a pinch of salt. Spoon into a lined small loaf tin and bake at 170°C conventional for 55 minutes until a skewer comes out clean. Cool completely. Cut four thick slices, halve each into bites and toast in a frying pan with 20g butter for 2 minutes per side. Save the remaining loaf for another day.","shop":["3 overripe bananas@Produce","140g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","200g self-raising flour@Pantry","salt@Pantry"]},{"n":"Detroit coney sliders","note":"home turf, a long way from Beverly Hills","how":"Brown 150g fine beef mince with half a finely diced onion in 1 tsp oil for 5 minutes. Stir in 1 tsp chilli powder, 1/2 tsp cumin and 150ml water. Simmer gently for 45 minutes, adding water if needed to keep a loose spoonable chilli. Heat 8 cocktail franks in a griddle pan for 5 minutes until piping hot. Fill 8 mini hot dog buns with the franks, chilli, 20g yellow mustard and the remaining half onion diced raw. Serve two sliders each.","shop":["150g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","8 cocktail franks@Meat","8 mini hot dog buns@Bakery","20g yellow mustard@Pantry"]}],"m":[{"n":"Beverly Palms room service","note":"the steak sandwich Axel puts on someone else's tab","how":"Cut 600g potatoes into fries, toss with 1 tbsp oil and bake at 220°C conventional for 30 minutes, turning halfway. Slowly cook 2 sliced brown onions in 20g butter over medium-low heat for 20 minutes until caramelised. Mix 60g mayonnaise with 20g horseradish. Season 600g sirloin steak and sear hard in a hot pan with 1 tsp oil for about 3 minutes per side to your preferred doneness. Rest 8 minutes and slice thin. Toast 4 brioche rolls. Fill with steak, caramelised onions, 100g Swiss cheese and horseradish mayo. Serve fries alongside.","shop":["600g potatoes@Produce","oil@Pantry","2 brown onions@Produce","20g butter@Dairy","60g mayonnaise@Pantry","20g horseradish@Pantry","600g sirloin steak@Meat","salt and pepper@Pantry","4 brioche rolls@Bakery","100g Swiss cheese@Dairy"]}],"w":[{"n":"Banana split","note":"vanilla, chocolate and strawberry scoops, hot fudge, crushed pineapple, cream, nuts and a cherry","how":"Split 4 bananas lengthways between four dishes. Put one 50ml scoop each of vanilla, chocolate and strawberry ice cream into each dish. Gently melt 80g dark chocolate with 60ml thickened cream to make hot fudge. Softly whip another 100ml cream. Add 100g drained crushed pineapple, 80ml strawberry sauce, the hot fudge and whipped cream, dividing evenly. Finish with 30g chopped nuts and 4 cherries. Serve immediately.","shop":["4 bananas@Produce","200ml vanilla ice cream@Frozen","200ml chocolate ice cream@Frozen","200ml strawberry ice cream@Frozen","80g dark chocolate@Pantry","160ml thickened cream@Dairy","100g crushed pineapple@Pantry","80ml strawberry sauce@Pantry","30g chopped nuts@Pantry","4 cherries@Produce"]}],"d":[{"n":"Axel's Beverly Palms piña colada","note":"Axel blags his way into the Beverly Palms","how":"Add 180ml white rum, 360ml pineapple juice, 200ml coconut cream, the juice of 1 lime and 3 cups of ice to a blender. Blend 30 seconds until thick and smooth. Pour into 4 tall glasses. Garnish each with a pineapple wedge on the rim and a cocktail cherry.","shop":["180ml white rum@Bottle shop","360ml pineapple juice@Drinks","200ml coconut cream@Pantry","1 lime@Produce","1 small pineapple@Produce","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}],"shopping":["3 overripe bananas@Produce","160g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","200g self-raising flour@Pantry","salt@Pantry","150g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","8 cocktail franks@Meat","8 mini hot dog buns@Bakery","20g yellow mustard@Pantry","600g potatoes@Produce","oil@Pantry","2 brown onions@Produce","60g mayonnaise@Pantry","20g horseradish@Pantry","600g sirloin steak@Meat","salt and pepper@Pantry","4 brioche rolls@Bakery","100g Swiss cheese@Dairy","4 bananas@Produce","200ml vanilla ice cream@Frozen","200ml chocolate ice cream@Frozen","200ml strawberry ice cream@Frozen","80g dark chocolate@Pantry","160ml thickened cream@Dairy","100g crushed pineapple@Pantry","80ml strawberry sauce@Pantry","30g chopped nuts@Pantry","4 cherries@Produce","180ml white rum@Bottle shop","360ml pineapple juice@Drinks","200ml coconut cream@Pantry","1 lime@Produce","1 small pineapple@Produce","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}},"Serendipity (2001)":{"poster":"assets/menu-posters/serendipity-2001.jpg","colour":"#842b3d","servings":4,"tagline":"Frozen hot chocolate. Fate decides.","cue":"Serve dessert when they first sit down at the dessert cafe.","menu":{"s":[{"n":"Gingerbread squares","note":"Christmas shopping in Manhattan","how":"Melt 125g butter with 100g brown sugar and 150g golden syrup. Stir into 250g flour, 1 tsp bicarbonate of soda, 2 tsp ground ginger and 1 tsp cinnamon with 1 egg and 125ml milk. Bake in a lined 20cm square tin at 170C for 35 minutes, cool, glaze with 100g icing sugar and lemon juice and cut into 16 squares.","shop":["125g butter@Dairy","100g brown sugar@Pantry","150g golden syrup@Pantry","250g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","2 tsp ground ginger@Pantry","1 tsp ground cinnamon@Pantry","1 egg@Dairy","125ml milk@Dairy","100g icing sugar@Pantry","1 lemon@Produce"]},{"n":"Wollman Rink roasted chestnuts","note":"ice skating in Central Park","how":"Score a cross through the shell of each of 400g chestnuts. Soak in water for 20 minutes and drain. Roast on a tray at 220°C conventional for 20 minutes until the shells curl back. Wrap in a clean towel for 5 minutes, then peel while still warm. Sprinkle with 1/4 tsp sea salt flakes and serve.","shop":["400g chestnuts@Produce","1/4 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Manhattan bistro steak","note":"sirloin seared and basted with butter and thyme, brandy peppercorn cream sauce, double-fried chips","how":"Cut 800g potatoes into thin frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool 15 minutes, then fry again at 185°C for 3 minutes until crisp. Season with salt. Season four 200g sirloin steaks and sear in a heavy hot pan with 1 tbsp neutral oil for about 3 minutes each side. Lower the heat, add 40g butter and 4 thyme sprigs, baste for 1 minute, then rest the steaks 8 minutes. Add 1 tsp cracked black peppercorns to the pan. Carefully add 40ml brandy away from the flame and simmer 1 minute. Add 150ml beef stock, reduce 5 minutes, stir in 100ml thickened cream and simmer 3 minutes. Serve with steaks and frites.","shop":["800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g sirloin steak@Meat","40g butter@Dairy","4 thyme sprigs@Produce","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy"]}],"w":[{"n":"Frozen hot chocolate","note":"dark chocolate and cocoa blended with milk and ice until slushy, whipped cream and shavings","how":"Gently melt 100g dark chocolate with 2 tbsp cocoa powder, 2 tbsp caster sugar and 100ml full cream milk, stirring until smooth. Cool completely. Blend with another 250ml full cream milk and 3 cups of ice, about 450g, until slushy. Divide into four small glasses. Softly whip 100ml thickened cream, spoon on top and finish with 20g shaved dark chocolate.","shop":["120g dark chocolate@Pantry","2 tbsp cocoa powder@Pantry","2 tbsp caster sugar@Pantry","350ml full cream milk@Dairy","450g ice@Frozen","100ml thickened cream@Dairy"]}],"d":[{"n":"Mulled cranberry punch","note":"cranberry juice warmed with orange slices, cinnamon and cloves, served hot in mugs","how":"Warm 1L cranberry juice with 1 sliced orange, 2 cinnamon sticks and 6 cloves over low heat for 15 minutes without boiling. Strain into 4 mugs and float a fresh orange slice on top of each.","shop":["1L cranberry juice@Drinks","2 oranges@Produce","2 cinnamon sticks@Pantry","6 cloves@Pantry"]}],"shopping":["165g butter@Dairy","100g brown sugar@Pantry","150g golden syrup@Pantry","250g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","2 tsp ground ginger@Pantry","1 tsp ground cinnamon@Pantry","1 egg@Dairy","125ml milk@Dairy","100g icing sugar@Pantry","1 lemon@Produce","400g chestnuts@Produce","1/4 tsp sea salt flakes@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g sirloin steak@Meat","4 thyme sprigs@Produce","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","200ml thickened cream@Dairy","120g dark chocolate@Pantry","2 tbsp cocoa powder@Pantry","2 tbsp caster sugar@Pantry","350ml full cream milk@Dairy","450g ice@Frozen","1L cranberry juice@Drinks","2 oranges@Produce","2 cinnamon sticks@Pantry","6 cloves@Pantry"]}},"Newsies (1992)":{"poster":"assets/menu-posters/newsies-1992.jpg","colour":"#912523","servings":4,"tagline":"Extra, extra, eat all about it.","cue":"Serve the mains when the strike starts.","menu":{"s":[{"n":"Hot pretzels","note":"dough knots dipped in a bicarb bath, coarse salt, baked golden, a penny on the corner","how":"Mix 250g bread flour, 4g dried yeast, 1 tsp sugar, 1/2 tsp fine salt and 160ml warm water. Knead 8 minutes and rise covered for 1 hour. Shape into four small pretzels. Bring 1 litre water with 30g bicarbonate of soda to a simmer and bathe each pretzel for 30 seconds. Drain onto a lined tray, sprinkle with 1 tsp coarse salt and bake at 220°C conventional for 12 minutes until deep golden.","shop":["250g bread flour@Pantry","4g dried yeast@Pantry","1 tsp sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry"]},{"n":"Street corn on the cob","note":"boiled cobs charred on the grill and rolled in butter and salt","how":"Boil 4 small corn cobs in water for 5 minutes. Drain, then char on a hot grill for 5 to 7 minutes, turning often. Roll in 30g softened butter and sprinkle with 1/2 tsp sea salt flakes. Serve one cob each.","shop":["4 small corn cobs@Produce","30g butter@Dairy","1/2 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Brooklyn hot dogs","note":"griddled frankfurts in steamed buns, mustard and sauerkraut, wrapped in yesterday's papers","how":"Griddle 8 hot dog franks over medium-high heat for 6 to 8 minutes until blistered and piping hot. Steam 8 soft hot dog buns for 1 to 2 minutes until warm. Fill each bun with a frank, 1 tsp yellow mustard and a spoonful from 200g drained sauerkraut. Wrap in food-safe newspaper-style paper or baking paper. Serve two each.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","40g yellow mustard@Pantry","200g sauerkraut@Pantry"]}],"w":[{"n":"Apple turnovers","note":"puff pastry squares folded over buttery spiced apple, egg-washed and baked golden","how":"Peel, core and dice 400g apples. Cook with 20g butter, 40g caster sugar and 1/2 tsp cinnamon over medium heat for 10 minutes until tender and fairly dry. Cool. Cut 2 sheets puff pastry into four squares each. Divide filling among the squares, fold diagonally and seal the edges. Brush with 1 beaten egg. Bake at 200°C conventional for 20 minutes until golden. Serve two small turnovers each.","shop":["400g apples@Produce","20g butter@Dairy","40g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Sarsaparilla ice cream spiders","note":"sarsaparilla poured over vanilla until it fizzes into a creamy foam, seize the day","how":"Put a scoop of vanilla ice cream in each of 4 tall glasses. Slowly pour 250ml chilled sarsaparilla over each, letting the foam rise and settle before topping up. Add a second small scoop, serve with long spoons and straws.","shop":["1 litre sarsaparilla@Drinks","1 litre vanilla ice cream@Frozen"]}],"shopping":["250g bread flour@Pantry","4g dried yeast@Pantry","1 tsp sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry","4 small corn cobs@Produce","50g butter@Dairy","1/2 tsp sea salt flakes@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","40g yellow mustard@Pantry","200g sauerkraut@Pantry","400g apples@Produce","40g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","2 sheets puff pastries@Frozen","1 egg@Dairy","1 litre sarsaparilla@Drinks","1 litre vanilla ice cream@Frozen"]}},"You've Got Mail (1998)":{"poster":"assets/menu-posters/youve-got-mail-1998.jpg","colour":"#29523a","servings":4,"tagline":"Two shops, one street, plenty of cheese.","cue":"Serve the snacks when Kathleen opens her first email of the day.","menu":{"s":[{"n":"Publishing party salmon cucumber bites","note":"thick cucumber rounds with lemon dill cream cheese and capers, where Kathleen and Joe first bicker","how":"Cut 2 telegraph cucumbers into 1.5cm rounds and pat dry. Beat 150g cream cheese with 2 tbsp chopped dill and the zest of half a lemon. Pipe or spoon onto each round. Top with a curl of smoked salmon from 200g, a couple of capers, a dill sprig and cracked pepper.","shop":["2 telegraph cucumbers@Produce","150g cream cheese@Dairy","1 bunch dill@Produce","1 lemon@Produce","200g smoked salmon@Seafood","1 tbsp capers@Pantry"]},{"n":"Upper West Side bagels","note":"toasted minis with spring onion and pepper cream cheese, for a dog named Brinkley","how":"Halve and toast 4 mini bagels until golden, about 3 minutes under a medium grill. Whip 120g cream cheese with 2 finely sliced spring onions and 1/4 tsp cracked black pepper. Spread over the eight toasted halves and serve two halves per person.","shop":["4 mini bagels@Bakery","120g cream cheese@Dairy","2 spring onions@Produce","black pepper@Pantry"]}],"m":[{"n":"Fox Books cafe sandwiches","note":"turkey, brie and cranberry pressed on sourdough, sold by the little shop's big rival","how":"Spread 8 slices sourdough with 60g cranberry sauce. Divide 300g sliced cooked turkey and 160g brie among four slices and close the sandwiches. Butter the outsides using 30g softened butter. Press in a hot sandwich pan or frying pan weighted with a second pan for 3 to 4 minutes per side, until golden, the turkey is piping hot and the brie melts. Cut each sandwich in half.","shop":["8 slices sourdough@Bakery","60g cranberry sauce@Pantry","300g sliced cooked turkey@Deli","160g brie@Dairy","30g butter@Dairy"]}],"w":[{"n":"Cafe cheesecake","note":"baked New York style with sugared strawberries, for the date with a book and a rose","how":"Use the remaining three quarters of the baked cheesecake slab prepared and chilled overnight for Cafe cheesecake bites. The shared slab uses 180g digestive biscuits, 75g butter, 600g cream cheese, 140g caster sugar, 150g sour cream, 3 eggs and 1 tsp vanilla extract; make it once only. Slice 250g fresh strawberries and toss with 15g caster sugar. Leave for 20 minutes to macerate. Cut the reserved cheesecake into four dessert slices and serve with the strawberries and their juices.","shop":["shared cheesecake slab, ingredients listed with snack@Dairy","250g strawberries@Produce","15g caster sugar@Pantry"]}],"d":[{"n":"Fox Books cafe cappuccino","note":"a coffee order with lots of decisions","how":"Use 72g decaf coffee beans to brew four double espressos, 60ml each, into warmed tall cups. Steam 600ml full cream milk in batches to 60°C, introducing enough air for a deep foam cap. Divide the steamed milk among the cups and spoon the foam on top. Serve immediately.","shop":["72g decaf coffee beans@Pantry","600ml full cream milk@Dairy"]}],"shopping":["2 telegraph cucumbers@Produce","270g cream cheese@Dairy","1 bunch dill@Produce","1 lemon@Produce","200g smoked salmon@Seafood","1 tbsp capers@Pantry","4 mini bagels@Bakery","2 spring onions@Produce","black pepper@Pantry","8 slices sourdoughs@Bakery","60g cranberry sauce@Pantry","300g sliced cooked turkey@Deli","160g brie@Dairy","30g butter@Dairy","shared cheesecake slab, ingredients listed with snack@Dairy","250g strawberries@Produce","15g caster sugar@Pantry","72g decaf coffee beans@Pantry","600ml full cream milk@Dairy"]}},"When Harry Met Sally... (1989)":{"poster":"assets/menu-posters/when-harry-met-sally-1989.jpg","colour":"#8f202c","servings":4,"tagline":"Twelve years, three cities, one deli lunch.","cue":"Serve the mains when Harry and Sally sit down at Katz's.","menu":{"s":[{"n":"Fried deli pickles with mustard mayo","note":"half-sour spears in crisp rye batter, sharp mustard dip, for the drive to New York","how":"Cut 4 half-sour or dill pickles into spears and pat very dry; keep 1 tsp of the brine. Whisk 80g plain flour, 40g rye flour, 1/2 tsp paprika and 150ml cold soda water into a thin batter. Heat 1 litre vegetable oil to 180°C. Dip the spears and fry in batches for about 2 minutes until crisp. Drain on a rack and salt lightly. Stir 100g mayonnaise with 2 tbsp yellow mustard and the brine and serve alongside.","shop":["4 half-sour or dill pickles@Deli","80g plain flour@Pantry","40g rye flour@Pantry","1/2 tsp paprika@Pantry","150ml soda water@Drinks","1 litre vegetable oil@Pantry","100g mayonnaise@Pantry","30g yellow mustard@Pantry"]},{"n":"Sally's chef salad","note":"dressing on the side, everything on the side","how":"Hard-boil 4 eggs for 10 minutes, cool in cold water, peel and halve. Wash 2 cos lettuces, dry well and tear onto a large platter. Arrange 200g sliced leg ham, 200g sliced turkey, 150g Swiss cheese cut into strips, the eggs, 2 sliced tomatoes and half a sliced cucumber in rows over the lettuce. Pour 60ml olive oil and 30ml red wine vinegar into two little jugs and serve them on the side.","shop":["4 eggs@Dairy","2 cos lettuces@Produce","200g sliced leg ham@Deli","200g sliced turkey@Deli","150g Swiss cheese@Dairy","2 tomatoes@Produce","1 cucumber@Produce","60ml olive oil@Pantry","30ml red wine vinegar@Pantry"]}],"m":[{"n":"Pastrami on rye","note":"steamed glossy, piled high on seeded bread with yellow mustard, I'll have what she's having","how":"Place 600g sliced pastrami in a steamer over gently boiling water and steam for 10 minutes until glossy, soft and piping hot. Spread 8 slices seeded rye bread with 40g yellow mustard. Divide the pastrami between four slices, pile high and close the sandwiches. Serve each with 1 full sour dill pickle on the side.","shop":["600g sliced pastrami@Deli","8 slices seeded rye bread@Bakery","40g yellow mustard@Pantry","4 full sour dill pickles@Pantry"]}],"w":[{"n":"Apple pie à la mode, her way","note":"warm slice with strawberry ice cream alongside, real whipped cream if they don't have it","how":"Cut four slices from a 600g ready-baked apple pie. Warm on a tray at 180°C conventional for 10 minutes. Serve 75ml strawberry ice cream in a separate small bowl beside each slice. If strawberry ice cream is unavailable, softly whip 150ml thickened cream and serve it on the side instead.","shop":["600g ready-baked apple pie@Bakery","300ml strawberry ice cream or 150ml thickened cream@Frozen"]}],"d":[{"n":"Egg cream","note":"chocolate syrup and cold milk with soda water blasted in hard, stirred to a foamy head","how":"Put 25ml chocolate syrup in each of four tall glasses. Pour 100ml very cold full cream milk into each. Add 150ml chilled soda water quickly and stir briskly to form a foamy head. Serve immediately. This drink contains no egg or cream.","shop":["100ml chocolate syrup@Drinks","400ml full cream milk@Dairy","600ml soda water@Drinks"]}],"shopping":["4 half-sour or dill pickles@Deli","80g plain flour@Pantry","40g rye flour@Pantry","1/2 tsp paprika@Pantry","750ml soda water@Drinks","1 litre vegetable oil@Pantry","100g mayonnaise@Pantry","70g yellow mustard@Pantry","4 eggs@Dairy","2 cos lettuces@Produce","200g sliced leg ham@Deli","200g sliced turkey@Deli","150g Swiss cheese@Dairy","2 tomatoes@Produce","1 cucumber@Produce","60ml olive oil@Pantry","30ml red wine vinegar@Pantry","600g sliced pastrami@Deli","8 slices seeded rye bread@Bakery","4 full sour dill pickles@Pantry","600g ready-baked apple pie@Bakery","300ml strawberry ice cream or 150ml thickened cream@Frozen","100ml chocolate syrup@Drinks","400ml full cream milk@Dairy"]}},"The Secret of My Success (1987)":{"poster":"assets/menu-posters/the-secret-of-my-success-1987.jpg","colour":"#236164","servings":4,"tagline":"Mailroom by day. Executive by night.","cue":"Serve the mains when Brantley changes from mailroom clothes to his suit in the lift.","menu":{"s":[{"n":"Mailroom sandwich bites","note":"ham, cheddar and pickle on buttered white, crusts off, cut in fingers, eaten between deliveries","how":"Butter 8 slices of white bread with 30g softened butter. Layer 120g leg ham, 80g cheddar and 50g thinly sliced pickles across four slices. Top with the other slices, trim off the crusts and cut each sandwich into three fingers. Wrap in baking paper and refrigerate until serving.","shop":["8 slices white bread@Bakery","30g butter@Dairy","120g leg ham@Deli","80g cheddar@Dairy","50g pickles@Pantry"]},{"n":"Kansas corn fritters","note":"spoonfuls of kernel batter with spring onion, shallow-fried golden, sour cream for dipping","how":"Cut the kernels from 2 corn cobs, about 200g. Whisk 80g plain flour, 1 tsp baking powder, 1 egg and 60ml milk into a thick batter. Stir in the corn, 2 thinly sliced spring onions and 1/4 tsp salt. Heat 3 tbsp neutral oil in a frying pan over medium heat. Shallow-fry 8 spoonfuls of batter in batches for 3 minutes per side until golden and cooked through. Drain and serve with 100g sour cream for dipping.","shop":["2 corn cobs@Produce","80g plain flour@Pantry","1 tsp baking powder@Pantry","1 egg@Dairy","60ml milk@Dairy","2 spring onions@Produce","salt@Pantry","3 tbsp neutral oil@Pantry","100g sour cream@Dairy"]}],"m":[{"n":"Executive rib eye","note":"dry-brined, seared hard and basted in butter, thyme and garlic, for Brantley's double life upstairs","how":"Pat dry four 200g rib eye steaks. Sprinkle evenly with 1 tsp fine salt and refrigerate uncovered for 4 to 12 hours to dry-brine. Heat a heavy pan over high heat with 1 tbsp neutral oil. Sear the steaks for about 3 minutes per side, cooking in batches. Lower the heat, add 50g butter, 4 thyme sprigs and 3 lightly crushed garlic cloves. Baste repeatedly for 1 to 2 minutes. For medium rare, remove at 54°C in the centre; cook longer if preferred. Rest 8 minutes, then slice and spoon over the pan butter.","shop":["800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","50g butter@Dairy","4 thyme sprigs@Produce","3 garlic cloves@Produce"]}],"w":[{"n":"Kansas apple pie","note":"double crust with cinnamon apples, egg wash and sugar, baked golden, vanilla ice cream","how":"Line a 20cm pie dish with half of 400g sweet shortcrust pastry. Peel, core and slice 600g Granny Smith apples, then toss with 80g caster sugar and 1 tsp cinnamon. Fill the crust, cover with the remaining pastry and crimp. Cut steam vents, brush with 1 beaten egg and sprinkle with 1 tsp extra sugar. Bake at 190°C conventional for 50 minutes until golden and tender. Rest 20 minutes, divide into four portions and serve with 200ml vanilla ice cream.","shop":["400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","1 egg@Dairy","200ml vanilla ice cream@Frozen"]}],"d":[{"n":"Martini","note":"gin and a little dry vermouth, frozen glass, lemon twist, for the weekend party at Vera's","how":"Freeze four martini glasses for 15 minutes. Working in two batches, stir a total of 240ml gin and 40ml dry vermouth with 400g ice for 30 seconds per batch. Strain equally into the frozen glasses. Cut four thin twists from 1 lemon, express their oils over the drinks and garnish each with a twist.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","400g ice@Frozen","1 lemon@Produce"]}],"shopping":["8 slices white bread@Bakery","80g butter@Dairy","120g leg ham@Deli","80g cheddar@Dairy","50g pickles@Pantry","2 corn cobs@Produce","80g plain flour@Pantry","1 tsp baking powder@Pantry","2 eggs@Dairy","60ml milk@Dairy","2 spring onions@Produce","fine salt@Pantry","4 tbsp neutral oil@Pantry","100g sour cream@Dairy","800g rib eye steak@Meat","4 thyme sprigs@Produce","3 garlic cloves@Produce","400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","200ml vanilla ice cream@Frozen","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","400g ice@Frozen","1 lemon@Produce"]}},"The Adjustment Bureau (2011)":{"poster":"assets/menu-posters/the-adjustment-bureau-2011.jpg","colour":"#8d4e2e","servings":4,"tagline":"Fate has a plan. So does dessert.","cue":"Serve the snacks when David meets Elise on the bus.","menu":{"s":[{"n":"Hot honey-roasted nuts","note":"mixed nuts glazed with butter, sugar and cinnamon, in paper cones for the bus ride","how":"Melt 30g butter with 2 tbsp honey, 1 tbsp brown sugar, a pinch of cinnamon and 1/2 tsp salt. Toss through 300g mixed nuts, spread on a lined tray and roast at 170C for 12 minutes, stirring halfway. Cool for 5 minutes so they crisp, then pour into paper cones.","shop":["300g mixed nuts@Pantry","30g butter@Dairy","2 tbsp honey@Pantry","1 tbsp brown sugar@Pantry","1 pinch ground cinnamon@Pantry"]},{"n":"Bureau men's rooftop crostini","note":"keep your hat on, it opens the doors","how":"Cut half a baguette, about 150g, into 8 slices. Toast at 200°C conventional for 5 to 7 minutes until golden. Beat 120g soft goat's cheese with 30ml thickened cream until light. Warm 30g honey gently for 30 seconds. Spread the cheese on the toast, drizzle with warm honey and finish with 1 tsp thyme leaves and 1/4 tsp cracked black pepper.","shop":["150g baguette@Bakery","120g soft goat's cheese@Dairy","30ml thickened cream@Dairy","30g honey@Pantry","1 tsp thyme leaves@Produce","black pepper@Pantry"]}],"m":[{"n":"Manhattan steak frites","note":"seared sirloin under shallot red wine butter, double-fried chips, the date the plan won't allow","how":"Finely dice 2 shallots and simmer with 80ml red wine in a small pan for 8 minutes until almost dry. Cool, then mix into 60g softened butter with a pinch of salt. Chill. Cut 800g potatoes into frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool 15 minutes; fry again at 185°C for 3 minutes until crisp. Salt lightly. Season four 200g sirloin steaks, sear hard in a hot pan with 1 tbsp oil for about 3 minutes each side to your preferred doneness, then rest 8 minutes. Slice and top with the shallot red wine butter; serve with frites.","shop":["2 shallots@Produce","80ml red wine@Bottle shop","60g butter@Dairy","salt@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","800g sirloin steak@Meat"]}],"w":[{"n":"The Chairman's chocolate fondant","note":"dark chocolate and butter cake baked hot so the centre stays molten","how":"Butter four 150ml moulds using 10g extra butter. Heat the oven to 200°C conventional. Melt 125g dark chocolate with 125g butter gently and cool slightly. Whisk 2 whole eggs and 2 yolks with 60g caster sugar until pale. Stir in the chocolate mixture, then fold in 30g plain flour. Divide among the moulds and bake for 10 minutes until the edges are set and centres remain soft. Rest 1 minute, loosen the edges and carefully turn onto plates. Serve immediately.","shop":["125g dark chocolate@Pantry","135g butter@Dairy","4 eggs, 2 whole and 2 yolks@Dairy","60g caster sugar@Pantry","30g plain flour@Pantry"]}],"d":[{"n":"Election night French 75","note":"gin, lemon and sugar shaken and topped with brut in flutes, for the concession speech","how":"Dissolve 40g caster sugar in 40ml hot water and cool. Shake 120ml gin, 60ml lemon juice and 40ml syrup with ice for 10 seconds. Strain evenly into 4 chilled flutes. Top each with 90ml cold brut champagne, pouring slowly. Finish with a long strip of lemon peel.","shop":["120ml gin@Bottle shop","2 lemons@Produce","40g caster sugar@Pantry","1 bottle brut champagne@Bottle shop","1 bag ice@Frozen"]}],"shopping":["300g mixed nuts@Pantry","225g butter@Dairy","2 tbsp honey@Pantry","1 tbsp brown sugar@Pantry","1 pinch ground cinnamon@Pantry","150g baguette@Bakery","120g soft goat's cheese@Dairy","30ml thickened cream@Dairy","30g honey@Pantry","1 tsp thyme leaves@Produce","black pepper@Pantry","2 shallots@Produce","80ml red wine@Bottle shop","salt@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","800g sirloin steak@Meat","125g dark chocolate@Pantry","4 eggs, 2 whole and 2 yolks@Dairy","100g caster sugar@Pantry","30g plain flour@Pantry","120ml gin@Bottle shop","2 lemons@Produce","1 bottle brut champagne@Bottle shop","1 bag ice@Frozen"]}},"Frequency (2000)":{"poster":"assets/menu-posters/frequency-2000.jpg","colour":"#225444","servings":4,"tagline":"Father and son. Same radio. Same pizza.","cue":"Serve dinner during the 1969 World Series broadcast.","menu":{"s":[{"n":"Firehouse chilli bites","note":"beef chilli in baked wonton cups under melted cheddar, for Frank between call-outs","how":"Press 12 wonton wrappers into a lightly oiled mini muffin tin. Bake at 180°C conventional for 7 minutes until crisp. Brown 200g beef mince in 1 tsp oil for 5 minutes, add 1/2 diced onion and cook 3 minutes. Stir in 1 tsp chilli powder, 200g chopped tinned tomatoes and 120g drained kidney beans. Simmer 15 minutes until thick. Spoon into the baked cups, top with 60g grated cheddar and return to the oven for 3 minutes to melt. Serve three cups each.","shop":["12 wonton wrappers@Pantry","neutral oil@Pantry","200g beef mince@Meat","1/2 onion@Produce","1 tsp chilli powder@Pantry","200g tinned tomatoes@Pantry","120g drained kidney beans@Pantry","60g cheddar@Dairy"]},{"n":"Miracle Mets pretzels with beer mustard","note":"glossy bicarb-bathed soft knots with coarse salt and a sharp beer and wholegrain dip","how":"Mix 500g plain flour, 7g dried yeast, 1 tsp sugar, 1 tsp salt and 300ml warm water, knead 8 minutes and rise 1 hour. Shape 8 pretzels. Boil each for 30 seconds in 2 litres water with 60g bicarb, drain, sprinkle with coarse salt and bake at 220C for 12 to 14 minutes. Mix 100g wholegrain mustard, 2 tbsp lager and 1 tbsp honey for the dip.","shop":["500g plain flour@Pantry","7g dried yeast@Pantry","60g bicarbonate of soda@Pantry","coarse salt@Pantry","100g wholegrain mustard@Pantry","1 bottle lager@Bottle shop","1 tbsp honey@Pantry"]}],"m":[{"n":"Queens pizza","note":"thin base, crushed tomato, mozzarella and crumbled sausage, baked fast, eaten by the ham radio","how":"Mix 380g bread flour, 2g dried yeast, 1 tsp salt and 245ml cool water; knead 8 minutes. Divide into two balls and refrigerate covered for 24 to 48 hours to cold-ferment. Bring to room temperature for 2 hours. Heat a pizza steel at the oven's maximum temperature, about 250 to 275°C, for 45 minutes. Remove 200g Italian sausages from their casings and crumble; pan-fry 5 minutes until cooked. Stretch the dough thin into two pizzas. Top with 200g crushed tomatoes, 200g low-moisture mozzarella and the sausage, dividing evenly. Bake each on the steel for about 7 minutes until crisp and cooked. Cut into wedges for four people.","shop":["380g bread flour@Pantry","2g dried yeast@Pantry","1 tsp salt@Pantry","200g Italian sausages@Meat","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy"]}],"w":[{"n":"Julia's apple pie","note":"Granny Smiths and cinnamon in a double crust, egg washed, for a 1969 kitchen","how":"Line a 20cm pie dish with half of 400g sweet shortcrust pastry. Peel, core and thinly slice 600g Granny Smith apples. Toss with 80g caster sugar, 1 tsp cinnamon and 15g plain flour. Fill the pastry, cover with the remaining pastry and crimp the edges. Cut two steam vents, brush with 1 beaten egg and sprinkle with 1 tsp extra sugar. Bake at 190°C conventional for 50 minutes until golden and the apples are tender. Rest 20 minutes and cut into four portions.","shop":["400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","15g plain flour@Pantry","1 egg@Dairy"]}],"d":[{"n":"Firehouse lemon shandy","note":"cold lager topped with homemade lemonade and mint, for nine innings of the '69 Series","how":"Stir 100ml lemon juice, 80g caster sugar and 300ml cold water until the sugar dissolves. Chill 4 glasses in the freezer for 20 minutes. Pour 200ml cold lager into each glass and top with 100ml lemonade. Add a sprig of mint and a lemon wheel.","shop":["4 bottles lager@Bottle shop","3 lemons@Produce","80g caster sugar@Pantry","4 sprigs mint@Produce"]}],"shopping":["12 wonton wrappers@Pantry","neutral oil@Pantry","200g beef mince@Meat","1/2 onion@Produce","1 tsp chilli powder@Pantry","200g tinned tomatoes@Pantry","120g drained kidney beans@Pantry","60g cheddar@Dairy","515g plain flour@Pantry","9g dried yeast@Pantry","60g bicarbonate of soda@Pantry","coarse salt@Pantry","100g wholegrain mustard@Pantry","1 bottle lager@Bottle shop","1 tbsp honey@Pantry","380g bread flour@Pantry","1 tsp salt@Pantry","200g Italian sausages@Meat","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy","400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","165g caster sugar@Pantry","1 tsp cinnamon@Pantry","1 egg@Dairy","4 bottles lagers@Bottle shop","3 lemons@Produce","4 sprigs mints@Produce"]}},"After Hours (1985)":{"poster":"assets/menu-posters/after-hours-1985.jpg","colour":"#c04c19","servings":4,"tagline":"It's after midnight. Do you know where your dinner is?","cue":"Serve the bagels when Paul demands to see the bagel and cream cheese paperweights.","menu":{"s":[{"n":"Bagel paperweight bites with chive schmear","note":"Kiki's plaster bagel-and-cream-cheese paperweights, but edible","how":"Halve 8 mini bagels and toast until golden. Beat 250g cream cheese with 2 tbsp milk, 3 tbsp snipped chives and plenty of black pepper. Pipe or spread thickly onto the bagels. Top with 150g smoked salmon, a few capers and everything bagel seasoning made from sesame, poppy seeds, garlic flakes and salt.","shop":["8 mini bagels@Bakery","250g cream cheese@Dairy","1 bunch chives@Produce","150g smoked salmon@Seafood","1 tbsp capers@Pantry","sesame seeds@Pantry","poppy seeds@Pantry","garlic flakes@Pantry"]},{"n":"Mob truck choc-dipped sundae cones","note":"the angry mob chasing Paul in the ice cream truck","how":"Soften 1 litre vanilla ice cream for 10 minutes. Melt 150g dark chocolate with 40ml coconut oil and cool to room temperature. Pipe the ice cream into 8 cones with a large star nozzle and freeze for 20 minutes. Dip the tops into the chocolate, then straight into 50g crushed roasted peanuts or sprinkles. Freeze 5 minutes to set.","shop":["1 litre vanilla ice cream@Frozen","8 ice cream cones@Pantry","150g dark chocolate@Pantry","40ml coconut oil@Pantry","50g roasted peanuts@Pantry","sprinkles@Pantry"]}],"m":[{"n":"Last Stop burger","note":"thick chuck patty, cheddar, raw onion and pickles, for a long night in SoHo","how":"Hand-form 600g beef chuck mince into four thick patties without overworking. Heat a griddle over medium-high heat. Season with 1/2 tsp salt and 1/4 tsp pepper just before cooking. Griddle for 5 to 6 minutes each side until cooked through, checking the centre reaches 75°C. Top with 80g cheddar in the last minute. Toast 4 burger buns cut-side down. Assemble with the patties, 1 thinly sliced raw onion and 80g sliced dill pickles.","shop":["600g beef chuck mince@Meat","salt@Pantry","black pepper@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","1 onion@Produce","80g dill pickles@Pantry"]}],"w":[{"n":"White frosted plaster cake","note":"vanilla cake under thick matte meringue icing, roughly smoothed, before Paul ends up in papier mâché","how":"Heat the oven to 180°C conventional and line a 16cm cake tin. Beat 100g softened butter with 100g caster sugar until pale. Beat in 2 eggs and 1 tsp vanilla extract, then fold in 120g self-raising flour and 30ml milk. Bake for 30 to 35 minutes until a skewer comes out clean; cool completely. For seven-minute frosting, whisk 2 egg whites, 120g caster sugar and 1 tbsp water in a heatproof bowl over gently simmering water for 7 minutes, until thick, glossy and hot throughout. Remove from the heat and whisk 2 minutes more until stiff. Cover the cake in a thick matte-looking layer, roughly smoothing it like plaster. Cut into four pieces.","shop":["100g butter@Dairy","220g caster sugar@Pantry","4 eggs, 2 whole and 2 whites@Dairy","1 tsp vanilla extract@Pantry","120g self-raising flour@Pantry","30ml milk@Dairy"]}],"d":[{"n":"Terminal Bar whiskey sour","note":"bourbon, lemon and egg white shaken silky, bitters, cherry, after the twenty blows out the cab","how":"Dissolve 50g caster sugar in 50ml hot water and cool. Shake 180ml bourbon, 90ml lemon juice, 60ml syrup and 1 egg white hard without ice for 15 seconds, then with ice for 15 seconds. Strain into 4 ice-filled rocks glasses. Add 2 drops aromatic bitters to each foam and a cocktail cherry.","shop":["180ml bourbon@Bottle shop","4 lemons@Produce","50g caster sugar@Pantry","1 egg@Dairy","aromatic bitters@Bottle shop","4 cocktail cherries@Pantry","1 bag ice@Frozen"]}],"shopping":["8 mini bagels@Bakery","250g cream cheese@Dairy","1 bunch chives@Produce","150g smoked salmon@Seafood","1 tbsp capers@Pantry","sesame seeds@Pantry","poppy seeds@Pantry","garlic flakes@Pantry","1 litre vanilla ice cream@Frozen","8 ice cream cones@Pantry","150g dark chocolate@Pantry","40ml coconut oil@Pantry","50g roasted peanuts@Pantry","sprinkles@Pantry","600g beef chuck mince@Meat","salt@Pantry","black pepper@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","1 onion@Produce","80g dill pickles@Pantry","100g butter@Dairy","270g caster sugar@Pantry","4 eggs, 2 whole and 2 whites@Dairy","1 tsp vanilla extract@Pantry","120g self-raising flour@Pantry","30ml milk@Dairy","180ml bourbon@Bottle shop","4 lemons@Produce","1 egg@Dairy","aromatic bitters@Bottle shop","4 cocktail cherries@Pantry","1 bag ice@Frozen"]}},"King of New York (1990)":{"poster":"assets/menu-posters/king-of-new-york-1990.jpg","colour":"#16395c","servings":4,"tagline":"Uptown deals. Downtown appetite.","cue":"Serve the mains when Frank checks back into his hotel suite.","menu":{"s":[{"n":"Chinatown dumplings","note":"pork and chive parcels, crisp-bottomed and steamed, black vinegar dip, before the triad war","how":"Heat 1 tbsp neutral oil in a non-stick pan over medium-high heat. Add 12 frozen pork and chive dumplings and pan-fry for 3 minutes until their bottoms crisp. Add 80ml water and immediately cover. Steam for 7 to 9 minutes, or the packet time, until cooked through; remove the lid and let the water evaporate. Mix 2 tbsp black vinegar, 1 tbsp soy sauce and 1 tsp chilli oil for dipping.","shop":["12 frozen pork and chive dumplings@Frozen","1 tbsp neutral oil@Pantry","2 tbsp black vinegar@Pantry","1 tbsp soy sauce@Pantry","1 tsp chilli oil@Pantry"]},{"n":"Hotel suite prawn cocktail","note":"poached prawns on iceberg, sharp horseradish cocktail sauce, for Frank's release from Sing Sing","how":"Poach 500g green prawns in simmering salted water for 2 minutes, plunge into iced water, peel and chill. Mix 125ml tomato sauce with 2 tsp horseradish, the juice of half a lemon and a dash of Worcestershire. Fill 4 glasses with shredded iceberg, hang the prawns over the rims and spoon the sauce in the middle.","shop":["500g green prawns@Seafood","125ml tomato sauce@Pantry","2 tsp horseradish@Pantry","1 lemon@Produce","1 iceberg lettuce@Produce"]}],"m":[{"n":"Frank's suite steak dinner","note":"seared rib eye, cracked pepper, brandy and cream sauce, chips, room service for the crew","how":"Cut 800g potatoes into thin frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool, then fry at 185°C for 3 minutes until crisp. Season with salt. Pat dry four 200g rib eye steaks and season. Heat 1 tbsp neutral oil in a heavy pan, sear the steaks for about 3 minutes each side to your preferred doneness, then rest 8 minutes. For sauce, add 1 tsp cracked black peppercorns to the pan, then carefully add 40ml brandy away from the flame. Simmer 1 minute, add 150ml beef stock and reduce for 5 minutes. Add 100ml thickened cream and simmer 3 minutes. Serve steaks with sauce and frites.","shop":["800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g rib eye steak@Meat","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy"]}],"w":[{"n":"New York cheesecake","note":"dense baked cream cheese, sour cream and lemon on a biscuit base","how":"Line a 16cm springform tin and wrap the outside tightly in two layers of foil. Crush 120g digestive biscuits, mix with 50g melted butter and press into the base. Beat 450g cream cheese with 100g caster sugar until smooth, then beat in 80g sour cream, 2 eggs and zest of 1 lemon. Pour into the tin. Put the tin in a roasting pan and add hot water halfway up its sides. Bake at 150°C conventional for 70 minutes until the edges are set and the centre gently wobbles. Turn off the oven, leave the door ajar and cool inside for 1 hour. Refrigerate overnight. Cut into four generous slices.","shop":["120g digestive biscuits@Pantry","50g butter@Dairy","450g cream cheese@Dairy","100g caster sugar@Pantry","80g sour cream@Dairy","2 eggs@Dairy","1 lemon@Produce"]}],"d":[{"n":"Frank's suite champagne cocktails","note":"bitters-soaked sugar cube and a splash of cognac, topped with brut and a lemon twist","how":"Put a sugar cube in each of 4 flutes and shake 2 dashes of aromatic bitters onto each. Add 15ml cognac to each glass. Top slowly with 120ml chilled brut champagne, letting the sugar fizz. Twist a strip of lemon peel over each glass and drop it in.","shop":["4 sugar cubes@Pantry","aromatic bitters@Bottle shop","60ml cognac@Bottle shop","1 bottle brut champagne@Bottle shop","1 lemon@Produce"]}],"shopping":["12 frozen pork and chive dumplings@Frozen","1 tbsp neutral oil@Pantry","2 tbsp black vinegar@Pantry","1 tbsp soy sauce@Pantry","1 tsp chilli oil@Pantry","500g green prawns@Seafood","125ml tomato sauce@Pantry","2 tsp horseradish@Pantry","3 lemons@Produce","1 iceberg lettuce@Produce","800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g rib eye steak@Meat","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy","120g digestive biscuits@Pantry","50g butter@Dairy","450g cream cheese@Dairy","100g caster sugar@Pantry","80g sour cream@Dairy","2 eggs@Dairy","4 sugar cubes@Pantry","aromatic bitters@Bottle shop","60ml cognac@Bottle shop","1 bottle brut champagne@Bottle shop"]}},"Spider-Man 2 (2004)":{"poster":"assets/menu-posters/spider-man-2-2004.jpg","colour":"#a11f26","servings":4,"tagline":"Late again. Pizza's still hot.","cue":"Order the pizza when Peter drops the boxes on the desk. Pizza time!","menu":{"s":[{"n":"Joe's Pizza garlic knots","note":"tied dough strips baked hot, garlic butter and parsley, delivered in under 29 minutes","how":"Cut 300g pizza dough into 8 strips and tie into knots. Cover on a lined tray and prove 30 minutes. Bake at 230°C conventional for 12 minutes until golden. Melt 40g butter with 2 crushed garlic cloves over low heat for 2 minutes. Toss the hot knots in the garlic butter and 2 tbsp chopped parsley.","shop":["300g pizza dough@Bakery","40g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce"]},{"n":"Potato knishes","note":"mashed potato and fried onion wrapped in thin dough, egg washed, baked golden, mustard alongside","how":"Boil 700g potatoes and mash with 1 onion fried soft in 30g butter, plus salt and pepper. Cut 2 sheets puff pastry into 8, put a mound of potato on each, fold up and pinch closed. Brush with 1 beaten egg and bake at 200C for 25 minutes. Serve hot with yellow mustard.","shop":["700g potatoes@Produce","1 onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","4 tbsp yellow mustard@Pantry"]}],"m":[{"n":"Thirty-minute pepperoni pie","note":"Joe's Pizza, late again","how":"Mix 380g bread flour, 2g dried yeast, 1 tsp salt and 245ml cool water. Knead 8 minutes, divide into 2 balls and refrigerate covered for 24 to 48 hours to cold-ferment. Bring to room temperature for 2 hours. Heat a pizza steel in the oven at its maximum temperature, about 250 to 275°C, for 45 minutes. Stretch each dough ball thin. Spread each with half of 200g crushed tomatoes and top with half of 200g low-moisture mozzarella and 100g thinly sliced cupping pepperoni. Bake one at a time on the hot steel for about 7 minutes, until the crust is cooked and crisp. Cut both pizzas into wedges for four people.","shop":["380g bread flour@Pantry","2g dried yeast@Pantry","1 tsp salt@Pantry","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Aunt May's pancakes","note":"butter and syrup for her boy","how":"Separate 2 eggs. Mix 150g plain flour, 1 tsp baking powder, 20g sugar and a pinch of salt. Whisk the yolks with 180ml buttermilk and fold into the flour. Whip the whites to soft peaks and gently fold through. Melt a little of 30g butter in a frying pan over medium heat. Cook eight small pancakes in batches, about 2 minutes until bubbles set, then flip and cook 1 minute. Stack two per person and serve with 80ml maple syrup.","shop":["2 eggs@Dairy","150g plain flour@Pantry","1 tsp baking powder@Pantry","20g sugar@Pantry","salt@Pantry","180ml buttermilk@Dairy","30g butter@Dairy","80ml maple syrup@Pantry"]}],"d":[{"n":"Iced coffee","note":"cold brew over ice with milk and vanilla ice cream, for a man running late, always","how":"Steep 80g coarsely ground coffee beans in 800ml cold water, covered in the fridge, for 12 to 18 hours. Strain through a coffee filter. Divide 400g ice between four glasses, add 150ml cold brew and 100ml full cream milk to each, then top each with 50ml vanilla ice cream. Refrigerate leftover cold brew.","shop":["80g coffee beans@Pantry","400g ice@Frozen","400ml full cream milk@Dairy","200ml vanilla ice cream@Frozen"]}],"shopping":["300g pizza dough@Bakery","100g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce","700g potatoes@Produce","1 onion@Produce","2 sheets puff pastry@Frozen","1 egg@Dairy","4 tbsp yellow mustard@Pantry","380g bread flour@Pantry","2g dried yeast@Pantry","1 tsp salt@Pantry","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy","100g pepperoni@Deli","2 eggs@Dairy","150g plain flour@Pantry","1 tsp baking powder@Pantry","20g sugar@Pantry","salt@Pantry","180ml buttermilk@Dairy","80ml maple syrup@Pantry","80g coffee beans@Pantry","400g ice@Frozen","400ml full cream milk@Dairy","200ml vanilla ice cream@Frozen"]}},"Prizzi's Honor (1985)":{"poster":"assets/menu-posters/prizzis-honor-1985.jpg","colour":"#6c2025","servings":4,"tagline":"Love, honour and a very complicated wedding.","cue":"Serve dessert at the wedding, when Charley first spots Irene.","menu":{"s":[{"n":"Prizzi wedding antipasto","note":"olives, salami and marinated mushrooms for the reception","how":"Blanch 200g button mushrooms in boiling water for 1 minute and drain well. Toss with 2 tbsp olive oil, juice of half a lemon, 1 crushed garlic clove and 1 tbsp chopped parsley. Refrigerate covered overnight. Serve on a platter with 100g salami, 120g mixed olives and 150g drained marinated artichokes for four people.","shop":["200g button mushrooms@Produce","2 tbsp olive oil@Pantry","1/2 lemon@Produce","1 garlic clove@Produce","1 tbsp parsley@Produce","100g salami@Deli","120g mixed olives@Deli","150g marinated artichokes@Pantry"]},{"n":"Fried zucchini","note":"church hall wedding style","how":"Cut 2 medium zucchini, about 400g, into batons and pat dry. Toss with 30g plain flour. Whisk 100g plain flour with 150ml cold sparkling water to a light batter. Heat neutral oil in a deep sturdy pan to 185°C. Dip the batons in batter and fry in small batches for 3 minutes until crisp and golden. Drain, season with 1/4 tsp salt and serve with the remaining half lemon cut into wedges.","shop":["400g zucchini@Produce","130g plain flour@Pantry","150ml sparkling water@Drinks","neutral oil for frying@Pantry","salt@Pantry","1/2 lemon@Produce"]}],"m":[{"n":"Don Corrado's baked ziti","note":"pasta tubes in sausage sugo with ricotta and mozzarella, baked blistered, the old man's way","how":"Remove 400g Italian sausages from their casings. Brown in 1 tbsp olive oil for 8 minutes, breaking up the meat. Add 1 diced onion and cook 5 minutes, then 2 crushed garlic cloves for 1 minute. Add 700g passata, 150ml water and 1 tsp dried oregano. Simmer gently for 45 minutes, stirring. Boil 350g ziti or penne for 2 minutes less than the packet time. Mix 250g ricotta with 1/4 tsp each salt and pepper. Layer the pasta and sausage sugo with spoonfuls of ricotta in an ovenproof dish, scattering 200g mozzarella between layers and over the top. Bake at 200°C conventional for 25 minutes until piping hot and blistered; rest 10 minutes before serving.","shop":["400g Italian sausages@Meat","1 tbsp olive oil@Pantry","1 onion@Produce","2 garlic cloves@Produce","700g passata@Pantry","1 tsp dried oregano@Pantry","350g ziti or penne@Pantry","250g ricotta@Dairy","salt@Pantry","black pepper@Pantry","200g mozzarella@Dairy"]}],"w":[{"n":"Wedding almond cookies","note":"chewy almond amaretti rolled in icing sugar and crackled, wrapped in tulle as bomboniere","how":"Heat the oven to 170°C conventional. Whisk 2 egg whites to stiff peaks in a clean bowl. Gently fold in 250g almond meal, 200g caster sugar and 1/2 tsp almond extract. Shape into 20 small balls, roll in 40g icing sugar and space on lined trays. Bake 15 minutes until crackled and lightly golden. Cool on the trays for 10 minutes, then transfer to a rack. Serve five small cookies each, or save extras in an airtight tin.","shop":["2 eggs, whites only@Dairy","250g almond meal@Pantry","200g caster sugar@Pantry","1/2 tsp almond extract@Pantry","40g icing sugar@Pantry"]}],"d":[{"n":"Prizzi wedding white peach Bellini","note":"ripe peach purée with lemon topped with prosecco, for the moment Charley spots Irene","how":"Peel and stone 2 ripe white peaches. Blend with 2 tsp lemon juice and 1 tsp caster sugar until smooth, then chill for 30 minutes. Spoon 40ml purée into each of 4 chilled flutes. Top slowly with 120ml prosecco each, pouring down the side of the glass. Stir once with a long spoon and serve straight away.","shop":["2 white peaches@Produce","1 lemon@Produce","1 tsp caster sugar@Pantry","1 bottle prosecco@Bottle shop"]}],"shopping":["200g button mushrooms@Produce","3 tbsp olive oil@Pantry","1/2 lemon@Produce","1 garlic clove@Produce","1 tbsp parsley@Produce","100g salami@Deli","120g mixed olives@Deli","150g marinated artichokes@Pantry","400g zucchini@Produce","130g plain flour@Pantry","150ml sparkling water@Drinks","neutral oil for frying@Pantry","salt@Pantry","400g Italian sausages@Meat","1 onion@Produce","2 garlic cloves@Produce","700g passata@Pantry","1 tsp dried oregano@Pantry","350g ziti or penne@Pantry","250g ricotta@Dairy","black pepper@Pantry","200g mozzarella@Dairy","2 eggs, whites only@Dairy","250g almond meal@Pantry","200g caster sugar@Pantry","1/2 tsp almond extract@Pantry","40g icing sugar@Pantry","2 white peaches@Produce","1 lemon@Produce","1 tsp caster sugar@Pantry","1 bottle prosecco@Bottle shop"]}},"A Bronx Tale (1993)":{"poster":"assets/menu-posters/a-bronx-tale-1993.jpg","colour":"#6b201b","servings":4,"tagline":"Two fathers, one neighbourhood, plenty of gravy.","cue":"Do the car door test before dessert comes out.","menu":{"s":[{"n":"Chez Bippy provolone-stuffed fried olives","note":"bar food from Sonny's place, Chez Bippy","how":"Drain 24 large pitted green olives and pat dry. Cut 80g sharp provolone into small sticks and push one into each olive. Roll in 40g plain flour, dip in 1 beaten egg, then coat in 80g fine breadcrumbs. Heat oil to 180C and fry in two batches for 2 minutes until deep golden, then drain. Stir the zest and juice of half a lemon and 1 crushed garlic clove into 100g mayonnaise. Dust the olives with chilli flakes and serve with the aioli.","shop":["24 large pitted green olives@Deli","80g sharp provolone@Deli","40g plain flour@Pantry","1 egg@Dairy","80g fine breadcrumbs@Pantry","1 lemon@Produce","1 garlic clove@Produce","100g whole-egg mayonnaise@Pantry","chilli flakes@Pantry","1 litre vegetable oil@Pantry"]},{"n":"Doo-wop garlic knots","note":"eaten on the stoop while the street corner singers warm up","how":"Cut 400g pizza dough into 12 strips and tie each in a loose knot. Place on a lined tray, cover and prove in a warm place for 30 minutes. Bake at 230°C conventional for 12 minutes until golden. Melt 50g butter with 2 finely minced garlic cloves over low heat for 2 minutes. Toss the hot knots straight from the oven with the garlic butter, 2 tbsp chopped parsley and 30g finely grated parmesan.","shop":["400g pizza dough@Bakery","50g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce","30g parmesan@Dairy"]}],"m":[{"n":"Sonny's Sunday rigatoni","note":"gravy and meatballs at the neighbourhood boss's table","how":"Mix 400g pork and beef mince with 1 egg, 40g breadcrumbs, 1/2 tsp salt and 1/4 tsp black pepper; shape into 12 meatballs. Brown the meatballs and 400g pork ribs in 2 tbsp olive oil in a heavy pot for 8 minutes, turning, then set aside. Soften 1 diced onion for 5 minutes, add 3 sliced garlic cloves for 1 minute, then add 800g tinned tomatoes, 200ml water and 10 basil leaves. Return the meat, cover partly and simmer gently for 2 hours, stirring occasionally and adding water if needed. Check the ribs are tender and the meatballs are cooked through. Boil 400g rigatoni in salted water for the packet time, drain and toss with sauce. Serve the meat on a platter with the pasta.","shop":["400g pork and beef mince@Meat","400g pork ribs@Meat","1 egg@Dairy","40g breadcrumbs@Pantry","salt@Pantry","black pepper@Pantry","2 tbsp olive oil@Pantry","1 onion@Produce","3 garlic cloves@Produce","800g tinned tomatoes@Pantry","10 basil leaves@Produce","400g rigatoni@Pantry"]}],"w":[{"n":"Arthur Avenue cannoli","note":"a box from Belmont's bakery for Sonny","how":"Drain 250g fresh ricotta in a lined sieve in the fridge for at least 2 hours. Beat with 40g icing sugar and 1/2 tsp vanilla extract until smooth; fold in 30g mini chocolate chips. Pipe into 8 small bought cannoli shells just before serving. Dip the ends in 30g finely crushed pistachios. Serve two small cannoli per person.","shop":["250g fresh ricotta@Dairy","40g icing sugar@Pantry","1/2 tsp vanilla extract@Pantry","30g mini chocolate chips@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Espresso with anisette","note":"short black, anisette on the side, lemon curl, the saddest thing is wasted talent","how":"Use 36g espresso beans to brew four 30ml short espressos into warmed demitasse cups. Serve 15ml anisette or sambuca beside each cup for pouring in. Cut four small curls from the remaining peel of the lemon used for the olives, avoiding bitter white pith, and serve one with each coffee.","shop":["36g espresso beans@Pantry","60ml anisette or sambuca@Bottle shop","1 lemon shared with snacks@Produce"]}],"shopping":["24 large pitted green olives@Deli","80g sharp provolone@Deli","40g plain flour@Pantry","2 eggs@Dairy","80g fine breadcrumbs@Pantry","1 lemon@Produce","1 garlic clove@Produce","100g whole-egg mayonnaise@Pantry","chilli flakes@Pantry","1 litre vegetable oil@Pantry","400g pizza dough@Bakery","50g butter@Dairy","5 garlic cloves@Produce","2 tbsp parsley@Produce","30g parmesan@Dairy","400g pork and beef mince@Meat","400g pork ribs@Meat","40g breadcrumbs@Pantry","salt@Pantry","black pepper@Pantry","2 tbsp olive oil@Pantry","1 onion@Produce","800g tinned tomatoes@Pantry","10 basil leaves@Produce","400g rigatoni@Pantry","250g fresh ricotta@Dairy","40g icing sugar@Pantry","1/2 tsp vanilla extract@Pantry","30g mini chocolate chips@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry","36g espresso beans@Pantry","60ml anisette or sambuca@Bottle shop","1 lemon shared with snacks@Produce"]}},"Con Air (1997)":{"poster":"assets/menu-posters/con-air-1997.jpg","colour":"#b86427","servings":4,"tagline":"One flight. Every convict. One bunny.","cue":"Serve dessert when Poe boards the plane with the bunny.","menu":{"s":[{"n":"Jailbird peanuts","note":"Honey roasted peanuts with chilli flakes and smoked salt","how":"Toss 300g honey-roasted peanuts with half a tsp chilli flakes and a pinch of smoked salt. Warm on a tray at 160C for 5 minutes, then cool for a few minutes. Divide between four small paper bags.","shop":["300g honey-roasted peanuts@Pantry","1 jar chilli flakes@Pantry","1 jar smoked salt@Pantry"]},{"n":"Vegas strip prawns","note":"Poached prawns served cold with horseradish cocktail sauce","how":"Poach 500g green prawns for 2 minutes, plunge into iced water and peel. Mix 100ml tomato sauce with 1 tbsp horseradish, lemon juice and a dash of hot sauce. Serve on shredded iceberg in martini glasses with lemon wedges.","shop":["500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 bottle tomato sauce@Pantry","1 jar horseradish@Pantry","2 lemons@Produce","1 bottle hot sauce@Pantry"]}],"m":[{"n":"Vegas buffet steak","note":"Seared sirloin with garlic butter, plus a baked potato","how":"Bake 4 large potatoes at 200C for an hour. Sear 4 sirloins hard and rest 5 minutes. Mash 60g butter with 2 garlic cloves and put a slice on each steak. Split the potatoes and load with sour cream and chives.","shop":["4 potatoes@Produce","4 sirloin steaks@Meat","60g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","1 bunch chives@Produce"]}],"w":[{"n":"Bunny cake","note":"Sponge cake with buttercream and coconut, cut and shaped like a rabbit","how":"Cut a round sponge cake into a body and two ears. Beat 200g butter with 350g icing sugar and cover the cake. Press 100g shredded coconut all over. Tint a little coconut pink for the ears and put it in a box with a bow.","shop":["1 sponge cake@Bakery","200g butter@Dairy","350g icing sugar@Pantry","100g shredded coconut@Pantry","1 bottle pink food colouring@Pantry"]}],"d":[{"n":"Cyrus the Virus bourbon smash","note":"Bourbon shaken with muddled lemon, mint and sugar syrup over ice","how":"In a shaker, muddle 1 lemon cut into 8 wedges with 12 mint leaves and 60ml sugar syrup. Add 200ml bourbon and a scoop of ice and shake for 10 seconds. Strain into 4 tumblers packed with crushed ice. Top each with a big sprig of mint, slapped between your hands first to wake it up.","shop":["200ml bourbon@Bottle shop","1 lemon@Produce","1 bunch mint@Produce","60ml sugar syrup@Pantry","1 bag crushed ice@Frozen"]}],"shopping":["300g honey-roasted peanuts@Pantry","1 jar chilli flakes@Pantry","1 jar smoked salt@Pantry","500g green prawns@Seafood","0.5 iceberg lettuce@Produce","1 bottle tomato sauce@Pantry","1 jar horseradish@Pantry","3 lemons@Produce","1 bottle hot sauce@Pantry","4 potatoes@Produce","4 sirloin steaks@Meat","260g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","1 bunch chives@Produce","1 sponge cake@Bakery","350g icing sugar@Pantry","100g shredded coconut@Pantry","1 bottle pink food colouring@Pantry","200ml bourbon@Bottle shop","1 bunch mint@Produce","60ml sugar syrup@Pantry","1 bag crushed ice@Frozen"]}},"Under Siege (1992)":{"poster":"assets/menu-posters/under-siege-1992.jpg","colour":"#25465a","servings":4,"tagline":"Galley rules.","cue":"Serve dinner when the birthday party chopper lands.","menu":{"s":[{"n":"Galley bread rolls","note":"Soft milk rolls brushed with butter and flaky salt","how":"Mix 500g bread flour, 7g yeast, 300ml warm milk, 50g butter, 2 tbsp sugar and 1 egg into a soft dough. Prove an hour, shape 12 rolls and prove 30 minutes more. Bake at 190C for 18 minutes and brush with butter and flaky salt.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml full cream milk@Dairy","80g butter@Dairy","1 bag caster sugar@Pantry","1 egg@Dairy","1 box sea salt flakes@Pantry"]},{"n":"Saffron rouille and prawn crostini","note":"a taste of the captain's birthday dinner","how":"Soak the saffron in 1 tbsp hot water for 5 minutes. Whisk the egg yolk with the crushed garlic, saffron water, chilli and 1 tsp lemon juice, then whisk in the olive oil a few drops at a time until thick. Season with salt. Poach the prawns in simmering salted water for 2 minutes until just pink, then cool. Slice the baguette into 16 rounds and toast at 200°C for 6 minutes, then rub each with the cut garlic. Spread with rouille, top with a prawn, a few fennel fronds and lemon zest.","shop":["1 pinch saffron threads@Spices","1 egg yolk@Dairy","2 garlic cloves@Produce","1 pinch chilli flakes@Spices","1 lemon@Produce","150ml olive oil@Pantry","16 green prawns@Seafood","1 baguette@Bakery","1 fennel bulb with fronds@Produce"]}],"m":[{"n":"Ryback's spit-free bouillabaisse","note":"Saffron fish and prawn stew with rouille toast. Fifty gallons, due tomorrow.","how":"Soften 1 fennel, 1 leek, 1 onion and 3 garlic cloves in oil with saffron, orange peel and 1 tin tomatoes. Add 1L fish stock and simmer 20 minutes. Add 500g fish, then 500g mussels and 300g prawns. Serve with rouille and toasted baguette.","shop":["1 fennel bulb@Produce","1 leek@Produce","1 onion@Produce","3 garlic cloves@Produce","1 packet saffron@Pantry","1 orange@Produce","1 tin crushed tomatoes@Pantry","1L fish stock@Pantry","500g firm white fish@Seafood","500g mussels@Seafood","300g green prawns@Seafood","1 baguette@Bakery","1 jar aioli@Pantry"]}],"w":[{"n":"Captain's birthday cake","note":"Two-layer butter cake. Jordan Tate came in a bigger one.","how":"Beat 200g butter and 200g sugar, add 4 eggs and fold in 200g self-raising flour. Bake in two tins at 175C for 25 minutes. Beat 250g butter with 400g icing sugar, fill and cover the cake, then pipe the message in blue.","shop":["450g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","200g self-raising flour@Pantry","400g icing sugar@Pantry","1 bottle blue food colouring@Pantry"]}],"d":[{"n":"USS Missouri navy grog","note":"Dark and white rum with lime, grapefruit and honey over crushed ice","how":"Dissolve 2 tbsp honey in 2 tbsp hot water. Shake 90ml dark rum, 90ml white rum, 60ml fresh lime juice, 60ml grapefruit juice and the honey syrup with ice for 15 seconds. Strain into 4 tumblers packed with crushed ice. Add a lime wheel to each and grate a little nutmeg on top.","shop":["90ml dark rum@Bottle shop","90ml white rum@Bottle shop","3 limes@Produce","1 grapefruit@Produce","2 tbsp honey@Pantry","1 whole nutmeg@Pantry","1 bag crushed ice@Frozen"]}],"shopping":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml full cream milk@Dairy","530g butter@Dairy","1 bag caster sugar@Pantry","5 eggs@Dairy","1 box sea salt flakes@Pantry","1 sponge cake@Bakery","300ml thickened cream@Dairy","1 jar raspberry jam@Pantry","450g icing sugar@Pantry","1 fennel bulb@Produce","1 leek@Produce","1 onion@Produce","3 garlic cloves@Produce","1 packet saffron@Pantry","1 orange@Produce","1 tin crushed tomatoes@Pantry","1L fish stock@Pantry","500g firm white fish@Seafood","500g mussels@Seafood","300g green prawns@Seafood","1 baguette@Bakery","1 jar aioli@Pantry","200g caster sugar@Pantry","200g self-raising flour@Pantry","1 bottle blue food colouring@Pantry","90ml dark rum@Bottle shop","90ml white rum@Bottle shop","3 limes@Produce","1 grapefruit@Produce","2 tbsp honey@Pantry","1 whole nutmeg@Pantry","1 bag crushed ice@Frozen"]}},"Alien (1979)":{"poster":"assets/menu-posters/alien-1979.jpg","colour":"#4a6744","servings":4,"tagline":"Seven crew. One very long haul.","cue":"Serve the mains when the crew wakes up and sits down to breakfast.","menu":{"s":[{"n":"Nostromo crew noodles","note":"Wheat noodles in sesame, soy, black vinegar and chilli oil, spring onion","how":"Cook 400g fresh wheat noodles, rinse cold and drain. Whisk 3 tbsp sesame paste, 2 tbsp soy, 1 tbsp black vinegar, 1 tbsp chilli oil and a crushed garlic clove. Toss through and top with cucumber matchsticks and spring onion.","shop":["400g fresh wheat noodles@Produce","1 jar sesame paste@Pantry","1 bottle soy sauce@Pantry","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","1 garlic clove@Produce","1 Lebanese cucumber@Produce","1 bunch spring onions@Produce"]},{"n":"Freighter stores crackers","note":"Seeded crackers with lemon cream cheese and a smoked oyster on each","how":"Whip 150g cream cheese with the zest of a lemon. Spread on 16 seeded crackers and top each with a smoked oyster from 2 drained tins. Finish with cracked pepper and snipped chives. Serve straight away.","shop":["150g cream cheese@Dairy","1 lemon@Produce","1 packet seeded crackers@Pantry","2 tins smoked oysters@Pantry","1 bunch chives@Produce"]}],"m":[{"n":"Nostromo crew dinner","note":"Pork and vegetable noodle stir-fry in bowls","how":"Slice 500g pork shoulder thin and toss with soy. Stir-fry in a smoking wok, then add a quarter cabbage, 2 carrots and 1 capsicum, all sliced, with grated ginger. Add 400g egg noodles, 3 tbsp oyster sauce and 2 tbsp soy, toss and serve in bowls.","shop":["500g pork shoulder@Meat","1 bottle soy sauce@Pantry","0.25 cabbage@Produce","2 carrots@Produce","1 red capsicum@Produce","1 knob ginger@Produce","400g fresh egg noodles@Produce","1 bottle oyster sauce@Pantry"]}],"w":[{"n":"Red velvet chestburster cake","note":"Red velvet cake filled with raspberry jam, cream cheese frosting","how":"Beat 125g butter and 250g sugar, add 2 eggs, then fold in 250g self-raising flour, 2 tbsp cocoa, 250ml buttermilk, 1 tsp vinegar and red colouring. Bake in a bowl at 170C for 50 minutes. Hollow, fill with raspberry jam and cover in cream cheese frosting.","shop":["125g butter@Dairy","250g caster sugar@Pantry","2 eggs@Dairy","250g self-raising flour@Pantry","1 tin cocoa@Pantry","250ml buttermilk@Dairy","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 jar raspberry jam@Pantry","250g cream cheese@Dairy","200g icing sugar@Pantry"]}],"d":[{"n":"Hypersleep wake-up iced mocha","note":"Chilled coffee blended with dark chocolate and milk, whipped cream on top","how":"Brew 300ml strong coffee and stir in 80g chopped dark chocolate and 2 tbsp brown sugar until melted, then cool. Blend with 400ml cold milk and 2 cups of ice for 20 seconds until frothy. Pour into 4 tall glasses, top with whipped cream and shave dark chocolate over the top.","shop":["300ml brewed coffee@Pantry","100g dark chocolate@Pantry","2 tbsp brown sugar@Pantry","400ml full cream milk@Dairy","1 can whipped cream@Dairy","1 bag ice@Frozen"]}],"shopping":["400g fresh wheat noodles@Produce","1 jar sesame paste@Pantry","2 bottles soy sauce@Pantry","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","1 garlic clove@Produce","1 Lebanese cucumber@Produce","1 bunch spring onions@Produce","400g cream cheese@Dairy","1 lemon@Produce","1 packet seeded crackers@Pantry","2 tins smoked oysters@Pantry","1 bunch chives@Produce","500g pork shoulder@Meat","0.25 cabbage@Produce","2 carrots@Produce","1 red capsicum@Produce","1 knob ginger@Produce","400g fresh egg noodles@Produce","1 bottle oyster sauce@Pantry","125g butter@Dairy","250g caster sugar@Pantry","2 eggs@Dairy","250g self-raising flour@Pantry","1 tin cocoa@Pantry","250ml buttermilk@Dairy","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 jar raspberry jam@Pantry","200g icing sugar@Pantry","300ml brewed coffee@Pantry","100g dark chocolate@Pantry","2 tbsp brown sugar@Pantry","400ml full cream milk@Dairy","1 can whipped cream@Dairy","1 bag ice@Frozen"]}},"Lethal Weapon 3 (1992)":{"poster":"assets/menu-posters/lethal-weapon-3-1992.jpg","colour":"#92352b","servings":4,"tagline":"Eight days left. Make every meal count.","cue":"Pour drinks during the retirement countdown.","menu":{"s":[{"n":"Hockey game hot dogs","note":"Griddled franks in steamed buns with yellow mustard","how":"Simmer 8 franks in water for 5 minutes, then griddle until blistered all over. Steam 8 hot dog buns until soft. Fill with franks and top with yellow mustard, sweet relish and a spoon of finely chopped onion.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 jar sweet relish@Pantry","1 onion@Produce"]},{"n":"Building implosion popcorn","note":"Popcorn tossed in melted butter, garlic powder and grated parmesan","how":"Heat 2 tbsp oil in a big pot with 3 kernels. When they pop, add 120g kernels, cover and shake until popping slows. Toss with 50g melted butter, 1 tsp garlic powder and 40g finely grated parmesan while still hot.","shop":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","50g butter@Dairy","1 jar garlic powder@Pantry","40g parmesan@Deli"]}],"m":[{"n":"Trish's chicken and dumplings","note":"Chicken thighs simmered in stock with vegetables and self-raising dumplings","how":"Simmer 800g chicken thighs with 1 onion, 2 celery sticks, 2 carrots, thyme and 1.5L stock for 40 minutes. Shred the chicken back in. Mix 200g self-raising flour, 50g butter and 150ml milk, drop spoonfuls on top and steam covered for 15 minutes.","shop":["800g chicken thighs@Meat","1 brown onion@Produce","2 celery sticks@Produce","2 carrots@Produce","1 bunch thyme@Produce","1.5L chicken stock@Pantry","200g self-raising flour@Pantry","50g butter@Dairy","150ml full cream milk@Dairy"]}],"w":[{"n":"Retirement cake","note":"Lemon zest butter cake soaked in lemon syrup","how":"Beat 175g butter with 175g sugar, add 3 eggs, then fold in 175g self-raising flour and the zest of 2 lemons. Bake at 170C for 50 minutes. Mix the juice of 2 lemons with 100g sugar and pour over the hot loaf.","shop":["175g butter@Dairy","275g caster sugar@Pantry","3 eggs@Dairy","175g self-raising flour@Pantry","2 lemons@Produce"]}],"d":[{"n":"Eight days to go whiskey sour","note":"Bourbon, lemon and sugar syrup shaken with egg white until foamy","how":"Add 240ml bourbon, 120ml fresh lemon juice, 80ml sugar syrup and 2 egg whites to a shaker without ice and shake hard for 15 seconds to foam. Add a big handful of ice and shake again for 10 seconds. Strain into 4 tumblers over fresh ice. Shake 2 dashes of aromatic bitters onto the foam of each and add a cocktail cherry.","shop":["240ml bourbon@Bottle shop","4 lemons@Produce","80ml sugar syrup@Pantry","2 eggs@Dairy","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}],"shopping":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 jar sweet relish@Pantry","1 onion@Produce","120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","275g butter@Dairy","1 jar garlic powder@Pantry","40g parmesan@Deli","800g chicken thighs@Meat","1 brown onion@Produce","2 celery sticks@Produce","2 carrots@Produce","1 bunch thyme@Produce","1.5L chicken stock@Pantry","375g self-raising flour@Pantry","150ml full cream milk@Dairy","275g caster sugar@Pantry","5 eggs@Dairy","6 lemons@Produce","240ml bourbon@Bottle shop","80ml sugar syrup@Pantry","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 bag ice@Frozen"]}},"Dragnet (1987)":{"poster":"assets/menu-posters/dragnet-1987.jpg","colour":"#183d58","servings":4,"tagline":"By the book. And the food.","cue":"Serve dinner when Friday meets his new partner Streebek.","menu":{"s":[{"n":"PAGAN parmesan stuffed mushrooms","note":"Button mushrooms stuffed with garlic cream cheese and parmesan, crumb topping","how":"Heat the oven to 200C. Pull the stalks from 20 button mushrooms and chop them finely. Mix the stalks with 150g softened cream cheese, 2 crushed garlic cloves, 40g grated parmesan and chopped parsley. Fill each mushroom cap. Mix 30g breadcrumbs with 1 tbsp melted butter and press on top. Bake 15 minutes until bubbling and golden.","shop":["20 button mushrooms@Produce","150g cream cheese@Dairy","2 garlic cloves@Produce","40g parmesan@Dairy","1 bunch parsley@Produce","30g breadcrumbs@Pantry","15g butter@Dairy"]},{"n":"Friday's by-the-book glazed doughnut holes","note":"Yeast doughnut holes dipped in vanilla icing","how":"Warm 180ml milk with 30g butter and 2 tbsp caster sugar, add 7g yeast and 1 egg, then mix into 350g plain flour with a pinch of salt. Knead 5 minutes and prove 1 hour. Roll into 30 small balls and prove 20 minutes. Fry at 175C for 2 minutes, turning, until golden. Whisk 200g icing sugar with 3 tbsp milk and 1 tsp vanilla, dip the warm doughnuts and set on a rack.","shop":["350g plain flour@Pantry","7g dried yeast@Pantry","200ml milk@Dairy","30g butter@Dairy","2 tbsp caster sugar@Pantry","1 egg@Dairy","200g icing sugar@Pantry","1 tsp vanilla extract@Pantry","2 litres vegetable oil@Pantry"]}],"m":[{"n":"Streebek's LA carnitas tacos","note":"Orange and cumin pork shoulder braised, then crisped, in corn tortillas","how":"Cut 1.2kg pork shoulder into chunks, rub with cumin, oregano and salt and braise with 1 orange, 3 garlic cloves and 250ml water at 160C for 2.5 hours. Shred, crisp in the pan and serve in 16 corn tortillas with diced onion, coriander and lime.","shop":["1.2kg pork shoulder@Meat","1 jar ground cumin@Pantry","1 jar dried oregano@Pantry","1 orange@Produce","3 garlic cloves@Produce","16 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","2 limes@Produce"]}],"w":[{"n":"By-the-book vanilla slice","note":"Puff pastry layers with thick vanilla custard and white icing","how":"Bake 2 sheets puff pastry pricked and weighted at 200C for 15 minutes. Whisk 1L milk, 6 egg yolks, 150g sugar, 90g cornflour and 2 tsp vanilla over medium heat until very thick. Spread between the pastry in a lined tin, chill 4 hours, ice with 200g icing sugar mixed with a little water and cut into squares.","shop":["2 sheets puff pastry@Frozen","1L full cream milk@Dairy","6 eggs@Dairy","150g caster sugar@Pantry","90g cornflour@Pantry","2 tsp vanilla extract@Pantry","200g icing sugar@Pantry"]}],"d":[{"n":"Friday's cold brew tonic","note":"Cold brew coffee poured over tonic water with an orange peel twist","how":"The night before, stir 100g coarsely ground coffee into 800ml cold water in a jug, cover and leave in the fridge for 12 to 16 hours. Strain through a paper filter. Fill 4 tall glasses with ice, pour in 150ml tonic water each, then slowly pour 100ml cold brew over the top so it layers. Squeeze a strip of orange peel over each glass and drop it in.","shop":["100g ground coffee@Pantry","600ml tonic water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["20 button mushrooms@Produce","150g cream cheese@Dairy","5 garlic cloves@Produce","40g parmesan@Dairy","1 bunch parsley@Produce","30g breadcrumbs@Pantry","45g butter@Dairy","350g plain flour@Pantry","7g dried yeast@Pantry","200ml milk@Dairy","2 tbsp caster sugar@Pantry","7 eggs@Dairy","400g icing sugar@Pantry","3 tsp vanilla extract@Pantry","2 litres vegetable oils@Pantry","1.2kg pork shoulder@Meat","1 jar ground cumin@Pantry","1 jar dried oregano@Pantry","2 oranges@Produce","16 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","2 limes@Produce","2 sheets puff pastries@Frozen","1L full cream milk@Dairy","150g caster sugar@Pantry","90g cornflour@Pantry","100g ground coffee@Pantry","600ml tonic water@Drinks","1 bag ice@Frozen"]}},"Back to the Future Part III (1990)":{"poster":"assets/menu-posters/back-to-the-future-part-iii-1990.jpg","colour":"#965127","servings":4,"tagline":"Hill Valley, 1885. Bring an appetite.","cue":"Pour the drinks when Marty walks into the Palace Saloon and asks for water.","menu":{"s":[{"n":"Festival corn on the cob","note":"Boiled then charred corn rolled in butter, flaky salt and smoked paprika","how":"Boil 4 corn cobs in salted water for 5 minutes, then char on a hot grill for about 6 minutes, turning. Roll each in melted butter, about 60g in total, and sprinkle with flaky salt and smoked paprika.","shop":["4 corn cobs@Produce","60g butter@Dairy","1 jar smoked paprika@Pantry","1 box sea salt flakes@Pantry"]},{"n":"Clara's apple slices","note":"Fanned apple slices with a honey cinnamon yoghurt dip","how":"Slice 3 crisp apples and toss in the juice of a lemon so they don't brown. Whip 250g Greek yoghurt with 2 tbsp honey and half a tsp cinnamon. Fan the apples around a bowl of the yoghurt for dipping.","shop":["3 apples@Produce","1 lemon@Produce","1 jar honey@Pantry","250g Greek yoghurt@Dairy","1 jar cinnamon@Pantry"]}],"m":[{"n":"Doc's blacksmith shop stew","note":"Beef chuck braised with onion, carrot and dark ale, crusty bread","how":"Brown 1kg diced beef chuck in batches. Soften 2 onions and 3 carrots in the same pot. Add 375ml dark ale and 500ml stock, cover and braise at 150C for 3 hours until the beef falls apart. Serve with crusty bread.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","375ml dark ale@Bottle shop","500ml beef stock@Pantry","1 crusty loaf@Bakery"]}],"w":[{"n":"Clara's festival apple pie","note":"Double crust Granny Smith apple pie with cinnamon and nutmeg","how":"Toss 1kg sliced Granny Smiths with 120g sugar, 1 tsp cinnamon, a grating of nutmeg and 2 tbsp flour. Line a pie dish with 2 sheets sweet shortcrust, fill and cover with 2 more. Egg wash, sprinkle with sugar and bake at 190C for 50 minutes.","shop":["1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar cinnamon@Pantry","1 jar nutmeg@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Wake-up juice","note":"Fresh lemon, ginger, honey and chilli topped with ginger beer, no alcohol","how":"Blitz the juice of 3 lemons with a 5cm knob of grated ginger, 2 tbsp honey and a pinch of chopped red chilli, then strain. Divide between four glasses of ice and top each with about 150ml very cold ginger beer.","shop":["3 lemons@Produce","1 knob ginger@Produce","1 jar honey@Pantry","1 red chilli@Produce","600ml ginger beer@Drinks"]}],"shopping":["4 corn cobs@Produce","60g butter@Dairy","1 jar smoked paprika@Pantry","1 box sea salt flakes@Pantry","3 apples@Produce","4 lemons@Produce","2 jars honey@Pantry","250g Greek yoghurt@Dairy","2 jars cinnamon@Pantry","1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","375ml dark ale@Bottle shop","500ml beef stock@Pantry","1 crusty loaf@Bakery","1kg Granny Smith apples@Produce","120g caster sugar@Pantry","1 jar nutmeg@Pantry","1 bag plain flour@Pantry","4 sheets sweet shortcrust pastry@Frozen","1 egg@Dairy","1 knob ginger@Produce","1 red chilli@Produce","600ml ginger beer@Drinks"]}},"E.T. the Extra-Terrestrial (1982)":{"poster":"assets/menu-posters/et-the-extra-terrestrial-1982.jpg","colour":"#253b78","servings":4,"tagline":"Suburban secrets. Order in.","cue":"Lay out a trail of peanut butter chocolates when Elliott lures E.T. into the house.","menu":{"s":[{"n":"Alphabet crackers","note":"Cheddar crackers cut into letters, for the day E.T. learns English","how":"Pulse 150g grated cheddar, 60g cold butter and 100g flour with salt until it forms a dough, adding a splash of water. Roll thin and cut into letters with small cutters. Bake at 180C for 12 minutes until crisp.","shop":["150g cheddar@Dairy","60g butter@Dairy","100g plain flour@Pantry"]},{"n":"Halloween caramel popcorn and lolly mix","note":"popped corn baked in a brown sugar and golden syrup glaze, chocolate buttons, jellies and peanuts","how":"Heat the oven to 120°C. Pop the corn and tip it into a large roasting tray. Melt the butter with the brown sugar and golden syrup, boil for 4 minutes, then stir in the bicarb and a pinch of salt. Pour over the popcorn and toss well. Bake for 45 minutes, stirring every 15 minutes. Cool, break up and toss with the chocolate buttons, jelly lollies and peanuts.","shop":["120g popcorn kernels@Pantry","100g butter@Dairy","200g brown sugar@Pantry","3 tbsp golden syrup@Pantry","0.5 tsp bicarb soda@Pantry","150g chocolate buttons@Pantry","150g jelly lollies@Pantry","80g roasted peanuts@Pantry"]}],"m":[{"n":"Game night pepperoni pizza","note":"Pepperoni pizza in squares, as Michael's friends wait on the pizza man","how":"Stretch 500g pizza dough into 2 thin bases. Spread with pizza sauce and top with 250g mozzarella and 100g pepperoni. Bake on a steel or tray at the oven's highest heat for 7 to 8 minutes, then cut into squares.","shop":["500g pizza dough@Bakery","1 jar pizza sauce@Pantry","250g mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Homemade peanut butter cups","note":"Milk chocolate cups filled with sweet peanut butter","how":"Melt 300g milk chocolate. Spoon a little into 12 cupcake liners and chill. Mix 150g peanut butter with 50g icing sugar and put a spoon on each. Cover with the rest of the chocolate and chill until set.","shop":["300g milk chocolate@Pantry","150g peanut butter@Pantry","50g icing sugar@Pantry"]}],"d":[{"n":"Fridge raid root beer floats","note":"Root beer over vanilla ice cream with a drizzle of chocolate syrup","how":"Chill 4 tall glasses in the freezer for 10 minutes. Add 2 scoops of vanilla ice cream to each glass. Slowly pour 250ml cold root beer down the side of each glass so the foam rises without spilling over. Top with a drizzle of chocolate syrup and serve straight away with long spoons and straws.","shop":["1 litre root beer@Drinks","1 litre vanilla ice cream@Frozen","chocolate syrup@Pantry"]}],"shopping":["350g peanut butter@Pantry","150g icing sugar@Pantry","90g butter@Dairy","250g candy melts@Pantry","150g cheddar@Dairy","100g plain flour@Pantry","500g pizza dough@Bakery","1 jar pizza sauce@Pantry","250g mozzarella@Dairy","100g pepperoni@Deli","300g milk chocolate@Pantry","1 litre root beer@Drinks","1 litre vanilla ice cream@Frozen","chocolate syrup@Pantry"]}},"Predator (1987)":{"poster":"assets/menu-posters/predator-1987.jpg","colour":"#31503c","servings":4,"tagline":"Jungle rescue first. Then dinner.","cue":"Serve the snacks when Dutch and Dillon do that famous handshake.","menu":{"s":[{"n":"Mud-camo bean dip","note":"Black beans, garlic, cumin and lime blended, topped with feta, corn chips","how":"Blitz 2 drained tins black beans with 2 garlic cloves, 1 tsp cumin and the juice of 2 limes until smooth. Spread in a bowl and top with 80g crumbled feta, coriander and a sliced green chilli. Serve with corn chips.","shop":["2 tins black beans@Pantry","2 garlic cloves@Produce","1 jar ground cumin@Pantry","2 limes@Produce","80g feta@Deli","1 bunch coriander@Produce","1 green chilli@Produce","1 bag corn chips@Pantry"]},{"n":"Billy's plantain chips","note":"Thin fried green plantain chips with lime zest salt","how":"Peel 3 green plantains and slice very thin on a mandoline. Fry at 175C in batches until crisp, about 2 minutes. Drain and toss straight away with flaky salt mixed with the zest of a lime.","shop":["3 green plantains@Produce","1L vegetable oil@Pantry","1 lime@Produce","1 box sea salt flakes@Pantry"]}],"m":[{"n":"Chopper pad steak","note":"Smoked paprika rump steaks grilled hard, with garlic parsley chilli sauce","how":"Rub 4 rump steaks with salt, pepper and 2 tsp smoked paprika. Grill over high heat for 4 minutes a side and rest. Chop a bunch of parsley with 2 garlic cloves and mix with 3 tbsp red wine vinegar, 100ml oil and chilli flakes. Spoon over.","shop":["4 rump steaks@Meat","1 jar smoked paprika@Pantry","1 bunch parsley@Produce","2 garlic cloves@Produce","1 bottle red wine vinegar@Pantry","1 bottle extra virgin olive oil@Pantry","1 jar chilli flakes@Pantry"]}],"w":[{"n":"Mud cake","note":"Dense chocolate mud cake with a chocolate cream glaze","how":"Melt 250g dark chocolate and 250g butter. Whisk in 4 eggs and 300g sugar, then fold in 150g flour and 30g cocoa. Bake at 160C for 70 minutes. Melt 150g chocolate with 150ml cream, pour over and drag with a fork.","shop":["400g dark chocolate@Pantry","250g butter@Dairy","4 eggs@Dairy","300g caster sugar@Pantry","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Val Verde jungle rum punch","note":"Dark rum, pineapple, passionfruit and lime over crushed ice","how":"Shake 180ml dark rum, 120ml pineapple juice, the pulp of 4 passionfruit, 60ml fresh lime juice and 20ml grenadine with ice for 15 seconds. Strain into 4 tumblers packed with crushed ice. Grate a little nutmeg on top of each and garnish with a pineapple wedge.","shop":["180ml dark rum@Bottle shop","120ml pineapple juice@Drinks","4 passionfruit@Produce","3 limes@Produce","20ml grenadine@Drinks","1 whole nutmeg@Pantry","1 small pineapple@Produce","1 bag crushed ice@Frozen"]}],"shopping":["2 tins black beans@Pantry","4 garlic cloves@Produce","1 jar ground cumin@Pantry","5 limes@Produce","80g feta@Deli","1 bunch coriander@Produce","1 green chilli@Produce","1 bag corn chips@Pantry","3 green plantains@Produce","1L vegetable oil@Pantry","1 lime@Produce","1 box sea salt flakes@Pantry","4 rump steaks@Meat","1 jar smoked paprika@Pantry","1 bunch parsley@Produce","1 bottle red wine vinegar@Pantry","1 bottle extra virgin olive oil@Pantry","1 jar chilli flakes@Pantry","400g dark chocolate@Pantry","250g butter@Dairy","4 eggs@Dairy","300g caster sugar@Pantry","150g plain flour@Pantry","30g cocoa@Pantry","150ml thickened cream@Dairy","180ml dark rum@Bottle shop","120ml pineapple juice@Drinks","4 passionfruits@Produce","20ml grenadine@Drinks","1 whole nutmeg@Pantry","1 small pineapple@Produce","1 bag crushed ice@Frozen"]}},"Blade Runner (1982)":{"poster":"assets/menu-posters/blade-runner-1982.jpg","colour":"#364e68","servings":4,"tagline":"Noodles in the rain.","cue":"Serve the noodles when Deckard sits down at the street noodle bar in the rain.","menu":{"s":[{"n":"Noodle bar gyoza","note":"Pan fried pork and cabbage gyoza with a soy and chilli oil dip","how":"Mix 400g pork mince with 2 cups finely shredded cabbage, salted and squeezed, plus soy and ginger. Fill 30 gyoza wrappers and pleat. Fry until crisp underneath, add water and steam with a lid for 4 minutes. Dip in soy, rice vinegar and chilli oil.","shop":["400g pork mince@Meat","0.25 cabbage@Produce","1 bottle soy sauce@Pantry","1 knob ginger@Produce","30 gyoza wrappers@Frozen","1 bottle rice vinegar@Pantry","1 jar chilli oil@Pantry"]},{"n":"Origami crackers","note":"Rice paper triangles fried until puffed, dusted with shichimi togarashi","how":"Cut 10 rice paper sheets into small triangles with scissors. Fry a few at a time at 180C for a few seconds until they puff and turn white. Drain and toss with flaky salt and a good shake of shichimi togarashi.","shop":["10 rice paper sheets@Pantry","1L vegetable oil@Pantry","1 box sea salt flakes@Pantry","1 jar shichimi togarashi@Pantry"]}],"m":[{"n":"Rain-soaked ramen","note":"Braised pork belly ramen with soft-boiled egg, nori and spring onion","how":"Braise 600g pork belly in 125ml soy, 125ml mirin, 125ml sake and 500ml water for 2 hours, then slice. Marinate 4 soft-boiled eggs in some of the liquid. Cook 4 serves ramen into 1.5L hot stock seasoned with soy. Top with pork, egg, nori and spring onion.","shop":["600g pork belly@Meat","1 bottle soy sauce@Pantry","125ml mirin@Pantry","125ml sake@Bottle shop","4 eggs@Dairy","400g ramen noodles@Pantry","1.5L chicken stock@Pantry","1 packet nori@Pantry","1 bunch spring onions@Produce"]}],"w":[{"n":"Origami cookies","note":"Thin crisp sesame cookies folded into shapes while still warm","how":"Whisk 2 egg whites with 100g sugar, then stir in 50g flour, 50g melted butter and 2 tbsp sesame seeds. Spread thin circles on a lined tray and bake at 180C for 6 minutes. Fold or twist into shapes while still hot and soft.","shop":["2 eggs@Dairy","100g caster sugar@Pantry","50g plain flour@Pantry","50g butter@Dairy","1 jar sesame seeds@Pantry"]}],"d":[{"n":"Deckard's Black Label highball","note":"Scotch whisky and soda water over ice with a lemon peel twist","how":"Pack 4 tall glasses to the top with ice and stir with a bar spoon for 10 seconds to chill the glass, then pour off any water. Add 45ml Scotch whisky to each and stir 10 times. Top slowly with 150ml very cold soda water, pouring down the spoon to keep the bubbles. Stir once and squeeze a strip of lemon peel over each glass.","shop":["180ml Scotch whisky@Bottle shop","600ml soda water@Drinks","1 lemon@Produce","2 bags ice@Frozen"]}],"shopping":["400g pork mince@Meat","0.25 cabbage@Produce","2 bottles soy sauce@Pantry","1 knob ginger@Produce","30 gyoza wrappers@Frozen","1 bottle rice vinegar@Pantry","1 jar chilli oil@Pantry","10 rice paper sheets@Pantry","1L vegetable oil@Pantry","1 box sea salt flakes@Pantry","1 jar shichimi togarashi@Pantry","600g pork belly@Meat","125ml mirin@Pantry","125ml sake@Bottle shop","6 eggs@Dairy","400g ramen noodles@Pantry","1.5L chicken stock@Pantry","1 packet nori@Pantry","1 bunch spring onions@Produce","100g caster sugar@Pantry","50g plain flour@Pantry","50g butter@Dairy","1 jar sesame seeds@Pantry","180ml Japanese whisky@Bottle shop","600ml soda water@Drinks","1 lemon@Produce","2 bags ices@Frozen"]}},"Spaceballs (1987)":{"poster":"assets/menu-posters/spaceballs-1987.jpg","colour":"#5b3f76","servings":4,"tagline":"Space parody night. Snacks at full speed.","cue":"Serve the pizza when Pizza the Hutt appears.","menu":{"s":[{"n":"Spaceball One pretzels","note":"Pretzel rods dipped in dark chocolate with a striped candy melt plaid","how":"Melt 200g dark chocolate and dip 20 pretzel rods two-thirds of the way. Set on baking paper. Melt 100g coloured candy melts, pipe stripes across in two directions for a plaid pattern and let them set.","shop":["200g dark chocolate@Pantry","20 pretzel rods@Pantry","100g candy melts@Pantry"]},{"n":"Yogurt's snack mix","note":"Cereal, pretzel and peanut mix baked in honey butter, with mini marshmallows","how":"Toss 150g cereal squares, 100g pretzels and 100g peanuts with 50g butter melted with 2 tbsp honey. Bake at 140C for 20 minutes, stirring once. Cool completely, then toss through 100g mini marshmallows.","shop":["150g cereal squares@Pantry","100g pretzels@Pantry","100g peanuts@Pantry","50g butter@Dairy","1 jar honey@Pantry","100g mini marshmallows@Pantry"]}],"m":[{"n":"Pizza the Hutt","note":"Deep pan pizza loaded with mozzarella, provolone, cheddar and pepperoni","how":"Press 600g pizza dough into an oiled deep tray and prove 30 minutes. Spread with a jar of pizza sauce and pile on 200g mozzarella, 100g provolone, 50g parmesan, 100g cheddar and 100g pepperoni. Bake at 220C for 20 minutes until molten.","shop":["600g pizza dough@Bakery","1 jar pizza sauce@Pantry","200g mozzarella@Dairy","100g provolone@Deli","50g parmesan@Deli","100g cheddar@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Yoghurt parfait","note":"Honey yoghurt, granola, berries. Even with strawberries.","how":"Whip 500g Greek yoghurt with 3 tbsp honey and a little vanilla. Layer in four tall glasses with 200g granola and 250g mixed berries, finishing with berries on top. Serve straight away so the granola stays crunchy.","shop":["500g Greek yoghurt@Dairy","1 jar honey@Pantry","1 bottle vanilla extract@Pantry","200g granola@Pantry","250g berries@Produce"]}],"d":[{"n":"Perri-Air sparkling lime and mint cooler","note":"Lime, mint and cucumber with sparkling water over ice, no alcohol","how":"Muddle 12 mint leaves, 4 slices cucumber and 60ml sugar syrup in a jug. Add the juice of 3 limes and stir. Fill 4 tall glasses with ice and divide the mix between them. Top each with 150ml cold sparkling water. Garnish with a mint sprig and a lime wheel.","shop":["1 bunch mint@Produce","1 Lebanese cucumber@Produce","60ml sugar syrup@Pantry","4 limes@Produce","600ml sparkling water@Drinks","1 bag ice@Frozen"]}],"shopping":["200g dark chocolate@Pantry","20 pretzel rods@Pantry","100g candy melts@Pantry","150g cereal squares@Pantry","100g pretzels@Pantry","100g peanuts@Pantry","50g butter@Dairy","2 jars honey@Pantry","100g mini marshmallows@Pantry","600g pizza dough@Bakery","1 jar pizza sauce@Pantry","200g mozzarella@Dairy","100g provolone@Deli","50g parmesan@Deli","100g cheddar@Dairy","100g pepperoni@Deli","500g Greek yoghurt@Dairy","1 bottle vanilla extract@Pantry","200g granola@Pantry","250g berries@Produce","1 bunch mint@Produce","1 Lebanese cucumber@Produce","60ml sugar syrup@Pantry","4 limes@Produce","600ml sparkling water@Drinks","1 bag ice@Frozen"]}},"Hitch (2005)":{"poster":"assets/menu-posters/hitch-2005.jpg","colour":"#8e394e","servings":4,"tagline":"Every dinner date needs a coach.","cue":"Serve the snacks when the Benadryl hunt starts, Aisle 2.","menu":{"s":[{"n":"Ellis Island crostini","note":"Grilled ciabatta rubbed with garlic, topped with diced tomato and basil","how":"Slice a ciabatta, grill until charred and rub with a cut garlic clove. Dice 4 ripe tomatoes and mix with torn basil, a little finely chopped red onion, 2 tbsp olive oil and salt. Spoon on just before serving.","shop":["1 ciabatta@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 red onion@Produce","1 bottle extra virgin olive oil@Pantry"]},{"n":"Albert's meatball sliders","note":"Pork and veal meatballs in tomato sauce on small slider buns","how":"Roll 500g pork and veal mince with breadcrumbs, egg and parmesan into 12 balls. Brown, then simmer in 700ml passata for 25 minutes. Put each in a slider bun with a slice of provolone and basil and grill until the cheese melts.","shop":["500g pork and veal mince@Meat","50g breadcrumbs@Pantry","1 egg@Dairy","30g parmesan@Deli","700ml passata@Pantry","12 slider buns@Bakery","150g provolone@Deli","1 bunch basil@Produce"]}],"m":[{"n":"Chicken piccata","note":"Pan seared chicken in a lemon, caper and white wine sauce","how":"Pound 2 large chicken breasts thin, cut in half, flour and sear in oil. Add 125ml white wine, the juice of 2 lemons and 2 tbsp capers and reduce. Whisk in 60g butter. Toss with 400g cooked angel hair and serve the chicken on top.","shop":["2 chicken breasts@Meat","1 bag plain flour@Pantry","125ml white wine@Bottle shop","2 lemons@Produce","1 jar capers@Pantry","60g butter@Dairy","400g angel hair pasta@Pantry"]}],"w":[{"n":"Sara's chocolate-dipped strawberries","note":"Large strawberries dipped in melted dark chocolate","how":"Wash and fully dry 500g large strawberries, leaving the green tops on. Melt 200g dark chocolate in a bowl over simmering water. Dip each strawberry two thirds of the way in, let the excess drip off, and lay on baking paper. Sprinkle with 30g crushed pistachios. Melt 50g white chocolate and drizzle across in thin lines with a spoon. Chill 20 minutes until set.","shop":["500g large strawberries@Produce","200g dark chocolate@Pantry","50g white chocolate@Pantry","30g shelled pistachios@Pantry"]}],"d":[{"n":"Date doctor French 75","note":"Gin, lemon and sugar syrup shaken, then topped with sparkling wine","how":"Chill 4 flutes. Shake 120ml gin, 60ml fresh lemon juice and 40ml sugar syrup with ice for 10 seconds. Strain evenly into the flutes. Top each with about 90ml cold brut sparkling wine, pouring slowly so it doesn't foam over. Twist a long strip of lemon peel over each glass and drop it in.","shop":["120ml gin@Bottle shop","1 bottle brut sparkling wine@Bottle shop","3 lemons@Produce","40ml sugar syrup@Pantry","1 bag ice@Frozen"]}],"shopping":["1 ciabatta@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","2 bunches basil@Produce","1 red onion@Produce","1 bottle extra virgin olive oil@Pantry","500g pork and veal mince@Meat","50g breadcrumbs@Pantry","1 egg@Dairy","30g parmesan@Deli","700ml passata@Pantry","12 slider buns@Bakery","150g provolone@Deli","2 chicken breasts@Meat","1 bag plain flour@Pantry","125ml white wine@Bottle shop","5 lemons@Produce","1 jar capers@Pantry","60g butter@Dairy","400g angel hair pasta@Pantry","500g large strawberries@Produce","200g dark chocolate@Pantry","50g white chocolate@Pantry","30g shelled pistachios@Pantry","120ml gin@Bottle shop","1 bottle brut sparkling wine@Bottle shop","40ml sugar syrup@Pantry","1 bag ice@Frozen"]}},"Oliver & Company (1988)":{"poster":"assets/menu-posters/oliver-and-company-1988.jpg","colour":"#3b6687","servings":4,"tagline":"Strays of New York. Dinner's ready.","cue":"Serve the hot dogs when Oliver and Dodger raid the hot dog cart.","menu":{"s":[{"n":"Hot dog cart sausages","note":"Mini hot dogs glazed sticky with Dijon and honey, from Louie's cart","how":"Simmer 24 cocktail franks for 5 minutes and drain. Toss in a hot pan with 2 tbsp Dijon and 2 tbsp honey for 3 minutes until sticky and glazed. Spear each on a toothpick and serve while hot.","shop":["24 cocktail franks@Deli","1 jar Dijon mustard@Pantry","1 jar honey@Pantry"]},{"n":"Fish crackers","note":"Crisp cheddar and butter crackers cut into little fish shapes","how":"Pulse 150g grated cheddar, 60g cold butter and 100g flour with a pinch of salt until it forms a dough, adding a splash of water. Roll thin, cut into little fish shapes and bake at 180C for 12 minutes until crisp.","shop":["150g cheddar@Dairy","60g butter@Dairy","100g plain flour@Pantry"]}],"m":[{"n":"Louie's hot dogs with everything","note":"Franks liberated from Louie, in steamed buns with sauerkraut, mustard, onion and relish","how":"Simmer 8 franks for 5 minutes, then griddle until blistered. Warm 250g sauerkraut in a small pan. Steam 8 buns and fill with franks, mustard, chopped onion, sweet relish and the sauerkraut.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 onion@Produce","1 jar sweet relish@Pantry","1 jar sauerkraut@Pantry"]}],"w":[{"n":"Kitten cookies","note":"Iced cat-shaped butter cookies for Jenny's birthday party","how":"Beat 250g butter with 100g icing sugar and mix in 350g flour. Roll to 6mm, cut into cat shapes and bake at 160C for 18 minutes. Ice with 200g icing sugar tinted orange and pipe on little whiskers in white.","shop":["250g butter@Dairy","300g icing sugar@Pantry","350g plain flour@Pantry","1 bottle orange food colouring@Pantry"]}],"d":[{"n":"Honey and cinnamon warm milk","note":"Whole milk warmed with honey, cinnamon and vanilla, no alcohol","how":"Pour 1 litre full cream milk into a saucepan with 3 tbsp honey, 1 cinnamon stick and 1 tsp vanilla extract. Warm over medium heat for 5 minutes until steaming but not boiling. Remove the cinnamon stick and whisk hard or use a frother until foamy. Pour into 4 mugs, dust with a pinch of grated nutmeg and add a fresh cinnamon stick to each.","shop":["1 litre full cream milk@Dairy","3 tbsp honey@Pantry","5 cinnamon sticks@Pantry","1 tsp vanilla extract@Pantry","1 whole nutmeg@Pantry"]}],"shopping":["24 cocktail franks@Deli","1 jar Dijon mustard@Pantry","1 jar honey@Pantry","150g cheddar@Dairy","310g butter@Dairy","450g plain flour@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","1 onion@Produce","1 jar sweet relish@Pantry","1 jar sauerkraut@Pantry","300g icing sugar@Pantry","1 bottle orange food colouring@Pantry","1 litre full cream milk@Dairy","3 tbsp honey@Pantry","5 cinnamon sticks@Pantry","1 tsp vanilla extract@Pantry","1 whole nutmeg@Pantry"]}},"Coming to America (1988)":{"poster":"assets/menu-posters/coming-to-america-1988.jpg","colour":"#90253d","servings":4,"tagline":"A prince walks into a burger joint in Queens.","cue":"Serve the burgers when the Big Mick comes out at McDowell's.","menu":{"s":[{"n":"Golden fries","note":"straight off the McDowell's fryer","how":"Cut 1kg russets into thin fries and soak in cold water for 30 minutes, then dry well. Fry at 140C for 5 minutes, rest, then fry at 190C until golden and crisp. Salt straight away and serve hot.","shop":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry"]},{"n":"Beef patties from the corner shop","note":"golden turnovers of curried beef mince and thyme, baked flaky, for a prince in Queens","how":"Soften the onion in the oil, then brown the mince with the curry powder, thyme and salt. Add the stock and simmer until almost dry, then stir in the breadcrumbs and cool. Heat the oven to 200C. Brush the pastry sheets with turmeric mixed into the beaten egg and cut two 12cm rounds from each. Spoon the filling onto half of each round, fold over and crimp with a fork. Brush the tops with the rest of the egg. Bake on lined trays until golden and flaky, about 25 minutes. Serve hot with hot sauce.","shop":["1 brown onion, finely diced@Produce","2 tbsp vegetable oil@Pantry","400g beef mince@Meat","2 tsp mild curry powder@Pantry","1 tsp dried thyme@Pantry","1 tsp salt@Pantry","125ml beef stock@Pantry","30g dry breadcrumbs@Pantry","4 sheets frozen shortcrust pastry@Frozen","1 tsp ground turmeric@Pantry","1 egg, beaten@Dairy","1 bottle hot sauce@Pantry"]}],"m":[{"n":"Big Mick burger","note":"McDowell's signature burger, on a bun with no seeds","how":"Mix 100g mayo, 2 tbsp relish, 1 tsp mustard, paprika and a dash of vinegar. Smash 8 thin patties from 800g mince, add cheese. Build each in a three-piece sesame bun with sauce, shredded iceberg, diced onion and pickles.","shop":["1 jar mayonnaise@Pantry","1 jar sweet relish@Pantry","1 bottle yellow mustard@Pantry","800g beef mince@Meat","8 slices American cheese@Dairy","6 sesame burger buns@Bakery","0.5 iceberg lettuce@Produce","1 brown onion@Produce","1 jar dill pickles@Pantry"]}],"w":[{"n":"Apple turnovers","note":"something sweet at McDowell's, totally original","how":"Cook 3 diced apples with 30g butter, 3 tbsp sugar and 1 tsp cinnamon for 8 minutes, then cool. Cut 2 sheets puff pastry into quarters, fill, fold into triangles and crimp. Egg wash and bake at 200C for 20 minutes.","shop":["3 apples@Produce","30g butter@Dairy","50g caster sugar@Pantry","1 jar cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Vanilla thick shake","note":"three scoops of ice cream blended with milk until dense, from a counter that isn't McDonald's","how":"For each shake, blend 3 scoops vanilla ice cream with 150ml cold milk until thick and smooth. Pour into a chilled tall glass and serve with a wide straw. Make four, one after the other, so they stay thick.","shop":["1.5L vanilla ice cream@Frozen","600ml full cream milk@Dairy"]}],"shopping":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry","1 brown onion, finely diced@Produce","2 tbsp vegetable oil@Pantry","1.2kg beef mince@Meat","2 tsp mild curry powder@Pantry","1 tsp dried thyme@Pantry","1 tsp salt@Pantry","125ml beef stock@Pantry","30g dry breadcrumbs@Pantry","4 sheets frozen shortcrust pastry@Frozen","1 tsp ground turmeric@Pantry","1 egg, beaten@Dairy","1 bottle hot sauce@Pantry","1 jar mayonnaise@Pantry","1 jar sweet relish@Pantry","1 bottle yellow mustard@Pantry","8 slices American cheese@Dairy","6 sesame burger buns@Bakery","0.5 iceberg lettuce@Produce","1 brown onion@Produce","1 jar dill pickles@Pantry","3 apples@Produce","30g butter@Dairy","50g caster sugar@Pantry","1 jar cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy","1.5L vanilla ice cream@Frozen","600ml full cream milk@Dairy"]}},"Wall Street (1987)":{"poster":"assets/menu-posters/wall-street-1987.jpg","colour":"#806637","servings":4,"tagline":"Insider tips. Outsized lunches.","cue":"Serve dinner when Bud finally gets his meeting in Gekko's office.","menu":{"s":[{"n":"Steak tartare","note":"Hand-chopped raw beef with shallot, capers, cornichons and egg yolk","how":"Finely chop 300g well-chilled eye fillet by hand. Mix with 1 diced shallot, 1 tbsp capers, 4 chopped cornichons, 1 tsp Dijon, a dash of Worcestershire and 1 yolk. Season well and serve with toasted brioche slices.","shop":["300g eye fillet@Meat","1 shallot@Produce","1 jar capers@Pantry","1 jar cornichons@Pantry","1 jar Dijon mustard@Pantry","1 bottle Worcestershire sauce@Pantry","1 egg@Dairy","1 brioche loaf@Bakery"]},{"n":"Gekko's oysters on ice","note":"Fresh oysters on crushed ice, red wine vinegar and shallot dressing, lemon","how":"Lay 24 freshly shucked oysters on crushed ice. Mix 80ml red wine vinegar with 1 finely diced shallot and cracked pepper. Serve with lemon wedges and the dressing on the side.","shop":["24 oysters@Seafood","80ml red wine vinegar@Pantry","1 shallot@Produce","2 lemons@Produce"]}],"m":[{"n":"Raider's rib eye","note":"Butter-basted rib eye with a flamed brandy and cracked peppercorn cream sauce","how":"Dry-brine 4 rib eyes overnight. Sear hard, then baste with 60g butter and rosemary and rest 8 minutes. In the pan, crush 1 tbsp peppercorns, flame 60ml brandy, add 125ml stock and 200ml cream and reduce until it coats a spoon.","shop":["4 rib eye steaks@Meat","60g butter@Dairy","1 bunch rosemary@Produce","1 jar black peppercorns@Pantry","60ml brandy@Bottle shop","125ml beef stock@Pantry","200ml thickened cream@Dairy"]}],"w":[{"n":"Gekko's birthday cheesecake","note":"Baked cream cheese cheesecake with lemon zest on a biscuit crust","how":"Mix 250g crushed biscuits with 100g melted butter and press into a tin. Beat 750g cream cheese with 200g sugar, 3 eggs and lemon zest. Bake in a water bath at 150C for 60 minutes. Spread 300g sour cream on top and bake 10 minutes more. Chill overnight.","shop":["250g digestive biscuits@Pantry","100g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","1 lemon@Produce","300g sour cream@Dairy"]}],"d":[{"n":"Teldar speech old fashioned","note":"Bourbon, sugar syrup and bitters stirred over one big ice cube, citrus twist","how":"For each drink, stir 60ml bourbon, 10ml sugar syrup and 2 dashes aromatic bitters over ice for 30 seconds. Strain over one big ice cube in a short glass and twist a strip of orange peel over the top. Makes four.","shop":["240ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","1 bag caster sugar@Pantry"]}],"shopping":["300g eye fillet@Meat","2 shallot@Produce","1 jar capers@Pantry","1 jar cornichons@Pantry","1 jar Dijon mustard@Pantry","1 bottle Worcestershire sauce@Pantry","1 egg@Dairy","1 brioche loaf@Bakery","24 oysters@Seafood","80ml red wine vinegar@Pantry","2 lemons@Produce","4 rib eye steaks@Meat","160g butter@Dairy","1 bunch rosemary@Produce","1 jar black peppercorns@Pantry","60ml brandy@Bottle shop","125ml beef stock@Pantry","200ml thickened cream@Dairy","250g digestive biscuits@Pantry","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","1 lemon@Produce","300g sour cream@Dairy","240ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce"]}},"Ghost (1990)":{"poster":"assets/menu-posters/ghost-1990.jpg","colour":"#635076","servings":4,"tagline":"Love and clay.","cue":"Serve dessert when the pottery wheel scene starts.","menu":{"s":[{"n":"Hush puppies","note":"Cornmeal fritters, honey butter. Oda Mae's a fake, until Sam turns up","how":"Mix 150g cornmeal, 75g flour, 2 tsp baking powder, 1 tsp sugar and 1 tsp salt. Stir in 200ml buttermilk, 1 egg and 3 sliced spring onions. Drop teaspoons into oil at 180C and fry 3 minutes until golden. Serve hot with 60g butter beaten with 2 tbsp honey.","shop":["150g cornmeal@Pantry","75g plain flour@Pantry","2 tsp baking powder@Pantry","200ml buttermilk@Dairy","1 egg@Dairy","3 spring onions@Produce","60g butter@Dairy","2 tbsp honey@Pantry","2L vegetable oil@Pantry"]},{"n":"Tribeca loft crostini","note":"Garlic baguette, tomato and basil. Watch Sam float a penny for Molly","how":"Grill 16 baguette slices until charred at the edges and rub each with a cut garlic clove. Dice 4 ripe tomatoes and dress with torn basil, salt and 2 tbsp good olive oil. Spoon on just before serving so the toasts stay crisp.","shop":["1 baguette@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 bottle extra virgin olive oil@Pantry"]}],"m":[{"n":"Sam's Tribeca loft pasta","note":"Rigatoni with Italian sausage, fennel, white wine and cream","how":"Brown 4 Italian sausages, skins off and crumbled. Add 1 sliced fennel bulb and 2 garlic cloves and cook 8 minutes. Deglaze with 125ml white wine, add 150ml cream, and toss with 500g cooked rigatoni and 60g grated parmesan.","shop":["4 Italian sausages@Meat","1 fennel bulb@Produce","2 garlic cloves@Produce","125ml white wine@Bottle shop","150ml thickened cream@Dairy","500g rigatoni@Pantry","60g parmesan@Deli"]}],"w":[{"n":"Pottery wheel pie","note":"Apple pie in hand-pleated pastry, shaped at the wheel. Ditto","how":"Roll a sheet of shortcrust pastry into a rough circle. Toss 4 sliced apples with 60g sugar and 1 tsp cinnamon and pile in the middle. Fold the edges up by hand, pleating as you go, and bake at 200C for 40 minutes until golden.","shop":["1 sheet shortcrust pastry@Frozen","4 apples@Produce","60g caster sugar@Pantry","1 jar cinnamon@Pantry"]}],"d":[{"n":"Molly's studio mulled pinot noir","note":"Mulled red for Molly. Molly, you in danger, girl","how":"Pour 750ml pinot noir into a saucepan with 2 strips orange peel, the juice of 1 orange, 1 cinnamon stick, 2 star anise, 4 cloves and 3 tbsp honey. Warm over low heat for 15 minutes without boiling. Strain into 4 mugs and add a thin orange slice to each.","shop":["750ml pinot noir@Bottle shop","2 oranges@Produce","1 cinnamon stick@Pantry","2 star anise@Pantry","4 whole cloves@Pantry","3 tbsp honey@Pantry"]}],"shopping":["150g cornmeal@Pantry","75g plain flour@Pantry","2 tsp baking powder@Pantry","200ml buttermilk@Dairy","1 egg@Dairy","3 spring onions@Produce","60g butter@Dairy","5 tbsp honey@Pantry","2L vegetable oil@Pantry","1 baguette@Bakery","1 garlic clove@Produce","4 tomatoes@Produce","1 bunch basil@Produce","1 bottle extra virgin olive oil@Pantry","4 Italian sausages@Meat","1 fennel bulb@Produce","2 garlic cloves@Produce","125ml white wine@Bottle shop","150ml thickened cream@Dairy","500g rigatoni@Pantry","60g parmesan@Deli","1 sheet shortcrust pastry@Frozen","4 apples@Produce","60g caster sugar@Pantry","1 jar cinnamon@Pantry","750ml pinot noir@Bottle shop","2 oranges@Produce","1 cinnamon stick@Pantry","2 star anises@Pantry","4 whole cloves@Pantry"]}},"Brewster's Millions (1985)":{"poster":"assets/menu-posters/brewsters-millions-1985.jpg","colour":"#30634d","servings":4,"tagline":"Spend thirty million in thirty days. Start with dinner.","cue":"Order the most expensive thing on the menu when Monty books his hotel suite.","menu":{"s":[{"n":"Prawn cocktail for the whole hotel","note":"poached iced prawns on shredded iceberg with Marie Rose and a dusting of paprika","how":"Poach 500g green prawns in salted water with lemon and a bay leaf for 2 minutes, then plunge into iced water and peel. Mix 4 tbsp mayo with 2 tbsp tomato sauce and a squeeze of lemon. Serve on shredded iceberg in glasses, dusted with paprika.","shop":["500g green prawns@Seafood","1 lemon@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","0.5 iceberg lettuce@Produce","1 jar smoked paprika@Pantry"]},{"n":"Caviar blini","note":"warm buckwheat pancakes, crème fraîche, a big spoon of roe and chives, spend, spend, spend","how":"Warm 16 buckwheat blini on a tray at 180C for 5 minutes. Top each with a teaspoon of crème fraîche, about 150ml in total, then half a teaspoon of salmon roe and a few snipped chives. Serve straight away while they are still warm.","shop":["16 buckwheat blini@Bakery","150ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce"]}],"m":[{"n":"Surf and turf","note":"eye fillet and half a lobster tail with garlic butter and béarnaise, thirty million to burn","how":"Reduce 60ml white wine vinegar with tarragon to 2 tbsp, whisk with 3 yolks over a low heat and drizzle in 200g warm clarified butter. Sear 4 eye fillet steaks to medium rare and rest. Split 2 lobster tails, brush with garlic butter and grill for 6 minutes.","shop":["60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","250g butter@Dairy","4 eye fillet steaks@Meat","2 lobster tails@Seafood","2 garlic cloves@Produce"]}],"w":[{"n":"Rare stamp shortbread","note":"butter, icing sugar and rice flour biscuits with pinked edges, for the world's priciest postage","how":"Beat 250g butter with 100g icing sugar, then mix in 250g plain flour and 60g rice flour. Roll to 6mm, cut into rectangles with a pinking cutter and bake at 160C for 20 minutes. Cool and pipe a little stamp design on each with icing.","shop":["250g butter@Dairy","200g icing sugar@Pantry","250g plain flour@Pantry","60g rice flour@Pantry"]}],"d":[{"n":"Monty's champagne cocktails for the bar","note":"brut poured over a bitters-soaked sugar cube with orange liqueur and an orange twist","how":"Drop a sugar cube into each of 4 flutes and shake 2 dashes aromatic bitters onto each. Add 15ml orange liqueur to each glass. Top slowly with 120ml chilled brut champagne. Twist a strip of orange peel over each glass and drop it in.","shop":["4 sugar cubes@Pantry","aromatic bitters@Bottle shop","60ml orange liqueur@Bottle shop","1 bottle brut champagne@Bottle shop","1 orange@Produce"]}],"shopping":["500g green prawns@Seafood","1 lemon@Produce","1 jar mayonnaise@Pantry","1 bottle tomato sauce@Pantry","0.5 iceberg lettuce@Produce","1 jar smoked paprika@Pantry","16 buckwheat blinis@Bakery","150ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce","60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","500g butter@Dairy","4 eye fillet steaks@Meat","2 lobster tails@Seafood","2 garlic cloves@Produce","200g icing sugar@Pantry","250g plain flour@Pantry","60g rice flour@Pantry","4 sugar cubes@Pantry","aromatic bitters@Bottle shop","60ml orange liqueur@Bottle shop","1 bottle brut champagne@Bottle shop","1 orange@Produce"]}},"Splash (1984)":{"poster":"assets/menu-posters/splash-1984.jpg","colour":"#237d82","servings":4,"tagline":"Fresh from the ocean. Mostly.","cue":"Serve the lobster when Madison eats it whole at the restaurant.","menu":{"s":[{"n":"Oysters natural","note":"freshly shucked, straight off the Cape","how":"Finely dice 2 shallots and mix with 80ml red wine vinegar and plenty of cracked pepper. Rest 20 minutes. Lay 24 freshly shucked oysters on crushed ice, with lemon wedges and the mignonette in a small bowl with a spoon.","shop":["24 freshly shucked oysters@Seafood","2 shallots@Produce","80ml red wine vinegar@Pantry","2 lemons@Produce"]},{"n":"Fish and chip cones","note":"Cape Cod, where they first meet","how":"Whisk 150g flour, 50g cornflour and 300ml cold lager to a batter. Cut 600g potatoes into chips and fry twice. Dip 500g flathead strips in batter and fry at 180C for 3 minutes. Serve in paper cones with tartare and lemon.","shop":["150g plain flour@Pantry","50g cornflour@Pantry","375ml lager@Bottle shop","600g potatoes@Produce","500g flathead fillets@Seafood","1 jar tartare sauce@Pantry","1 lemon@Produce","2L vegetable oil@Pantry"]}],"m":[{"n":"Whole lobster","note":"drawn butter, shell optional, Madison eats it all","how":"Cook 2 raw lobsters, about 800g each, in boiling salted water for 8 minutes per 500g. Split lengthways, crack the claws and brush the flesh with 100g butter melted with 3 garlic cloves. Grill flesh-side up for 2 minutes. Serve with drawn butter and lemon.","shop":["2 whole lobsters@Seafood","200g butter@Dairy","3 garlic cloves@Produce","2 lemons@Produce"]}],"w":[{"n":"Ocean blue jelly cups","note":"Madison's home under the sea","how":"Bloom 3 gelatine leaves and stir into 400ml warm coconut milk with 60g sugar. Set in four glasses for 2 hours. Steep 10 butterfly pea flowers in 400ml hot water with 60g sugar, add 3 more gelatine leaves, cool and pour over. Set, then add gummy fish.","shop":["6 gelatine leaves@Pantry","400ml coconut milk@Pantry","120g caster sugar@Pantry","1 packet dried butterfly pea flowers@Pantry","1 bag gummy fish@Pantry"]}],"d":[{"n":"Blue lagoon","note":"vodka and curaçao topped with lemonade over ice, lemon wheel, for the dive off the pier","how":"For each drink, fill a tall glass with ice and add 30ml vodka and 20ml blue curaçao. Top with about 150ml lemonade and stir gently. Garnish with a lemon wheel. Makes four, so mix them one at a time.","shop":["120ml vodka@Bottle shop","80ml blue curaçao@Bottle shop","600ml lemonade@Drinks","1 lemon@Produce"]}],"shopping":["24 freshly shucked oysters@Seafood","2 shallots@Produce","80ml red wine vinegar@Pantry","6 lemons@Produce","150g plain flour@Pantry","50g cornflour@Pantry","375ml lager@Bottle shop","600g potatoes@Produce","500g flathead fillets@Seafood","1 jar tartare sauce@Pantry","2L vegetable oil@Pantry","2 whole lobsters@Seafood","200g butter@Dairy","3 garlic cloves@Produce","6 gelatine leaves@Pantry","400ml coconut milk@Pantry","120g caster sugar@Pantry","1 packet dried butterfly pea flowers@Pantry","1 bag gummy fish@Pantry","120ml vodka@Bottle shop","80ml blue curaçao@Bottle shop","600ml lemonade@Drinks"]}},"Big (1988)":{"poster":"assets/menu-posters/big-1988.jpg","colour":"#9c292c","servings":4,"tagline":"Grown-up food for a kid at heart.","cue":"Serve the snacks when Josh eats baby corn like a tiny corn cob at the company party.","menu":{"s":[{"n":"Baby corn","note":"eat it off the cob with both hands, like Josh","how":"Blanch 400g baby corn in salted boiling water for 2 minutes and drain well. Char on a hot griddle for 3 minutes with 30g butter, then sprinkle with chilli flakes, lime zest and salt. Serve with lime wedges and eat it like a cob.","shop":["400g baby corn@Produce","30g butter@Dairy","2 limes@Produce","1 jar chilli flakes@Pantry"]},{"n":"Caviar on crackers","note":"water biscuits with crème fraîche, salmon roe and chives, for Josh to spit out politely","how":"Spread 20 water crackers with a teaspoon of crème fraîche each, about 200ml in total. Top each with half a teaspoon of salmon roe and a few snipped chives. Assemble just before serving so the crackers stay crisp and Josh can spit one out.","shop":["1 packet water crackers@Pantry","200ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce"]}],"m":[{"n":"Street cart hot dog","note":"Josh and Billy loose in the city","how":"Simmer 8 franks in water with half an onion for 5 minutes, then griddle until blistered. Soften 2 sliced onions in oil for 15 minutes, add 2 tbsp tomato paste and a splash of vinegar. Steam 8 buns, fill and top with mustard and sauerkraut.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","3 brown onions@Produce","1 jar sauerkraut@Pantry","1 tube tomato paste@Pantry"]}],"w":[{"n":"Giant choc chip cookie","note":"brown butter dough baked whole in a pizza tray, soft centre, piano keys piped in icing","how":"Brown 150g butter and cool. Beat with 200g brown sugar and 1 egg, then mix in 250g flour, half a tsp bicarb and 200g choc chips. Press into a pizza tray and bake at 180C for 18 minutes. Cool and pipe white icing piano keys across it.","shop":["150g butter@Dairy","200g brown sugar@Pantry","1 egg@Dairy","250g plain flour@Pantry","200g choc chips@Pantry","200g icing sugar@Pantry"]}],"d":[{"n":"Chocolate egg cream","note":"chocolate syrup, milk and soda stirred to foam, for a boy of twelve in a suit","how":"For each of 4 tall glasses add 2 tbsp chocolate syrup and 80ml cold milk. Pour in 150ml chilled soda water hard from a height, stirring with a long spoon so a white foam head rises up the glass. Serve with a straw straight away.","shop":["120ml chocolate syrup@Pantry","320ml milk@Dairy","600ml soda water@Drinks"]}],"shopping":["400g baby corn@Produce","180g butter@Dairy","2 limes@Produce","1 jar chilli flakes@Pantry","1 packet water crackers@Pantry","200ml crème fraîche@Dairy","100g salmon roe@Seafood","1 bunch chives@Produce","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","3 brown onions@Produce","1 jar sauerkraut@Pantry","1 tube tomato paste@Pantry","200g brown sugar@Pantry","1 egg@Dairy","250g plain flour@Pantry","200g choc chips@Pantry","200g icing sugar@Pantry","120ml chocolate syrup@Pantry","320ml milk@Dairy","600ml soda water@Drinks"]}},"C.H.U.D. (1984)":{"poster":"assets/menu-posters/c-h-u-d-1984.jpg","colour":"#486234","servings":4,"tagline":"Don't go down the drain.","cue":"Serve the soup when the Reverend's soup kitchen opens.","menu":{"s":[{"n":"Soup kitchen cheddar and onion rolls","note":"the Reverend's shelter, ready for dunking into the stew","how":"Fry 1 sliced onion in 20g butter for 15 minutes until golden. Mix 500g bread flour, 7g yeast, 1 tsp salt, 1 tsp sugar, 300ml warm milk and 30g melted butter, knead 8 minutes and rise 1 hour. Knead in the onion and 100g grated cheddar, shape 12 rolls and pack into a tin. Rise 30 minutes, top with 50g more cheddar and bake at 200C for 20 minutes.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml milk@Dairy","70g butter@Dairy","1 onion@Produce","150g sharp cheddar@Dairy","1 tsp sugar@Pantry"]},{"n":"Manhole cover mini pizzas","note":"round, cheesy and heavy","how":"Roll 500g pizza dough thin and cut 12 rounds. Spread with pizza sauce, using 150ml, and top with 150g grated mozzarella. Slice 80g pepperoni into thin strips and lay them in a crosshatch like a manhole grate. Bake at 230C for 8 minutes.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","80g pepperoni@Deli"]}],"m":[{"n":"The Reverend's soup kitchen stew","note":"hearty, nothing from below ground","how":"Brown 1kg diced beef chuck in batches. Add 2 chopped brown onions, 3 carrots, 2 celery sticks and 2 tbsp tomato paste and cook 5 minutes, then 1 litre beef stock. Cover and braise at 160C for 2.5 hours, adding 600g potatoes in chunks for the last hour. Serve with a loaf of Italian bread.","shop":["1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","2 celery sticks@Produce","2 tbsp tomato paste@Pantry","1L beef stock@Pantry","600g potatoes@Produce","1 loaf Italian bread@Bakery"]}],"w":[{"n":"Manhattan cider doughnuts","note":"soft cake rings made with reduced apple juice, tossed in cinnamon sugar","how":"Reduce 500ml apple juice to 125ml. Mix with 60g melted butter, 1 egg, 100g sugar and 250g self-raising flour into a soft dough. Pat out, cut 12 rings and fry at 175C for 2 minutes a side. Toss in sugar and cinnamon.","shop":["500ml apple juice@Drinks","60g butter@Dairy","1 egg@Dairy","200g caster sugar@Pantry","250g self-raising flour@Pantry","1 tsp ground cinnamon@Pantry","1L vegetable oil@Pantry"]}],"d":[{"n":"Glowing green cordial","note":"lime cordial topped with tonic, which glows under a black light, like what's under the manhole","how":"Pour 40ml lime cordial into each of four tall glasses over ice and top with tonic water, about 250ml each. Tonic glows blue-white under a black light, so switch the lights off.","shop":["160ml lime cordial@Drinks","1L tonic water@Drinks","1kg ice@Frozen"]}],"shopping":["500g bread flour@Pantry","7g dried yeast@Pantry","300ml milk@Dairy","130g butter@Dairy","1 onion@Produce","150g sharp cheddar@Dairy","1 tsp sugar@Pantry","500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","80g pepperoni@Deli","1kg beef chuck@Meat","2 brown onions@Produce","3 carrots@Produce","2 celery sticks@Produce","2 tbsp tomato paste@Pantry","1L beef stock@Pantry","600g potatoes@Produce","1 loaf Italian bread@Bakery","500ml apple juice@Drinks","1 egg@Dairy","200g caster sugar@Pantry","250g self-raising flour@Pantry","1 tsp ground cinnamon@Pantry","1L vegetable oil@Pantry","160ml lime cordial@Drinks","1L tonic water@Drinks","1kg ice@Frozen"]}},"Money Train (1995)":{"poster":"assets/menu-posters/money-train-1995.jpg","colour":"#cf6024","servings":4,"tagline":"Last train of the night. Snacks for the platform.","cue":"Pour drinks when Charlie sneaks aboard the money train on New Year's Eve.","menu":{"s":[{"n":"Token booth honey roasted nuts","note":"a mixed handful glazed in honey, sugar and cinnamon, oven-toasted, before the Torch turns up","how":"Toss 300g mixed nuts with 2 tbsp honey, 1 tbsp caster sugar, 1/2 tsp ground cinnamon and a pinch of salt. Spread on a lined tray and roast at 170C for 15 minutes, stirring halfway. Keep stirring as they cool so they don't clump.","shop":["300g mixed nuts@Pantry","2 tbsp honey@Pantry","1 tbsp caster sugar@Pantry","1/2 tsp ground cinnamon@Pantry"]},{"n":"Gold token cookies","note":"round, gold and stamped like a subway token","how":"Beat 200g soft butter with 100g icing sugar and mix in 300g plain flour to a dough. Roll 5mm thick, cut rounds the size of a subway token and cut a small hole from the middle of each. Bake at 160C for 15 minutes and cool. Brush with edible gold dust mixed with a drop of water.","shop":["200g butter@Dairy","100g icing sugar@Pantry","300g plain flour@Pantry","1 jar edible gold dust@Pantry"]}],"m":[{"n":"Arroz con pollo","note":"browned thighs, sofrito, annatto, olives and capers, cooked with rice, for Grace the decoy cop","how":"Brown 800g chicken thighs and set aside. Fry 1 onion, 1 capsicum, 3 garlic cloves and a handful of coriander until soft, add 1 tsp ground annatto, 300g long grain rice, 60g green olives, 1 tbsp capers and 650ml chicken stock. Sit the chicken on top, cover and cook on low for 25 minutes until the rice is tender.","shop":["800g chicken thighs@Meat","1 brown onion@Produce","1 capsicum@Produce","3 garlic cloves@Produce","1 bunch coriander@Produce","1 tsp ground annatto@Pantry","300g long grain rice@Pantry","60g green olives@Deli","1 tbsp capers@Pantry","650ml chicken stock@Pantry"]}],"w":[{"n":"Guava pastelitos","note":"flaky puff pastry squares filled with guava paste and cream cheese, glazed with syrup","how":"Cut 2 sheets puff pastry into 8 squares each. Put a slice of guava paste and a little cream cheese on half, cover with the rest and seal. Bake at 200C for 20 minutes and brush with sugar syrup.","shop":["2 sheets puff pastry@Frozen","250g guava paste@Pantry","150g cream cheese@Dairy","3 tbsp caster sugar@Pantry"]}],"d":[{"n":"Money Train payday michelada","note":"a whole train full of fare money, too tempting for Charlie","how":"Mix 1 tbsp flaky salt with 1 tsp chilli powder. Rub a lime wedge around 4 glass rims and dip in the salt. Add ice, 30ml lime juice, 60ml tomato juice, 4 dashes hot sauce and 2 dashes Worcestershire to each glass. Top each with a 375ml cold lager, stir gently and slip the glasses into small paper bags.","shop":["4 bottles lager@Bottle shop","3 limes@Produce","240ml tomato juice@Drinks","hot sauce@Pantry","Worcestershire sauce@Pantry","chilli powder@Pantry","flaky sea salt@Pantry","1 bag ice@Frozen"]}],"shopping":["300g mixed nuts@Pantry","2 tbsp honey@Pantry","4 tbsp caster sugar@Pantry","1/2 tsp ground cinnamon@Pantry","200g butter@Dairy","100g icing sugar@Pantry","300g plain flour@Pantry","1 jar edible gold dust@Pantry","800g chicken thighs@Meat","1 brown onion@Produce","1 capsicum@Produce","3 garlic cloves@Produce","1 bunch coriander@Produce","1 tsp ground annatto@Pantry","300g long grain rice@Pantry","60g green olives@Deli","1 tbsp capers@Pantry","650ml chicken stock@Pantry","2 sheets puff pastries@Frozen","250g guava paste@Pantry","150g cream cheese@Dairy","4 bottles lagers@Bottle shop","3 limes@Produce","240ml tomato juice@Drinks","hot sauce@Pantry","Worcestershire sauce@Pantry","chilli powder@Pantry","flaky sea salt@Pantry","1 bag ice@Frozen"]}},"Inside Man (2006)":{"poster":"assets/menu-posters/inside-man-2006.jpg","colour":"#82652d","servings":4,"tagline":"The perfect heist needs a perfect lunch.","cue":"Serve the pizza when the hostages get their delivery.","menu":{"s":[{"n":"Hostage pizza bites","note":"mini dough rounds with tomato, mozzarella and pepperoni, like the boxes the cops send in bugged","how":"Roll 500g pizza dough thin and cut 16 rounds with a glass. Top each with a spoon of pizza sauce, using 150ml, a pinch of grated mozzarella, 150g in total, and a slice of pepperoni. Bake at 230C for 8 minutes until golden underneath.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperoni@Deli"]},{"n":"Brooklyn potato knishes","note":"slow butter-fried onion and mashed potato rolled in puff pastry, baked golden, hot mustard","how":"Boil 500g peeled potatoes 15 minutes and mash. Cook 1 diced brown onion in 30g butter over low heat for 15 minutes and mix in with salt and white pepper. Spread along 2 sheets puff pastry, roll into logs, cut into 8 and brush with 1 beaten egg. Bake at 200C for 25 minutes. Serve with 40g hot English mustard.","shop":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]}],"m":[{"n":"Manhattan steak sandwich","note":"seared sirloin on toasted ciabatta, caramelised onions, rocket and horseradish, for Madeleine White","how":"Cook 2 sliced brown onions in butter over low heat for 30 minutes until jammy. Sear 2 sirloin steaks, about 600g, hard for 3 minutes a side, rest and slice thin. Split and toast 4 pieces of ciabatta, spread with 100g horseradish cream and pile with steak, onions and 60g rocket.","shop":["2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce"]}],"w":[{"n":"Rainbow cookies","note":"from the Italian bakery round the corner","how":"Beat 200g butter with 200g sugar, then 4 eggs, 200g almond meal and 150g flour. Divide in 3, tint one green and one red, and bake each in a lined 20x30cm tin at 180C for 12 minutes. Stack with 150g apricot jam between, press under a tray overnight, spread with 150g melted dark chocolate and cut into small squares.","shop":["200g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","200g almond meal@Pantry","150g plain flour@Pantry","150g apricot jam@Pantry","150g dark chocolate@Pantry","1 pack food colouring@Pantry"]}],"d":[{"n":"Negotiator's espresso orange tonic","note":"fuel for the long negotiation outside the bank","how":"Brew 4 double espressos and let them cool for 5 minutes. Fill 4 tall glasses with ice and a thin orange slice each. Pour 150ml chilled tonic water into each glass. Slowly pour a double espresso over the back of a spoon so it floats on top. Stir at the table.","shop":["72g espresso coffee beans@Pantry","600ml tonic water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperonis@Deli","500g potatoes@Produce","3 brown onions@Produce","250g butter@Dairy","2 sheets puff pastries@Frozen","5 eggs@Dairy","40g hot English mustard@Pantry","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce","200g caster sugar@Pantry","200g almond meal@Pantry","150g plain flour@Pantry","150g apricot jam@Pantry","150g dark chocolate@Pantry","1 pack food colouring@Pantry","72g espresso coffee beans@Pantry","600ml tonic water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}},"Escape from New York (1981)":{"poster":"assets/menu-posters/escape-from-new-york-1981.jpg","colour":"#b93423","servings":4,"tagline":"Get in. Get the President. Get dinner.","cue":"Serve the mains when the Duke and his followers confront Snake in the street.","menu":{"s":[{"n":"Cabbie's smoky chilli beef jerky","note":"thin topside in soy, Worcestershire, smoked paprika and brown sugar, dried low until chewy","how":"Freeze 600g topside for 1 hour, then slice 3mm thick across the grain. Mix 80ml soy sauce, 2 tbsp Worcestershire, 2 tbsp brown sugar, 2 tsp smoked paprika, 1 tsp chilli flakes and 1 tsp garlic powder. Marinate the beef overnight. Pat dry, lay on racks over trays and dry at 75C with the oven door slightly open for 3 to 4 hours until leathery but still bendy.","shop":["600g beef topside@Meat","80ml soy sauce@Pantry","2 tbsp Worcestershire sauce@Pantry","2 tbsp brown sugar@Pantry","2 tsp smoked paprika@Pantry","1 tsp chilli flakes@Pantry","1 tsp garlic powder@Pantry"]},{"n":"Survival tin sardines","note":"eating out of tins in a city with no shops","how":"Drain 2 tins sardines in oil, about 220g. Lay a sardine on each of 24 saltine crackers, squeeze over lemon, add a drop of hot sauce and a little chopped parsley. Serve on the tin lids for the full survival look.","shop":["220g tinned sardines@Pantry","24 saltine crackers@Pantry","1 lemon@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce"]}],"m":[{"n":"Scavenger's hobo stew","note":"smoky sausage, potato, carrot, cabbage and beans simmered thick with paprika, served in tin mugs","how":"Brown 500g sliced smoked sausage in a big pot. Add 1 diced onion, 2 carrots and 600g diced potatoes, cook 5 minutes, then 1 tsp smoked paprika, 1 can cannellini beans, 400g crushed tomatoes and 750ml chicken stock. Simmer 30 minutes, add a quarter cabbage shredded for the last 10, season and serve in mugs.","shop":["500g smoked sausages@Meat","1 onion@Produce","2 carrots@Produce","600g potatoes@Produce","1 tsp smoked paprika@Pantry","400g cannellini beans@Pantry","400g crushed tomatoes@Pantry","750ml chicken stock@Pantry","1 cabbage@Produce"]}],"w":[{"n":"Ration-pack chocolate oat slice","note":"chewy golden syrup oats under dark chocolate and flaky salt, call me Snake","how":"Melt 150g butter with 3 tbsp golden syrup and 100g brown sugar. Stir in 250g rolled oats and a pinch of salt, then press firmly into a lined 20cm square tin. Bake at 180C for 20 minutes until golden. Melt 150g dark chocolate, spread over the warm slice and sprinkle with flaky salt. Cool, chill for 1 hour and cut into 16 bars.","shop":["150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","150g dark chocolate@Pantry","flaky sea salt@Pantry"]}],"d":[{"n":"Brain's bathtub moonshine sour","note":"clear corn whiskey shaken with lemon and sugar, in jam jars, for the bridge run","how":"Shake 60ml corn whiskey or white whiskey, 30ml lemon juice and 20ml sugar syrup with ice and strain into 4 ice-filled jam jars. Lemonade and lemon for anyone not drinking.","shop":["240ml white whiskey@Bottle shop","3 lemons@Produce","2 tbsp caster sugar@Pantry"]}],"shopping":["600g beef topside@Meat","80ml soy sauce@Pantry","2 tbsp Worcestershire sauce@Pantry","2 tbsp brown sugar@Pantry","3 tsp smoked paprika@Pantry","1 tsp chilli flakes@Pantry","1 tsp garlic powder@Pantry","220g tinned sardines@Pantry","24 saltine crackers@Pantry","4 lemons@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce","500g smoked sausages@Meat","1 onion@Produce","2 carrots@Produce","600g potatoes@Produce","400g cannellini beans@Pantry","400g crushed tomatoes@Pantry","750ml chicken stock@Pantry","1 cabbage@Produce","150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","150g dark chocolate@Pantry","flaky sea salt@Pantry","240ml white whiskey@Bottle shop","2 tbsp caster sugar@Pantry"]}},"Serpico (1973)":{"poster":"assets/menu-posters/serpico-1973.jpg","colour":"#656235","servings":4,"tagline":"One honest cop. No free sandwiches.","cue":"Serve the mains when Frank asks to pay for the free roast beef lunch.","menu":{"s":[{"n":"Village bagels and lox","note":"toasted with cream cheese, smoked salmon, capers and red onion, for the beard and the beads","how":"Split and toast 4 bagels. Spread each half thickly with cream cheese, using 200g in total. Top with 200g smoked salmon, 1 tbsp capers, thinly sliced red onion and small sprigs of dill. Cut each half in two to share.","shop":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce"]},{"n":"Deli pastrami on rye","note":"hot cured beef sliced thin and piled high with brown mustard, a pickle on the side","how":"Steam 500g sliced pastrami in a covered colander over simmering water for 8 minutes until hot and soft. Spread 8 slices rye bread with deli mustard, pile the pastrami high on 4 of them and close. Cut in half and serve with a dill pickle each.","shop":["500g pastrami@Deli","8 slices rye bread@Bakery","4 tbsp deli mustard@Pantry","4 dill pickles@Pantry"]}],"m":[{"n":"Deli hero, paid for","note":"steamed pastrami in a long roll with Swiss, coleslaw and Russian dressing","how":"Steam 500g sliced pastrami for 10 minutes until glossy. Mix 100g mayonnaise with 2 tbsp tomato sauce, 1 tsp horseradish and 1 tbsp chopped pickle for Russian dressing. Toss 250g coleslaw mix with half the dressing. Fill 4 long rolls with pastrami, 8 slices Swiss cheese, the slaw and the rest of the dressing.","shop":["500g pastrami@Deli","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheese@Deli"]}],"w":[{"n":"Black and white cookies","note":"soft vanilla rounds iced half white fondant, half chocolate, like a precinct split down the middle","how":"Beat 115g butter with 150g caster sugar, add 1 egg, 80g sour cream and 1 tsp vanilla, then mix in 250g plain flour and 1 tsp baking powder. Scoop 12 mounds onto lined trays and bake at 180C for 12 minutes. Make a thick icing with 250g icing sugar and hot water, ice half of each flat side, then add 2 tbsp cocoa to the rest and ice the other half.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Village vanilla iced coffee, paid for","note":"cold brew with vanilla syrup and milk over ice, a scoop of ice cream on top","how":"The night before, stir 80g coarse ground coffee into 800ml cold water and refrigerate 12 hours, then strain through a paper filter. Simmer 50g sugar with 50ml water and half a tsp vanilla extract for 1 minute and cool. Fill 4 glasses with ice, add 150ml coffee, 15ml syrup and 80ml milk to each. Top with a small scoop of vanilla ice cream.","shop":["80g coarse ground coffee@Pantry","50g sugar@Pantry","vanilla extract@Pantry","350ml milk@Dairy","500ml vanilla ice cream@Frozen","1 bag ice@Frozen"]}],"shopping":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce","1kg pastrami@Deli","8 slices rye breads@Bakery","4 tbsp deli mustard@Pantry","4 dill pickles@Pantry","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheeses@Deli","115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry","80g coarse ground coffee@Pantry","50g sugar@Pantry","vanilla extract@Pantry","350ml milk@Dairy","500ml vanilla ice cream@Frozen","1 bag ice@Frozen"]}},"Home Alone 2: Lost in New York (1992)":{"poster":"assets/menu-posters/home-alone-2-lost-in-new-york-1992.jpg","colour":"#205139","servings":4,"tagline":"Room service. Charge it to Dad.","cue":"Order room service when Kevin gets his own suite.","menu":{"s":[{"n":"Hotel minibar mix","note":"nuts and chocolate, the overpriced stuff","how":"Melt 30g butter with 2 tbsp brown sugar and 1 tbsp chopped rosemary. Toss through 300g mixed nuts, spread on a tray and roast at 170C for 12 minutes, stirring once. Cool, then mix with 150g chocolate almonds and 100g pretzels.","shop":["30g butter@Dairy","2 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","300g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry"]},{"n":"Kevin's room service club sandwiches","note":"triple-decker of chicken, bacon, lettuce, tomato and mayo, part of a $967 hotel bill","how":"Poach 2 chicken breasts (400g) for 12 minutes and slice. Grill 8 rashers bacon until crisp. Toast 12 slices white bread and spread with mayonnaise. Build 4 triple-deckers with chicken, bacon, iceberg and sliced tomato, cut into quarters and pin each with a toothpick.","shop":["400g chicken breast@Meat","8 rashers bacon@Meat","12 slices white bread@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","4 tbsp mayonnaise@Pantry"]}],"m":[{"n":"Lobster mac and cheese","note":"macaroni in a Gruyère and cheddar sauce with butter-poached lobster, buttery crumbs, baked","how":"Gently poach the meat of 2 lobster tails in 40g butter for 4 minutes and chop. Melt 40g butter, stir in 40g flour, then whisk in 600ml warm milk and simmer 5 minutes. Stir in 120g grated Gruyère and 100g cheddar. Fold through 400g cooked macaroni and the lobster, tip into a dish, top with 40g panko mixed with 20g melted butter and bake at 200C for 20 minutes.","shop":["2 lobster tails@Seafood","100g butter@Dairy","40g plain flour@Pantry","600ml full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry"]}],"w":[{"n":"Room service sundae","note":"hot fudge, caramel, nuts and a cherry, merry Christmas, ya filthy animal","how":"Melt 100g dark chocolate with 100ml thickened cream for hot fudge. Whip another 200ml cream. Pile 8 scoops vanilla ice cream into four tall glasses, pour over the fudge, add the cream, 40g chopped nuts, sprinkles and a maraschino cherry on each.","shop":["100g dark chocolate@Pantry","300ml thickened cream@Dairy","1L vanilla ice cream@Frozen","40g mixed nuts@Pantry","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry"]}],"d":[{"n":"Hot apple cider","note":"winter in Central Park with the pigeon lady","how":"Warm 1L cloudy apple juice with 2 cinnamon sticks, 6 cloves, 3 strips orange peel and 1 tbsp brown sugar over low heat for 15 minutes without boiling. Strain into 4 mugs and serve steaming with a cinnamon stick in each.","shop":["1L cloudy apple juice@Drinks","6 cinnamon sticks@Pantry","6 cloves@Pantry","1 orange@Produce","1 tbsp brown sugar@Pantry"]}],"shopping":["130g butter@Dairy","3 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","340g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry","400g chicken breast@Meat","8 rashers bacon@Meat","12 slices white bread@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","4 tbsp mayonnaise@Pantry","2 lobster tails@Seafood","40g plain flour@Pantry","600ml full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry","100g dark chocolate@Pantry","300ml thickened cream@Dairy","1L vanilla ice cream@Frozen","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry","1L cloudy apple juice@Drinks","6 cinnamon sticks@Pantry","6 cloves@Pantry","1 orange@Produce"]}},"The Departed (2006)":{"poster":"assets/menu-posters/the-departed-2006.jpg","colour":"#233c52","servings":4,"tagline":"Two rats. One city. Plenty of chowder.","cue":"Serve the mains when Costigan goes undercover in Costello's crew.","menu":{"s":[{"n":"Boston clam chowder cups","note":"with oyster crackers, the Boston way","how":"Fry 150g diced bacon until crisp, then sweat 1 diced onion and 2 celery sticks in the fat. Add 400g diced potatoes, 500ml clam juice or fish stock and thyme and simmer 15 minutes. Stir in 250g chopped clam meat and 200ml cream for the last 3 minutes. Serve in cups with 100g oyster crackers.","shop":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","400g potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","200ml thickened cream@Dairy","100g oyster crackers@Pantry"]},{"n":"Irish soda bread and butter","note":"wholemeal buttermilk loaf baked crusty with a deep cross, salted butter, for Frank Costello's crowd","how":"Mix 250g wholemeal flour, 250g plain flour, 1 tsp bicarbonate of soda and 1 tsp salt. Stir in 450ml buttermilk to a soft dough, shape into a round, cut a deep cross on top and bake at 220C for 35 minutes until it sounds hollow. Rest 10 minutes, slice thick and serve with 100g salted butter.","shop":["250g wholemeal flour@Pantry","250g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","450ml buttermilk@Dairy","100g salted butter@Dairy"]}],"m":[{"n":"Southie fish and chips","note":"flathead in crisp lager batter, triple-cooked potatoes, minty mushy peas and malt vinegar","how":"Whisk 200g plain flour, 50g cornflour and 330ml ice-cold lager into a batter. Dust 800g flathead fillets in flour, dip and fry at 180C for 4 minutes. Fry 1kg potatoes as chips at 140C then 185C. Cook 400g frozen peas, crush with butter and mint. Serve with malt vinegar.","shop":["200g plain flour@Pantry","50g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","1kg potatoes@Produce","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","2L vegetable oil@Pantry","2 tbsp malt vinegar@Pantry"]}],"w":[{"n":"Boston cream pie","note":"two genoise sponges filled with vanilla crème pâtissière under glossy dark chocolate ganache","how":"Whisk 4 eggs and 120g sugar until thick, fold in 120g flour and bake in two 20cm tins at 180C for 18 minutes. For custard, heat 300ml milk, whisk into 3 yolks, 60g sugar and 25g cornflour and cook until thick, then cool. Sandwich the sponges with custard. Melt 100g dark chocolate with 100ml cream and pour over the top.","shop":["7 eggs@Dairy","180g caster sugar@Pantry","120g plain flour@Pantry","300ml full cream milk@Dairy","25g cornflour@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy"]}],"d":[{"n":"Costigan's cranberry lime crush","note":"Costigan's bar order, and Mr. French who won't let it go","how":"Shake 400ml cranberry juice, 60ml lime juice, 60ml orange juice and 20ml sugar syrup with ice for 10 seconds. Strain into 4 short glasses filled with crushed ice. Top each with 50ml soda water and add a lime wedge. For the grown-up version, add 30ml vodka to each glass before topping.","shop":["400ml cranberry juice@Drinks","3 limes@Produce","1 orange@Produce","20ml sugar syrup@Pantry","200ml soda water@Drinks","1 bag crushed ice@Frozen"]}],"shopping":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","1.4kg potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","300ml thickened cream@Dairy","100g oyster crackers@Pantry","250g wholemeal flour@Pantry","570g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","450ml buttermilk@Dairy","100g salted butter@Dairy","75g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","2L vegetable oil@Pantry","2 tbsp malt vinegar@Pantry","7 eggs@Dairy","180g caster sugar@Pantry","300ml full cream milk@Dairy","100g dark chocolate@Pantry","400ml cranberry juice@Drinks","3 limes@Produce","1 orange@Produce","20ml sugar syrup@Pantry","200ml soda water@Drinks","1 bag crushed ice@Frozen"]}},"Get Shorty (1995)":{"poster":"assets/menu-posters/get-shorty-1995.jpg","colour":"#e15f20","servings":4,"tagline":"Loan shark goes Hollywood. Pass the dip.","cue":"Serve the mains when Chili starts pitching his movie idea.","menu":{"s":[{"n":"Ray Bones' Miami croquetas","note":"crumbed ham logs in nutmeg béchamel, crisp outside, before Chili gets his leather jacket back","how":"Melt 60g butter, cook 80g flour for 1 minute and whisk in 500ml milk until very thick. Stir in 200g finely chopped ham and nutmeg, chill 3 hours. Shape 20 logs, roll in egg and breadcrumbs and fry at 180C until golden.","shop":["60g butter@Dairy","80g plain flour@Pantry","500ml full cream milk@Dairy","200g leg ham@Deli","2 eggs@Dairy","120g breadcrumbs@Pantry","1L vegetable oil@Pantry"]},{"n":"Hollywood power lunch crudités","note":"baby carrots, radishes and cos with tarragon anchovy green goddess, for a studio pitch meeting","how":"Blitz the mayonnaise, sour cream, a big handful each of parsley and tarragon, half the chives, the anchovies and the lemon juice until smooth and green. Trim the carrots and radishes, leaving a little green on top. Cut the cucumber into batons and pull the cos into leaves. Stand the vegetables up in glasses of ice and serve with the green goddess in a bowl.","shop":["2 bunches baby carrots@Produce","1 bunch radishes@Produce","1 telegraph cucumber@Produce","2 baby cos lettuces@Produce","125g mayonnaise@Pantry","125g sour cream@Dairy","1 bunch flat-leaf parsley@Produce","1 bunch tarragon@Produce","1 bunch chives@Produce","3 anchovy fillets@Pantry","1 lemon@Produce"]}],"m":[{"n":"Chili Palmer's steak frites","note":"seared sirloin, shallot and red wine butter, double-fried chips, look at me","how":"Fry 1kg potatoes cut into thin frites at 140C for 5 minutes, rest, then at 185C until crisp. Season 4 sirloin steaks, about 800g, sear hard for 3 minutes a side and rest. Sweat 2 chopped shallots in the pan fat, add 150ml red wine and reduce by two thirds, then whisk in 50g cold butter. Slice the steak and spoon the sauce over.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","50g butter@Dairy"]}],"w":[{"n":"Harry Zimm's B-movie popcorn sundae","note":"vanilla ice cream, hot fudge, caramel popcorn and peanuts, for the cinema showing Touch of Evil","how":"Pop 40g popcorn kernels. Melt 50g butter with 80g brown sugar, toss through the popcorn and bake at 150C for 10 minutes to set. Melt 100g dark chocolate with 100ml cream for hot fudge. Scoop 8 balls of vanilla ice cream into four bowls, pour over the fudge and top with the popcorn and 50g salted peanuts.","shop":["40g popcorn kernels@Pantry","50g butter@Dairy","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry"]}],"d":[{"n":"Acting lesson Bloody Mary","note":"Chili showing a movie star how to stare a man down","how":"For each drink, put 45ml vodka, 120ml tomato juice, 10ml lemon juice, 2 dashes Worcestershire sauce, 2 dashes hot sauce and a pinch each of celery salt and pepper in a tin with ice. Pour back and forth between two tins 5 times, strain over fresh ice and add a celery stick. Makes four.","shop":["180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}],"shopping":["160g butter@Dairy","80g plain flour@Pantry","500ml full cream milk@Dairy","200g leg ham@Deli","2 eggs@Dairy","120g breadcrumbs@Pantry","2.5L vegetable oil@Pantry","2 bunches baby carrots@Produce","1 bunch radishes@Produce","1 telegraph cucumber@Produce","2 baby cos lettuces@Produce","125g mayonnaise@Pantry","125g sour cream@Dairy","1 bunch flat-leaf parsley@Produce","1 bunch tarragon@Produce","1 bunch chives@Produce","3 anchovy fillets@Pantry","2 lemons@Produce","1kg potatoes@Produce","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","40g popcorn kernels@Pantry","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry","180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}},"Bugsy (1991)":{"poster":"assets/menu-posters/bugsy-1991.jpg","colour":"#b78a37","servings":4,"tagline":"He dreamed up Las Vegas. Then he blew the budget.","cue":"Serve dessert when Ben first sees the Nevada desert.","menu":{"s":[{"n":"Hollywood party blini and caviar","note":"warm buckwheat pancakes with crème fraîche, roe or caviar and chives, for Ben's screen test","how":"Warm 16 buckwheat blini at 180C for 5 minutes. Top each with a teaspoon of crème fraîche, half a teaspoon of salmon roe and snipped chives. Serve straight away on a silver tray.","shop":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce"]},{"n":"Hollywood Cobb salad cups","note":"gem lettuce cups of chicken, bacon, avocado, egg, tomato and blue cheese with red wine dressing","how":"Poach 2 chicken breasts (about 400g) for 12 minutes, cool and dice. Fry 4 rashers bacon until crisp and crumble. Boil 2 eggs for 9 minutes and chop. Dice 1 avocado and 2 tomatoes. Fill 12 little gem leaves with everything, scatter 60g crumbled blue cheese and spoon over red wine vinaigrette.","shop":["2 little gem lettuces@Produce","400g chicken breast@Meat","4 rashers bacon@Meat","2 eggs@Dairy","1 avocado@Produce","2 tomatoes@Produce","60g blue cheese@Deli"]}],"m":[{"n":"Flamingo steak Diane","note":"scotch fillet in flamed brandy, Dijon and cream sauce, for the desert casino nobody believed in","how":"Flatten 4 scotch fillet steaks, about 800g, and sear hot for 2 minutes a side, then rest. In the same pan, soften 2 chopped shallots and 1 garlic clove in 30g butter, add 60ml brandy and flame. Stir in 1 tbsp Dijon mustard, 1 tbsp Worcestershire sauce, 150ml beef stock and 150ml cream and reduce 4 minutes. Return the steaks to coat.","shop":["800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 jar Dijon mustard@Pantry","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","150ml thickened cream@Dairy"]}],"w":[{"n":"Pink flamingo pavlova","note":"raspberry cream for the hotel's namesake","how":"Whisk 4 egg whites to soft peaks, then add 220g caster sugar a spoon at a time until glossy. Fold in 1 tsp cornflour and 1 tsp white vinegar, spread into a round and bake at 120C for 90 minutes, then cool in the oven. Whip 300ml thickened cream and fold through 125g crushed raspberries. Pile on top just before serving.","shop":["4 eggs@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","300ml thickened cream@Dairy","125g raspberries@Produce"]}],"d":[{"n":"Gin rickey for Virginia","note":"gin, fresh lime juice and soda water over ice, crisp and sharp, a 1940s favourite","how":"Fill 4 highball glasses with ice. Add 45ml gin and the juice of half a lime to each, drop in the squeezed shell and top with 150ml soda water.","shop":["180ml gin@Bottle shop","2 limes@Produce","600ml soda water@Drinks"]}],"shopping":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce","2 little gem lettuces@Produce","400g chicken breast@Meat","4 rashers bacon@Meat","6 eggs@Dairy","1 avocado@Produce","2 tomatoes@Produce","60g blue cheese@Deli","800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 jar Dijon mustard@Pantry","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","450ml thickened cream@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","125g raspberries@Produce","180ml gin@Bottle shop","2 limes@Produce","600ml soda water@Drinks"]}},"Donnie Brasco (1997)":{"poster":"assets/menu-posters/donnie-brasco-1997.jpg","colour":"#24413d","servings":4,"tagline":"Undercover at the table.","cue":"Serve the mains when Lefty first sizes Donnie up over the diamond ring.","menu":{"s":[{"n":"Miami garlic prawns","note":"butterflied prawns sizzled with chilli, white wine and butter, for Lefty's trip down to Florida","how":"Butterfly 500g green prawns. Heat 3 tbsp olive oil until very hot, add the prawns with 4 sliced garlic cloves and a pinch of chilli flakes and cook 2 minutes. Add 80ml white wine, bubble for a minute, then swirl in 30g butter and chopped parsley. Serve in the pan with crusty bread for the juices.","shop":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery"]},{"n":"Fried mozzarella","note":"marinara on the side","how":"Cut 400g low-moisture mozzarella into 16 fingers and freeze 20 minutes. Dip in 50g flour, then 2 beaten eggs, then 100g breadcrumbs, then egg and crumbs again. Fry at 180C for 90 seconds until golden. Warm 250ml passata with a pinch of salt and oregano for dipping.","shop":["400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","2 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Shoes-on teriyaki steak","note":"for the Japanese restaurant scene where nobody takes their shoes off","how":"Simmer 80ml soy sauce, 80ml mirin, 60ml sake and 2 tbsp sugar for 5 minutes until syrupy. Sear 4 sirloin steaks, about 800g, in a smoking pan for 3 minutes a side, brushing with glaze in the last minute. Rest 5 minutes and slice. Serve with 400g steamed short grain rice and 4 blanched bok choy.","shop":["80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choy@Produce"]}],"w":[{"n":"Ricotta cheesecake","note":"New York bread is like cake, says Sonny","how":"Drain 750g fresh ricotta in a sieve for 2 hours. Beat with 150g caster sugar, 4 eggs, the zest of 1 lemon and 1 tsp vanilla extract until smooth. Pour into a lined 22cm springform tin and bake at 160C for 60 minutes. Turn off the oven and cool inside with the door ajar. Dust with icing sugar to serve.","shop":["750g fresh ricotta@Dairy","150g caster sugar@Pantry","4 eggs@Dairy","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Social club Rob Roy","note":"Sonny Black's social club, where Joe keeps the drinks coming","how":"Put 4 heavy tumblers in the freezer for 15 minutes. Into a jug of ice pour 200ml blended Scotch, 80ml sweet vermouth and 8 dashes aromatic bitters. Stir for 30 seconds until very cold, then strain into the tumblers over a large ice cube each. Twist a strip of orange peel over each glass, drop it in and add a cocktail cherry.","shop":["200ml blended Scotch@Bottle shop","80ml sweet vermouth@Bottle shop","aromatic bitters@Bottle shop","1 orange@Produce","4 cocktail cherries@Pantry","1 bag large ice cubes@Frozen"]}],"shopping":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery","400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","6 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry","80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choys@Produce","750g fresh ricotta@Dairy","150g caster sugar@Pantry","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry","200ml blended Scotch@Bottle shop","80ml sweet vermouth@Bottle shop","aromatic bitters@Bottle shop","1 orange@Produce","4 cocktail cherries@Pantry","1 bag large ice cubes@Frozen"]}},"Carlito's Way (1993)":{"poster":"assets/menu-posters/carlitos-way-1993.jpg","colour":"#9f2442","servings":4,"tagline":"One last score, then paradise.","cue":"Have dessert out before Benny Blanco finds Carlito at Grand Central.","menu":{"s":[{"n":"Bacalaitos","note":"crisp salt cod fritters","how":"Soak 250g salt cod for 24 hours, changing the water three times, then flake. Whisk 200g plain flour, 2 tsp baking powder, 300ml water, 2 crushed garlic cloves and a handful of chopped coriander into a loose batter and fold in the cod. Fry wide flat spoonfuls in 180C oil until golden and lacy, drain and salt.","shop":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","2 garlic cloves@Produce","1 bunch coriander@Produce","1L vegetable oil@Pantry"]},{"n":"Tostones","note":"smashed plantain with garlic mojo","how":"Peel 3 green plantains and cut into 3cm chunks. Fry at 160C for 4 minutes until soft, smash flat with a heavy glass and fry again at 190C until crisp. Salt well. Mix 3 crushed garlic cloves with the juice of 2 limes and 60ml olive oil and spoon over.","shop":["3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml extra virgin olive oil@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Pernil","note":"slow roast pork shoulder with crackling, rice and pigeon peas","how":"Stab a 2kg pork shoulder all over and rub with 8 crushed garlic cloves, 2 tsp dried oregano, 2 tsp salt and 2 tbsp white vinegar. Marinate overnight. Roast skin up at 160C for 5 hours, then 230C for 20 minutes to crackle. Cook 400g long grain rice with a 400g tin of pigeon peas, stock and a little onion to serve alongside.","shop":["2kg pork shoulder@Meat","8 garlic cloves@Produce","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry"]}],"w":[{"n":"Paradise flan","note":"caramel and coconut, for the beach poster Carlito stares at","how":"Melt 150g caster sugar in a pan until deep amber and pour into a ring tin. Blend a 395g tin condensed milk, 270ml coconut milk, 375ml evaporated milk and 5 eggs and pour over the caramel. Bake in a water bath at 160C for 50 minutes until just set. Chill overnight, run a knife around and turn out onto a plate.","shop":["150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy"]}],"d":[{"n":"El Paraiso dark rum pineapple punch","note":"rum, fruit juice, lime and cinnamon syrup over ice, nutmeg, before the train to Miami","how":"Make spiced syrup by simmering 50g brown sugar, 50ml water and 1 cinnamon stick for 3 minutes, then cool. In a jug, stir together 180ml dark rum, 360ml pineapple juice, 60ml lime juice, 40ml spiced syrup and 4 dashes aromatic bitters. Fill 4 tall glasses with ice and pour the punch over. Grate a little nutmeg on top and garnish with a lime wheel.","shop":["180ml dark rum@Bottle shop","360ml pineapple juice@Drinks","3 limes@Produce","50g brown sugar@Pantry","1 cinnamon stick@Pantry","aromatic bitters@Bottle shop","whole nutmeg@Pantry","1 bag ice@Frozen"]}],"shopping":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","13 garlic cloves@Produce","1 bunch coriander@Produce","2L vegetable oil@Pantry","3 green plantains@Produce","5 limes@Produce","60ml extra virgin olive oil@Pantry","2kg pork shoulder@Meat","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry","150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy","180ml dark rum@Bottle shop","360ml pineapple juice@Drinks","50g brown sugar@Pantry","1 cinnamon stick@Pantry","aromatic bitters@Bottle shop","whole nutmeg@Pantry","1 bag ice@Frozen"]}},"The Godfather Part III (1990)":{"poster":"assets/menu-posters/the-godfather-part-iii-1990.jpg","colour":"#711e19","servings":4,"tagline":"The past never stays buried.","cue":"Serve the cannoli at the party after Michael's church honour, near the start.","menu":{"s":[{"n":"Palermo panelle","note":"chickpea fritters, salt and lemon, for the trip back to Sicily","how":"Whisk 250g chickpea flour into 750ml cold water with 1 tsp salt until smooth. Cook over medium heat, stirring constantly, for 10 minutes until very thick. Add 2 tbsp chopped parsley, spread 1cm thick on an oiled tray and leave to set for 1 hour. Cut into squares and fry in 180C oil until puffed and golden. Drain, salt, and serve with lemon wedges.","shop":["250g chickpea flour@Pantry","1 bunch parsley@Produce","2 lemons@Produce","1L vegetable oil@Pantry"]},{"n":"Prosciutto and melon","note":"a starter before Don Altobello's birthday cannoli","how":"Leave 1 rockmelon at room temperature for an hour. Halve, scoop out the seeds, cut into 12 long wedges and cut off the skin. Drape each wedge with a slice of prosciutto (about 150g in total), add a crack of black pepper and a drizzle of extra virgin olive oil just before serving.","shop":["1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry"]}],"m":[{"n":"Pasta alla Norma","note":"eggplant, tomato and ricotta salata, straight from Sicily","how":"Cut 2 eggplants into thick half moons and fry in batches in 120ml olive oil until deep gold, drain. Fry 3 sliced garlic cloves in 2 tbsp of the oil, add 800g San Marzano tomatoes and a handful of basil, simmer 20 minutes and season. Cook 500g rigatoni until al dente, toss with the sauce, eggplant and a splash of pasta water. Grate 100g ricotta salata heavily over the top.","shop":["2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli"]}],"w":[{"n":"Opera night cannoli","note":"ricotta and candied orange, eaten carefully in the opera box","how":"Drain 500g fresh ricotta in a sieve for 2 hours. Beat with 80g icing sugar, 1/2 tsp ground cinnamon and 40g finely chopped candied orange peel. Spoon into a piping bag and fill 8 cannoli shells just before serving. Dip each end in 30g chopped pistachios and dust with a little more icing sugar.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Teatro Massimo limoncello spritz","note":"limoncello, prosecco and soda over ice, lemon peel, just when he thought he was out","how":"Fill 4 large wine glasses with ice. Pour 40ml limoncello into each, then top each with 90ml chilled prosecco and 30ml soda water. Stir once gently so you keep the bubbles. Peel 4 wide strips of zest from 1 lemon, twist each over a glass to release the oil and drop it in. Finish with a small sprig of mint.","shop":["160ml limoncello@Bottle shop","1 bottle prosecco@Bottle shop","120ml soda water@Drinks","1 lemon@Produce","4 sprigs mint@Produce","1 bag ice@Frozen"]}],"shopping":["250g chickpea flour@Pantry","1 bunch parsley@Produce","3 lemons@Produce","1L vegetable oil@Pantry","1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry","2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry","160ml limoncello@Bottle shop","1 bottle prosecco@Bottle shop","120ml soda water@Drinks","4 sprigs mints@Produce","1 bag ice@Frozen"]}},"Quick Change (1990)":{"poster":"assets/menu-posters/quick-change-1990.jpg","colour":"#ddab20","servings":4,"tagline":"The bank job was easy. Leaving New York is hard.","cue":"Serve the mains when the cabbie who speaks no English drives them nowhere.","menu":{"s":[{"n":"Clown nose cherry tomatoes","note":"hollowed little tomatoes with basil whipped feta, for a bank robber in greasepaint","how":"Cut the tops off 24 cherry tomatoes and scoop out the seeds. Blitz 150g feta with a handful of basil, the zest of 1 lemon and 2 tbsp olive oil until smooth. Pipe into the tomatoes and top each with a small basil leaf. A red nose for every guest.","shop":["24 cherry tomatoes@Produce","150g feta@Dairy","1 bunch basil@Produce","1 lemon@Produce","2 tbsp olive oil@Pantry"]},{"n":"Airport bar chilli-lime wings","note":"oven-crisp wings in spicy honey butter, coriander and citrus, so close to the departure gate","how":"Pat 1kg chicken wings dry, toss with 1 tsp baking powder and 1 tsp salt. Roast on a rack at 220C for 40 to 45 minutes, turning once, until crisp and cooked through. Melt 30g butter with 2 tbsp honey, 2 tbsp sweet chilli sauce, 1 tsp chilli flakes and the zest and juice of 2 limes. Toss the wings through and scatter with coriander.","shop":["1kg chicken wings@Meat","1 tsp baking powder@Pantry","30g butter@Dairy","2 tbsp honey@Pantry","2 tbsp sweet chilli sauce@Pantry","chilli flakes@Pantry","3 limes@Produce","1 bunch coriander@Produce"]}],"m":[{"n":"Bodega sandwiches","note":"kaiser rolls of turkey, Swiss, tomato and mustard, for a city that won't let you leave","how":"Split 4 kaiser rolls, spread with 80g mayonnaise and 1 tbsp mustard. Fill with 400g sliced turkey, 8 slices Swiss cheese, shredded iceberg lettuce and 2 sliced tomatoes, and season with salt and pepper. Wrap each tightly in paper and cut in half.","shop":["4 kaiser rolls@Bakery","80g mayonnaise@Pantry","1 tbsp yellow mustard@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"Clown cake","note":"red nose and all","how":"Split a 400g sponge cake and fill with 100g raspberry jam. Beat 200g butter with 400g icing sugar and spread all over the cake. Tint a little leftover buttercream and pipe a clown face on top, then press a maraschino cherry in for the nose.","shop":["400g sponge cake@Bakery","100g raspberry jam@Pantry","200g butter@Dairy","400g icing sugar@Pantry","1 maraschino cherry@Pantry"]}],"d":[{"n":"Wheels-up bourbon smash","note":"a toast to finally leaving New York","how":"In a shaker, muddle 12 mint leaves and 4 lemon wedges with 40ml sugar syrup. Add 180ml bourbon and ice and shake hard for 10 seconds. Double strain into 4 glasses filled with crushed ice. Top with a fat sprig of mint and serve with short straws.","shop":["180ml bourbon@Bottle shop","1 bunch mint@Produce","1 lemon@Produce","40ml sugar syrup@Pantry","1 bag crushed ice@Frozen"]}],"shopping":["24 cherry tomatoes@Produce","150g feta@Dairy","1 bunch basil@Produce","2 lemons@Produce","2 tbsp olive oil@Pantry","1kg chicken wings@Meat","1 tsp baking powder@Pantry","230g butter@Dairy","2 tbsp honey@Pantry","2 tbsp sweet chilli sauce@Pantry","chilli flakes@Pantry","3 limes@Produce","1 bunch coriander@Produce","4 kaiser rolls@Bakery","80g mayonnaise@Pantry","1 tbsp yellow mustard@Pantry","400g sliced turkey@Deli","8 slices Swiss cheeses@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","400g sponge cake@Bakery","100g raspberry jam@Pantry","400g icing sugar@Pantry","1 maraschino cherry@Pantry","180ml bourbon@Bottle shop","1 bunch mint@Produce","40ml sugar syrup@Pantry","1 bag crushed ice@Frozen"]}},"Annie Hall (1977)":{"poster":"assets/menu-posters/annie-hall-1977.jpg","colour":"#8b6946","servings":4,"tagline":"Brooklyn nerves. Pass the lobster.","cue":"Serve the mains when the lobsters escape behind the fridge.","menu":{"s":[{"n":"Lobster bites","note":"chopped lobster in lemony mayo with celery and chives on toasted buttered brioche rounds","how":"Chop 300g cooked lobster meat and fold with 3 tbsp mayonnaise, the juice of half a lemon, 1 finely diced celery stick and chopped chives. Cut 16 rounds from buttered brioche slices and toast. Pile the lobster on top.","shop":["300g cooked lobster meat@Seafood","3 tbsp mayonnaise@Pantry","1 lemon@Produce","1 celery stick@Produce","1 bunch chives@Produce","6 slices brioche@Bakery","20g butter@Dairy"]},{"n":"Potato knishes","note":"flaky rounds of mashed potato and slow fried onion, baked golden, for Alvy's Brooklyn childhood","how":"Mash 800g boiled potatoes with 2 onions fried slowly in 40g butter, salt and pepper. Cut 2 sheets puff pastry into 8 squares, fill, pinch closed into rounds, brush with egg and bake at 200C for 25 minutes.","shop":["800g potatoes@Produce","2 onions@Produce","40g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy"]}],"m":[{"n":"Pastrami on white with mayo","note":"steamed glossy slices piled on soft bread with mayo, lettuce and tomato, no rye or mustard","how":"Steam 500g sliced pastrami for 10 minutes until glossy. Spread 8 slices soft white bread with 80g mayonnaise, add shredded iceberg lettuce and 2 sliced tomatoes, and pile the pastrami high. Alvy would want rye and mustard, so have them on the side.","shop":["500g pastrami@Deli","8 slices white bread@Bakery","80g mayonnaise@Pantry","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"New York cheesecake","note":"dense baked cream cheese, sour cream and lemon on biscuit, Alvy's city in a slice","how":"Crush 200g digestive biscuits with 80g melted butter and press into a 22cm tin. Beat 900g cream cheese with 220g caster sugar, 200g sour cream, 4 eggs and the zest of 1 lemon. Pour over and bake in a water bath at 150C for 70 minutes. Cool in the oven, then chill overnight.","shop":["200g digestive biscuits@Pantry","80g butter@Dairy","900g cream cheese@Dairy","220g caster sugar@Pantry","200g sour cream@Dairy","4 eggs@Dairy","1 lemon@Produce"]}],"d":[{"n":"Alvy's LA cucumber mint cooler","note":"Alvy's health food lunch in LA, alfalfa sprouts and all","how":"Blend 1 chopped Lebanese cucumber with 60ml lime juice, 2 tbsp honey and a handful of mint until smooth, then strain. Fill 4 glasses with ice and cucumber ribbons. Pour 60ml of the mix into each and top with 150ml sparkling water. Add a mint sprig.","shop":["2 Lebanese cucumbers@Produce","3 limes@Produce","2 tbsp honey@Pantry","1 bunch mint@Produce","600ml sparkling water@Drinks","1 bag ice@Frozen"]}],"shopping":["300g cooked lobster meat@Seafood","3 tbsp mayonnaise@Pantry","2 lemons@Produce","1 celery stick@Produce","1 bunch chives@Produce","6 slices brioches@Bakery","140g butter@Dairy","800g potatoes@Produce","2 onions@Produce","2 sheets puff pastries@Frozen","5 eggs@Dairy","500g pastrami@Deli","8 slices white breads@Bakery","80g mayonnaise@Pantry","1 iceberg lettuce@Produce","2 tomatoes@Produce","200g digestive biscuits@Pantry","900g cream cheese@Dairy","220g caster sugar@Pantry","200g sour cream@Dairy","2 Lebanese cucumbers@Produce","3 limes@Produce","2 tbsp honey@Pantry","1 bunch mint@Produce","600ml sparkling water@Drinks","1 bag ice@Frozen"]}},"Manhattan (1979)":{"poster":"assets/menu-posters/manhattan-1979.jpg","colour":"#353535","servings":4,"tagline":"New York in black and white. Dessert in colour.","cue":"Serve dessert as the Gershwin opening fades.","menu":{"s":[{"n":"Queensboro Bridge bagels and lox","note":"toasted with cream cheese, smoked salmon, capers and red onion, for the bench at dawn","how":"Whip 250g cream cheese with a splash of milk until light. Split and toast 4 bagels. Spread thickly, then layer with 200g smoked salmon, a few capers, paper-thin red onion and dill sprigs. Cut in half and serve on a board.","shop":["250g cream cheese@Dairy","4 bagels@Bakery","200g smoked salmon@Seafood","1 jar capers@Pantry","1 red onion@Produce","1 bunch dill@Produce"]},{"n":"Isaac's crostini","note":"toasted baguette with ricotta and honey, or mushrooms and parmesan, for the opening at Elaine's","how":"Slice 1 baguette into 20 rounds, brush with oil and toast at 200C for 8 minutes. Whip 200g ricotta with lemon zest and top 10 with it and a drizzle of honey. Fry 200g sliced mushrooms with thyme and garlic and pile on the other 10 with shaved parmesan.","shop":["1 baguette@Bakery","200g ricotta@Dairy","1 lemon@Produce","2 tbsp honey@Pantry","200g button mushrooms@Produce","1 bunch thyme@Produce","40g parmesan@Dairy"]}],"m":[{"n":"Chinese takeaway in bed","note":"Isaac's list has the crabs at Sam Wo's","how":"Marinate 700g diced chicken thigh in 2 tbsp soy and 1 tbsp cornflour. Fry hot with 10 dried chillies and 1 tsp Sichuan pepper. Add sauce of 2 tbsp black vinegar, 2 tbsp soy, 1 tbsp sugar and 2 tbsp Shaoxing, then 80g peanuts and spring onion. Serve with 300g jasmine rice.","shop":["700g chicken thighs@Meat","1 bottle soy sauce@Pantry","1 box cornflour@Pantry","1 packet dried chillies@Pantry","1 jar Sichuan pepper@Pantry","1 bottle black vinegar@Pantry","1 bottle Shaoxing wine@Pantry","80g roasted peanuts@Pantry","1 bunch spring onions@Produce","300g jasmine rice@Pantry"]}],"w":[{"n":"Isaac's list cheesecake","note":"dense lemon and vanilla cream cheese filling on a biscuit crumb, baked low and slow, chilled","how":"Crush 200g plain biscuits with 80g melted butter, press into a 20cm tin and bake 10 minutes at 160C. Beat 750g cream cheese with 200g sugar, 3 eggs, 150g sour cream, 1 tsp vanilla and the zest of 1 lemon. Pour in, bake at 150C for 60 minutes, cool in the oven with the door ajar and chill overnight.","shop":["200g plain biscuits@Pantry","80g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","1 lemon@Produce"]}],"d":[{"n":"Manhattan cocktail","note":"rye, sweet vermouth and bitters stirred and strained over a cherry, to Gershwin","how":"For each drink, stir 60ml rye, 30ml sweet vermouth and 2 dashes aromatic bitters over plenty of ice for 30 seconds. Strain into a chilled coupe and drop in a cocktail cherry. Makes four, so make them one or two at a time.","shop":["240ml rye whiskey@Bottle shop","120ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry"]}],"shopping":["250g cream cheese@Dairy","4 bagels@Bakery","200g smoked salmon@Seafood","1 jar capers@Pantry","1 red onion@Produce","1 bunch dill@Produce","1 baguette@Bakery","200g ricotta@Dairy","1 lemon@Produce","2 tbsp honey@Pantry","200g button mushrooms@Produce","1 bunch thyme@Produce","40g parmesan@Dairy","700g chicken thighs@Meat","1 bottle soy sauce@Pantry","1 box cornflour@Pantry","1 packet dried chillies@Pantry","1 jar Sichuan pepper@Pantry","1 bottle black vinegar@Pantry","1 bottle Shaoxing wine@Pantry","80g roasted peanuts@Pantry","1 bunch spring onions@Produce","300g jasmine rice@Pantry","200g plain biscuits@Pantry","80g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","240ml rye whiskey@Bottle shop","120ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry"]}},"Men in Black II (2002)":{"poster":"assets/menu-posters/men-in-black-ii-2002.jpg","colour":"#235c97","servings":4,"tagline":"Same suits. Still hungry.","cue":"Serve dinner when Frank the pug sings in the car.","menu":{"s":[{"n":"Ben's Famous pizza bites","note":"Mini pizza rounds, mozzarella, pepperoni. Two slices, says Serleena","how":"Roll out 500g pizza dough and cut into 16 rounds. Spread each with a spoon of pizza sauce, then add grated mozzarella and a slice of pepperoni. Bake on a hot tray at 230C for 8 minutes until the bases are crisp and the cheese bubbles.","shop":["500g pizza dough@Bakery","1 jar pizza sauce@Pantry","150g mozzarella@Dairy","100g pepperoni@Deli"]},{"n":"Truro post office sausage rolls","note":"Pork and fennel rolls, by Kevin Brown, postmaster","how":"Heat the oven to 200°C and line two trays. Mix the pork, onion, fennel seeds, breadcrumbs, 1 egg and a good pinch of salt and pepper. Cut each pastry sheet in half. Lay a log of filling along each half, roll up and press the seam down underneath. Cut each roll into 4, brush with the other egg, beaten, and bake for 25 minutes until golden and cooked through. Serve hot with tomato sauce.","shop":["500g pork mince@Meat","1 brown onion@Produce","1 tsp fennel seeds@Spices","40g dried breadcrumbs@Pantry","2 eggs@Dairy","3 sheets frozen puff pastry@Frozen","125ml tomato sauce@Pantry"]}],"m":[{"n":"Ben's Famous pizza","note":"Ask Ben about the Light of Zartha. Thin crust, sausage","how":"Stretch 2 balls of cold-fermented dough, 500g in total, thin. Spread with 200g crushed tomato seasoned with salt. Top with 250g low-moisture mozzarella and 3 Italian sausages, skins off, crumbled. Bake on a steel at max heat for 7 minutes.","shop":["500g pizza dough@Bakery","200g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","3 Italian sausages@Meat"]}],"w":[{"n":"Worm guys' glazed espresso doughnuts","note":"Once you've had worm, that's what you'll yearn. Espresso glazed","how":"Mix 200g icing sugar with 3 tbsp strong espresso and 10g melted butter until smooth. Dip the tops of 8 plain cake doughnuts and leave to set.","shop":["8 plain doughnuts@Bakery","200g icing sugar@Pantry","3 tbsp espresso coffee@Pantry","10g butter@Dairy"]}],"d":[{"n":"Worm guys' iced espresso shakes","note":"Espresso, vanilla ice cream, milk and caramel, topped with cream and gummy worms","how":"Brew 4 espressos and cool for 10 minutes. Blend with 6 scoops vanilla ice cream, 300ml cold milk and 2 tbsp caramel sauce until thick and smooth. Whip 300ml thickened cream to soft peaks. Pour the shakes into 4 tall glasses, top with the cream and drizzle with a little more caramel. Hang 2 gummy worms over each rim.","shop":["72g espresso coffee beans@Pantry","1 litre vanilla ice cream@Frozen","300ml milk@Dairy","2 tbsp caramel sauce@Pantry","300ml thickened cream@Dairy","8 gummy worms@Pantry"]}],"shopping":["1kg pizza dough@Bakery","1 jar pizza sauce@Pantry","150g mozzarella@Dairy","100g pepperoni@Deli","135g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","50g dark chocolate@Pantry","200g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","3 Italian sausages@Meat","8 plain doughnuts@Bakery","200g icing sugar@Pantry","3 tbsp espresso coffee@Pantry","72g espresso coffee beans@Pantry","1 litre vanilla ice cream@Frozen","300ml milk@Dairy","2 tbsp caramel sauce@Pantry","300ml thickened cream@Dairy","8 gummy worms@Pantry"]}},"Big Trouble in Little China (1986)":{"poster":"assets/menu-posters/big-trouble-in-little-china-1986.jpg","colour":"#9b2925","servings":4,"tagline":"Something big is cooking in Chinatown.","cue":"Serve the ribs when Jack drives the Pork-Chop Express into Chinatown.","menu":{"s":[{"n":"Pork and chive dumplings","note":"pork mince, garlic chives and ginger in pleated wrappers, crisp-bottomed, black vinegar dip","how":"Mix 400g pork mince with a chopped bunch of garlic chives, 1 tbsp grated ginger, 1 tbsp soy, 1 tbsp Shaoxing and 1 tsp sesame oil. Pleat into 30 gyoza wrappers. Fry until the bottoms crisp, add water and steam with the lid on for 4 minutes.","shop":["400g pork mince@Meat","1 bunch garlic chives@Produce","1 knob ginger@Produce","1 bottle soy sauce@Pantry","1 bottle Shaoxing wine@Pantry","1 bottle sesame oil@Pantry","30 gyoza wrappers@Frozen","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry"]},{"n":"Salt and pepper squid","note":"scored strips in five spice starch, fried fast, wok-tossed with garlic, chilli and spring onion","how":"Score 500g squid tubes and cut into strips. Toss in 100g potato starch with salt, white pepper and a pinch of five spice. Fry at 190C for 90 seconds. Wok-toss with fried garlic, 2 sliced chillies and spring onion.","shop":["500g squid tubes@Seafood","100g potato starch@Pantry","1 jar white pepper@Pantry","1 jar five spice@Pantry","2 red chillies@Produce","3 garlic cloves@Produce","1 bunch spring onions@Produce","1L vegetable oil@Pantry"]}],"m":[{"n":"Pork-Chop Express ribs","note":"char siu glaze, Jack's truck","how":"Rub 1.5kg pork ribs with 4 tbsp hoisin, 2 tbsp honey, 2 tbsp soy, 1 tsp five spice, 1 cube red fermented bean curd and 3 garlic cloves. Marinate overnight. Roast covered at 160C for 90 minutes, then uncover, glaze and blast at 220C until sticky.","shop":["1.5kg pork ribs@Meat","1 jar hoisin sauce@Pantry","1 jar honey@Pantry","1 bottle soy sauce@Pantry","1 jar five spice@Pantry","1 jar red fermented bean curd@Pantry","3 garlic cloves@Produce"]}],"w":[{"n":"Fortune cookies","note":"Jack would ignore his anyway","how":"Whisk 3 egg whites with 100g sugar, then stir in 60g flour, 40g melted butter and a little vanilla. Spread 8cm circles on a lined tray and bake at 180C for 6 minutes. Working fast, fold each around a paper fortune while hot.","shop":["3 eggs@Dairy","100g caster sugar@Pantry","60g plain flour@Pantry","40g butter@Dairy","1 bottle vanilla extract@Pantry"]}],"d":[{"n":"Egg Shen's magic potion","note":"Egg Shen's bottle for the trip below Chinatown","how":"Simmer 50g sugar, 50ml water and 20g sliced ginger for 5 minutes, then cool and strain. Shake 240ml plum wine, 60ml lemon juice, 40ml ginger syrup and 1 egg white without ice for 15 seconds, then with ice for 15 seconds. Strain into 4 ice-filled glasses and garnish with a pickled plum or cherry.","shop":["240ml plum wine@Bottle shop","2 lemons@Produce","50g sugar@Pantry","20g ginger@Produce","1 egg@Dairy","4 pickled plums@Pantry","1 bag ice@Frozen"]}],"shopping":["400g pork mince@Meat","1 bunch garlic chives@Produce","1 knob ginger@Produce","2 bottles soy sauce@Pantry","1 bottle Shaoxing wine@Pantry","1 bottle sesame oil@Pantry","30 gyoza wrappers@Frozen","1 bottle black vinegar@Pantry","1 jar chilli oil@Pantry","500g squid tubes@Seafood","100g potato starch@Pantry","1 jar white pepper@Pantry","2 jars five spice@Pantry","2 red chillies@Produce","6 garlic cloves@Produce","1 bunch spring onions@Produce","1L vegetable oil@Pantry","1.5kg pork ribs@Meat","1 jar hoisin sauce@Pantry","1 jar honey@Pantry","1 jar red fermented bean curd@Pantry","4 eggs@Dairy","100g caster sugar@Pantry","60g plain flour@Pantry","40g butter@Dairy","1 bottle vanilla extract@Pantry","240ml plum wine@Bottle shop","2 lemons@Produce","50g sugar@Pantry","20g ginger@Produce","4 pickled plums@Pantry","1 bag ice@Frozen"]}},"The Last Dragon (1985)":{"poster":"assets/menu-posters/the-last-dragon-1985.jpg","colour":"#a57825","servings":4,"tagline":"Find the glow. Then find the dumplings.","cue":"Serve dinner when Leroy eats popcorn with chopsticks at the cinema.","menu":{"s":[{"n":"Chopstick popcorn","note":"Stovetop popcorn tossed in melted butter and salt","how":"Heat 2 tbsp oil in a large pot with 3 kernels. When they pop, add 120g kernels, cover and shake until the popping slows. Toss with 50g melted butter, 3 tbsp furikake and a pinch of sugar. Hand out chopsticks and see who gives up first.","shop":["120g popcorn kernels@Pantry","2 tbsp vegetable oil@Pantry","50g butter@Dairy","1 jar furikake@Pantry","1 bag caster sugar@Pantry"]},{"n":"Harlem spring rolls","note":"Crisp rolls filled with cabbage, carrot, shiitake and glass noodles","how":"Stir-fry 2 cups shredded cabbage, 1 grated carrot and 100g sliced shiitake. Add 50g soaked glass noodles, soy and white pepper, then cool. Roll tightly in 16 spring roll wrappers, sealing with water, and fry at 180C until golden. Serve with sweet chilli.","shop":["0.25 cabbage@Produce","1 carrot@Produce","100g shiitake mushrooms@Produce","50g glass noodles@Pantry","1 bottle soy sauce@Pantry","16 spring roll wrappers@Frozen","1 bottle sweet chilli sauce@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"General Tso's chicken","note":"Crispy fried chicken thigh in a sweet, spicy soy and dried chilli sauce","how":"Toss 800g diced chicken thighs in 100g potato starch and fry twice at 180C. Fry 8 dried chillies, 3 garlic cloves and ginger, then add 3 tbsp soy, 2 tbsp black vinegar, 3 tbsp sugar and 125ml stock. Toss the chicken through. Serve with 300g jasmine rice.","shop":["800g chicken thighs@Meat","100g potato starch@Pantry","1 packet dried chillies@Pantry","3 garlic cloves@Produce","1 knob ginger@Produce","1 bottle soy sauce@Pantry","1 bottle black vinegar@Pantry","125ml chicken stock@Pantry","300g jasmine rice@Pantry","1L vegetable oil@Pantry"]}],"w":[{"n":"Glowing mango mochi","note":"Soft coconut rice dough wrapped around mango and whipped cream","how":"Mix 150g glutinous rice flour, 50g sugar and 200ml coconut milk, then steam for 20 minutes, stirring halfway. Dust a board with cornflour and divide into 8. Wrap each around a cube of mango and a spoon of whipped cream. Chill 30 minutes.","shop":["150g glutinous rice flour@Pantry","50g caster sugar@Pantry","200ml coconut milk@Pantry","1 box cornflour@Pantry","1 mango@Produce","150ml thickened cream@Dairy"]}],"d":[{"n":"Chrysanthemum iced tea","note":"Chilled chrysanthemum flower tea, lightly sweet with rock sugar","how":"Steep 15g dried chrysanthemum flowers in 1L just-boiled water with 50g rock sugar for 5 minutes. Strain, cool and chill well in the fridge. Pour over ice in four tall glasses and float a flower or two on top.","shop":["15g dried chrysanthemum@Pantry","50g rock sugar@Pantry"]}],"shopping":["120g popcorn kernels@Pantry","2 tbsp vegetable oil@Pantry","50g butter@Dairy","1 jar furikake@Pantry","1 bag caster sugar@Pantry","0.25 cabbage@Produce","1 carrot@Produce","100g shiitake mushrooms@Produce","50g glass noodles@Pantry","2 bottles soy sauce@Pantry","16 spring roll wrappers@Frozen","1 bottle sweet chilli sauce@Pantry","2L vegetable oil@Pantry","800g chicken thighs@Meat","100g potato starch@Pantry","1 packet dried chillies@Pantry","3 garlic cloves@Produce","1 knob ginger@Produce","1 bottle black vinegar@Pantry","125ml chicken stock@Pantry","300g jasmine rice@Pantry","150g glutinous rice flour@Pantry","50g caster sugar@Pantry","200ml coconut milk@Pantry","1 box cornflour@Pantry","1 mango@Produce","150ml thickened cream@Dairy","15g dried chrysanthemum@Pantry","50g rock sugar@Pantry"]}},"Crocodile Dundee (1986)":{"poster":"assets/menu-posters/crocodile-dundee-1986.jpg","colour":"#88712d","servings":4,"tagline":"Walkabout Creek to Manhattan. Bring an appetite.","cue":"Pour a beer when Mick first sees a bidet in the hotel.","menu":{"s":[{"n":"Garlic prawn skewers","note":"King prawns with garlic, chilli and lemon, grilled hot on skewers","how":"Toss 600g peeled king prawns with 3 crushed garlic cloves, 1 chopped chilli, lemon zest and 2 tbsp oil. Thread onto skewers and grill hot for 90 seconds a side. Brush with 50g butter melted with 1 tsp lemon myrtle and serve with lemon.","shop":["600g king prawns@Seafood","3 garlic cloves@Produce","1 red chilli@Produce","2 lemons@Produce","50g butter@Dairy","1 jar lemon myrtle@Pantry"]},{"n":"Wally's Walkabout Creek party pies","note":"Seasoned minced beef in gravy, shortcrust base and puff pastry lid","how":"Cook 500g beef mince with 1 onion, 2 tbsp Worcestershire, 2 tbsp tomato sauce and 250ml stock, thicken and cool. Line patty tins with 2 sheets shortcrust, fill, top with 2 sheets puff and bake at 200C for 20 minutes.","shop":["500g beef mince@Meat","1 brown onion@Produce","1 bottle Worcestershire sauce@Pantry","1 bottle tomato sauce@Pantry","250ml beef stock@Pantry","2 sheets shortcrust pastry@Frozen","2 sheets puff pastry@Frozen"]}],"m":[{"n":"Walkabout Creek barbecued barra","note":"Barra fillets, skin scored and grilled crisp, flipped for a minute, brought out with a big knife.","how":"Score the skin of 4 barramundi fillets and pat very dry. Grill skin down over high heat until crisp, about 4 minutes, then flip for 1 minute. Melt 80g butter with 2 garlic cloves and 1 tsp lemon myrtle and spoon over.","shop":["4 barramundi fillets@Seafood","80g butter@Dairy","2 garlic cloves@Produce","1 jar lemon myrtle@Pantry","2 lemons@Produce"]}],"w":[{"n":"Lamingtons","note":"Butter sponge squares dipped in chocolate icing and rolled in coconut","how":"Cut a 500g butter sponge into 16 squares. Whisk 400g icing sugar, 40g cocoa, 20g melted butter and 150ml milk into a thin icing. Dip each square, drain and roll in 200g desiccated coconut. Set on a rack for an hour.","shop":["1 sponge cake@Bakery","400g icing sugar@Pantry","40g cocoa@Pantry","20g butter@Dairy","150ml full cream milk@Dairy","200g desiccated coconut@Pantry"]}],"d":[{"n":"Walkabout Creek rum and ginger beer","note":"Dark rum floated over lime and ginger beer on ice","how":"Fill 4 tall glasses with ice. Squeeze 15ml lime juice into each and add 150ml chilled ginger beer. Slowly pour 45ml dark rum over the back of a spoon so it floats on top. Add a lime wedge and stir at the table.","shop":["180ml dark rum@Bottle shop","600ml ginger beer@Drinks","3 limes@Produce","1 bag ice@Frozen"]}],"shopping":["600g king prawns@Seafood","5 garlic cloves@Produce","1 red chilli@Produce","4 lemons@Produce","150g butter@Dairy","2 jars lemon myrtle@Pantry","500g beef mince@Meat","1 brown onion@Produce","1 bottle Worcestershire sauce@Pantry","1 bottle tomato sauce@Pantry","250ml beef stock@Pantry","2 sheets shortcrust pastries@Frozen","2 sheets puff pastries@Frozen","4 barramundi fillets@Seafood","1 sponge cake@Bakery","400g icing sugar@Pantry","40g cocoa@Pantry","150ml full cream milk@Dairy","200g desiccated coconut@Pantry","180ml dark rum@Bottle shop","600ml ginger beer@Drinks","3 limes@Produce","1 bag ice@Frozen"]}},"Crocodile Dundee II (1988)":{"poster":"assets/menu-posters/crocodile-dundee-ii-1988.jpg","colour":"#8e773b","servings":4,"tagline":"From New York back to the bush.","cue":"Serve the mains when Mick goes fishing with dynamite in the harbour.","menu":{"s":[{"n":"Bush damper with golden syrup","note":"Round oven-baked damper loaf, served with butter and golden syrup","how":"Rub 60g butter into 450g self-raising flour and a pinch of salt. Mix in about 300ml milk to a soft dough, shape into a round and score a cross. Bake at 200C for 30 minutes until it sounds hollow. Serve warm with butter and golden syrup.","shop":["100g butter@Dairy","450g self-raising flour@Pantry","300ml full cream milk@Dairy","1 tin golden syrup@Pantry"]},{"n":"Wally's Walkabout Creek snags","note":"Thick beef sausages grilled slowly, rolled in white bread with fried onions and tomato sauce.","how":"Grill 8 thick beef sausages slowly over medium heat for 15 minutes, turning often. Fry 2 sliced onions until soft and golden. Wrap each sausage in a slice of white bread with onions and a squeeze of tomato sauce.","shop":["8 thick beef sausages@Meat","8 slices white bread@Bakery","2 brown onions@Produce","1 bottle tomato sauce@Pantry"]}],"m":[{"n":"Dynamite-caught campfire barra","note":"Whole barramundi stuffed with lemon, ginger and coriander, wrapped in paperbark, cooked over coals.","how":"Stuff a 1.5kg whole barramundi with lemon slices, a sliced knob of ginger and a bunch of coriander. Dot with 50g butter and wrap well in foil. Cook over hot coals or a hot grill for 20 minutes, turning once.","shop":["1.5kg whole barramundi@Seafood","2 lemons@Produce","1 knob ginger@Produce","1 bunch coriander@Produce","50g butter@Dairy"]}],"w":[{"n":"I am home pavlova","note":"Crisp meringue with whipped cream, passionfruit and sliced mango","how":"Whip 4 whites to soft peaks, add 220g caster sugar gradually until glossy, then fold in 1 tsp cornflour and 1 tsp vinegar. Bake at 120C for 90 minutes and cool in the oven. Top with 300ml whipped cream, 4 passionfruit and a sliced mango.","shop":["4 eggs@Dairy","220g caster sugar@Pantry","1 box cornflour@Pantry","1 bottle white vinegar@Pantry","300ml thickened cream@Dairy","4 passionfruit@Produce","1 mango@Produce"]}],"d":[{"n":"Top End lemon myrtle gin and tonic","note":"Gin and tonic with a lemon myrtle sugar rim and a squeeze of lime","how":"Mix 1 tbsp caster sugar with 1 tsp ground lemon myrtle on a plate. Run lime around 4 glass rims and dip. Fill with ice, add 45ml gin and 15ml lime juice to each, then top with 150ml tonic water. Add a lime wheel.","shop":["180ml gin@Bottle shop","600ml tonic water@Drinks","3 limes@Produce","1 tsp ground lemon myrtle@Pantry","1 tbsp caster sugar@Pantry","1 bag ice@Frozen"]}],"shopping":["150g butter@Dairy","450g self-raising flour@Pantry","300ml full cream milk@Dairy","1 tin golden syrup@Pantry","8 thick beef sausages@Meat","8 slices white breads@Bakery","2 brown onions@Produce","1 bottle tomato sauce@Pantry","1.5kg whole barramundi@Seafood","2 lemons@Produce","1 knob ginger@Produce","1 bunch coriander@Produce","4 eggs@Dairy","220g caster sugar@Pantry","1 box cornflour@Pantry","1 bottle white vinegar@Pantry","300ml thickened cream@Dairy","4 passionfruits@Produce","1 mango@Produce","180ml gin@Bottle shop","600ml tonic water@Drinks","3 limes@Produce","1 tsp ground lemon myrtle@Pantry","1 tbsp caster sugar@Pantry","1 bag ice@Frozen"]}},"Annie (1982)":{"poster":"assets/menu-posters/annie-1982.jpg","colour":"#b13131","servings":4,"tagline":"From the orphanage to the mansion, with dessert.","cue":"Serve the snacks when Annie says \"Leaping lizards!\" at the mansion.","menu":{"s":[{"n":"Warbucks mansion canapés","note":"Creamy chicken and mushroom pastry cases, plus asparagus wrapped in prosciutto","how":"Bake 16 vol-au-vent cases until crisp. Fry 250g diced chicken thigh and 150g mushrooms, add 150ml cream and thyme and reduce. Fill the cases. Blanch 2 bunches asparagus and wrap each spear in half a slice of prosciutto.","shop":["16 vol-au-vent cases@Frozen","250g chicken thighs@Meat","150g mushrooms@Produce","150ml thickened cream@Dairy","1 bunch thyme@Produce","2 bunches asparagus@Produce","100g prosciutto@Deli"]},{"n":"Radio City popcorn","note":"Stovetop popcorn popped in coconut oil, tossed in melted butter and salt","how":"Heat 2 tbsp coconut oil with 3 kernels, and when they pop add 120g kernels, cover and shake until the popping slows. Toss with 50g melted butter and fine salt while hot. Roll paper into cones and fill them up.","shop":["2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","50g butter@Dairy","1 box fine salt@Pantry"]}],"m":[{"n":"Warbucks roast chicken","note":"Whole chicken with tarragon butter under the skin, roasted golden","how":"Dry-brine a 1.8kg chicken overnight. Push 60g butter mixed with chopped tarragon under the skin. Roast at 220C for 20 minutes, then 180C until the thigh hits 72C, with 1kg potatoes. Make gravy with 250ml stock. Serve with buttered peas.","shop":["1.8kg whole chicken@Meat","80g butter@Dairy","1 bunch tarragon@Produce","1kg potatoes@Produce","250ml chicken stock@Pantry","300g frozen peas@Frozen"]}],"w":[{"n":"Mansion sundaes","note":"Vanilla ice cream under hot fudge and cream, easier than Mrs. Pugh's baked Alaska","how":"Melt 150g dark chocolate with 150ml cream and 2 tbsp golden syrup into a hot fudge. Scoop vanilla ice cream into four tall glasses, pour over the fudge and top with whipped cream, toasted flaked almonds and a cherry.","shop":["150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","50g flaked almonds@Pantry","1 jar maraschino cherries@Pantry"]}],"d":[{"n":"Mansion ginger beer and orange punch","note":"Orange juice, lime, mint and ginger beer over ice, no alcohol","how":"In a large jug, combine 400ml orange juice, 60ml lime juice and a handful of torn mint. Add ice, then pour in 800ml chilled ginger beer and stir gently. Add orange slices and serve in glasses with a mint sprig.","shop":["800ml ginger beer@Drinks","400ml orange juice@Drinks","2 limes@Produce","1 orange@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}],"shopping":["16 vol-au-vent cases@Frozen","250g chicken thighs@Meat","150g mushrooms@Produce","450ml thickened cream@Dairy","1 bunch thyme@Produce","2 bunches asparagus@Produce","100g prosciutto@Deli","2 tbsp coconut oil@Pantry","120g popcorn kernels@Pantry","130g butter@Dairy","1 box fine salt@Pantry","1.8kg whole chicken@Meat","1 bunch tarragon@Produce","1kg potatoes@Produce","250ml chicken stock@Pantry","300g frozen peas@Frozen","150g dark chocolate@Pantry","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","50g flaked almonds@Pantry","1 jar maraschino cherries@Pantry","800ml ginger beer@Drinks","400ml orange juice@Drinks","2 limes@Produce","1 orange@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}},"Beverly Hills Cop III (1994)":{"poster":"assets/menu-posters/beverly-hills-cop-iii-1994.jpg","colour":"#285b9c","servings":4,"tagline":"The theme park ride from hell.","cue":"Serve the snacks when the Spider ride gets stuck.","menu":{"s":[{"n":"Wonder World popcorn","note":"Popcorn coated in a brown sugar and golden syrup caramel","how":"Pop 120g kernels. Boil 150g brown sugar, 80g butter and 3 tbsp golden syrup for 4 minutes, then stir in half a tsp bicarb. Pour over the popcorn, toss and bake at 120C for 45 minutes, stirring every 15. Cool and break up.","shop":["120g popcorn kernels@Pantry","150g brown sugar@Pantry","80g butter@Dairy","1 tin golden syrup@Pantry","1 box bicarb soda@Pantry"]},{"n":"Spider Rider midway corn dogs","note":"Franks on sticks dipped in cornmeal batter and fried","how":"Whisk 150g cornmeal, 100g flour, 2 tbsp sugar, 2 tsp baking powder, 1 egg and 250ml buttermilk. Pat 8 franks dry and push onto sticks. Dip in batter and fry at 180C for 4 minutes until deep gold. Serve with mustard.","shop":["150g fine cornmeal@Pantry","100g plain flour@Pantry","1 tin baking powder@Pantry","1 egg@Dairy","250ml buttermilk@Dairy","8 hot dog franks@Meat","1 bottle yellow mustard@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Uncle Dave's theme park turkey legs","note":"Drumsticks brined overnight, rubbed with paprika, roasted until falling off the bone","how":"Dissolve 80g salt and 80g brown sugar in 2L water with 1 tbsp smoked paprika. Brine 4 turkey drumsticks overnight. Pat dry, rub with more paprika and roast at 150C for 2 hours until the meat pulls easily from the bone.","shop":["80g sea salt@Pantry","80g brown sugar@Pantry","1 jar smoked paprika@Pantry","4 turkey drumsticks@Meat"]}],"w":[{"n":"Fairy floss and toffee apples","note":"Apples dipped in red hard toffee, served with a bag of cotton candy","how":"Push sticks into 4 apples. Boil 400g sugar, 125ml water and 1 tsp vinegar to 150C, then add a few drops of red colouring. Dip and twirl the apples, then set on baking paper. Serve with a bag of fairy floss.","shop":["4 apples@Produce","400g caster sugar@Pantry","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 bag fairy floss@Pantry"]}],"d":[{"n":"Wonder World blue raspberry slushie","note":"Blue raspberry cordial, lemonade and lime blended with ice, no alcohol","how":"Add 120ml blue raspberry cordial, 400ml lemonade, the juice of 1 lime and 4 cups of ice to a blender. Blitz in short bursts for 30 seconds until fine and slushy, adding more ice if it's thin. Drop a few frozen raspberries into 4 tall glasses, pour the slushie over and serve with straws straight away.","shop":["120ml blue raspberry cordial@Drinks","400ml lemonade@Drinks","1 lime@Produce","100g frozen raspberries@Frozen","2 bags ice@Frozen"]}],"shopping":["120g popcorn kernels@Pantry","230g brown sugar@Pantry","80g butter@Dairy","1 tin golden syrup@Pantry","1 box bicarb soda@Pantry","150g fine cornmeal@Pantry","100g plain flour@Pantry","1 tin baking powder@Pantry","1 egg@Dairy","250ml buttermilk@Dairy","8 hot dog franks@Meat","1 bottle yellow mustard@Pantry","1L vegetable oil@Pantry","80g sea salt@Pantry","1 jar smoked paprika@Pantry","4 turkey drumsticks@Meat","4 apples@Produce","400g caster sugar@Pantry","1 bottle white vinegar@Pantry","1 bottle red food colouring@Pantry","1 bag fairy floss@Pantry","120ml blue raspberry cordial@Drinks","400ml lemonade@Drinks","1 lime@Produce","100g frozen raspberries@Frozen","2 bags ices@Frozen"]}},"Once Upon a Time in America (1984)":{"poster":"assets/menu-posters/once-upon-a-time-in-america-1984.jpg","colour":"#6b4326","servings":4,"tagline":"Fifty years of friendship, one very long dinner.","cue":"Bring the charlotte russe out when young Patsy sits on the stairs and eats the one he bought for Peggy.","menu":{"s":[{"n":"Delancey Street knishes","note":"hot mustard, Lower East Side street food","how":"Boil 500g peeled potatoes 15 minutes, drain and mash. Cook 1 finely diced brown onion in 30g butter over low heat for 15 minutes until golden, then mix into the mash with salt and white pepper. Cut 2 sheets puff pastry into 4 squares each, fill, fold into parcels and brush with 1 beaten egg. Bake at 200C for 25 minutes. Serve with 40g hot English mustard.","shop":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]},{"n":"Bagel crisps with schmear","note":"Lower East Side breakfast","how":"Slice 3 day-old bagels into thin rounds, brush with 2 tbsp olive oil and bake at 180C for 12 minutes until crisp. Beat 250g cream cheese with 2 tbsp chopped chives and the zest of 1 lemon. Serve the crisps with the schmear and 150g smoked salmon on the side.","shop":["3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce","150g smoked salmon@Seafood"]}],"m":[{"n":"Fat Moe's back room brisket","note":"slow braised with onions and gravy","how":"Season a 1.5kg beef brisket with salt and pepper and sear hard on all sides. Slice 3 brown onions into a roasting dish, sit the brisket on top, and pour over 500ml beef stock whisked with 2 tbsp tomato paste and 2 tsp sweet paprika. Cover and braise at 150C for 4 hours. Rest 20 minutes, slice against the grain, and boil the juices for 10 minutes to make gravy.","shop":["1.5kg beef brisket@Meat","3 brown onions@Produce","500ml beef stock@Pantry","2 tbsp tomato paste@Pantry","2 tsp sweet paprika@Pantry"]}],"w":[{"n":"Patsy's charlotte russe","note":"sponge, whipped cream and a cherry, try not to eat it on the stairs","how":"Cut 8 rounds from a 300g sponge cake to fit the bottom of 8 paper cups. Whip 300ml thickened cream with 100g mascarpone, 2 tbsp icing sugar and 1 tsp vanilla extract to firm peaks. Pipe high over the sponge in a tall swirl and top each with a maraschino cherry. Chill 30 minutes before serving.","shop":["300g sponge cake@Bakery","300ml thickened cream@Dairy","100g mascarpone@Dairy","2 tbsp icing sugar@Pantry","1 tsp vanilla extract@Pantry","8 maraschino cherries@Pantry"]}],"d":[{"n":"Fat Moe's rye whiskey sour in teacups","note":"rye shaken with lemon and egg white, poured into china cups so it passes for tea","how":"Make sugar syrup by dissolving 50g caster sugar in 50ml hot water, then cool. Shake in two rounds: 120ml rye whiskey, 60ml lemon juice, 40ml sugar syrup and 1 egg white, first without ice for 15 seconds, then with ice for 15 seconds. Strain into 4 china teacups. Add 2 drops of aromatic bitters to the foam on each and serve straight away.","shop":["240ml rye whiskey@Bottle shop","4 lemons@Produce","50g caster sugar@Pantry","2 eggs@Dairy","aromatic bitters@Bottle shop","1 bag ice@Frozen"]}],"shopping":["500g potatoes@Produce","4 brown onions@Produce","30g butter@Dairy","2 sheets puff pastries@Frozen","3 eggs@Dairy","40g hot English mustard@Pantry","3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","5 lemons@Produce","150g smoked salmon@Seafood","1.5kg beef brisket@Meat","500ml beef stock@Pantry","2 tbsp tomato paste@Pantry","2 tsp sweet paprika@Pantry","300g sponge cake@Bakery","300ml thickened cream@Dairy","100g mascarpone@Dairy","2 tbsp icing sugar@Pantry","1 tsp vanilla extract@Pantry","8 maraschino cherries@Pantry","240ml rye whiskey@Bottle shop","50g caster sugar@Pantry","aromatic bitters@Bottle shop","1 bag ice@Frozen"]}},"The Pope of Greenwich Village (1984)":{"poster":"assets/menu-posters/the-pope-of-greenwich-village-1984.jpg","colour":"#72252a","servings":4,"tagline":"Big plans. Small cousins. Bad luck.","cue":"Pour the wine when Paulie gets caught skimming and loses them both their jobs.","menu":{"s":[{"n":"Bed Bug Eddie's clams oreganata","note":"steamed clams under garlic, oregano and parmesan crumbs with olive oil, grilled until golden","how":"Steam 1kg clams with a splash of water in a covered pan until they open, about 4 minutes, and discard any closed ones. Remove the top shells. Mix 60g breadcrumbs, 2 crushed garlic cloves, 1 tsp dried oregano, 30g grated parmesan and 3 tbsp olive oil. Top each clam and grill for 3 minutes until golden.","shop":["1kg clams@Seafood","60g breadcrumbs@Pantry","2 garlic cloves@Produce","1 tsp dried oregano@Pantry","30g parmesan@Dairy","3 tbsp olive oil@Pantry"]},{"n":"Waiter's antipasto","note":"prosciutto, melon and bocconcini, what Charlie plates up every night","how":"Cut 1 rockmelon into 12 skinless wedges and drape with 120g prosciutto. Blitz a bunch of basil with 80ml olive oil and a pinch of salt. Drain 220g bocconcini, dress with the basil oil and cracked pepper and serve beside the melon.","shop":["1 rockmelon@Produce","120g prosciutto@Deli","1 bunch basil@Produce","80ml olive oil@Pantry","220g bocconcini@Deli"]}],"m":[{"n":"Veal marsala","note":"floured veal, mushrooms and a fortified wine pan sauce, for Charlie's dream restaurant","how":"Dust 600g veal escalopes in seasoned flour and sear in butter and oil for 1 minute a side, then set aside. Brown 250g sliced button mushrooms in the same pan, add 150ml marsala and 150ml beef stock and reduce by half. Whisk in 40g cold butter, return the veal and warm through for a minute. Serve with crusty bread.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry"]}],"w":[{"n":"Zabaglione","note":"yolks, sugar and marsala whisked over simmering water, warm over berries, made tableside by Charlie","how":"Whisk 4 egg yolks, 60g caster sugar and 80ml marsala in a heatproof bowl over simmering water for 6 to 8 minutes until thick, pale and tripled in volume. Spoon warm over 250g halved strawberries in four glasses and serve straight away.","shop":["4 eggs@Dairy","60g caster sugar@Pantry","80ml marsala@Bottle shop","250g strawberries@Produce"]}],"d":[{"n":"Charlie's Americano on Paulie's tab","note":"red aperitivo, sweet vermouth, soda and orange, poured before the mains","how":"Fill 4 tumblers with ice. Pour 40ml bitter red aperitivo and 40ml sweet vermouth into each glass and stir for 10 seconds. Top each with 80ml chilled soda water and stir once more. Cut 1 orange into thick half-moons and tuck one into each glass. Serve before the mains, the way Charlie would.","shop":["160ml bitter red aperitivo@Bottle shop","160ml sweet vermouth@Bottle shop","320ml soda water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["1kg clams@Seafood","60g breadcrumbs@Pantry","2 garlic cloves@Produce","1 tsp dried oregano@Pantry","30g parmesan@Dairy","3 tbsp olive oil@Pantry","1 rockmelon@Produce","120g prosciutto@Deli","1 bunch basil@Produce","80ml olive oil@Pantry","220g bocconcini@Deli","600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","230ml marsala@Bottle shop","150ml beef stock@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","250g strawberries@Produce","160ml bitter red aperitivo@Bottle shop","160ml sweet vermouth@Bottle shop","320ml soda water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}},"Saturday Night Fever (1977)":{"poster":"assets/menu-posters/saturday-night-fever-1977.jpg","colour":"#c52a68","servings":4,"tagline":"Strut in. Fold your slice. Strut out.","cue":"Serve the slices as Tony struts down 86th Street to Stayin' Alive.","menu":{"s":[{"n":"Bay Ridge sausage and peppers","note":"grilled sausage bites, sweet capsicum and onion on sticks, for the paint store crew's Saturday","how":"Grill 6 Italian sausages until cooked and slice into chunks. Fry 2 sliced capsicums and 2 onions in olive oil until soft and sweet, toss with the sausage and a splash of red wine vinegar.","shop":["6 Italian sausages@Meat","2 red capsicums@Produce","2 onions@Produce","2 tbsp red wine vinegar@Pantry"]},{"n":"Disco fries","note":"gravy and cheese at 2am after the club","how":"Cut 1kg potatoes into chips, soak 30 minutes, dry and fry at 150C for 6 minutes, then at 190C until crisp. Melt 30g butter, stir in 2 tbsp flour for a minute, then whisk in 400ml hot beef stock and simmer 5 minutes into gravy. Pile the fries on a tray, pour over the gravy, top with 150g grated mozzarella and grill for a minute.","shop":["1kg potatoes@Produce","30g butter@Dairy","2 tbsp plain flour@Pantry","400ml beef stock@Pantry","150g mozzarella@Dairy","1L vegetable oil@Pantry"]}],"m":[{"n":"Two slices stacked","note":"thin New York pizza with tomato and mozzarella, folded double and eaten walking, like Tony","how":"Take 2 balls of pizza dough, about 500g, rested at room temperature for an hour. Blend 400g crushed tomatoes with 1 tsp salt and 1 tsp dried oregano. Stretch each base thin, spread with sauce and scatter 250g grated low-moisture mozzarella across both. Bake on a preheated tray at the oven's highest setting for 8 to 10 minutes. Cut into big slices, stack two and fold.","shop":["500g pizza dough@Bakery","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy"]}],"w":[{"n":"Disco ball cake pops","note":"silver sprinkles under the lights","how":"Crumble 400g butter cake into a bowl and mix with 100g cream cheese until it holds together. Roll into 16 balls and chill 30 minutes. Push a stick into each, dip in 300g melted white chocolate and roll in 50g silver cachous so they sparkle. Stand in a glass to set.","shop":["400g butter cake@Bakery","100g cream cheese@Dairy","300g white chocolate@Pantry","50g silver cachous@Pantry","16 lollipop sticks@Pantry"]}],"d":[{"n":"Disco floor whisky lemon fizz","note":"a round at the disco bar before the dance contest","how":"Dissolve 40g caster sugar in 40ml hot water and cool. Shake 180ml blended whisky, 60ml lemon juice and 40ml of the syrup with ice for 10 seconds. Strain into 4 ice-filled highball glasses. Top each with 60ml lemonade and 60ml soda water, stir once and add a lemon wheel.","shop":["180ml blended whisky@Bottle shop","3 lemons@Produce","40g caster sugar@Pantry","250ml lemonade@Drinks","250ml soda water@Drinks","1 bag ice@Frozen"]}],"shopping":["6 Italian sausages@Meat","2 red capsicums@Produce","2 onions@Produce","2 tbsp red wine vinegar@Pantry","1kg potatoes@Produce","30g butter@Dairy","2 tbsp plain flour@Pantry","400ml beef stock@Pantry","150g mozzarella@Dairy","1L vegetable oil@Pantry","500g pizza dough@Bakery","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","400g butter cake@Bakery","100g cream cheese@Dairy","300g white chocolate@Pantry","50g silver cachous@Pantry","16 lollipop sticks@Pantry","180ml blended whisky@Bottle shop","3 lemons@Produce","40g caster sugar@Pantry","250ml lemonade@Drinks","250ml soda water@Drinks","1 bag ice@Frozen"]}},"My Cousin Vinny (1992)":{"poster":"assets/menu-posters/my-cousin-vinny-1992.jpg","colour":"#237b8b","servings":4,"tagline":"Two Brooklyn boys walk into an Alabama diner.","cue":"Serve breakfast during the grits cross-examination.","menu":{"s":[{"n":"Five-minute grits","note":"the grits cross-examination, nobody can cook them that fast","how":"Bring 500ml milk and 500ml water to the boil with 1 tsp salt. Whisk in 150g stone-ground grits or polenta, then stir over low heat for 25 minutes until creamy. Finish with 40g butter and 80g grated sharp cheddar. Not five minutes, whatever anyone says.","shop":["500ml full cream milk@Dairy","150g stone-ground grits@Pantry","40g butter@Dairy","80g cheddar@Dairy"]},{"n":"Fried green tomatoes","note":"sliced unripe tomatoes dipped in buttermilk and cornmeal, crisp with a caper and hot sauce remoulade","how":"Slice 3 green tomatoes 1cm thick, salt and leave 10 minutes, then pat dry. Dip in 150ml buttermilk, then 120g fine cornmeal seasoned with salt and pepper, and shallow-fry at 180C for 2 minutes a side. Mix 100g mayonnaise, 1 tsp mustard, 1 tbsp chopped capers and a dash of hot sauce for the remoulade.","shop":["3 green tomatoes@Produce","150ml buttermilk@Dairy","120g fine cornmeal@Pantry","100g mayonnaise@Pantry","1 tbsp capers@Pantry","1 tsp hot sauce@Pantry","500ml vegetable oil@Pantry"]}],"m":[{"n":"Sac-O-Suds chicken fried steak","note":"pounded beef dipped in flour and buttermilk, fried crisp, peppery cream gravy, for the two yutes","how":"Pound 4 minute steaks, about 600g, very thin. Dredge in seasoned flour, dip in 200ml buttermilk, then flour again, and shallow-fry 3 minutes a side until crisp. Pour off most of the oil, stir 2 tbsp flour into the pan, whisk in 400ml milk and simmer thick with lots of black pepper. Serve over 800g mashed potato.","shop":["600g minute steaks@Meat","150g plain flour@Pantry","200ml buttermilk@Dairy","400ml full cream milk@Dairy","800g potatoes@Produce","30g butter@Dairy","500ml vegetable oil@Pantry"]}],"w":[{"n":"Mona Lisa's blackberry cobbler","note":"Wazoo, Alabama, ticking clock and all","how":"Toss 750g blackberries with 100g sugar and 1 tbsp cornflour in a dish. Rub 80g butter into 200g self-raising flour and 50g sugar, add 150ml milk and drop spoonfuls on top. Bake at 190C for 35 minutes and serve with 300ml cream.","shop":["750g frozen blackberries@Frozen","150g caster sugar@Pantry","1 tbsp cornflour@Pantry","80g butter@Dairy","200g self-raising flour@Pantry","150ml full cream milk@Dairy","300ml thickened cream@Dairy"]}],"d":[{"n":"Wazoo peach sweet tea","note":"Southern style in Wazoo, Alabama, so sweet your teeth hurt","how":"Simmer 2 sliced ripe peaches with 120g caster sugar and 150ml water for 10 minutes, mash lightly and strain, keeping the syrup. Steep 6 black tea bags in 1 litre just-boiled water for 5 minutes and remove. Stir in the peach syrup and juice of half a lemon, then chill for 2 hours. Serve over ice with fresh peach slices and mint.","shop":["3 ripe peaches@Produce","120g caster sugar@Pantry","6 black tea bags@Pantry","1 lemon@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}],"shopping":["1.05L full cream milk@Dairy","150g stone-ground grits@Pantry","150g butter@Dairy","80g cheddar@Dairy","3 green tomatoes@Produce","350ml buttermilk@Dairy","120g fine cornmeal@Pantry","100g mayonnaise@Pantry","1 tbsp capers@Pantry","1 tsp hot sauce@Pantry","1L vegetable oil@Pantry","600g minute steaks@Meat","150g plain flour@Pantry","800g potatoes@Produce","750g frozen blackberries@Frozen","270g caster sugar@Pantry","1 tbsp cornflour@Pantry","200g self-raising flour@Pantry","300ml thickened cream@Dairy","3 ripe peaches@Produce","6 black tea bags@Pantry","1 lemon@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}},"Teenage Mutant Ninja Turtles (1990)":{"poster":"assets/menu-posters/teenage-mutant-ninja-turtles-1990.jpg","colour":"#478b35","servings":4,"tagline":"Four brothers. Four pizzas. Zero leftovers.","cue":"Order the pizza when it gets delivered down the drain.","menu":{"s":[{"n":"Sewer pizza rolls","note":"thin dough spread with sauce, pepperoni and mozzarella, rolled and baked, cowabunga","how":"Roll 500g pizza dough into a thin rectangle. Spread with 150ml pizza sauce, cover with 80g sliced pepperoni and 150g grated mozzarella. Roll up tightly from the long side, slice into 12 rounds and place cut side up on a lined tray. Bake at 220C for 15 minutes until golden.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","80g pepperoni@Deli","150g mozzarella@Dairy"]},{"n":"Splinter's cheese plate","note":"he is a rat, after all","how":"Take 150g aged cheddar, 150g brie and 150g gouda out of the fridge an hour before serving. Arrange on a board with 150g crackers and a bunch of grapes. Drizzle 1 tbsp honey over the brie just before it goes on the table.","shop":["150g aged cheddar@Deli","150g brie@Deli","150g gouda@Deli","150g crackers@Pantry","500g grapes@Produce","1 tbsp honey@Pantry"]}],"m":[{"n":"Mikey's four-pie pizza night","note":"one for each brother, Mikey calls the toppings","how":"Divide 1kg pizza dough into 4 balls and stretch thin. Spread each with pizza sauce, using 400ml in total, and 400g grated mozzarella across all four. Top one with pepperoni, one with sliced mushrooms, one with pepperoni, mushroom and capsicum, and one with whatever is left. Bake each on a preheated tray at the oven's highest setting for 8 minutes.","shop":["1kg pizza dough@Bakery","400ml pizza sauce@Pantry","400g mozzarella@Dairy","150g pepperoni@Deli","200g button mushrooms@Produce","1 capsicum@Produce"]}],"w":[{"n":"Pizza cookie","note":"choc chip base with candy toppings","how":"Beat 125g soft butter with 150g brown sugar and 1 egg, then mix in 200g plain flour, 1/2 tsp bicarb soda and 150g choc chips. Press into a greased pizza tray and bake at 180C for 15 minutes. Drizzle with 50g melted chocolate and scatter 100g lollies over the top. Cut into wedges.","shop":["125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","1/2 tsp bicarb soda@Pantry","150g choc chips@Pantry","50g dark chocolate@Pantry","100g lollies@Pantry"]}],"d":[{"n":"Channel 3 green apple soda","note":"fresh apple and lime juice over ice with fizzy water, the colour of four brothers","how":"Blend 3 green apples with the juice of 2 limes and 200ml water and strain. Divide over ice in 4 glasses and top with soda water.","shop":["3 green apples@Produce","2 limes@Produce","800ml soda water@Drinks"]}],"shopping":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","80g pepperoni@Deli","150g mozzarella@Dairy","150g aged cheddar@Deli","150g brie@Deli","150g gouda@Deli","150g crackers@Pantry","500g grapes@Produce","1 tbsp honey@Pantry","1kg pizza dough@Bakery","400ml pizza sauce@Pantry","400g mozzarella@Dairy","150g pepperoni@Deli","200g button mushrooms@Produce","1 capsicum@Produce","125g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","200g plain flour@Pantry","1/2 tsp bicarb soda@Pantry","150g choc chips@Pantry","50g dark chocolate@Pantry","100g lollies@Pantry","3 green apples@Produce","2 limes@Produce","800ml soda water@Drinks"]}},"Spider-Man (2002)":{"poster":"assets/menu-posters/spider-man-2002.jpg","colour":"#b5212d","servings":4,"tagline":"Bitten in Queens. Fed at Aunt May's.","cue":"Serve the snacks at the wrestling match where Peter wins his first prize money.","menu":{"s":[{"n":"Bone Saw egg and cheese rolls","note":"three minutes in the ring, then breakfast","how":"Split 4 soft rolls and toast lightly. Fry 8 eggs in 20g butter, breaking the yolks, and lay 2 slices American cheese over each pair to melt. Stack into the rolls with salt, pepper and a dash of hot sauce, wrap each in foil for 2 minutes so it all steams together.","shop":["4 soft rolls@Bakery","8 eggs@Dairy","20g butter@Dairy","8 slices American cheese@Dairy","1 bottle hot sauce@Pantry"]},{"n":"Thanksgiving sliders","note":"turkey and cranberry for the awkward Osborn dinner","how":"Make a 170g stuffing mix as the packet says, press into a tray and bake at 190C for 25 minutes until crisp, then cut into 8 squares. Toast 8 slider buns. Fill each with 300g warm sliced roast turkey in total, a spoon of cranberry sauce and a square of stuffing.","shop":["170g stuffing mix@Pantry","8 slider buns@Bakery","300g roast turkey@Deli","150g cranberry sauce@Pantry"]}],"m":[{"n":"Aunt May's Thanksgiving roast","note":"brined turkey breast, stuffing, pan gravy, roast potato and pumpkin, before Norman sees the cut","how":"Brine a 1.2kg turkey breast overnight in 2 litres water with 100g salt. Pat dry, rub with butter and roast at 170C to 70C inside, about 75 minutes. Rest 15 minutes. Roast 800g potatoes and 600g pumpkin in chunks alongside. Bake a 170g stuffing mix. Make gravy from the pan juices, 2 tbsp flour and 400ml chicken stock.","shop":["1.2kg turkey breast@Meat","100g cooking salt@Pantry","30g butter@Dairy","800g potatoes@Produce","600g pumpkin@Produce","170g stuffing mix@Pantry","2 tbsp plain flour@Pantry","400ml chicken stock@Pantry"]}],"w":[{"n":"Forest Hills pancakes","note":"Aunt May's Forest Hills kitchen, with syrup","how":"Whisk 250g plain flour, 2 tbsp sugar, 2 tsp baking powder and a pinch of salt. Add 2 eggs, 400ml buttermilk and 40g melted butter and rest 15 minutes. Cook ladlefuls in a buttered pan over medium heat until bubbles set, then flip. Stack high and pour over 150ml maple syrup.","shop":["250g plain flour@Pantry","2 tbsp caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","400ml buttermilk@Dairy","60g butter@Dairy","150ml maple syrup@Pantry"]}],"d":[{"n":"Daily Bugle cherry lime rickey","note":"cherry syrup and citrus over ice with soda and a maraschino, for a photo-hungry editor","how":"Squeeze 4 limes. Into each of 4 tall glasses of ice pour 30ml lime juice and 30ml cherry syrup, top with 200ml soda water, stir once and drop in a maraschino cherry and a lime wedge.","shop":["5 limes@Produce","120ml cherry syrup@Pantry","800ml soda water@Drinks","4 maraschino cherries@Pantry"]}],"shopping":["4 soft rolls@Bakery","8 eggs@Dairy","20g butter@Dairy","8 slices American cheese@Dairy","1 bottle hot sauce@Pantry","170g stuffing mix@Pantry","8 slider buns@Bakery","300g roast turkey@Deli","150g cranberry sauce@Pantry","1.2kg turkey breast@Meat","100g cooking salt@Pantry","30g butter@Dairy","800g potatoes@Produce","600g pumpkin@Produce","2 tbsp plain flour@Pantry","400ml chicken stock@Pantry","250g plain flour@Pantry","2 tbsp caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","400ml buttermilk@Dairy","60g butter@Dairy","150ml maple syrup@Pantry","5 limes@Produce","120ml cherry syrup@Pantry","800ml soda water@Drinks","4 maraschino cherries@Pantry"]}},"The Taking of Pelham One Two Three (1974)":{"poster":"assets/menu-posters/the-taking-of-pelham-one-two-three-1974.jpg","colour":"#ba921f","servings":4,"tagline":"Subway hostage. Snacks on the platform.","cue":"Serve the snacks when the four men in disguise board the train.","menu":{"s":[{"n":"Cheese danish","note":"breakfast in the transit dispatch room","how":"Beat 200g cream cheese with 50g caster sugar, 1 egg yolk and 1 tsp lemon zest. Cut 2 sheets puff pastry into 8 squares, spoon filling into the middle and fold in the corners. Bake at 200C for 16 minutes, cool 5 minutes and drizzle with 60g icing sugar mixed with 1 tbsp lemon juice.","shop":["200g cream cheese@Dairy","50g caster sugar@Pantry","1 egg@Dairy","1 lemon@Produce","2 sheets puff pastry@Frozen","60g icing sugar@Pantry"]},{"n":"Transit office jam doughnuts","note":"Garber's command centre","how":"Warm 8 jam doughnuts on a tray at 160C for 2 minutes. Roll each straight away in 80g caster sugar so it sticks, and serve on a plate in the middle of the table like the transit office tray.","shop":["8 jam doughnuts@Bakery","80g caster sugar@Pantry"]}],"m":[{"n":"Transit authority hero","note":"long roll of turkey, Swiss, iceberg and tomato wrapped tight, for the transit cop on radio","how":"Split 4 long rolls and spread each with mayonnaise, using 100g in total. Layer with 400g sliced turkey, 8 slices Swiss cheese, shredded iceberg lettuce and 2 sliced tomatoes. Season, close, wrap tightly in paper and cut in half.","shop":["4 long rolls@Bakery","100g mayonnaise@Pantry","400g sliced turkey@Deli","8 slices Swiss cheese@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce"]}],"w":[{"n":"Transit authority rugelach","note":"cream cheese pastry crescents rolled with apricot jam, walnuts and cinnamon","how":"Rub 225g butter and 225g cream cheese into 280g flour and chill 1 hour. Roll into circles, spread with apricot jam, walnuts and cinnamon sugar, cut into wedges and roll up. Bake at 180C for 22 minutes.","shop":["225g butter@Dairy","225g cream cheese@Dairy","280g plain flour@Pantry","1 jar apricot jam@Pantry","100g walnuts@Pantry","50g caster sugar@Pantry","1 tsp ground cinnamon@Pantry"]}],"d":[{"n":"Mr Green's honey lemon whisky toddy","note":"Scotch, honey, ginger and citrus topped with boiling water, cinnamon stick","how":"Thinly slice a 3cm piece of ginger. Into each of 4 heatproof glasses put 40ml whisky, 1 tbsp honey, 15ml lemon juice and two slices of ginger. Top each with 150ml just-boiled water and stir until the honey dissolves. Add a lemon wheel and a cinnamon stick and serve hot.","shop":["160ml whisky@Bottle shop","4 tbsp honey@Pantry","2 lemons@Produce","3cm piece ginger@Produce","4 cinnamon sticks@Pantry"]}],"shopping":["425g cream cheese@Dairy","180g caster sugar@Pantry","1 egg@Dairy","3 lemons@Produce","2 sheets puff pastries@Frozen","60g icing sugar@Pantry","8 jam doughnuts@Bakery","4 long rolls@Bakery","100g mayonnaise@Pantry","400g sliced turkey@Deli","8 slices Swiss cheeses@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","225g butter@Dairy","280g plain flour@Pantry","1 jar apricot jam@Pantry","100g walnuts@Pantry","1 tsp ground cinnamon@Pantry","160ml whisky@Bottle shop","4 tbsp honey@Pantry","3cm piece ginger@Produce","4 cinnamon sticks@Pantry"]}},"Ghost Dog: The Way of the Samurai (1999)":{"poster":"assets/menu-posters/ghost-dog-the-way-of-the-samurai-1999.jpg","colour":"#303857","servings":4,"tagline":"Silent. Loyal. Hungry.","cue":"Serve dessert when Ghost Dog swaps books with Pearline.","menu":{"s":[{"n":"Rooftop mixed nuts","note":"a handful of nuts and pumpkin seeds roasted with soy, a little honey and sesame","how":"Toss 250g mixed nuts and 50g pumpkin seeds with 1 tbsp soy sauce, 1 tbsp honey and 1 tbsp sesame seeds. Spread on a lined tray and roast at 170C for 12 minutes, stirring once. Cool on the tray so they crisp.","shop":["250g mixed nuts@Pantry","50g pumpkin seeds@Pantry","1 tbsp soy sauce@Pantry","1 tbsp honey@Pantry","1 tbsp sesame seeds@Pantry"]},{"n":"Edamame","note":"young soybeans boiled with flaky salt and sesame oil, a quiet snack between chapters of Hagakure","how":"Boil 500g frozen edamame in salted water for 4 minutes and drain well. Toss with 1 tsp sea salt flakes and 1 tsp sesame oil and serve warm in a bowl, with another bowl for the empty pods.","shop":["500g frozen edamame@Frozen","1 tsp sea salt flakes@Pantry","1 tsp sesame oil@Pantry"]}],"m":[{"n":"Teriyaki rice bowl","note":"Ghost Dog's rooftop","how":"Simmer 80ml soy sauce, 80ml mirin, 60ml sake and 2 tbsp sugar for 5 minutes until syrupy. Sear 800g chicken thighs skin side down for 8 minutes, flip, cook 5 minutes, then pour in the sauce and turn until glazed. Slice over 400g steamed short grain rice with 40g pickled ginger and sliced spring onion.","shop":["80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g chicken thighs@Meat","400g short grain rice@Pantry","40g pickled ginger@Pantry","2 spring onions@Produce"]}],"w":[{"n":"Coconut ice cream","note":"tinned coconut, sugar and thickened dairy churned smooth, toasted flakes through","how":"Toast 50g shredded coconut in a dry pan until golden. Blend 400ml coconut cream, 200ml thickened cream and 120g caster sugar until the sugar dissolves, then stir in most of the coconut. Churn, or freeze in a tub and stir every hour for 4 hours. Scoop and finish with the rest of the coconut.","shop":["50g shredded coconut@Pantry","400ml coconut cream@Pantry","200ml thickened cream@Dairy","120g caster sugar@Pantry"]}],"d":[{"n":"Rooftop iced matcha honey lemonade","note":"whisked matcha over sweetened lemon juice and ice, lemon wheel and mint, bittersweet and green","how":"Whisk 2 tsp matcha powder with 100ml water at 80C until frothy. Stir 60ml honey into 100ml warm water, then add 100ml lemon juice and 500ml cold water. Fill 4 glasses with ice, pour in the lemonade, then float the matcha on top. Add a lemon wheel and mint and stir at the table.","shop":["2 tsp matcha powder@Pantry","60ml honey@Pantry","3 lemons@Produce","4 sprigs mint@Produce","1 bag ice@Frozen"]}],"shopping":["250g mixed nuts@Pantry","50g pumpkin seeds@Pantry","1 tbsp soy sauce@Pantry","1 tbsp honey@Pantry","1 tbsp sesame seeds@Pantry","500g frozen edamame@Frozen","1 tsp sea salt flakes@Pantry","1 tsp sesame oil@Pantry","80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g chicken thighs@Meat","400g short grain rice@Pantry","40g pickled ginger@Pantry","2 spring onions@Produce","50g shredded coconut@Pantry","400ml coconut cream@Pantry","200ml thickened cream@Dairy","120g caster sugar@Pantry","2 tsp matcha powder@Pantry","60ml honey@Pantry","3 lemons@Produce","4 sprigs mints@Produce","1 bag ice@Frozen"]}},"Die Hard with a Vengeance (1995)":{"poster":"assets/menu-posters/die-hard-with-a-vengeance-1995.jpg","colour":"#b34c29","servings":4,"tagline":"One very long day in New York. Snacks for the road.","cue":"Pour drinks when McClane gets the water jug puzzle.","menu":{"s":[{"n":"Bodega beef patties","note":"turmeric pastry turnovers of curried beef mince, grabbed between Simon's riddles","how":"Soften the onion in the oil, then brown the mince with the curry powder, thyme and salt. Add the stock and simmer until almost dry, then stir in the breadcrumbs and cool. Heat the oven to 200C. Brush the pastry sheets with turmeric mixed into the beaten egg and cut two 12cm rounds from each. Spoon the filling onto half of each round, fold over and crimp with a fork. Brush the tops with the rest of the egg. Bake on lined trays until golden and flaky, about 25 minutes. Serve hot with hot sauce.","shop":["1 brown onion, finely diced@Produce","2 tbsp vegetable oil@Pantry","400g beef mince@Meat","2 tsp mild curry powder@Pantry","1 tsp dried thyme@Pantry","1 tsp salt@Pantry","125ml beef stock@Pantry","30g dry breadcrumbs@Pantry","4 sheets frozen shortcrust pastry@Frozen","1 tsp ground turmeric@Pantry","1 egg, beaten@Dairy","1 bottle hot sauce@Pantry"]},{"n":"Bacon egg and cheese on a roll","note":"McClane hasn't stopped all day","how":"Fry 8 rashers bacon until crisp. Fry 4 eggs in the same pan, breaking the yolks, and lay a slice of American cheese on each to melt. Split and butter 4 kaiser rolls and toast them. Fill with 2 rashers bacon and an egg each, season with salt and pepper and add tomato sauce.","shop":["8 rashers bacon@Meat","4 eggs@Dairy","4 slices American cheese@Dairy","4 kaiser rolls@Bakery","20g butter@Dairy","3 tbsp tomato sauce@Pantry"]}],"m":[{"n":"Harlem chicken and waffles","note":"McClane's sandwich-board stroll through Harlem","how":"Soak 600g boneless chicken thighs in 300ml buttermilk with 1 tsp salt for 2 hours. Dredge in 200g flour with 1 tsp paprika and fry at 175C for 7 minutes until 74C inside. Cook 8 small waffles from a 300g mix. Warm 100ml honey with 2 tsp hot sauce and drizzle over the chicken on the waffles.","shop":["600g chicken thighs@Meat","300ml buttermilk@Dairy","200g plain flour@Pantry","1 tsp sweet paprika@Pantry","300g waffle mix@Pantry","100ml honey@Pantry","1 bottle hot sauce@Pantry","2L vegetable oil@Pantry"]}],"w":[{"n":"Zeus's salted peanut caramel slab","note":"chewy brown sugar caramel set with roasted peanuts, topped with milk chocolate and flaky salt","how":"Line a 20cm square tin. Heat 200g brown sugar, 100g butter, 150ml cream and 2 tbsp golden syrup, stirring, then boil 6 to 8 minutes to 118C. Stir in 200g roasted salted peanuts and pour into the tin. Cool 30 minutes, spread with 150g melted milk chocolate and sprinkle with flaky salt. Chill 2 hours and cut into squares.","shop":["200g brown sugar@Pantry","100g butter@Dairy","150ml thickened cream@Dairy","2 tbsp golden syrup@Pantry","200g roasted salted peanuts@Pantry","150g milk chocolate@Pantry","flaky sea salt@Pantry"]}],"d":[{"n":"Water jug lemonade","note":"lemon juice and sugar syrup topped up cold, solve the fountain jugs first","how":"Dissolve 300g caster sugar in 300ml hot water and cool. Add 400ml lemon juice, about 10 lemons, and top up with cold water to exactly 4 litres. Work it out with a 5 litre and a 3 litre jug if you're feeling brave. Serve over ice.","shop":["300g caster sugar@Pantry","10 lemons@Produce","1kg ice@Frozen"]}],"shopping":["1 brown onion, finely diced@Produce","2 tbsp vegetable oil@Pantry","400g beef mince@Meat","2 tsp mild curry powder@Pantry","1 tsp dried thyme@Pantry","1 tsp salt@Pantry","125ml beef stock@Pantry","30g dry breadcrumbs@Pantry","4 sheets frozen shortcrust pastry@Frozen","1 tsp ground turmeric@Pantry","1 egg, beaten@Dairy","1 bottle hot sauce@Pantry","8 rashers bacon@Meat","4 eggs@Dairy","4 slices American cheese@Dairy","4 kaiser rolls@Bakery","120g butter@Dairy","3 tbsp tomato sauce@Pantry","600g chicken thighs@Meat","300ml buttermilk@Dairy","200g plain flour@Pantry","1 tsp sweet paprika@Pantry","300g waffle mix@Pantry","100ml honey@Pantry","2L vegetable oil@Pantry","200g brown sugar@Pantry","150ml thickened cream@Dairy","2 tbsp golden syrup@Pantry","200g roasted salted peanuts@Pantry","150g milk chocolate@Pantry","flaky sea salt@Pantry","300g caster sugar@Pantry","10 lemons@Produce","1kg ice@Frozen"]}},"16 Blocks (2006)":{"poster":"assets/menu-posters/16-blocks-2006.jpg","colour":"#326d70","servings":4,"tagline":"Sixteen blocks. One long lunch.","cue":"Serve dessert when Eddie talks about opening a bakery.","menu":{"s":[{"n":"Salt and vinegar pork crackling","note":"Jack's stop at the liquor store before the walk starts","how":"Score the skin of 1kg boneless pork belly, pat dry and refrigerate uncovered overnight. Rub with 1 tbsp malt vinegar, then 1 tbsp salt. Roast skin up at 160C for 90 minutes, then 240C for 25 minutes until puffed and crackling. Rest 10 minutes, then cut into bite-sized pieces. Sprinkle with flaky salt mixed with a splash of malt vinegar. Serve with pickled onions and hot English mustard.","shop":["1kg boneless pork belly@Meat","malt vinegar@Pantry","salt@Pantry","flaky sea salt@Pantry","1 jar pickled onions@Pantry","hot English mustard@Pantry"]},{"n":"Chinatown dumplings","note":"pork parcels crisp underneath then steamed, soy, black vinegar and ginger, for the hideout","how":"Fry 24 frozen pork dumplings flat side down in 1 tbsp oil for 2 minutes, add 120ml water, cover and steam 4 minutes, then fry again until crisp underneath. Mix 3 tbsp soy sauce, 2 tbsp black vinegar and 1 tbsp fine ginger matchsticks for dipping.","shop":["24 frozen pork dumplings@Frozen","3 tbsp soy sauce@Pantry","2 tbsp black vinegar@Pantry","1 piece ginger@Produce"]}],"m":[{"n":"Chopped cheese","note":"griddled beef mince and onion, American slices melted through, in a long roll with salad","how":"Fry 1 diced onion on a hot griddle, add 600g beef mince and chop it up with a spatula as it browns, seasoning well. Lay 6 slices American cheese on top and chop through until melted. Pile into 4 toasted hero rolls with shredded lettuce, sliced tomato and mayo.","shop":["1 brown onion@Produce","600g beef mince@Meat","6 slices American cheese@Dairy","4 hero rolls@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","80g mayonnaise@Pantry"]}],"w":[{"n":"Eddie's birthday cake","note":"he wants to open a bakery and make birthday cakes","how":"Beat 200g butter with 200g caster sugar, add 4 eggs, then fold in 220g self-raising flour, 40g cocoa and 120ml milk. Bake in two 20cm tins at 180C for 25 minutes. Beat 150g butter with 300g icing sugar and 40g cocoa, sandwich and cover the cakes, and add birthday candles.","shop":["350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","220g self-raising flour@Pantry","80g cocoa@Pantry","120ml full cream milk@Dairy","300g icing sugar@Pantry","1 pack birthday candles@Pantry"]}],"d":[{"n":"Bodega iced coffee with condensed milk","note":"Jack needs it, badly, for a long walk to the courthouse","how":"Brew 600ml strong coffee using 60g ground coffee and cool for 10 minutes. Spoon 2 tbsp sweetened condensed milk into each of 4 glasses. Fill with ice, then pour 150ml coffee into each. Stir well until creamy and dust with a little cinnamon.","shop":["60g ground coffee@Pantry","1 tin sweetened condensed milk@Pantry","ground cinnamon@Pantry","1 bag ice@Frozen"]}],"shopping":["1kg boneless pork belly@Meat","malt vinegar@Pantry","salt@Pantry","flaky sea salt@Pantry","1 jar pickled onions@Pantry","hot English mustard@Pantry","24 frozen pork dumplings@Frozen","3 tbsp soy sauce@Pantry","2 tbsp black vinegar@Pantry","1 piece ginger@Produce","1 brown onion@Produce","600g beef mince@Meat","6 slices American cheeses@Dairy","4 hero rolls@Bakery","1 iceberg lettuce@Produce","2 tomatoes@Produce","80g mayonnaise@Pantry","350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","220g self-raising flour@Pantry","80g cocoa@Pantry","120ml full cream milk@Dairy","300g icing sugar@Pantry","1 pack birthday candles@Pantry","60g ground coffee@Pantry","1 tin sweetened condensed milk@Pantry","ground cinnamon@Pantry","1 bag ice@Frozen"]}},"Goodfellas (1990)":{"poster":"assets/menu-posters/goodfellas-1990.jpg","colour":"#7d2525","servings":4,"tagline":"A life in the crew, told one plate at a time.","cue":"Plate up the mains when young Henry starts running errands at the cab stand.","menu":{"s":[{"n":"Razor-thin garlic bruschetta","note":"Paulie's razor blade garlic, sliced so fine it melts in the oil","how":"Slice 6 garlic cloves paper thin on a mandoline and cook in 80ml extra virgin olive oil over low heat for 5 minutes until soft and barely golden. Grill 8 slices of ciabatta, rub with the cut side of 2 halved tomatoes and season with salt. Spoon the garlic and its oil over the top and finish with torn basil.","shop":["6 garlic cloves@Produce","80ml extra virgin olive oil@Pantry","1 loaf ciabatta@Bakery","2 truss tomatoes@Produce","1 bunch basil@Produce"]},{"n":"Karen's prawn cocktail","note":"poached prawns on iceberg with brandy Marie Rose and paprika, served in coupes at the Copa","how":"Poach 500g peeled green prawns for 2 minutes in salted water with a slice of lemon, then chill in iced water. Mix 120g mayonnaise with 2 tbsp tomato sauce, 1 tsp Worcestershire sauce, a few drops of hot sauce and 1 tsp brandy. Shred half an iceberg lettuce into four coupes, add the prawns and spoon over the sauce. Dust with paprika and serve with lemon wedges.","shop":["500g green prawns@Seafood","2 lemons@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp Worcestershire sauce@Pantry","1 iceberg lettuce@Produce"]}],"m":[{"n":"Prison gravy with three-meat meatballs","note":"veal, beef and pork, and fewer onions than Vinnie uses","how":"Soak 2 slices bread in 80ml milk, then mix with 200g veal mince, 200g beef mince, 200g pork mince, 1 egg, 40g grated pecorino, chopped parsley and 1 crushed garlic clove. Roll into 16 balls and brown. In the same pot gently cook 4 garlic cloves sliced razor thin and half a diced onion, add 800g San Marzano tomatoes and the meatballs and simmer 90 minutes. Serve over 500g spaghetti.","shop":["200g veal mince@Meat","200g beef mince@Meat","200g pork mince@Meat","1 egg@Dairy","40g pecorino@Deli","5 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","500g spaghetti@Pantry"]}],"w":[{"n":"Lemon ice","note":"a hot Brooklyn summer on the corner","how":"Simmer 200g caster sugar with 500ml water and the zest of 2 lemons for 5 minutes, then cool. Stir in 250ml lemon juice, about 6 lemons. Pour into a shallow tray and freeze, scraping with a fork every 30 minutes for 3 hours until light and fluffy. Serve in paper cups.","shop":["6 lemons@Produce","200g caster sugar@Pantry"]}],"d":[{"n":"Jimmy's Scotch and ginger highball","note":"whisky, honey ginger syrup, lemon and soda over big ice, toasting the Lufthansa score","how":"Make the syrup: simmer 60g honey, 60ml water and 30g sliced ginger for 5 minutes, then cool and strain. Fill 4 highball glasses with large ice cubes. Add 45ml Scotch, 15ml ginger syrup and 10ml lemon juice to each and stir for 10 seconds. Top each with 120ml chilled soda water, stir once and finish with a curl of lemon peel.","shop":["180ml blended Scotch@Bottle shop","60g honey@Pantry","30g ginger@Produce","2 lemons@Produce","500ml soda water@Drinks","1 bag ice@Frozen"]}],"shopping":["11 garlic cloves@Produce","80ml extra virgin olive oil@Pantry","1 loaf ciabatta@Bakery","2 truss tomatoes@Produce","1 bunch basil@Produce","500g green prawns@Seafood","10 lemons@Produce","120g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp Worcestershire sauce@Pantry","1 iceberg lettuce@Produce","200g veal mince@Meat","200g beef mince@Meat","200g pork mince@Meat","1 egg@Dairy","40g pecorino@Deli","800g San Marzano tomatoes@Pantry","500g spaghetti@Pantry","200g caster sugar@Pantry","180ml blended Scotch@Bottle shop","60g honey@Pantry","30g ginger@Produce","500ml soda water@Drinks","1 bag ice@Frozen"]}},"Mean Streets (1973)":{"poster":"assets/menu-posters/mean-streets-1973.jpg","colour":"#b62924","servings":4,"tagline":"Sins in the street. Penance at the bar.","cue":"Hit play on the jukebox and pour a round when Johnny Boy walks into Tony's bar.","menu":{"s":[{"n":"San Gennaro sausage bites","note":"charred and sliced, straight from the street feast","how":"Grill 500g Italian sausages over high heat for 12 minutes, turning, until blistered and cooked through. Grill 1 red capsicum and 1 onion cut into chunks until charred at the edges. Slice the sausages thick and thread onto toothpicks with the capsicum and onion. Serve with 50g hot mustard.","shop":["500g Italian sausages@Meat","1 red capsicum@Produce","1 brown onion@Produce","50g hot mustard@Pantry"]},{"n":"Fried calamari","note":"lemon, eaten at Tony's bar","how":"Slice 500g squid tubes into rings and soak in 250ml buttermilk for 30 minutes. Mix 100g fine semolina with 100g plain flour and plenty of salt. Drain the squid, toss in the flour mix and fry in 190C oil in batches for 90 seconds until pale gold. Salt and serve with 2 lemons cut into wedges.","shop":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","100g plain flour@Pantry","2 lemons@Produce","1L vegetable oil@Pantry"]}],"m":[{"n":"Penne arrabbiata","note":"as hot as Johnny Boy's temper","how":"Gently fry 4 sliced garlic cloves and 1 tsp dried chilli flakes in 4 tbsp olive oil for 2 minutes. Add 800g crushed tomatoes and simmer 15 minutes, seasoning well. Cook 500g penne until al dente and toss through the sauce with a splash of pasta water and chopped parsley. Finish with 50g grated pecorino.","shop":["4 garlic cloves@Produce","1 tsp dried chilli flakes@Pantry","4 tbsp olive oil@Pantry","800g crushed tomatoes@Pantry","500g penne@Pantry","1 bunch parsley@Produce","50g pecorino@Deli"]}],"w":[{"n":"Zeppole","note":"icing sugar, straight from the street feast","how":"Mix 250g plain flour, 7g dried yeast, 1 tbsp caster sugar, a pinch of salt and 200ml warm water into a sticky batter and leave to rise for 1 hour. Drop teaspoons into 175C oil and fry 3 minutes until puffed and golden. Drain, tip into a paper bag with 60g icing sugar, shake and eat hot.","shop":["250g plain flour@Pantry","7g dried yeast@Pantry","1 tbsp caster sugar@Pantry","60g icing sugar@Pantry","1L vegetable oil@Pantry"]}],"d":[{"n":"San Gennaro red wine with white peaches","note":"light red over sugared fruit, soaked and spooned into tumblers, on Johnny Boy's tab","how":"Halve and stone 3 ripe white peaches, then slice thinly into a large jug. Sprinkle with 1 tbsp caster sugar and leave 10 minutes. Pour over 750ml light Italian red, such as Lambrusco secco or a young Chianti, and refrigerate for at least 1 hour. Serve in tumblers with a spoonful of peach in each. Eat the peaches last.","shop":["750ml light Italian red wine@Bottle shop","3 white peaches@Produce","1 tbsp caster sugar@Pantry"]}],"shopping":["500g Italian sausages@Meat","1 red capsicum@Produce","1 brown onion@Produce","50g hot mustard@Pantry","500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","350g plain flour@Pantry","2 lemons@Produce","2L vegetable oil@Pantry","4 garlic cloves@Produce","1 tsp dried chilli flakes@Pantry","4 tbsp olive oil@Pantry","800g crushed tomatoes@Pantry","500g penne@Pantry","1 bunch parsley@Produce","50g pecorino@Deli","7g dried yeast@Pantry","2 tbsp caster sugar@Pantry","60g icing sugar@Pantry","750ml light Italian red wine@Bottle shop","3 white peaches@Produce"]}},"The Untouchables (1987)":{"poster":"assets/menu-posters/the-untouchables-1987.jpg","colour":"#203b4b","servings":4,"tagline":"Prohibition Chicago. Bring a fork.","cue":"Pour the drinks when Ness first meets Malone walking his beat.","menu":{"s":[{"n":"Capone's arancini","note":"crisp risotto balls with mozzarella centres and tomato sauce, before the Union Station steps","how":"Cook 300g arborio rice in 1L stock to a firm risotto, stir in 50g parmesan and cool completely. Roll into 16 balls around cubes of 150g mozzarella, roll in flour, beaten egg and breadcrumbs and fry at 180C for 4 minutes. Serve with 400g warm passata.","shop":["300g arborio rice@Pantry","1L chicken stock@Pantry","50g parmesan@Dairy","150g mozzarella@Dairy","2 eggs@Dairy","100g breadcrumbs@Pantry","400g passata@Pantry","1L vegetable oil@Pantry"]},{"n":"Capone's hotel antipasto","note":"salami, mortadella, prosciutto, artichokes and bocconcini, laid out for the baseball bat banquet","how":"Fold 100g salami, 100g mortadella and 80g prosciutto onto a long board. Add 200g marinated artichokes, 1 jar roast peppers torn into strips and 200g bocconcini dressed with olive oil, salt and pepper. Slice 1 Italian loaf and serve alongside so everyone builds their own.","shop":["100g salami@Deli","100g mortadella@Deli","80g prosciutto@Deli","200g marinated artichokes@Deli","1 jar roast peppers@Pantry","200g bocconcini@Dairy","1 Italian loaf@Bakery"]}],"m":[{"n":"Italian beef","note":"shaved, dipped and hot","how":"Rub a 1kg beef topside with salt, pepper and oregano and roast at 200C to 52C inside, about 35 minutes. Chill, then shave thin. Simmer 750ml beef stock with 3 crushed garlic cloves, 1 tsp dried oregano and plenty of black pepper. Warm the beef in the jus, pile into 4 long rolls, dip the whole sandwich, and top with 200g hot giardiniera.","shop":["1kg beef topside@Meat","750ml beef stock@Pantry","3 garlic cloves@Produce","2 tsp dried oregano@Pantry","4 long rolls@Bakery","200g hot giardiniera@Deli"]}],"w":[{"n":"Ricotta zeppole","note":"little ricotta and lemon doughnuts in icing sugar, for the Mountie raid at the border","how":"Mix 250g ricotta, 2 eggs, 2 tbsp sugar, 1 tsp vanilla and the zest of 1 lemon, then fold in 150g self-raising flour. Drop teaspoons into oil at 175C and fry 3 minutes until puffed and golden. Drain and toss in 60g icing sugar.","shop":["250g ricotta@Dairy","2 eggs@Dairy","2 tbsp caster sugar@Pantry","1 tsp vanilla extract@Pantry","1 lemon@Produce","150g self-raising flour@Pantry","1L vegetable oil@Pantry","60g icing sugar@Pantry"]}],"d":[{"n":"Repeal Day old fashioned","note":"rye, sugar and bitters on a big cube, orange twist, Ness finally has a drink","how":"Make sugar syrup by dissolving 40g caster sugar in 40ml hot water. For each drink, stir 60ml rye whiskey, 10ml syrup and 2 dashes aromatic bitters over ice for 30 seconds and strain over one big cube. Twist a strip of orange peel over the top. Makes four with 240ml rye.","shop":["240ml rye whiskey@Bottle shop","40g caster sugar@Pantry","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}],"shopping":["300g arborio rice@Pantry","1L chicken stock@Pantry","50g parmesan@Dairy","150g mozzarella@Dairy","4 eggs@Dairy","100g breadcrumbs@Pantry","400g passata@Pantry","2L vegetable oil@Pantry","100g salami@Deli","100g mortadella@Deli","80g prosciutto@Deli","200g marinated artichokes@Deli","1 jar roast peppers@Pantry","200g bocconcini@Dairy","1 Italian loaf@Bakery","1kg beef topside@Meat","750ml beef stock@Pantry","3 garlic cloves@Produce","2 tsp dried oregano@Pantry","4 long rolls@Bakery","200g hot giardiniera@Deli","250g ricotta@Dairy","1 tsp vanilla extract@Pantry","1 lemon@Produce","150g self-raising flour@Pantry","60g icing sugar@Pantry","240ml rye whiskey@Bottle shop","70g caster sugar@Pantry","1 bottle aromatic bitters@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}},"Analyze This (1999)":{"poster":"assets/menu-posters/analyze-this-1999.jpg","colour":"#244536","servings":4,"tagline":"Therapy, but make it Italian.","cue":"Serve dessert when Paul first turns up at Ben's office.","menu":{"s":[{"n":"Sobel wedding fried calamari","note":"buttermilk-soaked squid in semolina, cooked crisp, for the Miami nuptials Vitti keeps interrupting","how":"Slice 500g squid tubes into rings and soak in 250ml buttermilk for 30 minutes. Mix 100g fine semolina and 100g plain flour with plenty of salt. Toss the drained squid through and fry at 190C in batches for 90 seconds. Salt and serve with 2 lemons cut into wedges.","shop":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","100g plain flour@Pantry","2 lemons@Produce","1L vegetable oil@Pantry"]},{"n":"Mozzarella in carrozza","note":"comfort food for a man in crisis","how":"Cut the crusts off 8 slices white bread and make 4 sandwiches with 250g sliced mozzarella. Cut each into triangles. Dip in 3 eggs beaten with 3 tbsp milk, then press into 100g breadcrumbs. Shallow-fry in 1cm of oil for 2 minutes a side until golden and the cheese melts.","shop":["8 slices white bread@Bakery","250g mozzarella@Dairy","3 eggs@Dairy","3 tbsp full cream milk@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Paul Vitti's veal parm","note":"crumbed veal under marinara and mozzarella with spaghetti, you're good, you","how":"Dust 600g veal escalopes in flour, dip in 2 beaten eggs and coat in 120g breadcrumbs. Shallow-fry 2 minutes a side until golden. Top each with warm passata, 200g sliced mozzarella and 30g parmesan and grill until bubbling. Serve with 400g spaghetti tossed in the rest of the 700ml passata.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","2 eggs@Dairy","120g breadcrumbs@Pantry","700ml passata@Pantry","200g mozzarella@Dairy","30g parmesan@Dairy","400g spaghetti@Pantry"]}],"w":[{"n":"Vitti's ricotta cannoli","note":"Vitti's thank you to his shrink, in pastry form","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar and the zest of 1 orange. Melt 50g dark chocolate and dip the ends of 8 cannoli shells, then let set. Pipe the filling in just before serving.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery"]}],"d":[{"n":"Dr Sobel's calming Negroni","note":"gin, bitter red aperitif and sweet vermouth over a big cube, for a 3am house call","how":"For each drink, stir 30ml gin, 30ml bitter red aperitif and 30ml sweet vermouth over ice for 20 seconds and strain over a big ice cube in a tumbler. Add a slice of orange. Makes four with 120ml of each.","shop":["120ml gin@Bottle shop","120ml bitter red aperitif@Bottle shop","120ml sweet vermouth@Bottle shop","1 orange@Produce","4 large ice cubes@Frozen"]}],"shopping":["500g squid tubes@Seafood","250ml buttermilk@Dairy","100g fine semolina@Pantry","100g plain flour@Pantry","2 lemons@Produce","1L vegetable oil@Pantry","8 slices white bread@Bakery","250g mozzarella@Dairy","3 eggs@Dairy","3 tbsp full cream milk@Dairy","100g breadcrumbs@Pantry","600g veal escalopes@Meat","2 tbsp plain flour@Pantry","2 eggs@Dairy","120g breadcrumbs@Pantry","700ml passata@Pantry","200g mozzarella@Dairy","30g parmesan@Dairy","400g spaghetti@Pantry","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery","120ml gin@Bottle shop","120ml bitter red aperitif@Bottle shop","120ml sweet vermouth@Bottle shop","4 large ice cubes@Frozen"]}},"Mickey Blue Eyes (1999)":{"poster":"assets/menu-posters/mickey-blue-eyes-1999.jpg","colour":"#244b8b","servings":4,"tagline":"Marry the girl. Marry the family.","cue":"Serve the mains when Michael tries to do the Kansas City accent.","menu":{"s":[{"n":"English tea sandwiches","note":"crustless fingers of cucumber, egg and cress, and smoked salmon, before Michael proposes","how":"Boil 3 eggs for 10 minutes, then mash with 2 tbsp mayonnaise and cress. Butter 12 slices white bread. Make 2 sandwiches with thin cucumber, 2 with the egg, and 2 with 100g smoked salmon on 100g cream cheese. Cut off the crusts and cut each into 3 fingers.","shop":["12 slices white bread@Bakery","40g butter@Dairy","1 Lebanese cucumber@Produce","3 eggs@Dairy","2 tbsp mayonnaise@Pantry","1 punnet mustard cress@Produce","100g smoked salmon@Seafood","100g cream cheese@Dairy"]},{"n":"Kansas City Mickey's fried ravioli","note":"Michael's cover story, Mickey Blue Eyes from Kansas City","how":"Dip 400g fresh ricotta ravioli in 2 beaten eggs, then in 120g breadcrumbs. Fry at 180C in batches for 2 minutes until crisp and golden, then drain. Shower with 30g grated parmesan and serve with 300ml warm passata seasoned with salt and oregano for dipping.","shop":["400g ricotta ravioli@Dairy","2 eggs@Dairy","120g breadcrumbs@Pantry","30g parmesan@Dairy","300ml passata@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Frank Vitale's linguine with clams","note":"Gina's dad's restaurant, where the family drops in","how":"Soak 1kg clams in salted water for 30 minutes to purge. Gently fry 4 sliced garlic cloves and a pinch of chilli in 60ml olive oil, add the clams and 150ml white wine, cover and steam 4 minutes until open. Cook 400g linguine 1 minute short, finish it in the pan juices and toss with chopped parsley and more olive oil.","shop":["1kg clams@Seafood","4 garlic cloves@Produce","60ml olive oil@Pantry","150ml white wine@Bottle shop","400g linguine@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Accent lesson tiramisu","note":"savoiardi in espresso and marsala with mascarpone and cocoa, practise fuhgeddaboudit between bites","how":"Whisk 4 egg yolks with 100g caster sugar until pale, then fold in 500g mascarpone and 4 egg whites whipped stiff. Mix 300ml strong espresso with 3 tbsp marsala. Dip 24 savoiardi biscuits quickly and layer with the cream in a dish. Dust with 2 tbsp cocoa and chill overnight.","shop":["4 eggs@Dairy","100g caster sugar@Pantry","500g mascarpone@Dairy","300ml espresso@Pantry","3 tbsp marsala@Bottle shop","24 savoiardi biscuits@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Auction house gin and elderflower collins","note":"gin, floral cordial and lemon topped with soda, cucumber and mint, to steady an auctioneer's nerves","how":"Peel 8 long ribbons from 1 Lebanese cucumber and curl two into each of 4 tall glasses, then fill with ice. Shake 160ml gin, 60ml elderflower cordial and 60ml lemon juice with ice for 10 seconds. Strain over the glasses and top each with 100ml soda water. Add a sprig of mint and serve.","shop":["160ml gin@Bottle shop","60ml elderflower cordial@Drinks","2 lemons@Produce","1 Lebanese cucumber@Produce","400ml soda water@Drinks","4 sprigs mint@Produce","1 bag ice@Frozen"]}],"shopping":["12 slices white breads@Bakery","40g butter@Dairy","2 Lebanese cucumbers@Produce","9 eggs@Dairy","2 tbsp mayonnaise@Pantry","1 punnet mustard cress@Produce","100g smoked salmon@Seafood","100g cream cheese@Dairy","400g ricotta ravioli@Dairy","120g breadcrumbs@Pantry","30g parmesan@Dairy","300ml passata@Pantry","1L vegetable oil@Pantry","1kg clams@Seafood","4 garlic cloves@Produce","60ml olive oil@Pantry","150ml white wine@Bottle shop","400g linguine@Pantry","1 bunch parsley@Produce","100g caster sugar@Pantry","500g mascarpone@Dairy","300ml espresso@Pantry","3 tbsp marsala@Bottle shop","24 savoiardi biscuits@Pantry","2 tbsp cocoa@Pantry","160ml gin@Bottle shop","60ml elderflower cordial@Drinks","2 lemons@Produce","400ml soda water@Drinks","4 sprigs mints@Produce","1 bag ice@Frozen"]}},"Miller's Crossing (1990)":{"poster":"assets/menu-posters/millers-crossing-1990.jpg","colour":"#294730","servings":4,"tagline":"Hats, woods and loyalties.","cue":"Plate up when Johnny Caspar airs his gripe in Leo's office.","menu":{"s":[{"n":"Leo's office liver pâté toasts","note":"chicken livers flamed with brandy, blitzed with butter and thyme on toast, what's the rumpus","how":"Trim 400g chicken livers and sear in butter for 2 minutes a side until still pink. Add 2 chopped shallots and thyme, then 40ml brandy and let it bubble off. Blitz with 150g soft butter until silky, season and press into a dish. Pour over 50g melted clarified butter and chill 4 hours. Serve with 8 slices toasted rye.","shop":["400g chicken livers@Meat","200g butter@Dairy","2 shallots@Produce","1 bunch thyme@Produce","40ml brandy@Bottle shop","8 slices rye bread@Bakery"]},{"n":"Johnny Caspar's cheese straws","note":"puff pastry twists with aged cheddar, parmesan and cayenne, for a gripe about a fixed fight","how":"Brush 2 sheets puff pastry with 1 beaten egg. Scatter one sheet with 80g grated aged cheddar, 30g grated parmesan and a pinch of cayenne, lay the other on top and press. Cut into 1.5cm strips, twist each and bake at 220C for 12 minutes until puffed and golden.","shop":["2 sheets puff pastry@Frozen","1 egg@Dairy","80g cheddar@Dairy","30g parmesan@Dairy","1 pinch cayenne pepper@Pantry"]}],"m":[{"n":"Leo's slow-cooked Irish stew","note":"Leo's house, stewed low and slow","how":"Brown 1.2kg lamb neck chops in batches. Layer in a heavy pot with 2 sliced brown onions, 3 carrots in chunks and 800g potatoes in thick slices. Pour over 375ml stout and 300ml beef stock, cover and braise at 160C for 2 hours until tender. Finish with chopped parsley.","shop":["1.2kg lamb neck chops@Meat","2 brown onions@Produce","3 carrots@Produce","800g potatoes@Produce","375ml stout@Bottle shop","300ml beef stock@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Whisky bread pudding","note":"brioche and whiskey-soaked raisins in custard, look in your heart","how":"Soak 80g raisins in 60ml Irish whiskey for 30 minutes. Butter 8 slices stale brioche and layer in a dish with the raisins. Whisk 4 eggs, 300ml milk, 200ml cream and 80g sugar and pour over. Rest 30 minutes, then bake at 170C for 40 minutes until puffed and golden.","shop":["80g raisins@Pantry","60ml Irish whiskey@Bottle shop","8 slices brioche@Bakery","40g butter@Dairy","4 eggs@Dairy","300ml full cream milk@Dairy","200ml thickened cream@Dairy","80g caster sugar@Pantry"]}],"d":[{"n":"Tom Reagan's hot Irish whiskey toddy","note":"Tom never puts his glass down, whatever the weather","how":"Boil 600ml water. Stud 4 lemon wheels with 3 cloves each. In each of 4 heatproof glasses, put 45ml Irish whiskey, 1 tbsp honey and 15ml lemon juice. Top each with 150ml just-boiled water and stir until the honey dissolves. Float a studded lemon wheel on top, add a cinnamon stick and serve hot.","shop":["180ml Irish whiskey@Bottle shop","4 tbsp honey@Pantry","2 lemons@Produce","12 whole cloves@Pantry","4 cinnamon sticks@Pantry"]}],"shopping":["400g chicken livers@Meat","240g butter@Dairy","2 shallots@Produce","1 bunch thyme@Produce","40ml brandy@Bottle shop","8 slices rye breads@Bakery","2 sheets puff pastries@Frozen","5 eggs@Dairy","80g cheddar@Dairy","30g parmesan@Dairy","1 pinch cayenne pepper@Pantry","1.2kg lamb neck chops@Meat","2 brown onions@Produce","3 carrots@Produce","800g potatoes@Produce","375ml stout@Bottle shop","300ml beef stock@Pantry","1 bunch parsley@Produce","80g raisins@Pantry","240ml Irish whiskey@Bottle shop","8 slices brioches@Bakery","300ml full cream milk@Dairy","200ml thickened cream@Dairy","80g caster sugar@Pantry","4 tbsp honey@Pantry","2 lemons@Produce","12 whole cloves@Pantry","4 cinnamon sticks@Pantry"]}},"Moonstruck (1987)":{"poster":"assets/menu-posters/moonstruck-1987.jpg","colour":"#344d6c","servings":4,"tagline":"A full moon over Brooklyn. Eat up.","cue":"Bring out the bread when Ronny is in the bakery basement.","menu":{"s":[{"n":"Cammareri Bros. rosemary focaccia","note":"warm bread from Ronny's bakery, the Cammareri Bros. ovens","how":"Mix 500g bread flour, 7g dried yeast, 10g salt and 400ml warm water into a wet dough. Cover and rise 2 hours. Oil a 30 x 20cm tin with 60ml olive oil, tip in the dough and stretch to the corners. Rest 30 minutes, then dimple deeply with oiled fingers. Scatter with rosemary leaves and flaky salt and drizzle with 30ml oil. Bake at 230C for 22 to 25 minutes until deep golden.","shop":["500g bread flour@Pantry","7g dried yeast@Pantry","10g salt@Pantry","120ml olive oil@Pantry","2 sprigs rosemary@Produce","flaky sea salt@Pantry"]},{"n":"Eggs in the hole","note":"Rose's kitchen breakfast: a red capsicum ring and an egg in toast","how":"Cut a hole in 4 thick slices white bread. Melt 40g butter in a big pan and lay in the bread. Put a thick ring of red capsicum in each hole, crack an egg into it, and fry until the white sets, flipping the bread once. Season with salt and pepper.","shop":["4 slices white bread@Bakery","40g butter@Dairy","1 red capsicum@Produce","4 eggs@Dairy"]}],"m":[{"n":"Chicken scaloppine","note":"thin breast seared, lemon, white wine, butter and caper sauce, for Cosmo and Mona's night out","how":"Slice 2 large chicken breasts, about 600g, in half horizontally and pound thin. Dust in flour and sear in oil and 20g butter for 2 minutes a side, then set aside. Add 100ml white wine, the juice of 1 lemon and 2 tbsp capers, reduce by half and swirl in 40g cold butter and parsley. Return the chicken to coat.","shop":["600g chicken breasts@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","100ml white wine@Bottle shop","1 lemon@Produce","2 tbsp capers@Pantry","1 bunch parsley@Produce"]}],"w":[{"n":"Cannoli","note":"crisp shells piped with ricotta and orange zest, chocolate-dipped ends, snap out of it","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar and the zest of 1 orange. Dip the ends of 8 cannoli shells in 50g melted dark chocolate and let set. Pipe in the filling just before serving.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery"]}],"d":[{"n":"Brooklyn amaretto sours","note":"Loretta's family, bottle of wine and a full moon","how":"Shake 45ml amaretto, 25ml lemon juice and half an egg white hard without ice, then again with ice. Strain over fresh ice in 4 short glasses and add a cherry to each.","shop":["180ml amaretto@Bottle shop","3 lemons@Produce","2 eggs@Dairy","1 jar maraschino cherries@Pantry"]}],"shopping":["500g bread flour@Pantry","7g dried yeast@Pantry","10g salt@Pantry","120ml olive oil@Pantry","2 sprigs rosemaries@Produce","flaky sea salt@Pantry","4 slices white breads@Bakery","100g butter@Dairy","1 red capsicum@Produce","6 eggs@Dairy","600g chicken breasts@Meat","2 tbsp plain flour@Pantry","100ml white wine@Bottle shop","4 lemons@Produce","2 tbsp capers@Pantry","1 bunch parsley@Produce","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 orange@Produce","50g dark chocolate@Pantry","8 cannoli shells@Bakery","180ml amaretto@Bottle shop","1 jar maraschino cherries@Pantry"]}},"Big Night (1996)":{"poster":"assets/menu-posters/big-night-1996.jpg","colour":"#535825","servings":4,"tagline":"One night to save the restaurant.","cue":"Bring out the timpano when the dinner party is still waiting on Louis Prima.","menu":{"s":[{"n":"Arancini","note":"Primo's kitchen, every grain treated with respect","how":"Cook 300g arborio rice in 900ml stock with a pinch of saffron until thick and chill overnight on a tray. Wrap golf balls of rice around a cube of mozzarella and a few peas, using 100g mozzarella and 50g peas. Roll in flour, 2 beaten eggs and 100g breadcrumbs, and fry at 175C until deep gold.","shop":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","100g mozzarella@Dairy","50g frozen peas@Frozen","2 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]},{"n":"Antipasto board","note":"marinated eggplant, roast capsicum, artichokes, olives and provolone, waiting on Louis Prima","how":"Lay 100g prosciutto flat on a board. Dress 100g bresaola with lemon juice, olive oil and a handful of rocket. Add 150g marinated eggplant, 2 roasted red capsicums peeled and sliced, 150g mixed olives and a warm loaf of Italian bread.","shop":["100g prosciutto@Deli","100g bresaola@Deli","1 lemon@Produce","1 bag rocket@Produce","150g marinated eggplant@Deli","2 red capsicums@Produce","150g mixed olives@Deli","1 loaf Italian bread@Bakery"]}],"m":[{"n":"Timpano","note":"the giant baked pasta drum, sliced at the table","how":"Make dough with 300g 00 flour and 3 eggs, roll thin and line a buttered ovenproof bowl. Toss 400g cooked ziti with ragù made from 500g beef mince and 700ml passata. Layer in the bowl with 100g diced salami, 3 boiled eggs and 150g provolone. Fold the dough over, bake at 180C for 1 hour, rest 30 minutes, turn out and slice.","shop":["300g 00 flour@Pantry","6 eggs@Dairy","400g ziti or penne@Pantry","500g beef mince@Meat","700ml passata@Pantry","100g salami@Deli","150g provolone@Deli","20g butter@Dairy"]}],"w":[{"n":"Panna cotta","note":"a sweet finish after the timpano","how":"Soak 2 gelatine leaves in cold water. Heat 500ml thickened cream, 100ml milk, 80g caster sugar and a split vanilla bean until steaming. Squeeze the gelatine and whisk it in, strain, and pour into four moulds. Set 6 hours. Dip the moulds in hot water, turn out and serve with 250g berries.","shop":["2 gelatine leaves@Pantry","500ml thickened cream@Dairy","100ml full cream milk@Dairy","80g caster sugar@Pantry","1 vanilla bean@Pantry","250g berries@Produce"]}],"d":[{"n":"Primo's caffè corretto with grappa","note":"short espresso with grappa and a little sugar, almond biscuit, before the silent omelette","how":"Make 4 short espressos with 18g of finely ground coffee each, or brew 200ml very strong stovetop coffee. Pour into 4 small cups. Stir 1 tsp caster sugar into each cup, then add 20ml grappa. Serve each on a saucer with an amaretti biscuit, the way you would finish a long night in the kitchen.","shop":["72g espresso coffee beans@Pantry","4 tsp caster sugar@Pantry","80ml grappa@Bottle shop","4 amaretti biscuits@Pantry"]}],"shopping":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","100g mozzarella@Dairy","50g frozen peas@Frozen","8 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry","100g prosciutto@Deli","100g bresaola@Deli","1 lemon@Produce","1 bag rocket@Produce","150g marinated eggplant@Deli","2 red capsicums@Produce","150g mixed olives@Deli","1 loaf Italian bread@Bakery","300g 00 flour@Pantry","400g ziti or penne@Pantry","500g beef mince@Meat","700ml passata@Pantry","100g salami@Deli","150g provolone@Deli","20g butter@Dairy","2 gelatine leaves@Pantry","500ml thickened cream@Dairy","100ml full cream milk@Dairy","80g caster sugar@Pantry","1 vanilla bean@Pantry","250g berries@Produce","72g espresso coffee beans@Pantry","4 tsp caster sugar@Pantry","80ml grappa@Bottle shop","4 amaretti biscuits@Pantry"]}},"Raging Bull (1980)":{"poster":"assets/menu-posters/raging-bull-1980.jpg","colour":"#963329","servings":4,"tagline":"Fight hard. Eat harder.","cue":"Serve the steak when Jake starts complaining his steak is overcooked.","menu":{"s":[{"n":"Bronx devilled eggs with crisp pancetta","note":"halved boiled eggs filled with mustard mayo, topped with fried cured pork, paprika and chives","how":"Lower 6 eggs into boiling water, cook 10 minutes, then cool in iced water and peel. Fry 6 slices pancetta in a dry pan for 4 minutes until crisp, drain and crumble. Halve the eggs, mash the yolks with 3 tbsp mayonnaise, 1 tsp Dijon, 1 tsp white vinegar, salt and pepper. Pipe or spoon back into the whites. Top with pancetta, smoked paprika and snipped chives.","shop":["6 eggs@Dairy","6 slices pancetta@Deli","3 tbsp whole-egg mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","white vinegar@Pantry","smoked paprika@Pantry","1 bunch chives@Produce"]},{"n":"Joey's club prawns","note":"poached iced prawns with a sharp tomato, horseradish and lemon sauce, Copacabana style","how":"Poach 500g peeled green prawns in salted water for 2 minutes and chill in iced water. Mix 150ml tomato sauce with 2 tsp horseradish and the juice of 1 lemon. Serve the prawns on ice with the sauce and lemon wedges.","shop":["500g green prawns@Seafood","150ml tomato sauce@Pantry","2 tsp horseradish@Pantry","2 lemons@Produce"]}],"m":[{"n":"Jake's steak","note":"cooked properly this time, nobody gets yelled at","how":"Salt 2 porterhouse steaks, about 600g each, and leave uncovered in the fridge overnight. Sear in a smoking pan for 3 minutes a side, then add 50g butter, 3 crushed garlic cloves and a few thyme sprigs and baste until 52C inside. Rest 8 minutes and slice off the bone to share.","shop":["1.2kg porterhouse steak@Meat","50g butter@Dairy","3 garlic cloves@Produce","1 bunch thyme@Produce"]}],"w":[{"n":"Ricotta cake","note":"baked ricotta with lemon and vanilla, icing sugar, for Vickie at the pool","how":"Drain 750g fresh ricotta for 2 hours. Beat with 150g caster sugar, 4 eggs, the zest of 1 lemon and 1 tsp vanilla extract. Pour into a lined 22cm springform tin and bake at 160C for 60 minutes, then cool in the oven with the door ajar. Dust with icing sugar.","shop":["750g fresh ricotta@Dairy","150g caster sugar@Pantry","4 eggs@Dairy","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Jake's Miami club rum punch","note":"golden rum, orange, pineapple, lime and grenadine on crushed ice, for the nightclub stand-up set","how":"In a jug, stir 180ml golden rum, 240ml orange juice, 240ml pineapple juice, 60ml lime juice and 30ml grenadine. Refrigerate for 30 minutes. Fill 4 tall glasses with crushed ice, pour the punch over and finish each with an orange slice and a cocktail cherry on a pick.","shop":["180ml golden rum@Bottle shop","240ml orange juice@Drinks","240ml pineapple juice@Drinks","3 limes@Produce","30ml grenadine@Drinks","1 orange@Produce","4 cocktail cherries@Pantry","1 bag crushed ice@Frozen"]}],"shopping":["10 eggs@Dairy","6 slices pancettas@Deli","3 tbsp whole-egg mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","white vinegar@Pantry","smoked paprika@Pantry","1 bunch chives@Produce","500g green prawns@Seafood","150ml tomato sauce@Pantry","2 tsp horseradish@Pantry","3 lemons@Produce","1.2kg porterhouse steak@Meat","50g butter@Dairy","3 garlic cloves@Produce","1 bunch thyme@Produce","750g fresh ricotta@Dairy","150g caster sugar@Pantry","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry","180ml golden rum@Bottle shop","240ml orange juice@Drinks","240ml pineapple juice@Drinks","3 limes@Produce","30ml grenadine@Drinks","1 orange@Produce","4 cocktail cherries@Pantry","1 bag crushed ice@Frozen"]}},"Things to Do in Denver When You're Dead (1995)":{"poster":"assets/menu-posters/things-to-do-in-denver-when-youre-dead-1995.jpg","colour":"#22535b","servings":4,"tagline":"One last job in Denver.","cue":"Pour drinks when Jimmy gets the call from the Man with the Plan.","menu":{"s":[{"n":"Afterlife Advice devilled eggs","note":"boiled whites piped with yolk whipped with mayo, Dijon and pickle juice, paprika and chives","how":"Boil 6 eggs for 10 minutes, cool in iced water, peel and halve. Mash the yolks with 3 tbsp mayonnaise, 1 tsp Dijon, 1 tsp pickle juice, salt and pepper until smooth. Pipe back into the whites and finish with smoked paprika and chopped chives.","shop":["6 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1 tsp smoked paprika@Pantry","1 bunch chives@Produce"]},{"n":"Green chile queso","note":"Colorado green chile, with chips for dunking","how":"Melt 250g white American cheese with 125ml milk over low heat, stirring until smooth. Stir in 1 can (120g) chopped roasted green chiles, 1 crushed garlic clove and 1/2 tsp ground cumin. Simmer 2 minutes, pour into a warm bowl and serve straight away with 200g corn chips.","shop":["250g white American cheese@Dairy","125ml milk@Dairy","120g roasted green chiles@Pantry","1 garlic bulb@Produce","1 tsp ground cumin@Pantry","200g corn chips@Pantry"]}],"m":[{"n":"Patty melt","note":"thin beef patty on rye, Swiss and slow onions, griddled crisp, for planning the job","how":"Cook 2 sliced brown onions in butter over low heat for 25 minutes. Shape 600g beef mince into 4 thin oval patties and sear 2 minutes a side. Butter 8 slices rye bread on the outside, fill each sandwich with a patty, onions and 2 slices Swiss cheese, and griddle in butter until crisp and melted.","shop":["2 brown onions@Produce","60g butter@Dairy","600g beef mince@Meat","8 slices rye bread@Bakery","8 slices Swiss cheese@Deli"]}],"w":[{"n":"Mile-high sopapillas","note":"puffed pastry pillows split and drizzled with honey and cinnamon, for Jimmy's date with Dagney","how":"Mix 250g plain flour, 2 tsp baking powder, 1 tsp salt, 30g butter rubbed in and 180ml warm water into a soft dough. Rest 20 minutes, roll 3mm thick and cut into 16 squares. Fry at 180C until they puff and turn golden, about 1 minute a side. Drizzle with 120g honey and dust with cinnamon.","shop":["250g plain flour@Pantry","2 tsp baking powder@Pantry","30g butter@Dairy","1L vegetable oil@Pantry","120g honey@Pantry","1 tsp ground cinnamon@Pantry"]}],"d":[{"n":"Jimmy's crew piña coladas","note":"white rum blended with pineapple and coconut cream, toasted coconut rim, umbrella, boat drinks","how":"Toast 30g desiccated coconut in a dry pan for 2 minutes until golden, cool on a plate. Wet the rims of 4 glasses with a lime wedge and dip in the coconut. Blend 200ml white rum, 240ml pineapple juice, 160ml coconut cream, 30ml lime juice and 4 cups ice until thick and smooth. Pour into the glasses, add a pineapple wedge and a cocktail umbrella.","shop":["200ml white rum@Bottle shop","240ml pineapple juice@Drinks","160ml coconut cream@Pantry","2 limes@Produce","30g desiccated coconut@Pantry","1 small pineapple@Produce","4 cocktail umbrellas@Pantry","1 bag ice@Frozen"]}],"shopping":["6 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1 tsp smoked paprika@Pantry","1 bunch chives@Produce","250g white American cheese@Dairy","125ml milk@Dairy","120g roasted green chiles@Pantry","1 garlic bulb@Produce","1 tsp ground cumin@Pantry","200g corn chips@Pantry","2 brown onions@Produce","90g butter@Dairy","600g beef mince@Meat","8 slices rye breads@Bakery","8 slices Swiss cheeses@Deli","250g plain flour@Pantry","2 tsp baking powder@Pantry","1L vegetable oil@Pantry","120g honey@Pantry","1 tsp ground cinnamon@Pantry","200ml white rum@Bottle shop","240ml pineapple juice@Drinks","160ml coconut cream@Pantry","2 limes@Produce","30g desiccated coconut@Pantry","1 small pineapple@Produce","4 cocktail umbrellas@Pantry","1 bag ice@Frozen"]}},"Speed (1994)":{"poster":"assets/menu-posters/speed-1994.jpg","colour":"#b62923","servings":4,"tagline":"Keep it above 50.","cue":"Serve the mains when the lift rescue wraps up.","menu":{"s":[{"n":"Jack's runway nachos","note":"Corn chips baked with black beans, melted cheddar and sliced jalapeños","how":"Spread a 300g bag of corn chips on a tray. Scatter over a drained tin of black beans, 200g grated cheddar and sliced jalapeños. Bake at 200C for 8 minutes until melted. Top with sour cream and a jar of salsa.","shop":["300g corn chips@Pantry","1 tin black beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry"]},{"n":"Subway train snacks","note":"Smoky buttered pretzels and peanuts, baked and bagged for the ride","how":"Toss 200g hard pretzels and 200g roasted peanuts with 50g melted butter and 1 tsp smoked paprika. Spread on a tray and bake at 160C for 15 minutes, stirring once. Cool and tip into paper bags.","shop":["200g pretzels@Pantry","200g peanuts@Pantry","50g butter@Dairy","1 jar smoked paprika@Pantry"]}],"m":[{"n":"LA street tacos","note":"Grilled lime and orange marinated skirt steak in double corn tortillas, salsa verde","how":"Marinate 800g skirt steak in the juice of 2 limes and 1 orange, 3 garlic cloves and 1 tsp cumin for 2 hours. Grill very hot for 3 minutes a side, rest and chop. Serve in doubled corn tortillas with onion, coriander and salsa verde.","shop":["800g skirt steak@Meat","2 limes@Produce","1 orange@Produce","3 garlic cloves@Produce","1 jar ground cumin@Pantry","24 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","1 jar salsa verde@Pantry"]}],"w":[{"n":"Fifty mile an hour ice cream sandwiches","note":"Vanilla ice cream between soft chocolate chip cookies","how":"Soften 1L vanilla ice cream for 5 minutes. Sandwich a thick scoop between two soft choc chip cookies, using 8 cookies for 4 sandwiches. Roll the edges in sprinkles, wrap in baking paper and freeze for an hour.","shop":["8 choc chip cookies@Bakery","1L vanilla ice cream@Frozen","1 jar sprinkles@Pantry"]}],"d":[{"n":"Annie's coffee","note":"Overnight cold brew over ice with milk and a scoop of vanilla ice cream","how":"Steep 100g coarsely ground coffee in 1L cold water in the fridge overnight, then strain. Pour over ice in four tall glasses, about 200ml each, add a splash of milk and float a scoop of vanilla ice cream on top.","shop":["100g coffee beans@Pantry","200ml full cream milk@Dairy","500ml vanilla ice cream@Frozen"]}],"shopping":["300g corn chips@Pantry","1 tin black beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry","200g pretzels@Pantry","200g peanuts@Pantry","50g butter@Dairy","1 jar smoked paprika@Pantry","800g skirt steak@Meat","2 limes@Produce","1 orange@Produce","3 garlic cloves@Produce","1 jar ground cumin@Pantry","24 corn tortillas@Bakery","1 onion@Produce","1 bunch coriander@Produce","1 jar salsa verde@Pantry","8 choc chip cookies@Bakery","1.5L vanilla ice cream@Frozen","1 jar sprinkles@Pantry","100g coffee beans@Pantry","200ml full cream milk@Dairy"]}},"Last Action Hero (1993)":{"poster":"assets/menu-posters/last-action-hero-1993.jpg","colour":"#a33226","servings":4,"tagline":"Jack Slater. Pass the popcorn.","cue":"Serve the popcorn when Danny crashes into Jack Slater's movie.","menu":{"s":[{"n":"Magic ticket popcorn","note":"Popcorn popped in coconut oil and tossed with browned butter","how":"Cook 60g butter until golden and nutty. Heat 2 tbsp coconut oil with 3 kernels, then add 120g kernels once they pop, cover and shake until the popping slows. Toss with the brown butter and flaky salt and fill striped paper bags.","shop":["60g butter@Dairy","1 jar coconut oil@Pantry","120g popcorn kernels@Pantry","1 box sea salt flakes@Pantry"]},{"n":"Times Square knishes","note":"Puff pastry squares filled with mashed potato and fried onion","how":"Boil 4 large potatoes and mash with 1 onion fried soft in 30g butter, salt and pepper. Cut 2 sheets puff pastry into 8, put a mound of potato on each, fold up and pinch closed. Brush with 1 beaten egg and bake at 200C for 25 minutes. Serve hot with yellow mustard.","shop":["4 potatoes@Produce","1 onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","4 tbsp yellow mustard@Pantry"]}],"m":[{"n":"Slater's LA rib eye","note":"Dry-brined seared rib eye with garlic butter and baked potatoes","how":"Dry-brine 2 thick rib eyes overnight. Bake 4 potatoes at 200C for an hour. Sear the steaks, finish at 200C to 54C inside and rest. Top with 60g garlic butter, slice to share and load the potatoes with sour cream and 150g crispy bacon.","shop":["2 rib eye steaks@Meat","4 potatoes@Produce","60g butter@Dairy","2 garlic cloves@Produce","200g sour cream@Dairy","150g bacon@Meat"]}],"w":[{"n":"To cone a phrase sundae","note":"Vanilla ice cream with hot fudge sauce and whipped cream","how":"Melt 150g dark chocolate with 150ml cream and 2 tbsp golden syrup. Scoop vanilla ice cream into four bowls, pour over the hot fudge and top with whipped cream, a handful of salted peanuts and a cherry.","shop":["150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","100g peanuts@Pantry","1 jar maraschino cherries@Pantry"]}],"d":[{"n":"Danny's Pandora choc malt thickshake","note":"Thick chocolate malt shake blended with vanilla ice cream","how":"Add 500ml cold milk, 6 scoops vanilla ice cream, 2 tbsp cocoa powder and 4 tbsp malted milk powder to a blender. Blend 30 seconds until thick. Pour into 4 tall glasses. Top with whipped cream and a handful of crushed chocolate malt balls. Serve with wide straws and long spoons.","shop":["500ml full cream milk@Dairy","1 tub vanilla ice cream@Frozen","2 tbsp cocoa powder@Pantry","4 tbsp malted milk powder@Pantry","1 can whipped cream@Dairy","1 bag chocolate malt balls@Pantry"]}],"shopping":["150g butter@Dairy","1 jar coconut oil@Pantry","120g popcorn kernels@Pantry","1 box sea salt flakes@Pantry","8 potatoes@Produce","1 onion@Produce","2 sheets puff pastries@Frozen","1 egg@Dairy","4 tbsp yellow mustard@Pantry","2 rib eye steaks@Meat","2 garlic cloves@Produce","200g sour cream@Dairy","150g bacon@Meat","150g dark chocolate@Pantry","300ml thickened cream@Dairy","1 tin golden syrup@Pantry","1L vanilla ice cream@Frozen","100g peanuts@Pantry","1 jar maraschino cherries@Pantry","500ml full cream milk@Dairy","1 tub vanilla ice cream@Frozen","2 tbsp cocoa powder@Pantry","4 tbsp malted milk powder@Pantry","1 can whipped cream@Dairy","1 bag chocolate malt balls@Pantry"]}},"Airplane! (1980)":{"poster":"assets/menu-posters/airplane-1980.jpg","colour":"#315b86","servings":4,"tagline":"Fasten your seatbelts. Choose dinner carefully.","cue":"Serve the mains right after the fish course takes out the crew.","menu":{"s":[{"n":"Flight deck snack tray","note":"Cheese, crackers, grapes and onions","how":"Cut 200g cheddar into cubes. Thread cubes onto toothpicks with a green grape and a cocktail onion. Lay them out in neat rows on a tray beside a row of crackers, like an old airline snack service.","shop":["200g cheddar@Dairy","300g grapes@Produce","1 jar cocktail onions@Pantry","1 packet crackers@Pantry"]},{"n":"Airline peanuts","note":"Warm salted nuts in little packets","how":"Mix 200g dry-roasted peanuts and 100g almonds with a pinch of sugar and salt. Warm on a tray at 160C for 5 minutes. Cool slightly and divide into small paper packets, one for each passenger.","shop":["200g dry-roasted peanuts@Pantry","100g almonds@Pantry","1 box fine salt@Pantry"]}],"m":[{"n":"The steak, not the fish","note":"Seared sirloin in peppercorn cream, mashed potato and steamed green beans","how":"Sear 4 sirloins hard and rest. Crush 1 tbsp peppercorns into the pan, add 250ml cream and reduce until thick. Mash 1kg potatoes with butter and milk. Steam 300g green beans. Serve on trays, airline style.","shop":["4 sirloin steaks@Meat","1 jar black peppercorns@Pantry","250ml thickened cream@Dairy","1kg potatoes@Produce","60g butter@Dairy","100ml full cream milk@Dairy","300g green beans@Produce"]}],"w":[{"n":"Airline cheesecake","note":"Baked cheesecake with sour cream, cut into little squares","how":"Mix 250g crushed biscuits with 100g melted butter and press into a slab tin. Beat 750g cream cheese, 200g sugar, 3 eggs and 150g sour cream. Bake in a water bath at 150C for 50 minutes. Chill overnight, cut into squares and top each with a cherry.","shop":["250g digestive biscuits@Pantry","100g butter@Dairy","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","200g cherries@Produce"]}],"d":[{"n":"Wrong week to quit espresso martini","note":"Vodka, coffee liqueur and fresh espresso shaken over ice","how":"Brew 4 shots of espresso and cool for 5 minutes. Add the espresso, 160ml vodka, 80ml coffee liqueur and 20ml sugar syrup to a shaker full of ice. Shake very hard for 15 seconds to build the foam. Strain into 4 chilled coupes and float 3 coffee beans on each.","shop":["4 shots espresso coffee@Pantry","160ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop","20ml sugar syrup@Pantry","12 coffee beans@Pantry","1 bag ice@Frozen"]}],"shopping":["200g cheddar@Dairy","300g grapes@Produce","1 jar cocktail onions@Pantry","1 packet crackers@Pantry","200g dry-roasted peanuts@Pantry","100g almonds@Pantry","1 box fine salt@Pantry","4 sirloin steaks@Meat","1 jar black peppercorns@Pantry","250ml thickened cream@Dairy","1kg potatoes@Produce","160g butter@Dairy","100ml full cream milk@Dairy","300g green beans@Produce","250g digestive biscuits@Pantry","750g cream cheese@Dairy","200g caster sugar@Pantry","3 eggs@Dairy","150g sour cream@Dairy","200g cherries@Produce","4 shots espresso coffees@Pantry","160ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop","20ml sugar syrup@Pantry","12 coffee beans@Pantry","1 bag ice@Frozen"]}},"The Rock (1996)":{"poster":"assets/menu-posters/the-rock-1996.jpg","colour":"#244c56","servings":4,"tagline":"Alcatraz. Bring an appetite.","cue":"Serve the snacks when Mason gets his haircut at the hotel.","menu":{"s":[{"n":"San Francisco sourdough","note":"Warm sourdough with salted butter and oil with dukkah","how":"Warm a sourdough loaf at 200C for 8 minutes and tear into chunks. Serve with 125g soft salted butter and a shallow dish of extra virgin olive oil with 3 tbsp dukkah scattered on top for dipping.","shop":["1 sourdough loaf@Bakery","125g salted butter@Dairy","1 bottle extra virgin olive oil@Pantry","1 jar dukkah@Pantry"]},{"n":"Fisherman's Wharf prawns","note":"Prawns tossed in hot olive oil with garlic, chilli and butter","how":"Heat 3 tbsp olive oil, add 5 sliced garlic cloves and 1 sliced chilli, then 600g peeled green prawns. Toss over high heat for 2 minutes. Add 60g butter, a splash of white wine and parsley. Serve with bread for the juices.","shop":["1 bottle extra virgin olive oil@Pantry","5 garlic cloves@Produce","1 red chilli@Produce","600g green prawns@Seafood","60g butter@Dairy","100ml white wine@Bottle shop","1 bunch parsley@Produce"]}],"m":[{"n":"Mason's hotel room service","note":"Butter-basted rib eye with béarnaise and frites","how":"Reduce 60ml white wine vinegar with tarragon to 2 tbsp, whisk with 3 yolks over low heat and drizzle in 200g warm clarified butter. Fry 1kg potato chips twice. Sear 4 rib eyes, baste with 40g butter, thyme and garlic, rest and serve.","shop":["60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","3 eggs@Dairy","240g butter@Dairy","1kg potatoes@Produce","4 rib eye steaks@Meat","1 bunch thyme@Produce","2 garlic cloves@Produce","2L vegetable oil@Pantry"]}],"w":[{"n":"San Francisco chocolate squares","note":"Dense baked brownie squares with toasted walnuts","how":"Melt 200g dark chocolate with 150g butter. Whisk in 250g sugar and 3 eggs, then fold in 100g flour and 100g toasted walnuts. Bake in a lined tin at 175C for 25 minutes. Sprinkle with flaky salt, cool and cut into squares.","shop":["200g dark chocolate@Pantry","150g butter@Dairy","250g caster sugar@Pantry","3 eggs@Dairy","100g plain flour@Pantry","100g walnuts@Pantry","1 box sea salt flakes@Pantry"]}],"d":[{"n":"Mason's single malt Rob Roy","note":"Single malt Scotch stirred with sweet vermouth and bitters","how":"Chill 4 coupes. Fill a jug with ice, add 200ml single malt Scotch, 80ml sweet vermouth and 8 dashes aromatic bitters and stir for 30 seconds until icy. Strain into the coupes. Drop in a cocktail cherry and twist a strip of orange peel over each glass.","shop":["200ml single malt Scotch@Bottle shop","80ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["1 sourdough loaf@Bakery","125g salted butter@Dairy","2 bottles extra virgin olive oil@Pantry","1 jar dukkah@Pantry","7 garlic cloves@Produce","1 red chilli@Produce","600g green prawns@Seafood","450g butter@Dairy","100ml white wine@Bottle shop","1 bunch parsley@Produce","60ml white wine vinegar@Pantry","1 bunch tarragon@Produce","6 eggs@Dairy","1kg potatoes@Produce","4 rib eye steaks@Meat","1 bunch thyme@Produce","2L vegetable oil@Pantry","200g dark chocolate@Pantry","250g caster sugar@Pantry","100g plain flour@Pantry","100g walnuts@Pantry","1 box sea salt flakes@Pantry","200ml single malt Scotch@Bottle shop","80ml sweet vermouth@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 jar cocktail cherries@Pantry","1 orange@Produce","1 bag ice@Frozen"]}},"Face/Off (1997)":{"poster":"assets/menu-posters/face-off-1997.jpg","colour":"#ad552c","servings":4,"tagline":"Two faces. One dinner.","cue":"Serve the mains when the prison boots go on.","menu":{"s":[{"n":"Church shootout canapés","note":"Smoked salmon and crème fraîche on rye, doves optional","how":"Butter 6 slices rye bread and cut into small squares. Top each with a fold of smoked salmon, using 200g in total, a small spoon of crème fraîche, a dill sprig and a crack of black pepper. Serve cold on a tray.","shop":["6 slices rye bread@Bakery","30g butter@Dairy","200g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce"]},{"n":"Castor's peach slices","note":"Honey lime peach wedges. Castor eats them for hours.","how":"Cut 4 ripe peaches into wedges and arrange on a plate. Warm 2 tbsp honey with the juice of a lime and drizzle over. Scatter with torn mint and a small pinch of flaky salt. Serve straight away.","shop":["4 peaches@Produce","1 jar honey@Pantry","1 lime@Produce","1 bunch mint@Produce","1 box sea salt flakes@Pantry"]}],"m":[{"n":"Castor's lavish dinner","note":"lobster and champagne, he takes over the life","how":"Split 4 lobster tails lengthways. Brush with 80g butter melted with 2 garlic cloves and chopped parsley. Grill flesh side up for 6 to 8 minutes until just white. Toss salad leaves with a lemon and olive oil vinaigrette and serve alongside.","shop":["4 lobster tails@Seafood","80g butter@Dairy","2 garlic cloves@Produce","1 bunch parsley@Produce","2 lemons@Produce","150g salad leaves@Produce","1 bottle extra virgin olive oil@Pantry"]}],"w":[{"n":"Peach cobbler","note":"Baked cinnamon peaches under a buttermilk biscuit topping","how":"Toss 6 sliced peaches with 80g sugar, lemon juice and 1 tsp cinnamon in a baking dish. Rub 80g butter into 200g self-raising flour, stir in 150ml buttermilk and drop spoonfuls over the fruit. Bake at 190C for 35 minutes.","shop":["6 peaches@Produce","80g caster sugar@Pantry","1 lemon@Produce","1 jar cinnamon@Pantry","80g butter@Dairy","200g self-raising flour@Pantry","150ml buttermilk@Dairy"]}],"d":[{"n":"Peach Bellini","note":"Fresh peach purée topped with chilled prosecco","how":"Blend 3 ripe peaches with 1 tbsp sugar and a squeeze of lemon until smooth and strain. Put 50ml purée in each of 4 flutes and top slowly with chilled prosecco, stirring once.","shop":["3 peaches@Produce","1 tbsp caster sugar@Pantry","1 lemon@Produce","750ml prosecco@Bottle shop"]}],"shopping":["6 slices rye breads@Bakery","190g butter@Dairy","200g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","13 peaches@Produce","1 jar honey@Pantry","1 lime@Produce","1 bunch mint@Produce","1 box sea salt flakes@Pantry","4 lobster tails@Seafood","2 garlic cloves@Produce","1 bunch parsley@Produce","4 lemons@Produce","150g salad leaves@Produce","1 bottle extra virgin olive oil@Pantry","80g caster sugar@Pantry","1 jar cinnamon@Pantry","200g self-raising flour@Pantry","150ml buttermilk@Dairy","1 tbsp caster sugar@Pantry","750ml prosecco@Bottle shop"]}},"Cliffhanger (1993)":{"poster":"assets/menu-posters/cliffhanger-1993.jpg","colour":"#2c5571","servings":4,"tagline":"Hang on to your dinner.","cue":"Serve the mains when the money cases fall from the plane.","menu":{"s":[{"n":"Rocky Mountain smoked trout pâté","note":"Smoked trout and cream cheese spread on rye crackers with pickled red onion","how":"Flake 250g hot-smoked trout, removing any skin and bones. Blitz half with 200g cream cheese, the juice of half a lemon, 2 tsp horseradish and pepper, then fold in the rest of the trout with chopped dill so it stays chunky. Slice half a red onion thin and soak in 3 tbsp white wine vinegar with a pinch of sugar for 20 minutes. Spread thick on rye crackers and top with the pickled onion.","shop":["250g hot-smoked trout@Seafood","200g cream cheese@Dairy","1 lemon@Produce","1 jar horseradish@Pantry","1 bunch dill@Produce","1 red onion@Produce","3 tbsp white wine vinegar@Pantry","200g rye crackers@Pantry"]},{"n":"Ranger hut roast pumpkin soup","note":"Roasted pumpkin soup finished with cream and toasted pepitas","how":"Heat the oven to 200C. Toss 1kg diced pumpkin with oil and salt and roast 30 minutes until caramelised. Soften 1 diced onion and 2 garlic cloves in butter for 5 minutes, add the pumpkin and 750ml chicken stock and simmer 10 minutes. Blitz until smooth and stir in 100ml cream. Toast 40g pepitas in a dry pan for 3 minutes. Pour the soup into a warmed thermos and scatter pepitas on each mug.","shop":["1kg pumpkin@Produce","1 brown onion@Produce","2 garlic cloves@Produce","750ml chicken stock@Pantry","100ml thickened cream@Dairy","20g butter@Dairy","40g pepitas@Pantry"]}],"m":[{"n":"Gabe's ranger hut rump steak with foil-baked potatoes","note":"Rosemary rump steaks grilled over coals, potatoes baked in foil","how":"Wrap 4 potatoes with a knob of butter each in foil and bake in the coals for 45 minutes. Rub 4 rump steaks with salt, pepper and chopped rosemary. Grill over hot coals for 4 minutes a side and rest on a board.","shop":["4 potatoes@Produce","60g butter@Dairy","4 rump steaks@Meat","1 bunch rosemary@Produce"]}],"w":[{"n":"Treasury cash apple strudel","note":"Cinnamon apple and raisin filo strudel, served with cream","how":"Toss 4 sliced green apples with 60g sugar, 1 tsp cinnamon, 50g raisins and 40g breadcrumbs fried in 20g butter. Layer 8 sheets filo, brushing each with 60g melted butter, pile the apple along one edge and roll up. Bake at 190C for 35 minutes, dust with icing sugar and serve with 200ml cream.","shop":["4 green apples@Produce","60g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","50g raisins@Pantry","40g breadcrumbs@Pantry","80g butter@Dairy","8 sheets filo pastry@Frozen","200ml thickened cream@Dairy"]}],"d":[{"n":"Gabe Walker's hot buttered rum","note":"Dark rum with spiced brown sugar butter and boiling water","how":"Beat 80g soft butter with 80g brown sugar, 1 tsp cinnamon and a pinch of nutmeg and cloves. Put a heaped tablespoon in each of 4 mugs with 45ml dark rum and top with 150ml boiling water. Stir until melted.","shop":["80g butter@Dairy","80g brown sugar@Pantry","1 tsp ground cinnamon@Pantry","1 tsp ground nutmeg@Pantry","180ml dark rum@Bottle shop"]}],"shopping":["250g hot-smoked trout@Seafood","200g cream cheese@Dairy","1 lemon@Produce","1 jar horseradish@Pantry","1 bunch dill@Produce","1 red onion@Produce","3 tbsp white wine vinegar@Pantry","200g rye crackers@Pantry","1kg pumpkin@Produce","1 brown onion@Produce","2 garlic cloves@Produce","750ml chicken stock@Pantry","300ml thickened cream@Dairy","240g butter@Dairy","40g pepitas@Pantry","4 potatoes@Produce","4 rump steaks@Meat","1 bunch rosemary@Produce","4 green apples@Produce","60g caster sugar@Pantry","2 tsp ground cinnamon@Pantry","50g raisins@Pantry","40g breadcrumbs@Pantry","8 sheets filo pastries@Frozen","80g brown sugar@Pantry","1 tsp ground nutmeg@Pantry","180ml dark rum@Bottle shop"]}},"Back to the Future Part II (1989)":{"poster":"assets/menu-posters/back-to-the-future-part-ii-1989.jpg","colour":"#385c8b","servings":4,"tagline":"Hoverboards and hydrated pizza.","cue":"Serve the mains when Lorraine puts the tiny pizza in the hydrator.","menu":{"s":[{"n":"Cafe 80's fries","note":"Spiralized potatoes fried crisp, tossed with smoked paprika salt","how":"Spiralise 4 large potatoes and soak in cold water for 30 minutes. Dry very well on tea towels. Fry at 180C in batches until crisp and golden. Toss with fine salt mixed with 1 tsp smoked paprika and serve hot.","shop":["4 potatoes@Produce","2L vegetable oil@Pantry","1 box fine salt@Pantry","1 jar smoked paprika@Pantry"]},{"n":"Hoverboard tortilla chips","note":"Pink beetroot dusted tortilla chips with fresh guacamole","how":"Cut 6 flour tortillas into hoverboard shapes. Fry at 180C until crisp and toss with salt and 1 tsp beetroot powder for a pink colour. Mash 3 avocados with the juice of a lime and salt for guacamole.","shop":["6 flour tortillas@Bakery","1L vegetable oil@Pantry","1 jar beetroot powder@Pantry","3 avocados@Produce","1 lime@Produce"]}],"m":[{"n":"Hydrated pizza","note":"Thin crust pizza with crushed tomato, mozzarella and pepperoni","how":"Bake 4 mini pizza bases with sauce and cheese for the reveal. Then stretch 500g dough thin, spread with 200g crushed tomatoes, add 250g low-moisture mozzarella and 100g pepperoni, and bake on a hot steel at max heat for 7 minutes.","shop":["4 mini pizza bases@Bakery","500g pizza dough@Bakery","200g crushed tomatoes@Pantry","300g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Jaws 19 shark jelly","note":"Blue jelly with gummy sharks, topped with whipped cream waves","how":"Make 2 packets blue jelly crystals with 500ml boiling and 500ml cold water. Pour halfway into four glasses and chill until just starting to set. Push in gummy sharks, add the rest of the jelly and set. Top with whipped cream waves.","shop":["2 packets blue jelly crystals@Pantry","1 bag gummy sharks@Pantry","200ml thickened cream@Dairy"]}],"d":[{"n":"Cafe 80's milkshake","note":"Strawberry ice cream, fresh strawberries and milk blended thick","how":"For each shake, blend 3 scoops strawberry ice cream with 4 strawberries and 150ml cold milk until thick. Pour into a tall chilled glass with a straw. Make four one after the other so they stay thick.","shop":["1.5L strawberry ice cream@Frozen","250g strawberries@Produce","600ml full cream milk@Dairy"]}],"shopping":["4 potatoes@Produce","3L vegetable oil@Pantry","1 box fine salt@Pantry","1 jar smoked paprika@Pantry","6 flour tortillas@Bakery","1 jar beetroot powder@Pantry","3 avocados@Produce","1 lime@Produce","4 mini pizza bases@Bakery","500g pizza dough@Bakery","200g crushed tomatoes@Pantry","300g low-moisture mozzarella@Dairy","100g pepperoni@Deli","2 packets blue jelly crystals@Pantry","1 bag gummy sharks@Pantry","200ml thickened cream@Dairy","1.5L strawberry ice cream@Frozen","250g strawberries@Produce","600ml full cream milk@Dairy"]}},"I Am Legend (2007)":{"poster":"assets/menu-posters/i-am-legend-2007.jpg","colour":"#596346","servings":4,"tagline":"Last man in New York. Last tin of peaches.","cue":"Serve the snacks when Robert and Sam go hunting deer in Times Square.","menu":{"s":[{"n":"Central Park corn chips","note":"Fried corn tortilla chips with charred corn, tomato and lime salsa","how":"Cut 12 corn tortillas into wedges and fry at 180C until crisp, then salt. Char 2 corn cobs and cut off the kernels. Mix with 3 diced tomatoes, chopped coriander and the juice of 2 limes. Serve the salsa in a bowl with the chips.","shop":["12 corn tortillas@Bakery","1L vegetable oil@Pantry","2 corn cobs@Produce","3 tomatoes@Produce","1 bunch coriander@Produce","2 limes@Produce"]},{"n":"Pantry stash grilled peaches and honey","note":"Grilled canned peaches with honey yoghurt and toasted almonds","how":"Drain 2 tins peach halves (800g) and pat dry. Heat a griddle pan over high heat, brush with a little butter and grill the peaches cut side down for 4 minutes until charred and caramelised. Mix 200g Greek yoghurt with 2 tbsp honey. Toast 40g flaked almonds in a dry pan for 2 minutes. Serve the warm peaches with the yoghurt, almonds and a dusting of cinnamon.","shop":["2 tins peach halves (800g)@Pantry","15g butter@Dairy","200g Greek yoghurt@Dairy","2 tbsp honey@Pantry","40g flaked almonds@Pantry","ground cinnamon@Pantry"]}],"m":[{"n":"Pan-fried steak","note":"Garlic butter sirloin. Keep a plain piece for Sam.","how":"Season 4 sirloins well and sear in a hot pan for 3 minutes a side. Add 50g butter, 2 crushed garlic cloves and thyme and baste for a minute. Rest 5 minutes and slice. Keep a plain unseasoned piece aside for the dog.","shop":["4 sirloin steaks@Meat","50g butter@Dairy","2 garlic cloves@Produce","1 bunch thyme@Produce"]}],"w":[{"n":"Neville's Shrek night rice pudding","note":"Slow baked creamy rice pudding with nutmeg and raspberry jam","how":"Heat the oven to 150C. Butter a 1.5 litre baking dish. Stir 100g short grain rice, 60g caster sugar and 1 litre full cream milk together in the dish and add a long strip of lemon peel. Grate nutmeg over the top and dot with 20g butter. Bake 2 to 2.5 hours, stirring once after 30 minutes, until thick and creamy with a golden skin. Rest 10 minutes and serve warm with a spoon of raspberry jam.","shop":["100g short grain rice@Pantry","60g caster sugar@Pantry","1 litre full cream milk@Dairy","1 lemon@Produce","1 whole nutmeg@Pantry","30g butter@Dairy","1 jar raspberry jam@Pantry"]}],"d":[{"n":"Light up the darkness bourbon peach smash","note":"Bourbon shaken with canned peach, lemon and mint, over crushed ice","how":"Drain a 410g tin of sliced peaches, keeping 60ml of the syrup. Muddle half the peach slices with the syrup, the juice of 1 lemon and 10 mint leaves in a shaker. Add 200ml bourbon and ice and shake 15 seconds. Strain into 4 tumblers packed with crushed ice. Garnish each with a peach slice and a mint sprig.","shop":["1 tin sliced peaches (410g)@Pantry","1 lemon@Produce","1 bunch mint@Produce","200ml bourbon@Bottle shop","1 bag crushed ice@Frozen"]}],"shopping":["12 corn tortillas@Bakery","1L vegetable oil@Pantry","2 corn cobs@Produce","3 tomatoes@Produce","1 bunch coriander@Produce","2 limes@Produce","2 tins peach halves (800g)@Pantry","95g butter@Dairy","200g Greek yoghurt@Dairy","2 tbsp honey@Pantry","40g flaked almonds@Pantry","ground cinnamon@Pantry","4 sirloin steaks@Meat","2 garlic cloves@Produce","1 bunch thyme@Produce","100g short grain rice@Pantry","60g caster sugar@Pantry","1 litre full cream milk@Dairy","2 lemons@Produce","1 whole nutmeg@Pantry","1 jar raspberry jam@Pantry","1 tin sliced peaches (410g)@Pantry","1 bunch mint@Produce","200ml bourbon@Bottle shop","1 bag crushed ice@Frozen"]}},"The Terminator (1984)":{"poster":"assets/menu-posters/the-terminator-1984.jpg","colour":"#273b62","servings":4,"tagline":"Tech Noir by night. Big Jeff's by day.","cue":"Serve the mains when the Terminator tells the desk sergeant he'll be back.","menu":{"s":[{"n":"Big Jeff's fries","note":"Thin fries fried twice, served with tomato sauce","how":"Cut 1kg russets into thin fries and soak for 30 minutes, then dry well. Fry at 140C for 5 minutes, rest, then at 190C until golden. Salt straight away and serve with tomato sauce in a squeeze bottle.","shop":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 bottle tomato sauce@Pantry"]},{"n":"Tech Noir bar nachos","note":"Corn chips with refried beans, cheddar and jalapeños, sour cream and salsa","how":"Spread a 300g bag of corn chips on a tray and dot with a tin of refried beans. Scatter with 200g grated cheddar and sliced jalapeños. Bake at 200C for 8 minutes and top with sour cream and a jar of salsa.","shop":["300g corn chips@Pantry","1 tin refried beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry"]}],"m":[{"n":"Big Jeff's burger","note":"Thick chuck cheeseburger with iceberg, tomato, onion and pickles","how":"Shape 800g chuck mince into 4 thick patties, season just before cooking and griddle to medium. Melt cheddar on top under a lid. Build on toasted buns with shredded iceberg, sliced tomato, onion and pickles.","shop":["800g beef chuck mince@Meat","4 slices cheddar@Dairy","0.5 iceberg lettuce@Produce","2 tomatoes@Produce","1 onion@Produce","1 jar dill pickles@Pantry","4 burger buns@Bakery"]}],"w":[{"n":"Big Jeff's cherry pie","note":"Lattice topped cherry pie with a sweet shortcrust base","how":"Toss 800g pitted cherries, fresh or frozen, with 150g sugar, the juice of a lemon and 3 tbsp cornflour. Line a pie dish with 2 sheets sweet shortcrust, fill and weave a lattice from 2 more. Bake at 190C for 50 minutes.","shop":["800g cherries@Frozen","150g caster sugar@Pantry","1 box cornflour@Pantry","1 lemon@Produce","4 sheets sweet shortcrust pastry@Frozen"]}],"d":[{"n":"Tech Noir dark rum Cuba libre","note":"Dark rum, lime and cola over ice with a dash of bitters","how":"Cut 2 limes into quarters. Fill 4 highball glasses with ice and squeeze 2 lime quarters into each, dropping the shells in. Add 45ml dark rum to each glass and a dash of aromatic bitters. Top each with 150ml cold cola and stir once.","shop":["180ml dark rum@Bottle shop","2 limes@Produce","600ml cola@Drinks","1 bottle aromatic bitters@Bottle shop","1 bag ice@Frozen"]}],"shopping":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 bottle tomato sauce@Pantry","300g corn chips@Pantry","1 tin refried beans@Pantry","200g cheddar@Dairy","1 jar jalapeños@Pantry","200g sour cream@Dairy","1 jar salsa@Pantry","800g beef chuck mince@Meat","4 slices cheddars@Dairy","0.5 iceberg lettuce@Produce","2 tomatoes@Produce","1 onion@Produce","1 jar dill pickles@Pantry","4 burger buns@Bakery","800g cherries@Frozen","150g caster sugar@Pantry","1 box cornflour@Pantry","1 lemon@Produce","4 sheets sweet shortcrust pastry@Frozen","180ml dark rum@Bottle shop","2 limes@Produce","600ml cola@Drinks","1 bottle aromatic bitters@Bottle shop","1 bag ice@Frozen"]}},"RoboCop (1987)":{"poster":"assets/menu-posters/robocop-1987.jpg","colour":"#304d66","servings":4,"tagline":"Old Detroit. New cop. Cheap snacks.","cue":"Serve the snacks every time the news breaks for an ad.","menu":{"s":[{"n":"6000 SUX popcorn","note":"Popcorn with melted butter, cheddar powder and smoked paprika","how":"Pop 120g kernels in 2 tbsp oil. Toss with 50g melted butter, then 4 tbsp cheddar cheese powder, 1 tsp smoked paprika and a pinch of salt until every piece is orange. Serve in a big bowl.","shop":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","50g butter@Dairy","1 jar cheddar cheese powder@Pantry","1 jar smoked paprika@Pantry"]},{"n":"OCP boardroom canapés","note":"Smoked salmon and dill on rye, plus cucumber cups filled with whipped feta","how":"Butter 4 slices rye bread, cut into squares and top with 150g smoked salmon, crème fraîche and dill. Cut 2 cucumbers into thick rounds, scoop a little hollow and fill with 150g feta whipped with a splash of olive oil.","shop":["4 slices rye bread@Bakery","20g butter@Dairy","150g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","2 Lebanese cucumbers@Produce","150g feta@Deli"]}],"m":[{"n":"Detroit coney dog","note":"Frank in a steamed bun with beef chilli, mustard and diced white onion","how":"Brown 300g beef mince with half a diced onion, 2 tsp chilli powder and 1 tsp cumin. Add 200ml water and simmer 20 minutes until loose. Griddle 8 franks, put in steamed buns and top with chilli, mustard and diced white onion.","shop":["300g beef mince@Meat","2 onions@Produce","1 jar chilli powder@Pantry","1 jar ground cumin@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry"]}],"w":[{"n":"Nukem cupcakes","note":"Chocolate cupcakes topped with tall piped meringue, toasted with a torch","how":"Beat 125g butter and 150g sugar, add 2 eggs, then fold in 175g self-raising flour, 30g cocoa and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Whisk 3 whites and 150g sugar over hot water, beat to stiff peaks, pipe tall and torch.","shop":["125g butter@Dairy","300g caster sugar@Pantry","5 eggs@Dairy","175g self-raising flour@Pantry","30g cocoa@Pantry","125ml full cream milk@Dairy"]}],"d":[{"n":"Antonowsky's gas station boilermaker","note":"Rye whiskey shot with bitters and lemon peel, chased with cold lager","how":"Chill 4 cans or bottles of lager until icy and 4 shot glasses in the freezer. Pour 30ml rye whiskey into each shot glass with a dash of aromatic bitters and a small twist of lemon peel. Serve each shot alongside a cold lager poured into a chilled glass. Sip and chase.","shop":["4 lagers (375ml)@Bottle shop","120ml rye whiskey@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 lemon@Produce"]}],"shopping":["120g popcorn kernels@Pantry","1 bottle vegetable oil@Pantry","195g butter@Dairy","1 jar cheddar cheese powder@Pantry","1 jar smoked paprika@Pantry","4 slices rye breads@Bakery","150g smoked salmon@Seafood","100ml crème fraîche@Dairy","1 bunch dill@Produce","2 Lebanese cucumbers@Produce","150g feta@Deli","300g beef mince@Meat","2 onions@Produce","1 jar chilli powder@Pantry","1 jar ground cumin@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","1 bottle yellow mustard@Pantry","300g caster sugar@Pantry","5 eggs@Dairy","175g self-raising flour@Pantry","30g cocoa@Pantry","125ml full cream milk@Dairy","4 lagers (375ml)@Bottle shop","120ml rye whiskey@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 lemon@Produce"]}},"Three Men and a Baby (1987)":{"poster":"assets/menu-posters/three-men-and-a-baby-1987.jpg","colour":"#263e61","servings":4,"tagline":"Three bachelors. One baby. Zero clue.","cue":"Serve dessert when the guys sing the baby to sleep.","menu":{"s":[{"n":"Doorstep basket prawn toast","note":"minced prawn and ginger on sesame bread, fried, sweet chilli, for the surprise at the door","how":"Blitz 300g peeled green prawns with 1 egg white, 1 tsp ginger, 1 spring onion and a pinch of salt. Spread on 6 slices of white bread, press in 4 tbsp sesame seeds, cut into triangles and fry at 180C until golden. Serve with sweet chilli sauce.","shop":["300g green prawns@Seafood","1 egg@Dairy","1 knob ginger@Produce","1 spring onion@Produce","6 slices white bread@Bakery","4 tbsp sesame seeds@Pantry","1 bottle sweet chilli sauce@Pantry","1L vegetable oil@Pantry"]},{"n":"Bagel chips and schmear","note":"thin day-old slices baked crisp, cream cheese whipped with chives, for the morning nappy change","how":"Slice 3 day-old bagels into thin rounds, brush with 2 tbsp olive oil and bake at 180C for 12 minutes until crisp. Beat 250g cream cheese with 2 tbsp chopped chives and the zest of 1 lemon. Serve the chips around the schmear.","shop":["3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce"]}],"m":[{"n":"Peter's loft steak sandwich","note":"sliced sirloin, caramelised onions, Swiss and horseradish mayo on sourdough, for Peter the architect","how":"Cook 2 sliced brown onions in butter over low heat for 30 minutes. Sear 600g sirloin steak hard for 3 minutes a side, rest and slice thin. Mix 80g mayonnaise with 1 tbsp horseradish. Toast 8 slices sourdough, spread with the mayo, pile on steak and onions, lay 4 slices Swiss cheese on top and grill until melted.","shop":["2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","80g mayonnaise@Pantry","1 tbsp horseradish@Pantry","8 slices sourdough@Bakery","4 slices Swiss cheese@Deli"]}],"w":[{"n":"Baby Mary's bedtime vanilla custard","note":"smooth, no lumps, the way Peter and Michael learn to feed her","how":"Heat 500ml milk with a split vanilla bean until steaming. Whisk 4 egg yolks with 60g caster sugar and 2 tbsp cornflour, pour on the hot milk, then return to the pan and stir over low heat until thick. Serve warm, or chill with plastic pressed on the surface.","shop":["500ml full cream milk@Dairy","1 vanilla bean@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","2 tbsp cornflour@Pantry"]}],"d":[{"n":"Night-feed bourbon milk punch","note":"whiskey shaken with full cream milk and vanilla, nutmeg, test it on your wrist","how":"Shake 160ml bourbon, 400ml cold full cream milk, 40ml sugar syrup and half a tsp vanilla extract with ice for 15 seconds until frothy. Strain into 4 ice-filled glasses and grate nutmeg over the top. For a no-booze version, leave out the bourbon and add a spoon of honey.","shop":["160ml bourbon@Bottle shop","400ml full cream milk@Dairy","40ml sugar syrup@Pantry","vanilla extract@Pantry","whole nutmeg@Pantry","1 bag ice@Frozen"]}],"shopping":["300g green prawns@Seafood","5 eggs@Dairy","1 knob ginger@Produce","1 spring onion@Produce","6 slices white breads@Bakery","4 tbsp sesame seeds@Pantry","1 bottle sweet chilli sauce@Pantry","1L vegetable oil@Pantry","3 bagels@Bakery","2 tbsp olive oil@Pantry","250g cream cheese@Dairy","1 bunch chives@Produce","1 lemon@Produce","2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","80g mayonnaise@Pantry","1 tbsp horseradish@Pantry","8 slices sourdoughs@Bakery","4 slices Swiss cheeses@Deli","900ml full cream milk@Dairy","1 vanilla bean@Pantry","60g caster sugar@Pantry","2 tbsp cornflour@Pantry","160ml bourbon@Bottle shop","40ml sugar syrup@Pantry","vanilla extract@Pantry","whole nutmeg@Pantry","1 bag ice@Frozen"]}},"Trading Places (1983)":{"poster":"assets/menu-posters/trading-places-1983.jpg","colour":"#214d36","servings":4,"tagline":"One dollar bet. One very big swap.","cue":"Serve the mains when the Dukes make their one dollar bet.","menu":{"s":[{"n":"Duke & Duke club canapés","note":"almond-stuffed prunes wrapped in streaky bacon and baked crisp, for the Dukes' one-dollar bet","how":"Push an almond into each of 20 pitted prunes. Wrap each in half a rasher of streaky bacon, using 10 rashers, and secure with a toothpick. Bake at 200C for 15 minutes until the bacon is crisp. Serve warm.","shop":["20 pitted prunes@Pantry","20 almonds@Pantry","10 rashers streaky bacon@Meat"]},{"n":"Heritage Club Caesar","note":"cos in a coddled egg, anchovy and lemon dressing, croutons and parmesan, before Louis is framed","how":"Tear 200g sourdough into small pieces and fry in 40g butter, tossing, until golden and crisp. Lower 1 egg into simmering water for 1 minute, then cool it under the tap. Mash 2 garlic cloves and 6 anchovy fillets to a paste in a big bowl. Crack in the coddled egg, add the juice of 1 lemon, 1 tsp Worcestershire sauce and 1 tsp Dijon mustard, then whisk in 80ml olive oil slowly until thick. Add the leaves of 2 cos lettuces and toss at the table until every leaf is coated. Shave 60g parmesan over, scatter the croutons and serve straight away.","shop":["2 cos lettuces@Produce","200g sourdough loaf@Bakery","40g butter@Dairy","1 egg@Dairy","2 garlic cloves@Produce","6 anchovy fillets@Pantry","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp Dijon mustard@Pantry","80ml olive oil@Pantry","60g parmesan@Dairy"]}],"m":[{"n":"Santa Winthorpe's pocket roast beef","note":"standing rib roasted low, jus and horseradish, for New Year's Eve on the train","how":"Salt a 2kg standing rib roast the day before and leave uncovered in the fridge. Roast at 120C until 52C inside, about 2.5 hours, rest 30 minutes, then blast at 260C for 8 minutes for a crust. Simmer the pan juices with 300ml beef stock for jus. Serve with 150g horseradish cream and 1kg roast potatoes.","shop":["2kg standing rib roast@Meat","300ml beef stock@Pantry","150g horseradish cream@Pantry","1kg potatoes@Produce"]}],"w":[{"n":"Orange cake","note":"frozen concentrate glaze","how":"Beat 200g butter, 200g caster sugar and the zest of 2 oranges, add 3 eggs and fold in 250g self-raising flour with 100ml orange juice. Bake in a lined tin at 170C for 45 minutes. Boil 100ml orange juice concentrate with 50g sugar for 3 minutes and brush over the warm cake.","shop":["200g butter@Dairy","250g caster sugar@Pantry","2 oranges@Produce","3 eggs@Dairy","250g self-raising flour@Pantry","100ml orange juice@Drinks","100ml orange juice concentrate@Frozen"]}],"d":[{"n":"Mimosa","note":"fresh orange juice, the real winner","how":"Squeeze 4 oranges, about 300ml juice, and chill well. Fill four flutes halfway with the juice and gently top with chilled sparkling wine, about 300ml in total, pouring slowly so it does not foam over.","shop":["4 oranges@Produce","750ml sparkling wine@Bottle shop"]}],"shopping":["20 pitted prunes@Pantry","20 almonds@Pantry","10 rashers streaky bacon@Meat","100ml orange juice@Drinks","2 cos lettuces@Produce","200g sourdough loaf@Bakery","2 garlic cloves@Produce","6 anchovy fillets@Pantry","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp Dijon mustard@Pantry","80ml olive oil@Pantry","60g parmesan@Dairy","2kg standing rib roast@Meat","300ml beef stock@Pantry","150g horseradish cream@Pantry","1kg potatoes@Produce","240g butter@Dairy","250g caster sugar@Pantry","6 oranges@Produce","4 eggs@Dairy","250g self-raising flour@Pantry","100ml orange juice concentrate@Frozen","750ml sparkling wine@Bottle shop"]}},"Tootsie (1982)":{"poster":"assets/menu-posters/tootsie-1982.jpg","colour":"#982b36","servings":4,"tagline":"He's not a she. But she can cook.","cue":"Serve the mains when Dorothy demands the script be changed.","menu":{"s":[{"n":"Southwest General green room sandwiches","note":"egg and cress, ham and mustard, cucumber and cream cheese, crusts off, between soap takes","how":"Boil 4 eggs for 10 minutes, cool, mash with 2 tbsp mayo and a handful of cress. Spread 150g cream cheese on bread and layer with thin cucumber. Use 12 slices soft white bread in total, cut off the crusts and cut into triangles.","shop":["4 eggs@Dairy","1 jar mayonnaise@Pantry","1 punnet cress@Produce","150g cream cheese@Dairy","1 Lebanese cucumber@Produce","12 slices white bread@Bakery"]},{"n":"Sandy's audition capsicum and feta dip","note":"smoky capsicum blitzed with salty cheese and yoghurt, crackers, for the part that goes to Dorothy","how":"Char 2 red capsicums under a hot grill for 15 minutes, cover for 10 minutes, then peel and seed. Blitz with 150g feta, 100g Greek yoghurt, 1 garlic clove, half a tsp chilli flakes and 2 tbsp olive oil until smooth. Spoon into a bowl, drizzle with oil and serve with 200g seeded crackers.","shop":["2 red capsicums@Produce","150g feta@Dairy","100g Greek yoghurt@Dairy","1 garlic clove@Produce","chilli flakes@Pantry","olive oil@Pantry","200g seeded crackers@Pantry"]}],"m":[{"n":"Les's farm roast chicken","note":"dry-brined bird with lemon butter under the skin, roasted golden, potatoes cooked in the fat","how":"Dry-brine a 1.8kg chicken overnight. Push 50g butter mixed with lemon zest and thyme under the skin. Roast at 220C for 20 minutes then 180C for 50 minutes, with 1kg halved potatoes in the tray. Rest 15 minutes before carving.","shop":["1.8kg whole chicken@Meat","50g butter@Dairy","2 lemons@Produce","1 bunch thyme@Produce","1kg potatoes@Produce"]}],"w":[{"n":"Strawberry shortcake","note":"Les's farm on a weekend off","how":"Mix 300g self-raising flour with 200ml cream and 2 tbsp sugar to a soft dough. Pat out, cut 4 rounds and bake at 220C for 12 minutes. Toss 500g sliced strawberries with 2 tbsp sugar. Whip 200ml cream softly, split the scones and fill.","shop":["300g self-raising flour@Pantry","400ml thickened cream@Dairy","50g caster sugar@Pantry","500g strawberries@Produce"]}],"d":[{"n":"Dorothy Michaels' Russian caravan tea","note":"strong smoky black brew served in glasses with lemon slices and a spoon of cherry jam","how":"Brew 4 tsp loose black tea in 1L just-boiled water for 4 minutes, strain into 4 glasses. Serve with lemon slices and a small dish of cherry jam on the side for stirring in, the Russian Tea Room way.","shop":["4 tsp black tea@Pantry","1 lemon@Produce","100g cherry jam@Pantry"]}],"shopping":["4 eggs@Dairy","1 jar mayonnaise@Pantry","1 punnet cress@Produce","150g cream cheese@Dairy","1 Lebanese cucumber@Produce","12 slices white breads@Bakery","2 red capsicums@Produce","150g feta@Dairy","100g Greek yoghurt@Dairy","1 garlic clove@Produce","chilli flakes@Pantry","olive oil@Pantry","200g seeded crackers@Pantry","1.8kg whole chicken@Meat","50g butter@Dairy","3 lemons@Produce","1 bunch thyme@Produce","1kg potatoes@Produce","300g self-raising flour@Pantry","400ml thickened cream@Dairy","50g caster sugar@Pantry","500g strawberries@Produce","4 tsp black tea@Pantry","100g cherry jam@Pantry"]}},"Men in Black (1997)":{"poster":"assets/menu-posters/men-in-black-1997.jpg","colour":"#223d58","servings":4,"tagline":"Protecting Earth from the worst snacks in the universe.","cue":"Serve the drinks when Edgar starts demanding sugar water.","menu":{"s":[{"n":"Edgar's farmhouse cornbread","note":"Buttermilk cornbread baked in a hot cast-iron pan","how":"Heat a 25cm cast-iron pan in the oven at 210C. Mix 200g cornmeal, 125g flour, 2 tsp baking powder, 1 tsp salt and 2 tbsp sugar, then 350ml buttermilk, 2 eggs and 80g melted butter. Pour into the hot greased pan and bake 20 minutes. Cut in wedges with 50g butter beaten with 2 tbsp honey.","shop":["200g cornmeal@Pantry","125g plain flour@Pantry","2 tsp baking powder@Pantry","350ml buttermilk@Dairy","2 eggs@Dairy","130g butter@Dairy","2 tbsp honey@Pantry"]},{"n":"Black bean dip","note":"Smoky chipotle black bean dip with feta and coriander, corn chips","how":"Blitz 2 drained tins black beans with 2 garlic cloves, juice of 2 limes, 1 tsp cumin and 1 chipotle in adobo until smooth. Spoon into a bowl and top with 80g crumbled feta and coriander. Serve with corn chips.","shop":["2 tins black beans@Pantry","2 garlic cloves@Produce","2 limes@Produce","1 jar ground cumin@Pantry","1 tin chipotle in adobo@Pantry","80g feta@Deli","1 bunch coriander@Produce","1 bag corn chips@Pantry"]}],"m":[{"n":"Deli pastrami sandwiches","note":"Toasted rye with pastrami, Swiss cheese and deli mustard","how":"Spread 8 slices rye with deli mustard. Fill 4 with 500g sliced pastrami and 8 slices Swiss cheese, close and toast in a pan with 20g butter over medium heat, 3 minutes a side, until the cheese melts. Cut on the diagonal and serve with pickles.","shop":["8 slices rye bread@Bakery","4 tbsp deli mustard@Pantry","500g pastrami@Deli","8 slices Swiss cheese@Deli","20g butter@Dairy","4 dill pickles@Pantry"]}],"w":[{"n":"Neuralyser cake pops","note":"Butter cake and cream cheese icing balls on sticks, dipped in white chocolate","how":"Crumble a 500g butter cake and mix with 100g cream cheese icing until it holds together. Roll into 16 balls, push in sticks and chill an hour. Dip in 300g melted white chocolate, set, then brush with silver lustre dust.","shop":["1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry"]}],"d":[{"n":"Edgar's sugar water lemonade slush","note":"Icy blended lemonade slush with a lemon wheel, no alcohol","how":"Dissolve 150g caster sugar in 150ml hot water and cool. Blend with 150ml lemon juice, 300ml cold water and 4 cups ice until slushy. Pour into 4 glasses, add a lemon wheel and mint sprig and serve with spoons and straws.","shop":["150g caster sugar@Pantry","4 lemons@Produce","4 sprigs mint@Produce","1 bag ice@Frozen"]}],"shopping":["200g cornmeal@Pantry","125g plain flour@Pantry","2 tsp baking powder@Pantry","350ml buttermilk@Dairy","2 eggs@Dairy","150g butter@Dairy","2 tbsp honey@Pantry","2 tins black beans@Pantry","2 garlic cloves@Produce","2 limes@Produce","1 jar ground cumin@Pantry","1 tin chipotle in adobo@Pantry","80g feta@Deli","1 bunch coriander@Produce","1 bag corn chips@Pantry","8 slices rye breads@Bakery","4 tbsp deli mustard@Pantry","500g pastrami@Deli","8 slices Swiss cheeses@Deli","4 dill pickles@Pantry","1 butter cake@Bakery","100g cream cheese@Dairy","50g icing sugar@Pantry","300g white chocolate@Pantry","1 jar silver lustre dust@Pantry","150g caster sugar@Pantry","4 lemons@Produce","4 sprigs mints@Produce","1 bag ice@Frozen"]}},"Kate & Leopold (2001)":{"poster":"assets/menu-posters/kate-leopold-2001.jpg","colour":"#725630","servings":4,"tagline":"A duke from 1876 discovers modern margarine.","cue":"Serve dinner when Leopold sets up the rooftop dinner.","menu":{"s":[{"n":"Rooftop crostini","note":"Toasted baguette, whipped goat's cheese, honey poached pear and thyme","how":"Slice a baguette thin on the bias, brush with oil and toast at 200C for 8 minutes. Poach 2 sliced pears in simmering water with honey for 5 minutes. Spread toasts with 150g whipped goat's cheese, top with pear and drizzle with honey and thyme.","shop":["1 baguette@Bakery","150g goat's cheese@Deli","2 pears@Produce","1 jar honey@Pantry","1 bunch thyme@Produce"]},{"n":"Butter tasting","note":"cultured, salted Irish and honey-whipped brown butter on a board with warm sourdough and radishes","how":"Set out 100g cultured butter, 100g salted Irish butter and 100g butter browned, cooled and whipped with 1 tbsp honey. Warm 1 sourdough loaf at 180C for 8 minutes and slice. Halve 1 bunch radishes and serve with flaky salt for dipping.","shop":["200g cultured butter@Dairy","100g salted butter@Dairy","1 jar honey@Pantry","1 sourdough loaf@Bakery","1 bunch radishes@Produce","1 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Leopold's rooftop dinner","note":"Whole roast snapper with beurre blanc, candlelight on the roof","how":"Score a 1.5kg snapper, stuff with lemon slices, sliced fennel and dill, then roast at 220C for 25 minutes. Boil 800g new potatoes. Reduce 1 shallot with 100ml white wine and 2 tbsp vinegar, then whisk in 150g cold butter cube by cube.","shop":["1.5kg whole snapper@Seafood","2 lemons@Produce","1 fennel bulb@Produce","1 bunch dill@Produce","800g new potatoes@Produce","1 shallot@Produce","100ml white wine@Bottle shop","1 bottle white wine vinegar@Pantry","150g butter@Dairy"]}],"w":[{"n":"Chocolate mousse","note":"Dark chocolate mousse lightened with whipped egg whites and cream","how":"Melt 200g dark chocolate with 30g butter. Whisk in 4 yolks, then fold in 4 whites whipped to soft peaks with 40g sugar, then 150ml softly whipped cream. Spoon into four glasses and set in the fridge for 4 hours before serving.","shop":["200g dark chocolate@Pantry","30g butter@Dairy","4 eggs@Dairy","40g caster sugar@Pantry","150ml thickened cream@Dairy"]}],"d":[{"n":"Leopold's claret cup","note":"Red wine punch with brandy, orange liqueur, sliced orange and cucumber","how":"Mix 750ml red wine, 60ml brandy, 30ml orange liqueur and 2 tbsp sugar in a jug with sliced orange and cucumber. Chill 1 hour, then add ice and top with 400ml soda water.","shop":["750ml red wine@Bottle shop","60ml brandy@Bottle shop","30ml orange liqueur@Bottle shop","2 tbsp caster sugar@Pantry","1 orange@Produce","1 cucumber@Produce","400ml soda water@Drinks"]}],"shopping":["1 baguette@Bakery","150g goat's cheese@Deli","2 pears@Produce","2 jars honey@Pantry","1 bunch thyme@Produce","200g cultured butter@Dairy","100g salted butter@Dairy","1 sourdough loaf@Bakery","1 bunch radishes@Produce","1 tsp sea salt flakes@Pantry","1.5kg whole snapper@Seafood","2 lemons@Produce","1 fennel bulb@Produce","1 bunch dill@Produce","800g new potatoes@Produce","1 shallot@Produce","100ml white wine@Bottle shop","1 bottle white wine vinegar@Pantry","180g butter@Dairy","200g dark chocolate@Pantry","4 eggs@Dairy","40g caster sugar@Pantry","150ml thickened cream@Dairy","750ml red wine@Bottle shop","60ml brandy@Bottle shop","30ml orange liqueur@Bottle shop","2 tbsp caster sugar@Pantry","1 orange@Produce","1 cucumber@Produce","400ml soda water@Drinks"]}},"Lethal Weapon (1987)":{"poster":"assets/menu-posters/lethal-weapon-1987.jpg","colour":"#9c2428","servings":4,"tagline":"Two partners. One family dinner.","cue":"Serve the mains when Roger calls the roast a brown, roast-like substance.","menu":{"s":[{"n":"Riggs' trailer snacks","note":"crackers and whatever's left in his fridge","how":"Cut 250g sharp cheddar into slabs and fold 150g sliced salami into quarters. Lay out on a chopping board with a sleeve of saltine crackers and a small bowl of pickled jalapeños. Eat it straight off the board on the couch.","shop":["250g sharp cheddar@Deli","150g salami@Deli","1 packet saltine crackers@Pantry","1 jar pickled jalapeños@Pantry"]},{"n":"Christmas party crab dip","note":"Baked cream cheese and sour cream dip with crab and cheddar, crackers","how":"Mix 250g cream cheese, 150g sour cream, 2 tsp Worcestershire and a squeeze of lemon. Fold in 200g crab meat and half the 100g grated cheddar, top with the rest and bake at 190C for 20 minutes until bubbling. Serve with 200g crackers.","shop":["250g cream cheese@Dairy","150g sour cream@Dairy","2 tsp Worcestershire sauce@Pantry","1 lemon@Produce","200g crab meat@Seafood","100g cheddar@Dairy","200g water crackers@Pantry"]}],"m":[{"n":"Brown sticky stew, done right","note":"Beef chuck braised with onion, carrot, celery, tomato paste and red wine","how":"Brown 1kg diced beef chuck in batches. Soften 1 onion, 2 carrots and 2 celery sticks, stir in 2 tbsp tomato paste, then add 250ml red wine, 500ml stock and thyme. Braise at 150C for 3 hours. Serve on 1kg potatoes mashed with butter.","shop":["1kg beef chuck@Meat","1 brown onion@Produce","2 carrots@Produce","2 celery sticks@Produce","1 tube tomato paste@Pantry","250ml red wine@Bottle shop","500ml beef stock@Pantry","1 bunch thyme@Produce","1kg potatoes@Produce","60g butter@Dairy"]}],"w":[{"n":"Roger's birthday cake","note":"Two-layer chocolate cake filled and covered with chocolate buttercream","how":"Beat 200g butter with 250g sugar, add 4 eggs, then fold in 250g self-raising flour, 50g cocoa and 200ml milk. Bake in two tins at 170C for 35 minutes. Beat 200g butter, 300g icing sugar and 40g cocoa for buttercream. Fill, cover and add candles.","shop":["400g butter@Dairy","250g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","90g cocoa@Pantry","200ml full cream milk@Dairy","300g icing sugar@Pantry","1 box birthday candles@Pantry"]}],"d":[{"n":"Riggs' beach trailer michelada","note":"Cold lager with lime, tomato juice, hot sauce and a chilli salt rim","how":"Mix 2 tbsp salt with 1 tsp chilli powder on a plate. Rub the rims of 4 glasses with lime and dip in the chilli salt, then fill with ice. Into each glass add 30ml lime juice, 60ml tomato juice, 4 dashes hot sauce and 2 dashes Worcestershire sauce. Top each with a 375ml bottle of cold lager poured slowly and stir once. Garnish with lime wedges.","shop":["4 bottles lager (375ml)@Bottle shop","5 limes@Produce","250ml tomato juice@Drinks","hot sauce@Pantry","Worcestershire sauce@Pantry","1 tsp chilli powder@Pantry","1 bag ice@Frozen"]}],"shopping":["250g sharp cheddar@Deli","150g salami@Deli","1 packet saltine crackers@Pantry","1 jar pickled jalapeños@Pantry","250g cream cheese@Dairy","150g sour cream@Dairy","2 tsp Worcestershire sauce@Pantry","1 lemon@Produce","200g crab meat@Seafood","100g cheddar@Dairy","200g water crackers@Pantry","1kg beef chuck@Meat","1 brown onion@Produce","2 carrots@Produce","2 celery sticks@Produce","1 tube tomato paste@Pantry","250ml red wine@Bottle shop","500ml beef stock@Pantry","1 bunch thyme@Produce","1kg potatoes@Produce","460g butter@Dairy","250g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","90g cocoa@Pantry","200ml full cream milk@Dairy","300g icing sugar@Pantry","1 box birthday candles@Pantry","4 bottles lager (375ml)@Bottle shop","5 limes@Produce","250ml tomato juice@Drinks","hot sauce@Pantry","Worcestershire sauce@Pantry","1 tsp chilli powder@Pantry","1 bag ice@Frozen"]}},"Lethal Weapon 2 (1989)":{"poster":"assets/menu-posters/lethal-weapon-2-1989.jpg","colour":"#a74025","servings":4,"tagline":"Consulate trouble. Bring your own dessert.","cue":"Serve the snacks when Leo Getz first meets Riggs and Murtaugh.","menu":{"s":[{"n":"Leo Getz's drive-thru fries","note":"Thin russet fries fried twice until crisp","how":"Cut 1kg russet potatoes into thin fries, soak 30 minutes and dry well. Fry at 140C for 5 minutes, drain and cool, then fry again at 190C for 3 minutes until crisp. Toss with fine salt and serve in paper bags. Check the order before you leave.","shop":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 tsp fine salt@Pantry"]},{"n":"Consulate biltong","note":"Thin biltong with dried peaches and salted macadamias","how":"Roast 150g macadamias at 170C for 8 minutes and toss with salt while warm. Slice 250g biltong thinly across the grain. Pile on a board with 150g dried peaches and the macadamias in little bowls.","shop":["150g macadamias@Pantry","250g beef biltong@Deli","150g dried peaches@Pantry"]}],"m":[{"n":"Boerewors rolls","note":"Grilled boerewors sausage in rolls with tomato chilli relish","how":"Simmer 2 sliced onions, 4 chopped tomatoes, 1 chilli and 1 tsp sugar for 20 minutes into a relish. Grill a 1kg coil of boerewors over coals or a hot grill for 15 minutes, turning once. Cut and serve in 4 long rolls with relish.","shop":["1kg boerewors@Meat","4 long rolls@Bakery","2 onions@Produce","4 tomatoes@Produce","1 red chilli@Produce"]}],"w":[{"n":"TV ad cupcakes","note":"Vanilla cupcakes with swirled pastel buttercream and sprinkles","how":"Beat 125g butter with 150g sugar, add 2 eggs, then fold in 200g self-raising flour and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Beat 150g butter with 300g icing sugar, tint in pastel colours, swirl on and add sprinkles.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 jar sprinkles@Pantry"]}],"d":[{"n":"Roger's ginger and lime lager shandy","note":"Cold lager topped with ginger beer and fresh lime over ice","how":"Fill 4 tall glasses with ice. Squeeze half a lime into each. Pour 200ml cold lager into each glass, then top with 150ml ginger beer and stir gently once. Garnish each with a lime wheel and a sprig of mint. Serve straight away while it's still fizzing.","shop":["4 bottles lager (375ml)@Bottle shop","600ml ginger beer@Drinks","3 limes@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}],"shopping":["1kg russet potatoes@Produce","2L vegetable oil@Pantry","1 tsp fine salt@Pantry","150g macadamias@Pantry","250g beef biltong@Deli","150g dried peaches@Pantry","1kg boerewors@Meat","4 long rolls@Bakery","2 onions@Produce","4 tomatoes@Produce","1 red chilli@Produce","275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 jar sprinkles@Pantry","4 bottles lager (375ml)@Bottle shop","600ml ginger beer@Drinks","3 limes@Produce","1 bunch mint@Produce","1 bag ice@Frozen"]}},"48 Hrs. (1982)":{"poster":"assets/menu-posters/48-hrs-1982.jpg","colour":"#af3324","servings":4,"tagline":"Forty-eight hours. Eat fast.","cue":"Pour drinks when Reggie announces the new sheriff in town.","menu":{"s":[{"n":"Torchy's bar peanuts","note":"Peanuts roasted in the shell with salt and cayenne","how":"Spread 400g peanuts in the shell on a tray and roast at 180C for 20 minutes. Toss straight away with 1 tsp fine salt and a pinch of cayenne. Tip into a tin bucket and put an empty bowl out for the shells.","shop":["400g peanuts in the shell@Pantry","1 box fine salt@Pantry","1 jar cayenne pepper@Pantry"]},{"n":"San Francisco sourdough","note":"Warm torn sourdough with whipped roasted garlic butter","how":"Roast a garlic head wrapped in foil at 180C for 40 minutes. Squeeze into 125g soft salted butter and whip. Warm a sourdough round at 200C for 10 minutes, tear into chunks and serve with the butter.","shop":["1 garlic head@Produce","125g salted butter@Dairy","1 sourdough loaf@Bakery"]}],"m":[{"n":"San Francisco cioppino","note":"Seafood stew of crab, clams, mussels, prawns and fish in tomato and white wine","how":"Soften 1 sliced fennel, 1 onion and 3 garlic cloves in oil. Add 1 tin tomatoes, 250ml white wine and 500ml fish stock, simmer 20 minutes. Add 1 crab, then 500g clams and mussels, then 300g prawns and 300g fish. Serve with sourdough.","shop":["1 fennel bulb@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tin crushed tomatoes@Pantry","250ml white wine@Bottle shop","500ml fish stock@Pantry","1 blue swimmer crab@Seafood","250g clams@Seafood","250g mussels@Seafood","300g green prawns@Seafood","300g firm white fish@Seafood","1 sourdough loaf@Bakery"]}],"w":[{"n":"Jailhouse chocolate cake","note":"one-bowl cocoa sponge with buttermilk and coffee, thick fudge icing, for a 48 hour pass","how":"Whisk 250g flour, 300g sugar, 60g cocoa and 1 tsp bicarb. Add 125ml oil, 250ml buttermilk, 2 eggs and 250ml hot coffee. Bake at 170C for 35 minutes. Ice with 250g icing sugar, 40g cocoa, 60g soft butter and a splash of hot water.","shop":["250g plain flour@Pantry","300g caster sugar@Pantry","100g cocoa@Pantry","125ml vegetable oil@Pantry","250ml buttermilk@Dairy","2 eggs@Dairy","1 jar instant coffee@Pantry","250g icing sugar@Pantry","60g butter@Dairy"]}],"d":[{"n":"Torchy's bourbon boilermaker","note":"Ice cold lager served with a shot of bourbon, bitters and orange peel","how":"Chill 4 long neck lagers until icy. Pour 30ml bourbon into each of 4 shot glasses, add a dash of aromatic bitters and twist a small strip of orange peel over each. Serve each shot with a cold beer. Sip the bourbon and chase it with the beer, or drop it in if it's that kind of night.","shop":["4 long neck lagers@Bottle shop","120ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce"]}],"shopping":["400g peanuts in the shell@Pantry","1 box fine salt@Pantry","1 jar cayenne pepper@Pantry","1 garlic head@Produce","125g salted butter@Dairy","2 sourdough loaf@Bakery","1 fennel bulb@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tin crushed tomatoes@Pantry","250ml white wine@Bottle shop","500ml fish stock@Pantry","1 blue swimmer crab@Seafood","250g clams@Seafood","250g mussels@Seafood","300g green prawns@Seafood","300g firm white fish@Seafood","250g plain flour@Pantry","300g caster sugar@Pantry","100g cocoa@Pantry","125ml vegetable oil@Pantry","250ml buttermilk@Dairy","2 eggs@Dairy","1 jar instant coffee@Pantry","250g icing sugar@Pantry","60g butter@Dairy","4 long neck lagers@Bottle shop","120ml bourbon@Bottle shop","1 bottle aromatic bitters@Bottle shop","1 orange@Produce"]}},"Stakeout (1987)":{"poster":"assets/menu-posters/stakeout-1987.jpg","colour":"#223f4c","servings":4,"tagline":"Watch the girl. Eat the doughnuts.","cue":"Serve the snacks when Bill and Chris start their movie trivia game.","menu":{"s":[{"n":"Stakeout doughnuts","note":"Where are my donuts? Warm cake ones, cinnamon sugar","how":"Warm 8 cake doughnuts on a tray at 160C for 2 minutes. Drop them into a paper bag with 100g caster sugar and 2 tsp cinnamon, fold the top and shake until coated. Eat them out of the bag.","shop":["8 cake doughnuts@Bakery","100g caster sugar@Pantry","1 jar cinnamon@Pantry"]},{"n":"Movie trivia snack mix","note":"Pretzels, peanuts, cereal squares and seeds baked with Worcestershire butter","how":"Toss 150g pretzels, 150g peanuts, 150g cereal squares and 50g sunflower seeds with 60g melted butter, 2 tbsp Worcestershire and 1 tsp garlic powder. Bake at 130C for 45 minutes, stirring every 15 minutes. Cool before bagging up.","shop":["150g pretzels@Pantry","150g peanuts@Pantry","150g cereal squares@Pantry","50g sunflower seeds@Pantry","60g butter@Dairy","1 bottle Worcestershire sauce@Pantry","1 jar garlic powder@Pantry"]}],"m":[{"n":"Maria's home cooking","note":"Baked chicken enchiladas in red chilli sauce","how":"Soak 4 dried chillies in hot water, blitz with 1 tin tomatoes and garlic and simmer 10 minutes. Poach and shred 600g chicken thighs. Roll in 8 corn tortillas, cover with sauce and 150g cheddar and bake at 190C for 20 minutes. Serve with sour cream.","shop":["4 dried chillies@Pantry","1 tin crushed tomatoes@Pantry","2 garlic cloves@Produce","600g chicken thighs@Meat","8 corn tortillas@Bakery","150g cheddar@Dairy","200g sour cream@Dairy"]}],"w":[{"n":"Doughnut holes","note":"Yeast dough balls fried golden and served warm","how":"Mix 300g flour, 7g yeast, 2 tbsp sugar, 1 egg and 160ml warm milk into a soft dough and prove an hour. Roll into small balls and fry at 175C for 2 minutes. Roll in 100g caster sugar and 2 tsp cinnamon while warm.","shop":["300g plain flour@Pantry","7g dried yeast@Pantry","140g caster sugar@Pantry","1 egg@Dairy","160ml full cream milk@Dairy","1 jar cinnamon@Pantry","1L vegetable oil@Pantry"]}],"d":[{"n":"Reimers' night shift Irish coffee","note":"Hot coffee with brown sugar and Irish whiskey, floated with lightly whipped cream","how":"Brew 800ml strong coffee. Stir 4 tsp brown sugar and 160ml Irish whiskey into the hot coffee and pour into a warmed thermos if you're on the move. Lightly whip 150ml thickened cream until just thick but still pourable. Pour the coffee into 4 mugs and float the cream on top by pouring it over the back of a spoon.","shop":["800ml brewed coffee@Pantry","4 tsp brown sugar@Pantry","160ml Irish whiskey@Bottle shop","150ml thickened cream@Dairy"]}],"shopping":["8 cake doughnuts@Bakery","240g caster sugar@Pantry","2 jars cinnamon@Pantry","150g pretzels@Pantry","150g peanuts@Pantry","150g cereal squares@Pantry","50g sunflower seeds@Pantry","60g butter@Dairy","1 bottle Worcestershire sauce@Pantry","1 jar garlic powder@Pantry","4 dried chillies@Pantry","1 tin crushed tomatoes@Pantry","2 garlic cloves@Produce","600g chicken thighs@Meat","8 corn tortillas@Bakery","150g cheddar@Dairy","200g sour cream@Dairy","300g plain flour@Pantry","7g dried yeast@Pantry","1 egg@Dairy","160ml full cream milk@Dairy","1L vegetable oil@Pantry","800ml brewed coffee@Pantry","4 tsp brown sugar@Pantry","160ml Irish whiskey@Bottle shop","150ml thickened cream@Dairy"]}},"Kindergarten Cop (1990)":{"poster":"assets/menu-posters/kindergarten-cop-1990.jpg","colour":"#2e643c","servings":4,"tagline":"Undercover in Astoria. Lunch at recess.","cue":"Serve the snacks when Kimble catches the lunch thief.","menu":{"s":[{"n":"Lunch box crackers and cheese","note":"Cheddar cubes, apple slices and crackers","how":"Cut 200g cheddar into small cubes. Slice 2 apples and toss in lemon juice so they don't brown. Pack each lunch box with cheese, a handful of crackers, apple slices and 250g cherry tomatoes shared between them.","shop":["200g cheddar@Dairy","2 apples@Produce","1 lemon@Produce","1 packet crackers@Pantry","250g cherry tomatoes@Produce"]},{"n":"Ferret-free fruit cups","note":"Diced mango and pineapple, strawberries and grapes in orange juice","how":"Dice 1 mango and a quarter of a pineapple, halve 250g strawberries and 200g grapes. Toss together with the juice of an orange. Spoon into four cups and top each with a mint leaf. Keep cold until serving.","shop":["1 mango@Produce","0.25 pineapple@Produce","250g strawberries@Produce","200g grapes@Produce","1 orange@Produce","1 bunch mint@Produce"]}],"m":[{"n":"Astoria school lunch fish fingers","note":"Panko crumbed white fish fingers, oven chips, peas and tartare sauce","how":"Cut 600g firm white fish into fingers. Dip in flour, 2 beaten eggs and 150g panko and shallow-fry for 2 minutes a side. Cut 1kg potatoes into chips, toss in oil and roast at 220C for 35 minutes. Serve with tartare and 300g peas.","shop":["600g firm white fish@Seafood","1 bag plain flour@Pantry","2 eggs@Dairy","150g panko@Pantry","1kg potatoes@Produce","1 jar tartare sauce@Pantry","300g frozen peas@Frozen","500ml vegetable oil@Pantry"]}],"w":[{"n":"Kimble's class cupcakes","note":"Vanilla cupcakes with swirled red, yellow and blue buttercream and sprinkles","how":"Beat 125g butter with 150g sugar, add 2 eggs, then fold in 200g self-raising flour and 125ml milk. Bake 12 cupcakes at 180C for 18 minutes. Beat 150g butter with 300g icing sugar, tint in primary colours, swirl on and add sprinkles.","shop":["275g butter@Dairy","150g caster sugar@Pantry","2 eggs@Dairy","200g self-raising flour@Pantry","125ml full cream milk@Dairy","300g icing sugar@Pantry","1 box food colouring@Pantry","1 jar sprinkles@Pantry"]}],"d":[{"n":"Big and strong chocolate malt milkshake","note":"Chocolate malted milkshake blended with vanilla ice cream","how":"Add 600ml cold milk, 4 scoops vanilla ice cream, 2 tbsp cocoa powder, 4 tbsp malted milk powder and 2 tbsp caster sugar to a blender. Blend 30 seconds until thick and frothy. Pour into 4 glasses. Top each with a swirl of whipped cream and a pinch of chocolate sprinkles and serve with straws.","shop":["600ml full cream milk@Dairy","1 tub vanilla ice cream@Frozen","2 tbsp cocoa powder@Pantry","4 tbsp malted milk powder@Pantry","2 tbsp caster sugar@Pantry","1 can whipped cream@Dairy","chocolate sprinkles@Pantry"]}],"shopping":["200g cheddar@Dairy","2 apples@Produce","1 lemon@Produce","1 packet crackers@Pantry","250g cherry tomatoes@Produce","1 mango@Produce","0.25 pineapple@Produce","250g strawberries@Produce","200g grapes@Produce","1 orange@Produce","1 bunch mint@Produce","600g firm white fish@Seafood","1 bag plain flour@Pantry","4 eggs@Dairy","150g panko@Pantry","1kg potatoes@Produce","1 jar tartare sauce@Pantry","300g frozen peas@Frozen","500ml vegetable oil@Pantry","275g butter@Dairy","150g caster sugar@Pantry","200g self-raising flour@Pantry","725ml full cream milk@Dairy","300g icing sugar@Pantry","1 box food colouring@Pantry","1 jar sprinkles@Pantry","1 tub vanilla ice cream@Frozen","2 tbsp cocoa powder@Pantry","4 tbsp malted milk powder@Pantry","2 tbsp caster sugar@Pantry","1 can whipped cream@Dairy","chocolate sprinkles@Pantry"]}},"The Godfather Part II (1974)":{"poster":"assets/menu-posters/the-godfather-part-ii-1974.jpg","colour":"#74190e","servings":4,"tagline":"The family business goes international.","cue":"Serve the mains when young Vito arrives at Ellis Island.","menu":{"s":[{"n":"Genco olive oil arancini","note":"fried in the oil that started the family business","how":"Cook 300g arborio rice in 900ml stock with a pinch of saffron until thick, stir in 40g parmesan and chill overnight on a tray. Brown 150g beef mince with 50g frozen peas and 2 tbsp passata. Wrap golf balls of rice around a spoon of filling and a cube of mozzarella. Roll in flour, 2 beaten eggs and 100g breadcrumbs, and fry at 175C until deep gold.","shop":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","40g parmesan@Dairy","150g beef mince@Meat","50g frozen peas@Frozen","100g mozzarella@Dairy","2 eggs@Dairy","100g breadcrumbs@Pantry"]},{"n":"Havana Cuban sliders","note":"ham, roast pork, swiss and pickles, pressed flat for the Havana trip","how":"Split 8 slider rolls and smear the cut sides with 2 tbsp yellow mustard. Layer with 150g leg ham, 150g sliced roast pork, 8 slices Swiss cheese and sliced dill pickles. Brush the tops with 30g melted butter and press in a heavy pan over medium heat with a second pan on top, 3 minutes a side, until the cheese melts.","shop":["8 slider rolls@Bakery","2 tbsp yellow mustard@Pantry","150g leg ham@Deli","150g roast pork@Deli","8 slices Swiss cheese@Deli","4 dill pickles@Pantry","30g butter@Dairy"]}],"m":[{"n":"Vito's tenement baked ziti","note":"eggplant, ricotta and a mozzarella crust, the kind of thing a young family stretches over a week","how":"Dice 1 large eggplant and fry in 4 tbsp olive oil until soft and browned, add 2 sliced garlic cloves for a minute, then 700ml passata and half a bunch of basil, torn. Simmer 30 minutes until thick. Cook 500g ziti or penne 3 minutes short of done. Mix 400g ricotta with 50g grated parmesan, a pinch of nutmeg and the rest of the basil, chopped. Layer pasta, sauce and ricotta in a baking dish, top with 200g torn mozzarella and bake at 200C for 25 minutes until blistered.","shop":["1 large eggplant@Produce","4 tbsp olive oil@Pantry","2 garlic cloves@Produce","700ml passata@Pantry","1 bunch basil@Produce","500g ziti or penne@Pantry","400g ricotta@Dairy","50g parmesan@Dairy","1 pinch ground nutmeg@Spices","200g mozzarella@Dairy"]}],"w":[{"n":"Hyman Roth's birthday cake","note":"the sponge iced like Cuba, cut and shared around the table","how":"Beat 200g soft butter with 200g caster sugar, add 4 eggs and fold in 250g self-raising flour with 100ml milk. Bake in a lined slab tin at 180C for 30 minutes and cool. Trim into a rough island shape. Beat 150g butter with 300g icing sugar and a few drops of green food colouring, spread thinly then again, pipe happy birthday across and slice at the table.","shop":["350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","100ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle green food colouring@Pantry"]}],"d":[{"n":"Fredo's Havana daiquiri","note":"Fredo would ask for a banana in his","how":"Make sugar syrup by dissolving 60g caster sugar in 60ml hot water and cooling. For each drink shake 60ml white rum, 25ml fresh lime juice and 15ml syrup hard with plenty of ice, then double strain into a chilled coupe. Makes four, with 240ml rum and about 4 limes.","shop":["240ml white rum@Bottle shop","4 limes@Produce","60g caster sugar@Pantry","1kg ice@Frozen"]}],"shopping":["300g arborio rice@Pantry","900ml chicken stock@Pantry","1 pinch saffron@Pantry","40g parmesan@Dairy","150g beef mince@Meat","50g frozen peas@Frozen","100g mozzarella@Dairy","2 eggs@Dairy","100g breadcrumbs@Pantry","8 slider rolls@Bakery","2 tbsp yellow mustard@Pantry","150g leg ham@Deli","150g roast pork@Deli","8 slices Swiss cheese@Deli","4 dill pickles@Pantry","30g butter@Dairy","1 large eggplant@Produce","4 tbsp olive oil@Pantry","2 garlic cloves@Produce","700ml passata@Pantry","1 bunch basil@Produce","500g ziti or penne@Pantry","400g ricotta@Dairy","50g parmesan@Dairy","1 pinch ground nutmeg@Spices","200g mozzarella@Dairy","350g butter@Dairy","200g caster sugar@Pantry","4 eggs@Dairy","250g self-raising flour@Pantry","100ml full cream milk@Dairy","300g icing sugar@Pantry","1 bottle green food colouring@Pantry","240ml white rum@Bottle shop","4 limes@Produce","60g caster sugar@Pantry","1kg ice@Frozen"]}},"Casino (1995)":{"poster":"assets/menu-posters/casino-1995.jpg","colour":"#24402a","servings":4,"tagline":"Every muffin gets the same number of blueberries.","cue":"Bring out the muffins and count the blueberries before anyone takes one.","menu":{"s":[{"n":"Clams casino","note":"steamed clams baked with bacon, capsicum and garlic butter under crumbs, for the count room","how":"Steam 1kg clams until they open and remove the top shells. Mix 60g soft butter with garlic, diced red capsicum, parsley and 40g breadcrumbs. Top each clam with a spoon of the mix and a piece of bacon and grill 4 minutes until crisp.","shop":["1kg clams@Seafood","60g butter@Dairy","2 garlic cloves@Produce","1 red capsicum@Produce","1 bunch parsley@Produce","40g breadcrumbs@Pantry","4 rashers bacon@Meat"]},{"n":"Oysters Rockefeller","note":"grilled under spinach, herb butter and crumbs with aniseed, for the high rollers Ace keeps happy","how":"Blitz 100g spinach, a handful of parsley, 2 spring onions, 80g soft butter, 40g breadcrumbs and 1 tbsp aniseed liqueur. Spoon onto 16 freshly shucked oysters on a tray of rock salt and grill on high for 3 minutes until bubbling. Serve hot with lemon wedges.","shop":["16 oysters@Seafood","100g spinach@Produce","1 bunch parsley@Produce","2 spring onions@Produce","80g butter@Dairy","40g breadcrumbs@Pantry","1 tbsp aniseed liqueur@Bottle shop","1 lemon@Produce"]}],"m":[{"n":"Tangiers rib eye","note":"cooked exactly right, no excuses","how":"Salt 2 rib eye steaks, about 400g each, and leave uncovered on a rack in the fridge overnight. Sear in a smoking pan for 3 minutes a side, then add 50g butter, 4 sprigs thyme and 3 crushed garlic cloves and baste until 54C inside. Rest 8 minutes and slice. Wilt 500g spinach, squeeze dry and simmer with 150ml thickened cream and nutmeg.","shop":["800g rib eye steak@Meat","50g butter@Dairy","1 bunch thyme@Produce","3 garlic cloves@Produce","500g spinach@Produce","150ml thickened cream@Dairy"]}],"w":[{"n":"Equal-blueberry muffins","note":"buttermilk and butter batter baked golden, exactly ten blueberries pressed into every one","how":"Whisk 300g plain flour, 150g caster sugar and 2 tsp baking powder. Mix 2 eggs, 250ml buttermilk and 90g melted butter, then fold into the dry mix until just combined. Spoon into 12 lined muffin cases and press exactly 10 blueberries into the top of each. Bake at 190C for 20 minutes.","shop":["300g plain flour@Pantry","150g caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","250ml buttermilk@Dairy","90g butter@Dairy","125g blueberries@Produce"]}],"d":[{"n":"Dry martini","note":"gin and dry vermouth stirred cold, frozen glass, olive, under the eye in the sky","how":"Freeze four martini glasses for 30 minutes. For each drink stir 60ml gin with 10ml dry vermouth over plenty of ice for 30 seconds and strain into a frozen glass. Garnish with a green olive on a pick. Makes four with 240ml gin and 40ml vermouth.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","4 green olives@Deli","1kg ice@Frozen"]}],"shopping":["1kg clams@Seafood","280g butter@Dairy","5 garlic cloves@Produce","1 red capsicum@Produce","1 bunch parsley@Produce","80g breadcrumbs@Pantry","4 rashers bacon@Meat","16 oysters@Seafood","600g spinach@Produce","2 spring onions@Produce","1 tbsp aniseed liqueur@Bottle shop","1 lemon@Produce","800g rib eye steak@Meat","1 bunch thyme@Produce","150ml thickened cream@Dairy","300g plain flour@Pantry","150g caster sugar@Pantry","2 tsp baking powder@Pantry","2 eggs@Dairy","250ml buttermilk@Dairy","125g blueberries@Produce","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","4 green olives@Deli","1kg ice@Frozen"]}},"Scarface (1983)":{"poster":"assets/menu-posters/scarface-1983.jpg","colour":"#a31b24","servings":4,"tagline":"Little Havana to the top. Save the last croqueta.","cue":"Serve the mains when Tony first walks into the Babylon Club.","menu":{"s":[{"n":"Freedom Town croquetas de jamón","note":"camp food from under the freeway, before the green card","how":"Melt 60g butter, stir in 70g plain flour for 2 minutes, then whisk in 500ml warm milk and cook 8 minutes until very thick. Stir in 100g finely chopped serrano ham and a pinch of nutmeg. Spread on a tray, cover and chill overnight. Roll into 16 logs, dip in 2 beaten eggs and 100g fine breadcrumbs, and fry at 180C until golden.","shop":["60g butter@Dairy","70g plain flour@Pantry","500ml full cream milk@Dairy","100g serrano ham@Deli","2 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry"]},{"n":"Tostones","note":"garlic mojo, Little Havana's side order","how":"Peel 3 green plantains, cut into 3cm chunks and fry at 160C for 4 minutes until soft. Smash flat with a heavy glass and fry again at 190C until crisp. Mix 3 crushed garlic cloves, the juice of 2 limes and 60ml olive oil, spoon over and finish with flaky salt.","shop":["3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml olive oil@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Ropa vieja","note":"shredded beef with capsicum, rice and black beans","how":"Simmer 1kg flank steak with 2 bay leaves and half an onion in water for 2 hours until tender, then shred, keeping 250ml broth. Fry 1 sliced onion, 2 sliced capsicums and 3 garlic cloves until soft, add 2 tsp cumin, 1 tsp oregano, 400g crushed tomatoes, 80g green olives, the beef and broth and simmer 20 minutes. Serve with 300g rice and 2 tins black beans.","shop":["1kg flank steak@Meat","2 brown onions@Produce","2 capsicums@Produce","3 garlic cloves@Produce","2 tsp ground cumin@Pantry","400g crushed tomatoes@Pantry","80g green olives@Deli","300g long grain rice@Pantry","800g black beans@Pantry"]}],"w":[{"n":"Miami blimp guava pastelitos","note":"puff pastry squares of guava paste and cream cheese, sugared on top, for Mama Montana","how":"Cut 2 sheets puff pastry into 4 squares each. Put a 30g slice of guava paste and a teaspoon of cream cheese in the middle of 4 squares, using 120g guava and 100g cream cheese in total. Cover with the other squares, press the edges with a fork, brush with 1 beaten egg and sprinkle with sugar. Bake at 200C for 20 minutes until puffed.","shop":["2 sheets puff pastry@Frozen","120g guava paste@Pantry","100g cream cheese@Dairy","1 egg@Dairy","2 tbsp caster sugar@Pantry"]}],"d":[{"n":"Babylon Club mojito","note":"Tony's booth at the Babylon, before it all goes sideways","how":"Dissolve 60g caster sugar in 60ml hot water and cool. For each drink, gently muddle 8 mint leaves with 20ml syrup and 25ml lime juice in a tall glass, add 50ml white rum and fill with crushed ice. Top with soda water and stir. Makes four with 200ml rum and about 4 limes.","shop":["200ml white rum@Bottle shop","1 bunch mint@Produce","4 limes@Produce","60g caster sugar@Pantry","500ml soda water@Drinks","1kg crushed ice@Frozen"]}],"shopping":["60g butter@Dairy","70g plain flour@Pantry","500ml full cream milk@Dairy","100g serrano ham@Deli","2 eggs@Dairy","100g breadcrumbs@Pantry","1L vegetable oil@Pantry","3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml olive oil@Pantry","1kg flank steak@Meat","2 brown onions@Produce","2 capsicums@Produce","2 tsp ground cumin@Pantry","400g crushed tomatoes@Pantry","80g green olives@Deli","300g long grain rice@Pantry","800g black beans@Pantry","2 sheets puff pastry@Frozen","120g guava paste@Pantry","100g cream cheese@Dairy","1 egg@Dairy","2 tbsp caster sugar@Pantry","200ml white rum@Bottle shop","1 bunch mint@Produce","4 limes@Produce","60g caster sugar@Pantry","500ml soda water@Drinks","1kg crushed ice@Frozen"]}},"The Freshman (1990)":{"poster":"assets/menu-posters/the-freshman-1990.jpg","colour":"#23402b","servings":4,"tagline":"Some lessons aren't taught at film school.","cue":"Serve the mains when Clark first meets Carmine in Little Italy.","menu":{"s":[{"n":"Gourmet Club antipasto, all legal","note":"salami, mortadella, provolone, roast capsicum and seeded bread, a Komodo dragon nowhere in sight","how":"Arrange 100g salami, 100g mortadella and 150g provolone on a board. Add 2 roasted red capsicums cut into strips and 200g marinated artichokes. Tear a loaf of seeded Italian bread at the table.","shop":["100g salami@Deli","100g mortadella@Deli","150g provolone@Deli","2 red capsicums@Produce","200g marinated artichokes@Deli","1 loaf Italian bread@Bakery"]},{"n":"Little Italy fried calamari","note":"tender squid in light semolina, lemon and marinara, for an NYU film student","how":"Slice 500g squid tubes into rings, soak in 200ml milk for 20 minutes and toss in 120g flour mixed with 2 tbsp semolina and salt. Fry at 190C for 1 minute and serve with lemon and 250g marinara.","shop":["500g squid tubes@Seafood","200ml full cream milk@Dairy","120g plain flour@Pantry","2 tbsp semolina@Pantry","2 lemons@Produce","250g marinara sauce@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Carmine Sabatini's veal marsala","note":"thin veal seared in butter, mushroom and fortified wine pan sauce, an offer Clark can't refuse","how":"Dust 600g veal escalopes with seasoned flour and sear in 20g butter and a little oil for 1 minute a side, then set aside. Brown 250g sliced button mushrooms in the pan, add 150ml marsala and 150ml beef stock and reduce by half. Whisk in 40g cold butter, return the veal and warm through.","shop":["600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry"]}],"w":[{"n":"Cannoli","note":"a box from Little Italy for the drive back to campus","how":"Drain 500g fresh ricotta for 2 hours, then beat with 80g icing sugar, 1 tsp vanilla extract and 50g mini choc chips. Pipe into 8 cannoli shells just before serving and dip the ends in 30g chopped pistachios.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 tsp vanilla extract@Pantry","50g mini choc chips@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Carmine's amaro spritz","note":"amaro and prosecco over ice with soda and orange, bittersweet like Clark's first day in town","how":"Fill 4 large wine glasses with ice. Add 50ml Italian amaro to each glass, then 90ml chilled prosecco and 30ml soda water. Stir once gently. Cut 1 orange into thin wheels and slide one into each glass. Serve straight away while the bubbles are lively.","shop":["200ml Italian amaro@Bottle shop","1 bottle prosecco@Bottle shop","120ml soda water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}],"shopping":["100g salami@Deli","100g mortadella@Deli","150g provolone@Deli","2 red capsicums@Produce","200g marinated artichokes@Deli","1 loaf Italian bread@Bakery","500g squid tubes@Seafood","200ml full cream milk@Dairy","120g plain flour@Pantry","2 tbsp semolina@Pantry","2 lemons@Produce","250g marinara sauce@Pantry","1L vegetable oil@Pantry","600g veal escalopes@Meat","2 tbsp plain flour@Pantry","60g butter@Dairy","250g button mushrooms@Produce","150ml marsala@Bottle shop","150ml beef stock@Pantry","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1 tsp vanilla extract@Pantry","50g mini choc chips@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry","200ml Italian amaro@Bottle shop","1 bottle prosecco@Bottle shop","120ml soda water@Drinks","1 orange@Produce","1 bag ice@Frozen"]}},"Road to Perdition (2002)":{"poster":"assets/menu-posters/road-to-perdition-2002.jpg","colour":"#273a47","servings":4,"tagline":"Every father wants better for his son.","cue":"Serve dessert at the diner stop on the road to Perdition.","menu":{"s":[{"n":"Diner grilled cheese with quick pickles","note":"sharp cheddar toastie fried in butter, sweet dill cucumbers, a roadside stop en route to Chicago","how":"Thinly slice 2 Lebanese cucumbers and 1 small onion. Heat 150ml white vinegar, 100ml water, 60g sugar, 1 tsp salt and 1 tsp mustard seeds until dissolved, pour over and cool for 30 minutes. Butter 8 slices white bread on the outside, fill with 200g sliced cheddar and fry over medium heat for 3 minutes a side until golden. Cut into fingers and serve with the pickles.","shop":["2 Lebanese cucumbers@Produce","1 small onion@Produce","150ml white vinegar@Pantry","60g sugar@Pantry","1 tsp mustard seeds@Pantry","8 slices white bread@Bakery","200g sharp cheddar@Dairy","40g butter@Dairy"]},{"n":"Wake table soda bread","note":"warm craggy-crusted loaf torn by hand, sharp cheddar and salted butter alongside","how":"Mix 450g plain flour, 1 tsp bicarb soda and 1 tsp salt, add 400ml buttermilk and bring together into a round. Cut a deep cross on top and bake at 220C for 15 minutes, then 200C for 25 minutes. Serve warm with 100g salted butter and 200g sharp cheddar.","shop":["450g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","400ml buttermilk@Dairy","100g salted butter@Dairy","200g vintage cheddar@Dairy"]}],"m":[{"n":"Corned beef and cabbage","note":"simmered silverside, buttery cabbage, carrots and potatoes, hot mustard, for the Rooney family table","how":"Simmer a 1.5kg corned silverside with an onion, 2 bay leaves and 6 peppercorns for 2.5 hours. Add 600g potatoes and 3 carrots for the last 30 minutes and a quartered cabbage for the last 10. Slice the beef thick and serve with the veg, butter and hot English mustard.","shop":["1.5kg corned silverside@Meat","1 onion@Produce","2 bay leaves@Pantry","600g potatoes@Produce","3 carrots@Produce","1 cabbage@Produce","30g butter@Dairy","1 jar hot English mustard@Pantry"]}],"w":[{"n":"Apple pie with cheddar","note":"farmhouse style, like the old couple would serve","how":"Peel and slice 1kg Granny Smith apples, cook 5 minutes with 80g sugar and 1 tsp cinnamon, and cool. Line a deep pie dish with 1 sheet sweet shortcrust, fill, cover with a second sheet and cut slits. Bake at 190C for 45 minutes. Lay 120g sliced sharp cheddar on top for the last 5 minutes so it melts.","shop":["1kg Granny Smith apples@Produce","80g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 sheets sweet shortcrust pastry@Frozen","120g sharp cheddar@Dairy"]}],"d":[{"n":"McGovern wake Irish coffee","note":"hot strong brew with whiskey and brown sugar under a thick collar of whipped cream","how":"Whip 150ml thickened cream to soft ribbons, so it just holds its shape. Brew 600ml strong coffee. Warm 4 heatproof glasses with hot water and tip it out. Add 2 tsp brown sugar and 40ml Irish whiskey to each glass, then 150ml coffee, and stir until dissolved. Pour the cream gently over the back of a spoon to float on top. Do not stir.","shop":["600ml strong brewed coffee@Pantry","160ml Irish whiskey@Bottle shop","8 tsp brown sugar@Pantry","150ml thickened cream@Dairy"]}],"shopping":["2 Lebanese cucumbers@Produce","1 small onion@Produce","150ml white vinegar@Pantry","60g sugar@Pantry","1 tsp mustard seeds@Pantry","8 slices white breads@Bakery","320g sharp cheddar@Dairy","70g butter@Dairy","450g plain flour@Pantry","1 tsp bicarbonate of soda@Pantry","400ml buttermilk@Dairy","100g salted butter@Dairy","200g vintage cheddar@Dairy","1.5kg corned silverside@Meat","1 onion@Produce","2 bay leaves@Pantry","600g potatoes@Produce","3 carrots@Produce","1 cabbage@Produce","1 jar hot English mustard@Pantry","1kg Granny Smith apples@Produce","80g caster sugar@Pantry","1 tsp ground cinnamon@Pantry","2 sheets sweet shortcrust pastry@Frozen","600ml strong brewed coffee@Pantry","160ml Irish whiskey@Bottle shop","8 tsp brown sugar@Pantry","150ml thickened cream@Dairy"]}},"Do the Right Thing (1989)":{"poster":"assets/menu-posters/do-the-right-thing-1989.jpg","colour":"#ad3020","servings":4,"tagline":"Hottest day of the year. Coldest drinks in the house.","cue":"Turn the fan on and pour the drinks when Mookie heads in to work at Sal's.","menu":{"s":[{"n":"Sal's garlic knots","note":"tied pizza dough baked hot, tossed in garlic butter, parsley and parmesan, for Mookie's delivery run","how":"Cut 500g pizza dough into 12 strips, tie each into a knot and prove 30 minutes. Bake at 230C for 12 minutes until golden. Melt 50g butter with 3 crushed garlic cloves and chopped parsley, toss the hot knots through and shower with 30g grated parmesan.","shop":["500g pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy"]},{"n":"Chilli-lime watermelon and feta skewers","note":"ice-cold watermelon, salty white cheese and mint, citrus and spiced salt, waaake up","how":"Cut 1kg chilled seedless watermelon into 3cm cubes and 200g firm feta into 2cm cubes. Thread onto 16 skewers, alternating with small mint leaves. Mix 1 tsp flaky salt, half a tsp chilli flakes and the zest of 1 lime. Squeeze the lime juice over the skewers, sprinkle with the chilli salt and serve straight from the fridge.","shop":["1kg seedless watermelon@Produce","200g firm feta@Dairy","1 bunch mint@Produce","1 lime@Produce","flaky sea salt@Pantry","chilli flakes@Pantry","16 skewers@Pantry"]}],"m":[{"n":"Sal's Famous slice","note":"pepperoni and extra cheese, straight from the wall of fame","how":"Rest 2 balls of pizza dough, about 500g, at room temperature for an hour. Season 400g crushed tomatoes with salt and stretch the bases thin. Spread with sauce, top with 250g grated low-moisture mozzarella and 100g pepperoni and bake on a preheated tray at the oven's highest setting for 8 to 10 minutes. Sprinkle with oregano and cut big.","shop":["500g pizza dough@Bakery","400g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","1 tsp dried oregano@Pantry"]}],"w":[{"n":"Cherry shaved ice","note":"crushed ice soaked in homemade dark fruit syrup with lemon, from the street cart","how":"Simmer 300g cherries, pitted, with 150g caster sugar, 150ml water and the juice of 1 lemon for 10 minutes, then strain and cool the syrup. Shave or crush 1kg ice into four cups and pour the syrup over just before serving.","shop":["300g cherries@Produce","150g caster sugar@Pantry","1 lemon@Produce","1kg ice@Frozen"]}],"d":[{"n":"Heatwave lager and lemonade shandy","note":"Da Mayor and his cold beer on the hottest day of the year","how":"Make lemonade by stirring 100ml lemon juice, 80g caster sugar and 300ml cold water until dissolved. Chill 4 tall glasses in the freezer for 20 minutes. Half-fill each glass with ice-cold lager, about 180ml, then top with 100ml of the lemonade. Add a lemon wheel and serve straight away.","shop":["4 bottles lager@Bottle shop","3 lemons@Produce","80g caster sugar@Pantry"]}],"shopping":["1kg pizza dough@Bakery","50g butter@Dairy","3 garlic cloves@Produce","1 bunch parsley@Produce","30g parmesan@Dairy","1kg seedless watermelon@Produce","200g firm feta@Dairy","1 bunch mint@Produce","1 lime@Produce","flaky sea salt@Pantry","chilli flakes@Pantry","16 skewers@Pantry","400g crushed tomatoes@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","1 tsp dried oregano@Pantry","300g cherries@Produce","230g caster sugar@Pantry","4 lemons@Produce","1kg ice@Frozen","4 bottles lagers@Bottle shop"]}},"Elf (2003)":{"poster":"assets/menu-posters/elf-2003.jpg","colour":"#23572c","servings":4,"tagline":"Straight from the North Pole. Heavy on the syrup.","cue":"Pour coffee when Buddy first arrives in New York.","menu":{"s":[{"n":"Maple syrup popcorn","note":"Buddy puts syrup on everything","how":"Pop 60g popping corn in 1 tbsp vegetable oil. Boil 200ml maple syrup with 40g butter to 120C. Pour over the popcorn, toss quickly and spread on a lined tray to set for 30 minutes. Break into clusters.","shop":["60g popping corn@Pantry","1 tbsp vegetable oil@Pantry","200ml maple syrup@Pantry","40g butter@Dairy"]},{"n":"Candy cane pretzel rods","note":"Buddy's long walk south from the North Pole","how":"Melt 150g white chocolate in a bowl over barely simmering water. Dip 12 pretzel rods two-thirds into the chocolate, roll immediately in 60g crushed candy canes and set on baking paper for 30 minutes.","shop":["12 pretzel rods@Pantry","150g white chocolate@Pantry","60g candy canes@Pantry"]}],"m":[{"n":"New York street hot dogs","note":"griddled frankfurts, yellow mustard, tomato-stewed onions and sauerkraut, son of a nutcracker","how":"Cook 2 sliced brown onions in 20g butter over medium-low heat for 20 minutes. Add 200g crushed tomatoes and simmer for 10 minutes. Simmer 4 large franks in water for 5 minutes, drain and griddle for 2 minutes a side. Warm 200g sauerkraut in a saucepan for 5 minutes and steam 4 buns for 1 minute. Assemble with 4 tbsp yellow mustard and the tomato onions.","shop":["2 brown onions@Produce","20g butter@Dairy","200g crushed tomatoes@Pantry","4 large hot dog franks@Meat","200g sauerkraut@Pantry","4 hot dog buns@Bakery","4 tbsp yellow mustard@Pantry"]}],"w":[{"n":"Snowball fight cupcakes","note":"white coconut frosting","how":"Heat the oven to 180C. Beat 80g soft butter with 80g caster sugar, add 1 egg and 1 tsp vanilla, then fold in 100g self-raising flour and 40ml milk. Divide between 4 large cupcake cases and bake for 18 minutes. Cool completely. Beat 100g cream cheese with 20g butter and 100g icing sugar, dome over the cakes and roll in 40g shredded coconut.","shop":["100g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","40ml full cream milk@Dairy","100g cream cheese@Dairy","100g icing sugar@Pantry","40g shredded coconut@Pantry"]}],"d":[{"n":"Buddy's maple mocha","note":"Buddy's coffee, sweetened the elf way","how":"Heat 800ml milk with 100g chopped milk chocolate and 3 tbsp maple syrup, whisking until smooth and steaming. Stir in 200ml strong coffee, or leave it out for the kids. Pour into 4 mugs, top with whipped cream from 150ml thickened cream, a handful of mini marshmallows, a drizzle of maple syrup and crushed candy cane.","shop":["800ml milk@Dairy","100g milk chocolate@Pantry","4 tbsp maple syrup@Pantry","200ml strong brewed coffee@Pantry","150ml thickened cream@Dairy","1 bag mini marshmallows@Pantry","2 candy canes@Pantry"]}],"shopping":["60g popping corn@Pantry","1 tbsp vegetable oil@Pantry","200ml maple syrup@Pantry","160g butter@Dairy","12 pretzel rods@Pantry","150g white chocolate@Pantry","60g candy canes@Pantry","2 brown onions@Produce","200g crushed tomatoes@Pantry","4 large hot dog franks@Meat","200g sauerkraut@Pantry","4 hot dog buns@Bakery","4 tbsp yellow mustard@Pantry","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","40ml full cream milk@Dairy","100g cream cheese@Dairy","100g icing sugar@Pantry","40g shredded coconut@Pantry","800ml milk@Dairy","100g milk chocolate@Pantry","4 tbsp maple syrup@Pantry","200ml strong brewed coffee@Pantry","150ml thickened cream@Dairy","1 bag mini marshmallows@Pantry","2 candy canes@Pantry"]}},"Midnight Cowboy (1969)":{"poster":"assets/menu-posters/midnight-cowboy-1969.jpg","colour":"#795237","servings":4,"tagline":"Big city. Small bank balance.","cue":"Serve the mains when Joe first meets Ratso in the bar.","menu":{"s":[{"n":"Automat sandwiches","note":"leg ham and Swiss on white, mustard butter, crusts off, wrapped in paper, I'm walkin' here","how":"Mash 40g soft butter with 1 tsp Dijon mustard and spread over 8 slices white bread. Fill with 200g leg ham and 4 slices Swiss cheese. Cut off the crusts, cut into quarters and wrap in baking paper, like the automat windows.","shop":["40g butter@Dairy","1 tsp Dijon mustard@Pantry","8 slices white bread@Bakery","200g leg ham@Deli","4 slices Swiss cheese@Deli"]},{"n":"Cinnamon doughnut holes, coffee custard","note":"hot dough balls in spiced sugar, custard for dunking, bought with Joe's last coins","how":"Mix 250g self-raising flour, 50g caster sugar, 1 egg, 150ml milk and 30g melted butter into a soft dough. Roll into 24 small balls. Fry at 170C for 3 minutes until golden and cooked through, then roll in 80g caster sugar mixed with 2 tsp cinnamon. Heat 300ml custard with 2 tsp instant coffee dissolved in 1 tbsp hot water and serve warm for dipping.","shop":["250g self-raising flour@Pantry","130g caster sugar@Pantry","1 egg@Dairy","150ml milk@Dairy","30g butter@Dairy","2 tsp cinnamon@Pantry","300ml thick custard@Dairy","2 tsp instant coffee@Pantry","1 litre vegetable oil@Pantry"]}],"m":[{"n":"Florida coconut prawns","note":"butterflied prawns in crisp panko, sweet chilli and lime, for the Greyhound south","how":"Butterfly 600g green prawns, leaving the tails on. Dust in 50g flour, dip in 2 beaten eggs, then press into 80g panko mixed with 80g shredded coconut. Fry at 180C for 2 minutes until golden. Serve with 150ml sweet chilli sauce and lime wedges.","shop":["600g green prawns@Seafood","50g plain flour@Pantry","2 eggs@Dairy","80g panko@Pantry","80g shredded coconut@Pantry","150ml sweet chilli sauce@Pantry","2 limes@Produce","1L vegetable oil@Pantry"]}],"w":[{"n":"Florida orange cake","note":"whole boiled citrus blitzed into an almond meal and egg batter, moist and flourless","how":"Boil 2 whole oranges for 1 hour until soft, cool and blitz smooth, skin and all. Beat 6 eggs with 250g caster sugar, then mix in the oranges, 250g almond meal and 1 tsp baking powder. Pour into a lined 22cm tin and bake at 180C for 1 hour. Cool in the tin.","shop":["2 oranges@Produce","6 eggs@Dairy","250g caster sugar@Pantry","250g almond meal@Pantry","1 tsp baking powder@Pantry"]}],"d":[{"n":"Ratso's Florida coconut pineapple cooler","note":"coconut water, lime and fruit juice shaken with cream, over ice, white rum on the side","how":"Shake 400ml coconut water, 300ml pineapple juice, 60ml lime juice and 60ml coconut cream with ice for 15 seconds until frothy. Strain into 4 ice-filled tall glasses. Add 30ml white rum to each glass for a boozy version. Garnish with a pineapple wedge and a lime wheel.","shop":["400ml coconut water@Drinks","300ml pineapple juice@Drinks","2 limes@Produce","60ml coconut cream@Pantry","1 small pineapple@Produce","120ml white rum@Bottle shop","1 bag ice@Frozen"]}],"shopping":["70g butter@Dairy","1 tsp Dijon mustard@Pantry","8 slices white breads@Bakery","200g leg ham@Deli","4 slices Swiss cheeses@Deli","250g self-raising flour@Pantry","380g caster sugar@Pantry","9 eggs@Dairy","150ml milk@Dairy","2 tsp cinnamon@Pantry","300ml thick custard@Dairy","2 tsp instant coffee@Pantry","1 litre vegetable oil@Pantry","600g green prawns@Seafood","50g plain flour@Pantry","80g panko@Pantry","80g shredded coconut@Pantry","150ml sweet chilli sauce@Pantry","4 limes@Produce","1L vegetable oil@Pantry","2 oranges@Produce","250g almond meal@Pantry","1 tsp baking powder@Pantry","400ml coconut water@Drinks","300ml pineapple juice@Drinks","60ml coconut cream@Pantry","1 small pineapple@Produce","120ml white rum@Bottle shop","1 bag ice@Frozen"]}},"Dog Day Afternoon (1975)":{"poster":"assets/menu-posters/dog-day-afternoon-1975.jpg","colour":"#8c3027","servings":4,"tagline":"Pizza for the hostages.","cue":"Order the pizza when it gets delivered to the bank.","menu":{"s":[{"n":"Barricade chips and onion dip","note":"caramelised onion in sour cream and cream cheese, ridged crisps, while Sonny yells Attica","how":"Cook 2 thinly sliced brown onions in 2 tbsp oil over low heat for 40 minutes until deep brown, then cool. Stir into 200g sour cream and 100g cream cheese with 2 tbsp chopped chives and salt. Serve with 300g ridged potato chips.","shop":["2 brown onions@Produce","200g sour cream@Dairy","100g cream cheese@Dairy","1 bunch chives@Produce","300g ridged potato chips@Pantry"]},{"n":"Deli hero wedges","note":"long rolls of ham, salami, provolone, lettuce and tomato, cut for passing round to the hostages","how":"Split 2 long hero rolls lengthwise. Layer 150g ham, 100g salami and 100g sliced provolone, then shredded iceberg and sliced tomato. Dress with 2 tbsp olive oil, 1 tbsp red wine vinegar, oregano, salt and pepper. Press down firmly, then cut each hero into 6 wedges.","shop":["2 long rolls@Bakery","150g ham@Deli","100g salami@Deli","100g provolone@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","1 tbsp red wine vinegar@Pantry"]}],"m":[{"n":"Hostage pizza","note":"delivered to the door, the delivery kid becomes a star","how":"Rest 2 balls of pizza dough, about 500g, at room temperature for an hour. Season 400g crushed tomatoes with salt and 1 tsp dried oregano. Stretch the bases thin, spread with sauce, top with 250g grated low-moisture mozzarella and 100g pepperoni, and bake on a preheated tray at the oven's highest setting for 8 minutes.","shop":["500g pizza dough@Bakery","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Italian ice","note":"lemon juice, zest and sugar frozen and scraped to icy flakes, for a sweltering bank job","how":"Simmer 200g caster sugar with 500ml water and the zest of 2 lemons for 5 minutes, then cool. Stir in 250ml lemon juice, about 6 lemons. Freeze in a shallow tray, scraping with a fork every 30 minutes for 3 hours until fluffy. Serve in paper cups.","shop":["200g caster sugar@Pantry","6 lemons@Produce"]}],"d":[{"n":"Heatwave lager with lime and chilli salt","note":"ice-cold beer over fresh citrus, spicy salted rim, for Sal, who has never flown","how":"Mix 1 tbsp flaky salt with half a tsp chilli powder and the zest of 1 lime on a plate. Run a lime wedge around the rims of 4 chilled glasses and dip in the chilli salt. Squeeze 15ml lime juice into each glass, add 2 ice cubes, then pour in a cold 375ml bottle of lager slowly.","shop":["4 bottles lager@Bottle shop","3 limes@Produce","flaky sea salt@Pantry","chilli powder@Pantry","1 bag ice@Frozen"]}],"shopping":["2 brown onions@Produce","200g sour cream@Dairy","100g cream cheese@Dairy","1 bunch chives@Produce","300g ridged potato chips@Pantry","2 long rolls@Bakery","150g ham@Deli","100g salami@Deli","100g provolone@Deli","1 iceberg lettuce@Produce","2 tomatoes@Produce","1 tbsp red wine vinegar@Pantry","500g pizza dough@Bakery","400g crushed tomatoes@Pantry","1 tsp dried oregano@Pantry","250g low-moisture mozzarella@Dairy","100g pepperoni@Deli","200g caster sugar@Pantry","6 lemons@Produce","4 bottles lagers@Bottle shop","3 limes@Produce","flaky sea salt@Pantry","chilli powder@Pantry","1 bag ice@Frozen"]}},"The Out-of-Towners (1970)":{"poster":"assets/menu-posters/the-out-of-towners-1970.jpg","colour":"#205455","servings":4,"tagline":"Every possible thing goes wrong.","cue":"Serve dessert when George cracks a tooth on Cracker Jacks.","menu":{"s":[{"n":"Handbag shortbread fingers with jam","note":"pale butter biscuits sandwiched with raspberry jam, icing sugar, kinder than Cracker Jacks","how":"Beat 200g soft butter with 100g icing sugar until pale. Mix in 250g plain flour and 50g cornflour to a soft dough. Press into a lined 20 x 30cm tin, prick all over and bake at 160C for 25 to 30 minutes until pale golden. Cut into 24 fingers while warm and cool in the tin. Sandwich pairs with 120g raspberry jam and dust with icing sugar.","shop":["200g butter@Dairy","120g icing sugar@Pantry","250g plain flour@Pantry","50g cornflour@Pantry","120g raspberry jam@Pantry"]},{"n":"Diverted flight cocktail franks","note":"little sausages sticky with honey, mustard and brown sugar, for the flight that lands in Boston","how":"Simmer 500g cocktail franks in water for 3 minutes and drain. In a frying pan melt 20g butter with 3 tbsp honey, 2 tbsp Dijon, 1 tbsp brown sugar and 1 tbsp Worcestershire. Add the franks and toss over medium heat for 5 minutes until sticky and glazed. Serve on toothpicks with cocktail onions.","shop":["500g cocktail franks@Deli","20g butter@Dairy","3 tbsp honey@Pantry","2 tbsp Dijon mustard@Pantry","1 tbsp brown sugar@Pantry","1 tbsp Worcestershire sauce@Pantry","1 jar cocktail onions@Pantry"]}],"m":[{"n":"Hotel rib eye breakfast","note":"seared steak, two fried eggs, crisp hash browns and buttered toast, the breakfast George never gets","how":"Grate 600g potatoes and squeeze dry in a tea towel. Season with 1/2 tsp salt, shape into 4 hash browns and fry in 40g butter over medium heat for 6 minutes a side. Sear 4 rib eye steaks, 200g each, in a very hot pan with 1 tbsp oil for about 3 minutes a side to 54C, then rest for 8 minutes. Fry 8 eggs in 20g butter for 3 minutes. Toast 4 sourdough slices and spread with 20g butter. Serve one steak, two eggs, one hash brown and one toast per person.","shop":["600g potatoes@Produce","1/2 tsp fine salt@Pantry","80g butter@Dairy","800g rib eye steak@Meat","1 tbsp vegetable oil@Pantry","8 eggs@Dairy","4 slices sourdough@Bakery"]}],"w":[{"n":"Checked-in cheesecake","note":"baked New York style in a water bath, chilled overnight and topped with strawberries","how":"Crush 120g digestive biscuits and mix with 50g melted butter. Press into a lined 18cm springform tin. Beat 400g cream cheese with 100g caster sugar, then mix in 100g sour cream, 2 eggs and 1 tsp vanilla. Pour over the base. Wrap the tin in two layers of foil and stand in a roasting dish with hot water halfway up its sides. Bake at 150C for 70 minutes until the centre gently wobbles. Cool for 1 hour, refrigerate overnight and top with 200g sliced strawberries. Cut four generous portions, with leftovers.","shop":["120g digestive biscuits@Pantry","50g butter@Dairy","400g cream cheese@Dairy","100g caster sugar@Pantry","100g sour cream@Dairy","2 eggs@Dairy","1 tsp vanilla extract@Pantry","200g strawberries@Produce"]}],"d":[{"n":"Hotel bar martini","note":"gin and a little dry vermouth stirred ice cold, frozen glass, olive, George has earned it","how":"For each of 4 drinks stir 60ml gin and 10ml dry vermouth over ice for 30 seconds. Strain into a frozen martini glass and garnish with 1 green olive.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","500g ice@Frozen","4 green olives@Pantry"]}],"shopping":["350g butter@Dairy","120g icing sugar@Pantry","250g plain flour@Pantry","50g cornflour@Pantry","120g raspberry jam@Pantry","500g cocktail franks@Deli","3 tbsp honey@Pantry","2 tbsp Dijon mustard@Pantry","1 tbsp brown sugar@Pantry","1 tbsp Worcestershire sauce@Pantry","1 jar cocktail onions@Pantry","600g potatoes@Produce","1/2 tsp fine salt@Pantry","800g rib eye steak@Meat","1 tbsp vegetable oil@Pantry","10 eggs@Dairy","4 slices sourdoughs@Bakery","120g digestive biscuits@Pantry","400g cream cheese@Dairy","100g caster sugar@Pantry","100g sour cream@Dairy","1 tsp vanilla extract@Pantry","200g strawberries@Produce","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","500g ice@Frozen","4 green olives@Pantry"]}}};